import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class UtilsService {

  constructor() { }

  /**
   * Converts a value (string or number) into a float, handling
   * regional formats (comma as decimal separator and dot as thousands separator).
   * @param value The input value.
   * @returns The resulting float value (number).
   */
  getFloatValue(value) {
    if (value === null || typeof value === 'undefined') {
      return NaN;
    }
    if (typeof value === 'number') {
      return value;
    }
    let sValue = String(value);
    if (sValue.includes(',')) {
      sValue = sValue.replace(/\./g, '').replace(/,/g, '.');
    }
    return parseFloat(sValue);
  }

  roundTo(num, decimals) {
    const factor = Math.pow(10, decimals);
    return Math.round(num * factor) / factor;
  }

  isInView = function (ele, container) {
    const bb = ele.getBoundingClientRect();
    const eleTop = bb.y;
    const eleBottom = eleTop + bb.height;
    const containerTop = 0; //container.scrollTop;
    const containerBottom = containerTop + container.clientHeight;
    // The element is fully visible in the container
    return (
      (eleTop >= containerTop && eleBottom <= containerBottom) ||
      // Some part of the element is visible in the container
      (eleTop < containerTop && containerTop < eleBottom) ||
      (eleTop < containerBottom && containerBottom < eleBottom)
    );
  };

}
