import {Component, Inject, OnInit} from '@angular/core';
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import * as moment from 'moment';
import {HomegenieAdapter} from "../../homegenie-adapter";
import {HomegenieApi} from "../../homegenie-api";

@Component({
  selector: 'app-logging-dialog',
  templateUrl: './logging-dialog.component.html',
  styleUrls: ['./logging-dialog.component.scss']
})
export class LoggingDialogComponent implements OnInit {
  adapter: HomegenieAdapter;
  changed = false;
  loggingConfig;

  get lastLogName() {
    return "last_log";
    //return moment(this.loggingConfig.LastLog).calendar().split(' ')[0];
  }
  get previousLogName() {
    return "previous_log";
    //return moment(this.loggingConfig.PreviousLog).calendar().split(' ')[0];
  }

  constructor(@Inject(MAT_DIALOG_DATA) private data) {
    this.adapter = data.adapter;
    this.loggingConfig = data.systemInfo.Configuration.Logging;
  }

  ngOnInit(): void {
  }

  onEnableLogsChange() {
    this.adapter.apiCall(this.loggingConfig.Enabled ?
      HomegenieApi.SystemConfig.Logging.Enable :
      HomegenieApi.SystemConfig.Logging.Disable
    ).subscribe((ar) => {
      console.log(ar.response);
    }, console.log);
  }

  onLogDownloadClick(type: string) {
    if (type === 'previous') {
      this.downloadCsv(1);
    } else {
      this.downloadCsv(0);
    }
  }

  private downloadCsv(type: number) {
    this.adapter.apiCall(HomegenieApi.SystemConfig.Logging.DownloadCsv(type), null, {
      responseType: 'blob'
    }).subscribe((ar) => {
      const date = type === 0 ? this.loggingConfig.LastLog : this.loggingConfig.PreviousLog;
      const a = document.createElement('a')
      const objectUrl = URL.createObjectURL(ar.response)
      a.href = objectUrl
      a.download = `homegenie_${moment(date).format('YYYYMMDD_HHmmss')}_log.csv`;
      a.click();
      URL.revokeObjectURL(objectUrl);
    });
  }
}
