import {Component, Inject, Optional} from '@angular/core';
import {MAT_BOTTOM_SHEET_DATA, MatBottomSheetRef} from "@angular/material/bottom-sheet";
import {HomegenieApi} from "../../../../adapters/home-genie/homegenie-api";
import {FLD, YotService} from "../../../../services/yot/yot.service";
import {HomegenieAdapter} from "../../../../adapters/home-genie/homegenie-adapter";
import {Module} from "../../../../services/yot/module";
import {Dashboard} from "../../../../services/dashboard/dashboard";
import * as moment from "moment/moment";

@Component({
  selector: 'app-programs-bottom-sheet',
  templateUrl: './programs-bottom-sheet.component.html',
  styleUrls: ['./programs-bottom-sheet.component.scss']
})
export class ProgramsBottomSheetComponent {

  dashboard: Dashboard;
  programs: Module[];
  isLoading = false;

  constructor(
    @Optional() private bsRef: MatBottomSheetRef<any>,
    @Inject(MAT_BOTTOM_SHEET_DATA) public data: any,
    private yot: YotService
  ) {
    this.dashboard = data.dashboard;
    this.programs = data.programs;
  }

  closeSheet() {
    this.bsRef.dismiss();
  }

  isRunning(program: Module) {
    return this.getStatusText(program) === 'Running';
  }
  getStatusText(program: Module): string {
    return program.field(FLD.Program.Status)?.value;
  }
  getActivityStatus(program: Module) {
    return moment(program.field(FLD.Program.Status)?.timestamp).fromNow();
  }

  protected selectProgram(program: any) {
    this.isLoading = true;
    const programAddress = program.id.split(':').splice(-1);
    (this.yot.getDefaultAdapter() as HomegenieAdapter)
      .apiCall(HomegenieApi.Automation.Programs.Toggle(programAddress, this.dashboard.name))
      .subscribe(() => {
        this.isLoading = false;
      });
  }
}
