import {Component, Input, OnDestroy, OnInit, QueryList, ViewChild, ViewChildren} from '@angular/core';
import {MatDialog} from "@angular/material/dialog";
import {Router} from "@angular/router";
import {Group, HomegenieAdapter} from "../homegenie-adapter";
import {concat, Subscription} from "rxjs";
import {RegionalSettingsComponent, SetupRegionalConfiguration} from "./regional-settings/regional-settings.component";
import {PagesRoute} from "../../../pages-route";
import {NavigationService} from "../../../services/navigation.service";
import {HomegenieApi, ResponseStatus} from "../homegenie-api";
import {MatSelectionList} from "@angular/material/list";
import {MatCheckbox} from "@angular/material/checkbox";
import {SystemSettingsComponent} from "./system-settings/system-settings.component";
import {SetupSystemConfiguration} from "../homegenie-maintenance/restore-backup/restore-backup.component";
import {ClientConfigService} from "../../../services/client-config.service";

import {AudioSetupFormComponent} from '../audio-setup-form/audio-setup-form.component';

enum SetupWizardPage {
  Welcome,
  RegionalSettings,
  SystemSettings,
  AdditionalSettingsStep,
  FinalStep
}

@Component({
  selector: 'app-setup-wizard',
  templateUrl: './setup-wizard.component.html',
  styleUrls: ['./setup-wizard.component.scss']
})
export class SetupWizardComponent implements OnInit, OnDestroy {
  @ViewChildren(AudioSetupFormComponent) audioForms: QueryList<AudioSetupFormComponent>;
  get audioConfigurationBusy(): boolean { return this.audioForms?.some(form => form.loading || form.busy || form.pending) || false; }

  @ViewChild('systemSettingsComponent', {static: false})
  systemSettingsComponent: SystemSettingsComponent;
  @ViewChild('regionalSettingsComponent', {static: false})
  regionalSettingsComponent: RegionalSettingsComponent;
  @ViewChild('matSelectionList') matSelectionListPrograms: MatSelectionList;
  @ViewChild('selectAllToggle') selectAllProgramsToggle: MatCheckbox;
  @Input()
  adapter: HomegenieAdapter;

  languagesList: any = {};

  currentPage = 0;
  installedPackages = 0;

  isLoading = false;

  WizardPage = SetupWizardPage;

  systemConfig = new SetupSystemConfiguration();
  regionalConfig = new SetupRegionalConfiguration();

  restoreProgressMessage = '';
  showBackupRestoreProgress = false;
  private moduleEventSubscription: Subscription;

  get requireAdditionalConfigStep(): boolean {
    const settings = this.systemConfig;
    return settings.configureX10 || settings.configureZWave
    || settings.configureZigBee || settings.configureVoiceRecognizer || settings.configureVoiceSynthesizer /* || settings.configureGPIO */
    || (settings.restoreBackup && settings.restoreProgramList.length > 0);
  }
  get packagesToInstall(): string[] {
    return this.systemConfig.packagesToInstall;
  }

  constructor(private dialog: MatDialog, private router: Router, private navigationService: NavigationService, protected clientConfigService: ClientConfigService) { }

  ngOnInit(): void {
    this.navigationService.hideToolbar();
//    this.router.routeReuseStrategy.shouldReuseRoute = () => false;
    this.moduleEventSubscription = this.adapter.onModuleEvent.subscribe((e) => {
      if (e.event.Domain === 'HomeGenie.BackupRestore' && e.event.Property === 'InstallProgress.Message') {
        this.restoreProgressMessage = e.event.Value;
      }
    });
    this.clientConfigService.getLanguagesList().subscribe(list => this.languagesList = list);
  }
  ngOnDestroy(): void {
    setTimeout(() => this.navigationService.showToolbar(), 250);
//    this.router.routeReuseStrategy.shouldReuseRoute = () => true;
    this.moduleEventSubscription.unsubscribe();
  }

  onUiLanguageChange(lang) {
    this.adapter.yot.setUiLanguage(lang)
      .subscribe((actualLanguage) => {
        this.adapter.yot.savePreferences();
      });
  }

  onSelectedProgramsChange() {
    this.matSelectionListPrograms.selectedOptions.selected.length === this.matSelectionListPrograms.options.length ?
      this.selectAllProgramsToggle.checked = true :
      this.selectAllProgramsToggle.checked = false;
  }

  onSelectAllProgramsClick() {
    this.selectAllProgramsToggle.checked ?
      this.matSelectionListPrograms.deselectAll() :
      this.matSelectionListPrograms.selectAll();
  }

  prevStep() {
    if (this.currentPage > SetupWizardPage.Welcome) {
      const newPage = this.currentPage - 1;
      this.leavePage(this.currentPage, newPage);
      this.currentPage = newPage;
      this.enterPage(this.currentPage);
    }
  }
  nextStep() {
    if (this.currentPage < SetupWizardPage.FinalStep) {
      const newPage = this.currentPage + 1;
      this.currentPage = this.leavePage(this.currentPage, newPage);
      this.enterPage(this.currentPage);
    }
  }

  private leavePage(page: SetupWizardPage, newPage: SetupWizardPage): number | any {
    switch (page) {
      case SetupWizardPage.RegionalSettings:
        this.regionalConfig = this.regionalSettingsComponent.configure();
        break;
      case SetupWizardPage.SystemSettings:
        this.systemConfig = this.systemSettingsComponent.configure();
        // if navigating to next step check for additional operations
        if (newPage > SetupWizardPage.SystemSettings) {
          if (this.systemConfig.configureManually) {
            this.router.navigate([PagesRoute.SetupPage])
              .then((res) => {
                // TODO: show some tip message (maybe)
              });
          } else if (!this.requireAdditionalConfigStep) {
            // go to final step if no additional configuration is required
            return (this.currentPage = SetupWizardPage.FinalStep);
          }
        }
        break;
    }
    return newPage;
  }

  private enterPage(page: SetupWizardPage) {
    if (this.currentPage === SetupWizardPage.AdditionalSettingsStep && this.systemConfig.restoreBackup) {
      setTimeout(() => {
        this.matSelectionListPrograms.selectAll();
        this.selectAllProgramsToggle.checked = true;
      });
    } else if (this.currentPage === SetupWizardPage.FinalStep) {
      // Last step: install packages and configure dashboards
      this.isLoading = true;
      const jobs = [];
      this.systemConfig.packagesToInstall.map((p) => {
        jobs.push(this.adapter
          .apiCall(HomegenieApi.Config.Packages.Install('homegenie', p)));
      });
      // install packages
      this.installedPackages = 0;
      concat(...jobs).subscribe((res: any) => {
        this.installedPackages++;
        if (this.installedPackages === this.systemConfig.packagesToInstall.length) {
          this.isLoading = false;
          if (this.systemConfig.restoreBackup) {
            this.showBackupRestoreProgress = true;
            this.isLoading = true;
            this.adapter
              .apiCall(HomegenieApi.SystemConfig.System.ConfigurationRestoreStep2(this.systemConfig.restoreProgramList.map(p => p.Address)))
              .subscribe((ar) => {
                this.isLoading = false;
                setTimeout(() => {
                  this.completeInstallation();
                }, 1000);
              }, (error) => {
                this.isLoading = false;
                // TODO: handle / report error
                console.log(error, error.message);
              });
          } else {
            setTimeout(() => {
              this.completeInstallation();
            }, 1000);
          }
        }
      }, (err) => {
        this.isLoading = false;
        console.log('ERROR', err);
      });
    }
  }

  private addGroup(g: Group, callback) {
    const done = () => {
      callback();
    }
    this.adapter.apiCall(HomegenieApi.Config.Groups.Add, g.Name)
      .subscribe({
        next: (res) => {
          if (res.response.Status === ResponseStatus.Error) {
            this.adapter.yot
              .notify(res.response.Status, res.response.Message);
            done();
          } else {
            this.adapter.apiCall(HomegenieApi.Config.Groups.Save, [g])
              .subscribe({
                next: (res) => {
                  done();
                },
                error: (err) => {
                  this.adapter.yot.notify('Error', err.message);
                  done();
                }
              });
          }
        },
        error: (err) => {
          this.adapter.yot.notify('Error', err.message);
          done();
        }
      });
  }
  private addDashboardForDomain(domain: string, dashboardName: string) {
    const d = this.adapter.yot.dashboardService.addDashboard(dashboardName);
    this.adapter.modules.filter((m) => m.Domain === domain && m.DeviceType && m.DeviceType !== 'Generic')
      .forEach((m) => {
        const ym = this.adapter.getModuleByRef(m);
        const widgetData = ym?.getWidgetData();
        if (widgetData) {
          d.addWidget(widgetData.type, ym, widgetData);
        } else {
          console.log('Could not add widget for module', ym);
        }
      });
  }

  private completeInstallation() {
    // TODO: improve this! (?)
    this.isLoading = true;
    this.adapter.disconnect().subscribe((res) => {
      this.adapter.importDashboards().subscribe(() => {

        const finish = () => {
          if (this.systemConfig.configureGPIO) {
// TODO: add Raspberry IoT widgets
            //this.addDashboardForDomain('RaspberryPi.GPIO', 'GPIO  ');
          }
          if (this.systemConfig.configureX10) {
            this.addDashboardForDomain('HomeAutomation.X10', 'X10');
          }
          if (this.systemConfig.configureZigBee) {
            this.addDashboardForDomain('HomeAutomation.ZigBee', 'ZigBee');
          }
          if (this.systemConfig.configureZWave) {
            this.addDashboardForDomain('HomeAutomation.ZWave', 'Z-Wave');
          }
          /*
          // UPnP devices (this is not needed anymore since UPnP group is automatically updated by HG-Server)
          const upnpDomain = 'Protocols.UPnP';
          const upnpGroup = new Group();
          upnpGroup.Name = "UPnP";
          this.adapter.modules.filter((m) => m.Domain === upnpDomain && m.DeviceType && m.DeviceType !== 'Generic')
            .forEach((m) => {
              const ym = this.adapter.getModuleByRef(m);
              const widgetData = ym?.getWidgetData();
              if (widgetData) {
                //d.addWidget(widgetData.type, ym, widgetData);
                upnpGroup.Modules.push({Domain: m.Domain, Address: m.Address});
              } else {
                console.log('Could not add widget for module', ym);
              }
            });
          this.navigationService.isLoading = true;
          this.addGroup(upnpGroup, () => {
            this.navigationService.isLoading = false;
            this.addDashboardForDomain(upnpDomain, 'UPnP');
          });
         */

          this.adapter.yot.saveConfiguration().subscribe((config) => {
            this.adapter.yot.notificationService.disable = false;
            const dashboard = this.adapter.yot.dashboardService.dashboards[0];
            if (dashboard) {
              this.router
                .navigate([PagesRoute.HomePage, dashboard.name])
                .then(() => this.isLoading = false);
            } else {
              this.router
                .navigate([ PagesRoute.HomePage ])
                .then((res) => this.isLoading = false);
            }
          });
        };
        this.clientConfigService.loadClientPreset('default')
          .subscribe({
            next: () => finish(),
            error: () => finish()
          });

      }, (err) => {
        this.adapter.yot.notify('Error', err.message);
      });
    });
  }

}
