import {Directive} from '@angular/core';
import {AbstractControl, NG_VALIDATORS, Validator} from '@angular/forms';
import {DashboardService} from "../services/dashboard/dashboard.service";

@Directive({
  selector: '[dashboardNameValidator]',
  providers: [{
    provide: NG_VALIDATORS,
    useExisting: DashboardNameValidatorDirective,
    multi: true
  }]
})
export class DashboardNameValidatorDirective implements Validator {
  constructor(private dashboardService: DashboardService) {
  }
  validate(control: AbstractControl) : {[key: string]: any} | null {
    if (control.value) {
      const alreadyExists = this.dashboardService.dashboards.find((d) => d.name.toLowerCase() === control.value.toLowerCase());
      if (alreadyExists) {
        return { 'duplicate': true };
      }
    }
    return null;
  }
}
