import {Component, Inject, OnInit} from '@angular/core';
import {MAT_DIALOG_DATA, MatDialogRef} from "@angular/material/dialog";
import {HomegenieApi} from "../../../adapters/home-genie/homegenie-api";
import {HomegenieAdapter} from "../../../adapters/home-genie/homegenie-adapter";

@Component({
  selector: 'app-about-dialog',
  templateUrl: './about-dialog.component.html',
  styleUrls: ['./about-dialog.component.scss']
})
export class AboutDialogComponent implements OnInit {
  isLoading = false;

  adapter: HomegenieAdapter;

  systemInfo: any = {};

  constructor(
    public dialogRef: MatDialogRef<AboutDialogComponent>,
    @Inject(MAT_DIALOG_DATA) public data: any
  ) {
    this.adapter = data?.adapter;
  }

  ngOnInit(): void {
    this.loadSystemSettings();
  }

  onCloseClick(): void {
    this.dialogRef.close();
  }


  private loadSystemSettings() {
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.SystemConfig.System.Info)
      .subscribe({
        next: (ar) => {
          if (ar.response) {
            this.systemInfo = ar.response;
          }
          this.isLoading = false;
        },
        error: (err) => this.isLoading = false
      });
  }
}
