import {Component, Inject} from '@angular/core';
import {HomegenieAdapter} from "../../../adapters/home-genie/homegenie-adapter";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {YotService} from "../../../services/yot/yot.service";
import {MatSelectionListChange} from "@angular/material/list";
import {Module, ModuleType} from "../../../services/yot/module";

@Component({
  selector: 'app-modules-select-dialog',
  templateUrl: './modules-select-dialog.component.html',
  styleUrls: ['./modules-select-dialog.component.scss']
})
export class ModulesSelectDialogComponent  {

  modulesList: Module[];
  selectedModules: Module[] = [];
  listMode = '';

  private adapter: HomegenieAdapter;
  private declaredModules: Module[] = [];
  private originalModules: Module[] = [];

  constructor(@Inject(MAT_DIALOG_DATA) public data: {declaredModules: Module[], selectedModules: Module[], adapter: HomegenieAdapter, mode?: 'modules' | 'programs'}, public yot: YotService) {
    this.adapter = data.adapter;
    this.listMode = data.mode;
    this.declaredModules = data.declaredModules;
    this.selectedModules = data.selectedModules;
    this.originalModules = [...data.declaredModules, ...data.selectedModules];
    // sorted list of all available modules
    let modules = this.yot.getModules();
    if (this.listMode === 'programs') {
      modules = yot.dashboardService.getAvailableDashboardPrograms(modules);
    }
    this.modulesList = modules.filter((mod) => mod.getAdapter() === this.adapter && mod.isOnline)
      .sort((a, b) => a.type === b.type ? (a.name <= b.name ? -1 : 1) : (a.type < b.type ? -1 : 1))
      .sort((a, b) => a.type !== b.type && a.type === ModuleType.Program ? 1 : b.type === ModuleType.Program ? -1 : 0);
  }

  onSelectionChange(e: MatSelectionListChange) {
//    console.log($event);
    const m: Module = e.options[0].value;
    if (!e.options[0].selected) {
      // exclude
      this.selectedModules = this.selectedModules.filter((mod) => {
        return (m.id !== mod.id) ? mod: undefined;
      });
    } else {
      // include
      /*
      const existingItem = this.originalGroup.Modules.find((mr) => mr.Domain === m.Domain && mr.Address === m.Address);
      const originalIndex = this.originalGroup.Modules.indexOf(existingItem);
      const mr: ModuleReference = { Address: m.Address, Domain: m.Domain };
      if (originalIndex >= 0) {
        this.group.Modules.splice(originalIndex, 0, mr);
      } else {
        this.group.Modules.push(mr);
      }*/
      this.selectedModules.push(m);
    }
  }

  isDeclared(m: Module): boolean {
    return this.declaredModules.find((mod) => m?.id === mod?.id) != null;
  }

  isIncluded(m: Module): boolean {
    return this.declaredModules.find((mod) => m?.id === mod?.id) != null
    || this.selectedModules.find((mod) => m?.id === mod?.id) != null;
  }

  wasIncluded(m: Module): boolean {
    return this.originalModules.find((mod) => m?.id === mod?.id) != null;
  }

}
