import {Component, OnDestroy, OnInit, ViewChild} from '@angular/core';
import {WidgetBaseComponent} from "../widget-base.component";
import {
  ModuleStatisticsDialogComponent
} from "../../components/dialogs/module-statistics-dialog/module-statistics-dialog.component";
import {
  WidgetActionRequest,
  WidgetActionRequestAction
} from "../common-parts/widget-actions-menu/widget-actions-menu.component";
import {ChartComponent} from "../../components/chart/chart.component";
import {Subscription} from "rxjs";

@Component({
  selector: 'app-statistics',
  templateUrl: './statistics.component.html',
  styleUrls: ['./statistics.component.scss']
})
export class StatisticsComponent extends WidgetBaseComponent implements OnInit, OnDestroy {
  private forceChartResume = false;

  private _chartComponent: ChartComponent | undefined;
  @ViewChild('chartComponent', { static: false })
  set chartComponent(component: ChartComponent | undefined) {
    if (this._chartComponent && !component) {
      // Component Unloaded
      this._chartComponent = component;
      return;
    }
    if (component && !this._chartComponent) {
      // Component Loaded
      this._chartComponent = component;
    }
    if (this._chartComponent) {
      // Initialize component
      if (this.forceChartResume) {
        component.resume();
      } else {
        this.forceChartResume = true;
      }
    }
  }
  get chartComponent(): ChartComponent | undefined {
    return this._chartComponent;
  }

  private statusChangeSubscription: Subscription;

  get isLoading(): boolean {
    return this.chartComponent?.isLoading;
  }

  private defaultTitle: string = 'Untitled';

  ngOnInit() {
    super.ngOnInit();
    this.yot.translate.get('untitled').subscribe((title) => {
      this.defaultTitle = title;
    });
    if (!this.configuration.size) {
      this.configuration.size = 'big';
    }
    this.statusChangeSubscription = this.widgetStatusChange.subscribe(status => {
      switch (status) {
        case 'widget:paused':
          if (this.chartComponent) {
            setTimeout(() => this.chartComponent.pause(), 200);
          }
          break;
        case 'widget:resumed':
          if (this.chartComponent) {
            setTimeout(() => this.chartComponent.resume(), 200);
          }
          break;
      }
    });
  }
  ngOnDestroy() {
    this.statusChangeSubscription?.unsubscribe();
  }

  public override onWidgetActionRequest(actionRequest: WidgetActionRequest): void {
    if (actionRequest.action === WidgetActionRequestAction.showChartEdit) {
      this.configure();
    }
    super.onWidgetActionRequest(actionRequest);
  }

  configure() {
    const dialogRef = this.dialog.open(ModuleStatisticsDialogComponent, {
      panelClass: 'dialog-no-padding',
      width: '100%',
      minWidth: '280px',
      maxWidth: '960px',
      disableClose: false,
      data: this.configuration
    });
    dialogRef.afterClosed().subscribe((config) => {
      if (config) {
        // destroy old instance to force component refresh
        this.configuration.chartConfig = null;
        setTimeout(() => {
          Object.assign(this.configuration, config);
          this.save();
          this.forceChartResume = true;
        });
      }
    });
  }

  protected getTitle() {
    if (this.configuration != null && (this.configuration.title == null || this.configuration.title.trim().length === 0)) {
      return this.defaultTitle;
    }
    return this.configuration?.title;
  }
}
