import {Component, OnDestroy, OnInit} from '@angular/core';
import {Adapter} from "../../adapters/adapter";
import {YotService} from "../../services/yot/yot.service";
import {SystemApi} from "../../api/system-api";
import {NavigationService} from "../../services/navigation.service";
import {
  AutomationItemAction,
  AutomationItemActionType
} from "../automation/automation-list-item/automation-list-item.component";
import {HomegenieAdapter, Program} from "../../adapters/home-genie/homegenie-adapter";
import {PagesRoute} from "../../pages-route";
import {FileSelectDialogComponent} from "../../components/dialogs/file-select-dialog/file-select-dialog.component";
import {
  ActionConfirmDialogComponent,
  ActionConfirmDialogConfig
} from "../../components/dialogs/action-confirm-dialog/action-confirm-dialog.component";
import {
  TextInputDialogComponent,
  TextInputDialogConfig
} from "../../components/dialogs/text-input-dialog/text-input-dialog.component";
import {ProgramAddDialogComponent} from "../automation/program-add-dialog/program-add-dialog.component";
import {HomegenieApi, ModuleParameter} from "../../adapters/home-genie/homegenie-api";
import {Subscription} from "rxjs";


export class ProgramGroup {
  name: string;
  programs: Program[];
  updateTime: number;
}


@Component({
  selector: 'app-automation-page',
  templateUrl: './automation-page.component.html',
  styleUrls: ['./automation-page.component.scss']
})
export class AutomationPageComponent implements OnInit, OnDestroy {

  selectedAdapter: Adapter;

  programsList: Program[] = [];
  groupsList: string[];

  programGroups: ProgramGroup[] = [];

  packagesList: any[];
  updatablePrograms: Program[] = [];

  programUpdateListener: Subscription;

  private _flagShowFiltered = true;
  getShowFiltered() {
    return this._flagShowFiltered && this.selectedGroups.length > 0 && !this._flagShowUpgradable;
  }
  toggleShowFiltered() {
    if (this._flagShowUpgradable) {
      this.toggleShowUpgradable();
      return;
    }
    this._flagShowFiltered = !this._flagShowFiltered;
    this.savePreferences();
  }

  private _flagShowDisabled = true;
  getShowDisabled() {
    return this._flagShowDisabled;
  }
  toggleShowDisabled() {
    this._flagShowDisabled = !this._flagShowDisabled;
    this.savePreferences();
  }

  private _flagShowUpgradable = false;
  getShowUpgradable() {
    return this._flagShowUpgradable;
  }
  toggleShowUpgradable() {
    this._flagShowUpgradable = !this._flagShowUpgradable;
  }

  protected selectedGroups: string[] = [];
  getSelectedGroups(): string[] {
    let selectedGroups: string[] = this.selectedGroups.length > 0 && this._flagShowFiltered && !this._flagShowUpgradable ? this.selectedGroups : this.groupsList;
    if (this._flagShowUpgradable) {
      return selectedGroups.filter((g) => {
        const pg = this.getProgramGroup(g);
        return pg.programs.find((p) => this.updatablePrograms.indexOf(p) !== -1);
      });
    }
    return selectedGroups;
  }
  getSelectedGroupsLabel(): string {
    const selected = this.selectedGroups.length;
    const total = this.groupsList?.length;
    return this.selectedGroups.join(', ') + ` (${selected}/${total})`;
  }

  constructor(public yot: YotService, protected navigationService: NavigationService) {
    this.selectedAdapter = this.yot.getDefaultAdapter();
  }

  ngOnInit(): void {
    this.navigationService
      .appMenuChange.next('automation');
    const adapter = (this.selectedAdapter as HomegenieAdapter);
    adapter.apiCall('HomeAutomation.HomeGenie/Config/Packages.List')
      .subscribe({
        next: (res) => {
          this.packagesList = res.response;
          this.refresh();
        }
      });
    this.navigationService.toolbarTitle.emit('programs');

    this.yot.layoutService.contextualHelpLink = 'https://homegenie.it/server/programming/intro/';

    this.programUpdateListener = this.yot.onProgramUpdated.subscribe({
      next: (v) => {
        // TODO: should focus/scroll-to the updated/added program
        this.refresh();
      }
    });

    this.selectedGroups = this.yot.preferences.ui.automation?.selectedGroups || [];
    this._flagShowFiltered = this.yot.preferences.ui.automation?.showFiltered != null ? this.yot.preferences.ui.automation?.showFiltered : this._flagShowFiltered;
    this._flagShowDisabled = this.yot.preferences.ui.automation?.showDisabled != null ? this.yot.preferences.ui.automation?.showDisabled : this._flagShowDisabled;
  }
  ngOnDestroy() {
    this.yot.layoutService.contextualHelpLink = '';

    this.navigationService
      .appMenuChange.next('');

    this.programUpdateListener?.unsubscribe();
  }

  getProgramGroup(groupName: string): ProgramGroup {
    let pg = this.programGroups.find((g) => g.name === groupName);
    if (pg && pg.programs && ((Date.now() - pg.updateTime) < 10000)) {
      return pg;
    }
    if (!pg) {
      pg = { name: groupName } as ProgramGroup;
      this.programGroups.push(pg);
    }
    pg.updateTime = Date.now();
    pg.programs = this.programsList?.filter((prg) => prg.Group === groupName) || [];
    return pg;
  }
  getPrograms(groupName?: string): any[] {
    let pg = this.getProgramGroup(groupName);
    const programList = pg.programs;
    if (this._flagShowUpgradable) {
      return programList.filter((prg) => {
        return this.updatablePrograms.indexOf(prg) != -1;
      });
    }
    return programList;
  }
  getFilteredPrograms(groupName?: string): any[] {
    const showAll = groupName == null || groupName.trim() === '';
    let programList: Program[] = [];
    if (showAll) {
      programList = this.programsList;
    } else {
      let pg = this.getProgramGroup(groupName);
      programList = pg.programs;
    }
    programList = programList.filter((prg) => prg.IsEnabled || this._flagShowDisabled)
      .sort((a, b) => ((a.Address < b.Address) ? -1 : 0));
    if (this._flagShowUpgradable) {
      return programList.filter((prg) => {
        return this.updatablePrograms.indexOf(prg) != -1;
      });
    }
    return programList;
  }

  onItemActionRequest(action: AutomationItemAction) {
    switch (action.type) {
      case AutomationItemActionType.Edit:
        this.navigationService.router.navigate([
          PagesRoute.AutomationPage,
          this.selectedAdapter.id,
          action.item.Address
        ]).then(() => {
          // TODO: ..
        });
        break;
      case AutomationItemActionType.Enable:
        this.onEnableButtonClick(action.item);
        break;
      case AutomationItemActionType.Disable:
        this.onDisableButtonClick(action.item);
        break;
      case AutomationItemActionType.Run:
        this.onRunButtonClick(action.item);
        break;
      case AutomationItemActionType.Stop:
        this.onStopButtonClick(action.item);
        break;
      case AutomationItemActionType.Export:
        this.onExportButtonClick(action.item);
        break;
      case AutomationItemActionType.Clone:
        this.omProgramCloneClick(action.item);
        break;
      case AutomationItemActionType.Delete:
        this.onProgramDeleteClick(action.item);
        break;
      case AutomationItemActionType.Restore:
        this.onProgramRestoreClick(action.item);
        break;
      case AutomationItemActionType.Upgrade:
        this.onProgramUpgradeClick(action.item);
        break;
    }
  }

  onRunButtonClick(program: any) {
    this.navigationService.isLoading = true;
    (this.selectedAdapter as HomegenieAdapter)
      .apiCall(HomegenieApi.Automation.Programs.Run(program.Address))
      .subscribe(() => {
        this.navigationService.isLoading = false;
        this.refresh();
      }, err => this.operationError(err));
  }
  onStopButtonClick(program: any) {
    this.navigationService.isLoading = true;
    (this.selectedAdapter as HomegenieAdapter)
      .apiCall(HomegenieApi.Automation.Programs.Break(program.Address))
      .subscribe(() => {
        this.navigationService.isLoading = false;
        this.refresh();
      }, err => this.operationError(err));
  }
  onEnableButtonClick(program: any) {
    this.navigationService.isLoading = true;
    (this.selectedAdapter as HomegenieAdapter)
      .apiCall(HomegenieApi.Automation.Programs.Enable(program.Address))
      .subscribe((res) => {
        this.navigationService.isLoading = false;
        this.refresh();
      });
  }
  onDisableButtonClick(program: any) {
    this.navigationService.isLoading = true;
    (this.selectedAdapter as HomegenieAdapter)
      .apiCall(HomegenieApi.Automation.Programs.Disable(program.Address))
      .subscribe((res) => {
        this.navigationService.isLoading = false;
        this.refresh();
      });
  }
  onExportButtonClick(program: any) {
    this.navigationService.isLoading = true;
    // TODO: should ask for new name
    (this.selectedAdapter as HomegenieAdapter)
      .apiCall(HomegenieApi.Automation.Programs.Export(program.Address))
      .subscribe({
        next: (res) => {
          //console.log(res);
          this.navigationService.isLoading = false;
          this.refresh();
        },
        error: (err) => this.operationError(err)
      });
  }

  onProgramImportClick(e) {
    const dialogRef = this.yot.dialog.open(FileSelectDialogComponent, {
      width: '340px',
      disableClose: false,
      data: {
        accept: '.hgx, text/xml, application/xml'
      }
    });
    dialogRef.afterClosed().subscribe((filesList) => {
      if (filesList) {
        this.uploadProgramFile(filesList[0]);
      }
    });
  }
  omProgramCloneClick(program: any) {
    const dialogRef = this.yot.dialog.open(TextInputDialogComponent, {
      disableClose: false,
      data: {
        title: 'clone_program',
        label: 'name',
        placeholder: 'enter_name',
        value: program.Name
      } as TextInputDialogConfig
    });
    dialogRef.afterClosed().subscribe((programName) => {
      if (programName) {
        this.navigationService.isLoading = true;
// TODO: implement 'new name' parameter for 'programName'
        (this.selectedAdapter as HomegenieAdapter)
          .apiCall(HomegenieApi.Automation.Programs.Clone(program.Address, programName))
          .subscribe({
            next: (res) => {
              this.navigationService.isLoading = false;
              this.refresh();
            },
            error: (err) => {
              this.operationError(err);
            }
          });
      }
    });
  }
  onProgramAddClick(programType: 'csharp' | 'javascript' | 'python' | 'visual' ) {
    // TODO: ...
    const adapter = this.selectedAdapter;
    const program = new Program();
    program.Type = programType;
    const dialogRef = this.yot.dialog.open(ProgramAddDialogComponent, {
      maxWidth: '480px',
      width: '100%',
      data: {
        program,
        adapter
      }
    });
    dialogRef.afterClosed().subscribe((program) => {
      if (program) {
        this.navigationService.isLoading = true;
        (this.selectedAdapter as HomegenieAdapter)
          .apiCall(HomegenieApi.Automation.Programs.Add, program)
          .subscribe((res) => {
            const newProgramId = +res.response.ResponseValue;
            // delay opening of program editor page, otherwise the preview module won't show
            setTimeout(() => {
              this.navigationService.router.navigate([
                PagesRoute.AutomationPage,
                this.selectedAdapter.id,
                newProgramId
              ]).then(() => {
                this.navigationService.isLoading = false;
              });
            }, 1000);
          }, err => this.operationError(err));
      }
    });
  }
  onProgramDeleteClick(program: any) {
    this.yot.translate.get(['delete_program', 'action_cannot_be_undone'])
      .subscribe((res) => {
        const dialogRef = this.yot.dialog.open(ActionConfirmDialogComponent, {
          data: {
            title: res['delete_program'],
            message: res['action_cannot_be_undone']
          } as ActionConfirmDialogConfig
        });
        dialogRef.afterClosed().subscribe((confirm) => {
          if (confirm) {
            this.navigationService.isLoading = true;
            (this.selectedAdapter as HomegenieAdapter)
              .apiCall(HomegenieApi.Automation.Programs.Delete(program.Address))
              .subscribe((res) => {
                const module = (this.selectedAdapter as HomegenieAdapter)
                  .getModuleByRef(program as any)
                this.yot.removeModule(module);
                this.navigationService.isLoading = false;
                this.refresh();
              }, err => this.operationError(err));
          }
        });
      });
  }

  onProgramRestoreClick(program: any) {
    this.yot.translate.get(['restore_program', 'action_cannot_be_undone'])
      .subscribe((res) => {
        const dialogRef = this.yot.dialog.open(ActionConfirmDialogComponent, {
          data: {
            title: res['restore_program'],
            message: res['action_cannot_be_undone']
          } as ActionConfirmDialogConfig
        });
        dialogRef.afterClosed().subscribe((confirm) => {
          if (confirm) {
            this.installProgram(program);
          }
        });
      });
  }

  onProgramUpgradeClick(program: any) {
    this.yot.translate.get(['upgrade_program', 'latest_version_install'])
      .subscribe((res) => {
        const dialogRef = this.yot.dialog.open(ActionConfirmDialogComponent, {
          data: {
            title: res['upgrade_program'],
            message: res['latest_version_install'],
          } as ActionConfirmDialogConfig
        });
        dialogRef.afterClosed().subscribe((confirm) => {
          if (confirm) {
            this.installProgram(program);
          }
        });
      });
  }

  protected onNgModelChange($event: any) {
    if (this.selectedGroups.length > 0) {
      this._flagShowFiltered = true;
    }
    // save prefs
    this.savePreferences();
  }

  private savePreferences() {
    this.yot.preferences.ui.automation = this.yot.preferences.ui.automation || {
      selectedGroups: [],
      showFiltered: true,
      showDisabled: true
    };
    this.yot.preferences.ui.automation.selectedGroups = this.selectedGroups;
    this.yot.preferences.ui.automation.showDisabled = this._flagShowDisabled;
    this.yot.preferences.ui.automation.showFiltered = this._flagShowFiltered;
    this.yot.savePreferences();
  }

  private installProgram(program: Program) {
    const pkg = program.PackageInfo;
    this.navigationService.isLoading = true;
    (this.selectedAdapter as HomegenieAdapter)
      .apiCall(HomegenieApi.Config.Packages.Install(pkg.repository, pkg.packageId), [pkg.id])
      .subscribe((res) => {
        this.navigationService.isLoading = false;
        this.refresh();
      }, (err) => {
        // TODO: report error
        this.navigationService.isLoading = false;
      });
  }

  protected refresh() {
    this.navigationService.isLoading = true;
    // load programs list
    this.selectedAdapter.system(SystemApi.Automation.Programs.List)
      .subscribe((programs) => {

        const adapter = this.selectedAdapter as HomegenieAdapter;
        if (programs == null) {
          this.navigationService.isLoading = false;
          //subject.error(new Error('Could not read programs list.'));
          return;
        }
        programs.filter((p) => {
          let hasOptions = false;
          let module = adapter.getModule({Domain: p.Domain, Address: `${p.Address}`});
          if (module) {
            hasOptions = module.Properties
              .filter((p: ModuleParameter) => p.Name.startsWith('ConfigureOptions.'))
              .length > 0;
          }
          const isConfigurable = p.IsRunning && hasOptions;
          // translate Name and Description
          const titleKey = `${adapter.translationPrefix}.$options.${p.Address}.Title`;
          this.yot.translate.get(titleKey).subscribe((tr) => {
            if (tr !== titleKey) {
              p.Name = tr;
            }
          });
          const descriptionKey = `${adapter.translationPrefix}.$options.${p.Address}.Description`;
          this.yot.translate.get(descriptionKey).subscribe((tr) => {
            if (tr !== descriptionKey) {
              p.Description = tr;
            }
          });
/*          if (isConfigurable) {
            // translate Name and Description
            const titleKey = `${adapter.translationPrefix}.$options.${p.Address}.Title`;
            this.yot.translate.get(titleKey).subscribe((tr) => {
              if (tr !== titleKey) {
                p.Name = tr;
              }
            });
            const descriptionKey = `${adapter.translationPrefix}.$options.${p.Address}.Description`;
            this.yot.translate.get(descriptionKey).subscribe((tr) => {
              if (tr !== descriptionKey) {
                p.Description = tr;
              }
            });
          } else */ if (module) {
            adapter.getModuleDisplayName(module);
            if (module.Name?.length > 0) p.Name = module.Name;
            if (module.Description?.length > 0) p.Description = module.Description;
          }
          return isConfigurable ? p : undefined;
        });

        this.updatablePrograms = [];

        this.programsList = programs.sort((p1, p2) => {
          return (p1.Group < p2.Group ? -1 : p1.Group > p2.Group ? 1 : 0)
            || (p1.Name < p2.Name ? -1 : p1.Name > p2.Name ? 1 : 0);
        });
        this.groupsList = [];
        this.programsList.forEach((p) => {

          // version update check
          const pi = p.PackageInfo;
          const repositoryPackage = this.packagesList.find(p => p.repository === pi.repository && p.id == pi.packageId);
          if (repositoryPackage) {
            const repositoryProgram = repositoryPackage.programs.find(prg => prg.id === pi.id)
            if (repositoryProgram) {
              const versionStatus = this.yot.util.versionCompare(repositoryProgram.version, pi.version);
              if (versionStatus > 0) {
                this.updatablePrograms.push(p);
              }
            }
          }

          if (!this.groupsList.includes(p.Group)) {
            this.groupsList.push(p.Group);
          }
          /*
          if (this.updatablePrograms.length > 0) {
            this.yot.translate.get(['updates_available', 'update_system_programs_message'], {programs_count: this.updatablePrograms.length}).subscribe((txt) => {
              this.yot.notify(txt['updates_available'], txt['update_system_programs_message']);
            });
          }
          */
        });

        adapter.updateProgramsBadge(this.programsList, this.packagesList);

        // The last successful upgrade must not leave the page in an empty filter.
        if (this.updatablePrograms.length === 0) {
          this._flagShowUpgradable = false;
        }

        // invalidate cache
        this.programGroups.map((g) => g.updateTime = 0);

        this.navigationService.isLoading = false;
      }, (err) => this.operationError(err));
  }

  private uploadProgramFile(file: File) {
    this.navigationService.isLoading = true;
    let formData:FormData = new FormData();
    formData.append('uploadFile', file, file.name);
    const  options = {};
    this.yot.http
      .post(`/api/${HomegenieApi.Automation.Programs.Import}`, formData, options)
      .subscribe({
        next: (res: any) => {
          const programId = +res.ResponseValue;
          // TODO: ... maybe scroll to the newly added element
          const adapter = (this.selectedAdapter as HomegenieAdapter);
          adapter.loadPrograms().subscribe((programs) => {

            this.navigationService.isLoading = false;
            this.refresh();

            const prg = programs.find((p)=> p.Address === programId);
            this.yot.translate.get(['import_program', 'imported_program_name_group'], {
              name: prg.Name,
              address: prg.Address,
              group: prg.Group,
            }).subscribe((tr) => {
              this.yot.notify(tr['import_program'], tr['imported_program_name_group']);
            });

          });
        },
        error: (err) => this.operationError(err)
      });
  }

  private operationError(err) {
    this.yot.translate.get('error_occurred')
      .subscribe((title) => {
        this.yot.notify(title, err.message);
      });
    this.navigationService.isLoading = false;
  }

  protected getDeactivatedProgramsCount(groupName: string) {
    return (this.getPrograms(groupName).length - this.getFilteredPrograms(groupName).length);
  }
}
