import { Directive, Input } from '@angular/core';
import { Validator, NG_VALIDATORS, AbstractControl, ValidationErrors, Validators, ValidatorFn } from '@angular/forms';

@Directive({
  selector: '[appI18nPattern]',
  providers: [{
    provide: NG_VALIDATORS,
    useExisting: I18nPatternValidatorDirective,
    multi: true
  }]
})
export class I18nPatternValidatorDirective implements Validator {

  private validator: ValidatorFn;

  @Input()
  set appI18nPattern(value: string) {
    this.createValidator(value);
  }

  private createValidator(pattern: string): void {
    if (!pattern) {
      this.validator = Validators.nullValidator;
      return;
    }

    try {

      const regex = new RegExp(pattern, 'u');
      this.validator = Validators.pattern(regex);

    } catch (e) {
      console.error("Pattern non valido in appI18nPattern", e);
      this.validator = Validators.nullValidator;
    }
  }

  validate(control: AbstractControl): ValidationErrors | null {
    if (!this.validator) {
      return null;
    }
    return this.validator(control);
  }
}
