import {Component, Input, OnDestroy, OnInit} from '@angular/core';
import {concat, of, Subject, Subscription, timer} from 'rxjs';
import {debounceTime, last, map, switchMap, takeUntil} from 'rxjs/operators';
import {ApiResponse, HomegenieAdapter} from '../homegenie-adapter';
import {HomegenieApi} from '../homegenie-api';
import {TranslateService} from '@ngx-translate/core';
import {ClientConfigService} from '../../../services/client-config.service';

@Component({selector: 'app-audio-setup-form', templateUrl: './audio-setup-form.component.html', styleUrls: ['./audio-setup-form.component.scss']})
export class AudioSetupFormComponent implements OnInit, OnDestroy {
  @Input() adapter: HomegenieAdapter;
  @Input() domain: string;
  @Input() showToggle = false;
  available = false;
  enabled = false;
  connected = false;
  busy = false;
  toggling = false;
  controlBusy = false;
  loading = true;
  controlsAvailable = false;
  error = '';
  engineError = '';
  saved = false;
  pending = false;
  values: {[name: string]: string} = {};
  knownModels: string[] = [];
  languages: {code: string, label: string}[] = [{code: 'en', label: 'English'}];
  private readonly whisperLanguages = new Set(('en zh de es ru ko fr ja pt tr pl ca nl ar sv it id hi fi vi he uk el ms cs ro da hu ta no th ur hr bg lt la mi ml cy sk te fa lv bn sr az sl kn et mk br eu is hy ne mn bs kk sq sw gl mr pa si km sn yo so af oc ka be tg sd gu am yi lo uz fo ht ps tk nn mt sa lb my bo tl mg as tt haw ln ha ba jw su').split(' '));
  get englishOnly(): boolean { return this.recognizer && /\.en\.bin$/i.test(this.model || ''); }
  get recognitionLanguages(): {code: string, label: string}[] {
    return this.englishOnly ? this.languages.filter(language => language.code === 'en') : this.languages;
  }
  modelFilter = "";
  private original: {[name: string]: string} = {};
  private modelStatus: {[name: string]: any} = {};
  private readonly edits = new Subject<void>();
  private readonly destroyed = new Subject<void>();
  private readonly subscriptions = new Subscription();
  private polling = false;
  get recognizer(): boolean { return this.domain === 'Audio.VoiceRecognizer'; }
  get model(): string { return this.recognizer ? this.values.ModelName : this.values.Voice; }
  get filteredModels(): string[] { return this.knownModels.filter(name => name.toLowerCase().includes(this.modelFilter.toLowerCase())); }
  get validOptions(): boolean { return this.valid(); }
  get optionNames(): string[] { return this.recognizer ? ['ModelName', 'Language', 'Threads', 'Acceleration'] : ['Voice', 'Speed', 'Threads']; }
  get downloadState(): string { return String(this.serviceValue('Download.State') || ''); }
  get downloading(): boolean { return this.enabled && ['Downloading', 'Extracting', 'Stopping'].includes(this.downloadState); }
  get downloadProgress(): number { return Number(this.serviceValue('Download.Progress') ?? -1); }
  get downloadModel(): string { return String(this.serviceValue('Download.Model') || ''); }
  get downloadError(): string { return this.enabled && this.downloadState === 'Error' ? String(this.serviceValue('Download.Error') || '') : ''; }
  get installed(): boolean { return this.modelStatus['Model.Installed'] === true; }
  constructor(private translate: TranslateService, private clientConfig: ClientConfigService) {}
  get modelFile(): string {
    const path = String(this.modelStatus['Model.File'] || '').replace(/\\/g, '/');
    const start = path.search(/(?:^|\/)data\//i);
    return start < 0 ? path : path.slice(start + (path[start] === '/' ? 1 : 0));
  }
  get resumable(): boolean { return this.partialBytes > 0 || this.downloadState === 'Paused'; }
  get fileStatusTooltip(): string {
    const fileKey = !this.controlsAvailable ? 'audio_file_unknown' : this.installed ? 'audio_file_installed' : this.partialBytes > 0 ? 'audio_file_partial' : 'audio_file_missing';
    const stateKey = this.loading ? 'audio_loading' : this.busy ? 'audio_working' : this.statusKey;
    return [this.translate.instant('HOMEGENIE.' + fileKey), this.translate.instant('HOMEGENIE.' + stateKey),
      this.error || this.engineError || this.downloadError].filter(Boolean).join(' - ');
  }
  get modelBytes(): number { return Number(this.modelStatus['Model.Bytes'] || 0); }
  get partialBytes(): number { return Number(this.modelStatus['Model.PartialBytes'] || 0); }
  get statusKey(): string { return this.connected ? 'audio_ready' : this.engineError ? 'audio_engine_error' : 'audio_not_ready'; }
  number(value: string): number { return Number(value); }
  bytes(value: number): string { return (value / 1048576).toFixed(1) + ' MiB'; }
  private serviceValue(name: string): any {
    const module = this.adapter.getModule({Domain: this.domain, Address: 'service'});
    return this.modelStatus[name] ?? module?.Properties?.find(p => p.Name === name)?.Value;
  }

  ngOnInit(): void {
    if (this.recognizer) this.subscriptions.add(this.clientConfig.getLanguagesList().pipe(takeUntil(this.destroyed)).subscribe({
      next: list => {
        const languages = new Map<string, string>();
        Object.entries(list).forEach(([key, language]: [string, any]) => {
          const code = String(language.code || key).toLowerCase().split(/[-_]/)[0];
          if (this.whisperLanguages.has(code) && !languages.has(code)) languages.set(code, language.nativeName || language.name || code);
        });
        this.languages = Array.from(languages, ([code, label]) => ({code, label})).sort((a, b) => a.label.localeCompare(b.label));
      }, error: () => {}
    }));
    this.subscriptions.add(this.edits.pipe(debounceTime(600), takeUntil(this.destroyed)).subscribe(() => this.save()));
    this.values = this.recognizer ? {ModelName:'ggml-base.bin', Language:'auto', Threads:'6', Acceleration:'cpu'} : {Voice:'it_IT-paola-medium', Speed:'1.0', Threads:'2'};
    this.knownModels = this.recognizer ? ['ggml-tiny.bin','ggml-tiny.en.bin','ggml-base.bin','ggml-base.en.bin','ggml-small.bin','ggml-small.en.bin','ggml-medium.bin','ggml-medium.en.bin'] : ['it_IT-paola-medium','it_IT-riccardo-x_low','en_US-amy-low','en_US-lessac-medium'];
    this.subscriptions.add(this.adapter.apiCall(HomegenieApi.Config.Interfaces.List).subscribe({
      next: res => {
        const config = res.response.find((i: any) => i.Domain === this.domain);
        this.available = !!config;
        this.enabled = !this.showToggle || config?.IsEnabled === true || config?.IsEnabled === 'true';
        if (config) this.optionNames.forEach(name => {
          const option = config.Options?.find((o: any) => o.Name.toLowerCase() === name.toLowerCase());
          if (option?.Value?.trim()) this.values[name] = option.Value;
        });
        this.original = {...this.values}; this.loading = false;
        if (this.enabled) this.loadModels();
        this.refreshStatus();
      }, error: err => { this.loading = false; this.showError(err); }
    }));
    this.subscriptions.add(timer(1000, 1000).subscribe(() => { if (this.enabled && !this.loading) this.refreshStatus(); }));
  }
  ngOnDestroy(): void { this.destroyed.next(); this.destroyed.complete(); this.subscriptions.unsubscribe(); }
  edited(): void { this.saved = false; this.pending = true; this.edits.next(); }
  modelEdited(value: string): void { this.modelFilter = value; this.values[this.recognizer ? 'ModelName' : 'Voice'] = value; this.saved = false; }
  modelCommitted(): void { if (this.model !== this.original[this.recognizer ? 'ModelName' : 'Voice']) this.edited(); }
  modelSelected(value: string): void { this.modelEdited(value); this.modelFilter = ""; this.pending = true; this.save(); }
  sliderEdited(name: string, value: number): void { this.values[name] = String(value); this.edited(); }

  save(): void {
    this.pending = false;
    if (this.englishOnly) this.values.Language = 'en';
    if (!this.enabled || this.busy || !this.available || !this.valid()) return;
    const names = this.optionNames.filter(name => String(this.values[name]).trim() !== this.original[name]);
    if (!names.length) return;
    const reload = (this.recognizer ? ['ModelName','Acceleration'] : ['Voice','Threads']).some(name => names.includes(name));
    this.busy = true; this.error = ''; this.saved = false;
    this.subscriptions.add((reload && this.controlsAvailable ? this.serviceCall('Download.Stop') : of(undefined)).pipe(
      switchMap(() => this.saveOptions()),
      switchMap(() => reload && (this.downloadState !== 'Paused' || names.includes(this.recognizer ? 'ModelName' : 'Voice')) ? this.serviceCall('Model.Load') : of(undefined)), takeUntil(this.destroyed)
    ).subscribe({next: () => { this.busy = false; this.saved = true; this.modelStatus = {}; this.refreshStatus(); },
      error: err => { this.busy = false; this.showError(err); }}));
  }

  setEnabled(enable: boolean): void {
    if (this.toggling || !this.available) return;
    const previous = this.enabled; this.enabled = enable; this.pending = false; this.toggling = true; this.error = '';
    // Enable immediately, using the same API as the other interfaces.
    this.subscriptions.add(this.adapter.apiCall(enable ? HomegenieApi.Config.Interfaces.Enable(this.domain) : HomegenieApi.Config.Interfaces.Disable(this.domain), null, {}).pipe(
      map(res => this.checkResponse(res)), takeUntil(this.destroyed)
    ).subscribe({next: () => { this.toggling = false; if (enable) { this.loadModels(); this.refreshStatus(); } },
      error: err => { this.toggling = false; this.enabled = previous; this.showError(err); }}));
  }
  download(action: 'Stop'|'Resume'|'Restart'): void {
    if (!this.enabled || this.controlBusy || !this.controlsAvailable) return;
    this.controlBusy = true; this.error = '';
    this.subscriptions.add(this.serviceCall('Download.' + action).subscribe({
      next: () => { this.controlBusy = false; this.refreshStatus(); },
      error: err => { this.controlBusy = false; this.showError(err); }
    }));
  }
  private serviceCall(command: string) {
    return this.adapter.apiCall(`${this.domain}/service/${command}`, null, {}).pipe(map(res => { this.checkResponse(res); return res; }), takeUntil(this.destroyed));
  }
  private loadModels(): void {
    this.subscriptions.add(this.serviceCall('Models.List').subscribe({next: res => { if (Array.isArray(res.response)) this.knownModels = res.response; }, error: () => {}}));
  }
  private refreshStatus(): void {
    if (!this.available || !this.enabled || this.polling) return;
    this.polling = true;
    this.subscriptions.add(this.serviceCall('Model.Status').subscribe({
      next: res => {
        this.polling = false; this.controlsAvailable = true; this.modelStatus = res.response;
        this.connected = res.response['Model.Ready'] === true;
        this.engineError = this.connected ? '' : String(this.adapter.getModule({Domain:this.domain, Address:'0'})?.Properties?.find(p => p.Name === 'Voice.Error')?.Value || '');
      }, error: () => {
        this.polling = false; this.controlsAvailable = false;
        this.subscriptions.add(this.adapter.apiCall(HomegenieApi.Config.Interfaces.Status).subscribe({next: res => {
          const status = res.response.find((i: any) => i.Domain === this.domain);
          this.connected = status?.IsConnected === true || status?.IsConnected === 'True';
        }, error: err => this.showError(err)}));
      }
    }));
  }
  private valid(): boolean {
    return /^[A-Za-z0-9][A-Za-z0-9_.-]*$/.test(this.model) && !this.model.includes('..')
      && Number.isInteger(Number(this.values.Threads)) && Number(this.values.Threads) > 0
      && (this.recognizer ? /^(auto|[a-z]{2,3})$/.test(this.values.Language) : Number.isFinite(Number(this.values.Speed)) && Number(this.values.Speed) > 0);
  }
  private saveOptions() {
    const names = this.optionNames.filter(name => String(this.values[name]).trim() !== this.original[name]);
    if (!names.length) return of(undefined);
    return concat(...names.map(name => {
      const value = String(this.values[name]).trim();
      return this.adapter.apiCall(`MIGService.Interfaces/${this.domain}/Options.Set/${name}/${encodeURIComponent(value)}`, null, {}).pipe(map(res => {
        this.checkResponse(res); this.values[name] = value; this.original[name] = value;
      }));
    })).pipe(last(), takeUntil(this.destroyed));
  }
  private checkResponse(res: ApiResponse): void {
    if (res.code !== 200 || (String(res.response?.Status).toLowerCase() === 'error' || res.response?.Status === 1)) throw new Error(res.response?.Message || res.response?.ResponseValue || 'Request failed');
  }
  private showError(err: any): void { this.error = err?.error?.Message || err?.message || String(err); }
}
