import {Component, OnDestroy, OnInit} from '@angular/core';
import {WidgetBaseComponent} from "../widget-base.component";
import {HomegenieAdapter} from "../../adapters/home-genie/homegenie-adapter";
import {DomainNames, HomegenieApi, ModuleTypes} from "../../adapters/home-genie/homegenie-api";
import {Module as YotModule} from 'src/app/services/yot/module';
import {Subscription} from "rxjs";
import {
  AddWidgetDialogComponent,
  AddWidgetDialogData
} from "../../components-extras/dialogs/add-widget-dialog/add-widget-dialog.component";

const MQTT_NETWORK_SYSTEM_PROGRAM_ID = 77;

@Component({
  selector: 'app-homegenie-mini',
  templateUrl: './homegenie-mini.component.html',
  styleUrls: ['./homegenie-mini.component.scss']
})
export class HomegenieMiniComponent extends WidgetBaseComponent implements OnInit, OnDestroy {

  modelName: string;
  modelVersion: string;
  modelDescription: string;

  //protected subModules: YotModule[] = [];
  protected programModule: YotModule = undefined;
  private adapter: HomegenieAdapter;
  private moduleEvents: Subscription;

  protected loadingCount = 0;
  protected get isLoading(): boolean {
    return this.loadingCount > 0;
  }
  protected set isLoading(isLoading: boolean) {
    isLoading ? this.loadingCount++ : this.loadingCount--;
  }

  get lastUpdateTimestamp(): number {
    let lastUpdateTimestamp = 0;
    const f = this.module.field('UPnP.FriendlyName');
    if (f != null) {
      lastUpdateTimestamp = new Date(f.timestamp).getTime();
    }
    return lastUpdateTimestamp;
  }
  get subModules(): YotModule[] {
    if (this.programModule == null || this.isLoading) return null;
    const pm = this.adapter.getModule(this.programModule.id);
    if ((pm == null && this.programModule.field('Program.Status')?.value !== 'Stopping')
    || this.programModule.field('Program.Status')?.value == 'Removed') {
      // Connection program was removed
      this.programModule = undefined;
      return null;
    }
    return this.adapter.modules
      .filter((m) => m !== pm && m.Properties.find((p) => p.Name == 'VirtualModule.ParentId' && p.Value == pm?.Address))
      .map((m) => this.yot.getModuleByRef({
        moduleId: this.adapter.getModuleId(m),
        adapterId: this.adapter.id
      }));
  }
  get freeMemory() {
    return +this.getMainModule()?.field('System.BytesFree')?.value;
  }
  get systemInfo() {
    const info = this.getMainModule()?.field('System.Info')?.value;
    return info ? JSON.parse(info) : null;
  }
  get firmwareInfo() {
    return this.systemInfo
      ? `Firmware: ${this.systemInfo?.Runtime}`
      : undefined;
  }
  get socName() {
    if (this.systemInfo?.Platform?.startsWith('espressif32')) {
      return 'ESP32';
    }
    return 'ESP8266';
  }

  ngOnInit(): void {
    super.ngOnInit();
    this.adapter = (this.module.getAdapter() as HomegenieAdapter);
    this.modelName = this.module.field('UPnP.ModelName')?.value;
    this.modelVersion = this.module.field('UPnP.ModelNumber')?.value || this.module.field('UPnP.Version')?.value;
    this.modelDescription = this.module.field('UPnP.ModelDescription')?.value;
    this.resetProgramModule();
  }
  ngOnDestroy(): void {
    this.moduleEvents?.unsubscribe();
  }


  showModulesDialog() {
    const dialogRef = this.dialog.open(AddWidgetDialogComponent, {
      panelClass: 'dialog-no-padding',
      width: '100%',
      minWidth: '280px',
      maxWidth: '576px',
      minHeight: '280px',
      data: {
        dashboard: this.yot.dashboardService.getCurrentDashboard(),
        modulesList: this.subModules
      }
    });
    dialogRef.afterClosed().subscribe((res: AddWidgetDialogData | undefined) => {
      if (res?.modules && res?.dashboard) {
        res.modules.forEach((m) => {
          const options = m.getWidgetData();
          this.yot.dashboardService
            .addDashboardWidget(res.dashboard.name, options?.type, m, options);
          this.yot.saveConfiguration().subscribe((config) => {
            this.yot.translate.get(['add_widget', 'widget_added_message'], {count: res.modules.length, name: res.dashboard.name}).subscribe((txt) => {
              this.yot.notify(txt['add_widget'], txt['widget_added_message'], {
                duration: 2000,
                verticalPosition: 'bottom',
                data: {action: undefined}
              });
            });
          });
        });
      }
    });
  }


  resetProgramModule() {
    const modules = this.adapter.modules;
    for (let i = 0; i < modules.length; i++) {
      const m = modules[i];
      if (m.DeviceType == ModuleTypes.Program) {
        const addr = m.Properties.find(p => p.Name == 'ConfigureOptions.ServerAddress');
        if (addr?.Value == this.module.field('UPnP.PresentationURL')?.value) {
          this.programModule = this.yot.getModuleByRef({
            moduleId: this.adapter.getModuleId(m),
            adapterId: this.adapter.id
          });
          break;
        }
      }
    }
  }

  isMqttLinkEnabled(): boolean {
    return this.programModule?.field('Program.Status')?.value === 'Running'
        || this.programModule?.field('Program.Status')?.value === 'Background'
        || this.programModule?.field('Program.Status')?.value === 'Idle';
  }
  getMqttStatus() {
    return this.programModule?.field('MQTT.Status')?.value;
  }
  getMainModule() {
    return this.subModules?.find(m => m.id.endsWith('HomeAutomation.HomeGenie:mini'));
  }

  disableLink() {
    if (this.programModule != null) {
      const pid = +this.programModule.id.split(':').reverse()[0];
      if (pid > 0) {
        this.isLoading = true;
        this.adapter
          .apiCall(HomegenieApi.Automation.Programs.Delete(pid))
          .subscribe({
            next: (res) => {
              this.yot.removeModule(this.programModule);
              this.isLoading = false;
            },
            error: (err) => {
              this.yot.translate.get('mqtt_connection_delete_error').subscribe((title) => {
                this.yot.notify(title, err.message);
              });
              this.isLoading = false;
            }
          });
      }
    }
  }

  private waitProgramRunning(id, callback) {
    this.moduleEvents?.unsubscribe();
    this.moduleEvents = this.adapter.onModuleEvent.subscribe(e => {
      const m = e.module;
      if (`${e.event?.Domain}/${e.event?.Source}` == id && (e.event?.Value == 'Running' || e.event?.Value.startsWith('MODULE_ADDED '))) {
        this.moduleEvents.unsubscribe();
        callback(m);
      }
    });
  }

  enableLink() {
    this.programModule = null; // !== undefined to triggers button disabled
    this.isLoading = true;
    const adapter = (this.module.getAdapter() as HomegenieAdapter);
    adapter
      .apiCall(HomegenieApi.Automation.Programs.Clone(MQTT_NETWORK_SYSTEM_PROGRAM_ID, `${this.module.name}`, 'HomeGenie Mini device link.'))
      .subscribe({
        next: (res) => {
          const pid = res?.response?.ResponseValue;

          // MQTT program configuration
          const config = {
              'ConfigureOptions.ServerAddress': this.module.field('UPnP.PresentationURL')?.value,
              'ConfigureOptions.ServerPort': '8000',
              'ConfigureOptions.WebSockets': 'On',
              'ConfigureOptions.ImportExternal': 'On'
          };

          adapter.apiCall(HomegenieApi.Automation.Programs.Enable(+pid))
            .subscribe({
              next: (res) => {
                const mqttProgramId = DomainNames.HomeAutomation_HomeGenie_Automation + '/' + pid;
                if (mqttProgramId != null) {
                  this.waitProgramRunning(mqttProgramId, (m) => {

                    adapter.apiCall(
                      HomegenieApi.Config.Modules.ParameterSet(mqttProgramId),
                      config
                    ).subscribe({
                      next: (res) => {
                        // TODO: ..........
                        this.waitProgramRunning(mqttProgramId, (m) => {
                          this.moduleEvents = null;
                          this.programModule = m;
                          this.isLoading = false;
                        });
                      },
                      error: (err) => {
                        this.yot.translate.get('mqtt_configure_error').subscribe((title) => {
                          this.yot.notify(title, err.message);
                        });
                        this.isLoading = false;
                      }
                    });

                  });
                }
              },
              error: (err) => {
                this.yot.translate.get('mqtt_configure_error').subscribe((title) => {
                  this.yot.notify(title, err.message);
                });
                this.isLoading = false;
              }
            });
        },
        error: (err) => {
          this.yot.translate.get('mqtt_connection_create_error').subscribe((title) => {
            this.yot.notify(title, err.message);
          });
          this.isLoading = false;
        }
      });
  }
}
