import {EventEmitter, Injectable, OnDestroy} from '@angular/core';
import {Dashboard, DashboardWidget} from "./dashboard";
import {Subject} from "rxjs";
import {WidgetType} from "../../api/widgets/widget-type";
import {Module, ModuleType} from "../yot/module";
import {WidgetData} from "../../widgets/widget-data";
import {Color} from "@iplab/ngx-color-picker";
import {HomegenieAdapter} from "../../adapters/home-genie/homegenie-adapter";

export enum DashboardLayoutEventValue {
  ArrangeStart= 'arrange-start',
  ArrangeDone = 'arrange-done',
  LayoutStart = 'layout-start',
  LayoutDone = 'layout-done',
  LayoutRefresh = 'layout-refresh'
}

@Injectable({
  providedIn: 'root',
})
export class DashboardService implements OnDestroy {
  public layoutEvents = new EventEmitter<DashboardLayoutEventValue>();
  public isDragSortEnabled = true;

  dashboards: Array<Dashboard> = [];
  currentDashboardIndex = -1;

  onDashboardAdded = new Subject<Dashboard>();
  onDashboardRenamed = new Subject<Dashboard>();
  onDashboardRemoved = new Subject<Dashboard>();
  onDashboardWidgetAdded = new Subject<{dashboard: Dashboard, widget: DashboardWidget}>();
  onDashboardWidgetRemoved = new Subject<{dashboard: Dashboard, widget: DashboardWidget}>();

  onBottomSheetRequested = new Subject<string>();

  private defaultTheme = {
    dark: {
      wallpaper: '',
      cardColor: '#424242',
      cardOpacity: 85,
      cardBlur: 50
    },
    light: {
      wallpaper: '',
      cardColor: '#f6f6f6',
      cardOpacity: 85,
      cardBlur: 50
    }
  };

  dockedPanelWidth = '30vw';

  constructor() { }

  ngOnDestroy() {
    this.onDashboardAdded.complete();
    this.onDashboardRenamed.complete();
    this.onDashboardRemoved.complete();
    this.onDashboardWidgetAdded.complete();
    this.onDashboardWidgetRemoved.complete();
  }

  getCurrentDashboard(): Dashboard {
    return this.currentDashboardIndex >= 0 ? this.dashboards[this.currentDashboardIndex] : undefined;
  }
  setCurrentDashboard(dashboard: Dashboard | number) {
    if (dashboard == null) return;

    if (typeof dashboard !== 'number') {
      this.currentDashboardIndex = this.dashboards.indexOf(dashboard);
    } else {
      this.currentDashboardIndex = dashboard;
    }

    // Apply dashboard theme
    const theme = this.getDashboardTheme(dashboard as Dashboard);
    if (theme) {
      // Cards color / opacity
      this.setDashboardCardColor(theme.cardColor, theme.cardOpacity, theme.cardBlur);
      // Wallpaper
      const dashboardCss = this.getCSSRule(".dashboard-page");
      const wallpaper = theme.wallpaper;
      if (wallpaper) {
        dashboardCss.style.backgroundImage = `url('${wallpaper}')`;
      } else {
        dashboardCss.style.backgroundImage = 'none';
      }
//      dashboardCss.style.backgroundSize = 'contain';
    }
  }

  getDashboard(name: string): Dashboard {
    return this.dashboards.find((d) => d.name === name);
  }
  addDashboard(name: string, description?: string, config?: any): Dashboard {
    let d = this.getDashboard(name);
    if (d != null) return d;
    d = new Dashboard();
    d.name = name;
    d.description = description;
    d.config = {
      ...{
        theme: {
          dark: {cardBlur: 50, cardColor: "#050052", cardOpacity: 80, wallpaper: "assets/images/wallpapers/dark/01.jpg" },
          light: {cardBlur: 50, cardColor: "#f6f6f6", cardOpacity: 80, wallpaper: "assets/images/wallpapers/light/01.jpg" }
        }
      },
      ...config
    };
    this.dashboards.push(d);
    this.onDashboardAdded.next(d);
    return d;
  }
  renameDashboard(name: string, newName: string) {
    const dashboard = this.getDashboard(name);
    if (dashboard) {
      dashboard.name = newName;
      this.onDashboardRenamed.next(dashboard);
    }
  }
  removeDashboard(name: string) {
    const dashboard = this.getDashboard(name);
    if (dashboard) {
      this.dashboards.splice(this.dashboards.indexOf(dashboard), 1);
      this.onDashboardRemoved.next(dashboard);
    }
  }
  removeAllDashboards() {
    while (this.dashboards.length > 0) {
      const dashboard = this.dashboards.splice(0, 1);
      this.onDashboardRemoved.next(dashboard[0]);
    }
  }

  addDashboardWidget(dashboardName: string, widgetType: WidgetType, module?: Module, data?: WidgetData, config?: any): DashboardWidget {
    let widget: DashboardWidget;
    const dashboard = this.getDashboard(dashboardName);
    if (dashboard) {
      widget = dashboard.addWidget(widgetType, module, data, config)
      this.onDashboardWidgetAdded.next({ dashboard, widget });
    }
    return widget;
  }
  removeDashboardWidget(dashboardName: string, widget: DashboardWidget) {
    const dashboard = this.getDashboard(dashboardName);
    if (dashboard) {
      dashboard.removeWidget(widget);
      this.onDashboardWidgetRemoved.next({ dashboard, widget });
    }
  }

  getDefaultTheme() {
    const themeId = this.getUiTheme();
    return this.defaultTheme[themeId];
  }

  getDashboardTheme(dashboard: Dashboard): any {
    const themeId = this.getUiTheme();
    let theme = this.defaultTheme;
    dashboard.config = dashboard.config || {
      theme
    }
    theme = dashboard.config.theme || theme;
    return theme[themeId];
  }

  setDashboardCardColor(hexColor?: string, opacity?: number, blur?: number) {
    const themeId = this.getUiTheme();
    const matCardCss = this.getCSSRule(`.${themeId}-theme .mat-card`);
    if (!matCardCss) return;
    const color = hexColor ? Color.from(hexColor) : new Color();
    if (opacity == null) opacity = 60;
    if (hexColor == null) {
      if (themeId == 'dark') {
        // default dark-theme color
        color.setRgba(66, 66, 66, opacity / 100.0);
      } else {
        // default light-theme color
        color.setRgba(255, 255, 255, opacity / 100.0);
      }
    }
    const rgba = color.getRgba();
    rgba.alpha = opacity / 100.0;
    color.setRgba(rgba.red, rgba.green, rgba.blue, rgba.alpha);
    matCardCss.style.background = `rgba(${rgba.red}, ${rgba.green}, ${rgba.blue}, ${rgba.alpha})`;
    if (blur) {
      matCardCss.style.backdropFilter = `blur(${blur / 100 * 24}px)`;
    } else {
      matCardCss.style.backdropFilter = '';
    }
  }
  setDashboardCardBlur(blur: number) {
    const themeId = this.getUiTheme();
    if (blur == null) blur = 50;
    const matCardCss = this.getCSSRule(`.${themeId}-theme .mat-card`);
    matCardCss.style.backdropFilter = `blur(${blur / 100 * 24}px)`;
  }

  setDashboardWallpaper(wallpaper: any) {
    const dashboardContainer = this.getCSSRule('.dashboard-page');
    dashboardContainer.style.backgroundImage = `url('${wallpaper}')`;
  }


  getAvailableDashboardPrograms(modules: Module[]): Module[] {
    return modules.filter((module) => {
      const adapter = module.getAdapter() as HomegenieAdapter;
      let isProgramMacro = false;
      if (module.type === ModuleType.Program) {
        const programModule = adapter.getModule(module.id);
        if (!programModule) return;
        const programWidget = adapter.getModuleWidget(programModule);
        if (programWidget === 'homegenie/generic/program') {
          isProgramMacro = true;
        }
      }
      return module.isOnline && isProgramMacro;
    });
  }


  private getUiTheme(): string | null {
    const SUFFIX = '-theme';
    const themeClass = Array.from(document.body.classList)
      .find(cls => (cls.startsWith('light') || cls.startsWith('dark')) && cls.endsWith(SUFFIX));
    if (themeClass) {
      return themeClass.slice(0, -SUFFIX.length);
    }
    return null;
  }

  private getCSSRule(ruleName: string, deleteFlag?: 'delete'): any {
    const lowerCaseRuleName = ruleName.toLowerCase();

    if (!document.styleSheets) {
      return false;
    }

    for (const styleSheet of Array.from(document.styleSheets)) {
      try {
        if (!styleSheet.cssRules) {
          continue;
        }

        for (let i = 0; i < styleSheet.cssRules.length; i++) {
          const cssRule = styleSheet.cssRules[i] as any;
          if (cssRule.selectorText?.toLowerCase() === lowerCaseRuleName) {
            if (deleteFlag === 'delete') {
              styleSheet.deleteRule(i);
              return true;
            }
            return cssRule;
          }
        }
      } catch (e) {
        // ignored
      }
    }

    return false;
  }
}
