import {Component, OnDestroy, OnInit, ViewChild} from '@angular/core';

import {ModuleField} from "../../services/yot/module";
import {WidgetBaseComponent} from "../widget-base.component";
import {EnergyMonitorData} from "../../services/yot/widgets-model";
import {Subscription} from "rxjs";
import {ChartDataWorkerConfig} from "../../components/chart/chart-data.worker";
import {
  ChartComponent,
  ChartProvider,
  HgChartOptions,
  INTERFACE_STATISTICS_PROVIDER
} from "../../components/chart/chart.component";
import {
  WidgetActionRequest,
  WidgetActionRequestAction
} from "../common-parts/widget-actions-menu/widget-actions-menu.component";

@Component({
  selector: 'app-energy-monitor',
  templateUrl: './energy-monitor.component.html',
  styleUrls: ['./energy-monitor.component.scss']
})
export class EnergyMonitorComponent extends WidgetBaseComponent implements OnInit, OnDestroy {
  @ViewChild('chartComponent', {static:false})
  chartComponent: ChartComponent;

  private moduleEventsSubscription: Subscription;
  private statusChangeSubscription: Subscription;
  private chartDataConfig: ChartDataWorkerConfig;

  get data(): EnergyMonitorData {
    return super.data;
  }

  get actualLoad(): ModuleField {
    return this.data?.wattLoad;
  }
  get lightsCount(): ModuleField {
    return this.data?.operatingLights;
  }
  get appliancesCount(): ModuleField {
    return this.data?.operatingAppliances;
  }
  get totalCounter(): ModuleField {
    return this.data?.totalCounter;
  }
  get todayCounter(): ModuleField {
    return this.data?.todayCounter;
  }

  override get configuration(): any {
    if (!this.chartDataConfig) {
      this.chartDataConfig = new ChartDataWorkerConfig();
      this.chartDataConfig.moduleId = this.module.id;
      this.chartDataConfig.chartOptions = new HgChartOptions();
      this.chartDataConfig.chartOptions.fill = true;
      const rangeEnd = new Date().getTime();
      this.chartDataConfig.queryOptions = {
        dataFilter: 'MovingAverage',
        field: 'EnergyMonitor.WattLoad',
        rangeStart: rangeEnd - (24 * 60 * 60 * 1000),
        rangeEnd,
        timeRange: 24
      };
    }
    return [ this.chartDataConfig ];
  }

  ngOnInit(): void {
    super.ngOnInit();

    // real-time chart update
    this.moduleEventsSubscription = this.yot.onModuleEvent.subscribe((e) => {
      if (e.module === this.module && e.event.key === 'EnergyMonitor.WattLoad') {
        if (this.chartComponent) {
          this.chartComponent.refresh();
        }
      }
    });
    this.statusChangeSubscription = this.widgetStatusChange.subscribe(status => {
      switch (status) {
        case 'widget:paused':
          if (this.chartComponent) {
            setTimeout(() => this.chartComponent.pause(), 200);
          }
          break;
        case 'widget:resumed':
          if (this.chartComponent) {
            setTimeout(() => this.chartComponent.resume(), 200);
          }
          break;
      }
    });
  }
  ngOnDestroy() {
    this.moduleEventsSubscription?.unsubscribe();
    this.statusChangeSubscription?.unsubscribe();
  }

  public override onWidgetActionRequest(actionRequest: WidgetActionRequest): void {
    super.onWidgetActionRequest(actionRequest);
    if (actionRequest.action === WidgetActionRequestAction.resizeWidget) {
      setTimeout(() => this.chartComponent.resume(), 100);
    }
  }
}
