import {Injectable, OnDestroy} from '@angular/core';
import {HomegenieAdapter, Program} from "../adapters/home-genie/homegenie-adapter";
import {YotService} from "./yot/yot.service";
import {Subject, Subscription} from "rxjs";
import {SystemApi} from "../api/system-api";
import {VoiceControlService} from "./voice-control.service";
import {Module as YotModule, ModuleReference} from "./yot/module";
import {SpeechSynthesisService} from "./speech-synthesis.service";
import {DomainNames} from "../adapters/home-genie/homegenie-api";

export interface HistoryMessagePart {
  text: string;
}
export interface ActionExecutionResult {
  Index: number; Command: string; ActionId: string; RequestId: string;
  State: 'completed' | 'failed' | 'unknown'; Success: boolean;
  DurationMs: number; Error?: string; Response?: any; Replayed: boolean;
}
export interface ChatRequestMetadata {
  requestId: string;
  startedAt: string;
  outcome: 'submitted' | 'completed' | 'error' | 'cancelled';
  durationMs: number;
  firstTokenMs?: number | null;
  generationMs?: number | null;
  actionsMs: number;
  actionCount: number;
  failedActions: number;
  actions?: ActionExecutionResult[];
}
export interface HistoryMessage {
  role: 'user' | 'model';
  parts: HistoryMessagePart[];
  createdAt?: string;
  metadata?: ChatRequestMetadata;
}
export interface ChatMessage {
  createdAt?: string;
  metadata?: ChatRequestMetadata;
  author: string;
  text: string;
}

export class AiChatGenie {
  public module: ModuleReference;
  public providerId: number;
  public apiUrl: string;
  public interface: string;
  public options: any
  public name: string;
  public description: string;
}

export enum VoiceControlStatus {
  Idle,
  Listening,
  Error,
  ProcessingInput,
  CommandNotUnderstood
}

@Injectable({
  providedIn: 'root'
})
export class AiChatService implements OnDestroy {
  aiChatGenies: AiChatGenie[] = [];
  messages: ChatMessage[] = [];
  currentUserInput: string = '';
  scrollPosition = 0;

  voiceControlStatus = VoiceControlStatus.Idle;
  voiceControlStatusInfo: any;

  onVoiceControlInput = new Subject<string>();

  promptHint = '';

  private listenSubscription: Subscription;
  private errorSubscription: Subscription;
  private endedSubscription: Subscription;

  private selectedAiChatGenie: AiChatGenie;
  private historyRequest: Subscription;
  private historyRequestVersion = 0;

  constructor(public voiceControlService: VoiceControlService, public speechSynthesizer: SpeechSynthesisService, private yot: YotService) {

    this.listenSubscription = voiceControlService
      .listenStarted.subscribe(() => {
        this.voiceControlStatus = VoiceControlStatus.Listening;
      });
    this.errorSubscription = voiceControlService
      .listenError.subscribe((err) => {
        this.voiceControlStatus = VoiceControlStatus.Error;
        this.voiceControlStatusInfo = err;
      });
    this.endedSubscription = voiceControlService
      .listenEnded.subscribe((sentence) => {
        if (this.voiceControlStatus == VoiceControlStatus.Error) {
          return;
        }
        if (sentence.trim().length === 0) {
          this.voiceControlStatus = VoiceControlStatus.Error;
          return;
        }
        this.voiceControlStatus = VoiceControlStatus.ProcessingInput;
        this.onVoiceControlInput.next(sentence);
      });

  }
  ngOnDestroy() {
    this.historyRequestVersion++;
    this.historyRequest?.unsubscribe();
    this.voiceControlService.stop();
    this.listenSubscription.unsubscribe();
    this.errorSubscription.unsubscribe();
    this.endedSubscription.unsubscribe();
  }

  public setCurrentAiChatGenie(genie: AiChatGenie, options?: {success: Function, error?: Function}) {
    if (this.selectedAiChatGenie?.providerId === genie?.providerId) {
      options?.success();
      return;
    }
    this.historyRequestVersion++;
    this.historyRequest?.unsubscribe();
    this.scrollPosition = 0;
    this.selectedAiChatGenie = genie;
    this.clearChat();
    if (this.selectedAiChatGenie?.providerId === 0) {
      // builtin chatbot for basic commands
      // add an intro message to the history.
      const selectionVersion = this.historyRequestVersion;
      this.yot.translate.get('ai_chatbot_teaser').subscribe((text) => {
        if (selectionVersion !== this.historyRequestVersion) return;
        this.addMessage('ai', text)
      });
      options?.success();
      return;
    }

    this.loadHistory(null, options);
  }
  public getCurrentAiChatGenie(): AiChatGenie {
    return this.selectedAiChatGenie;
  }


  /**
   * Loads a conversation history and replaces the current one.
   * This is the main method to be called from the outside.
   * @param history An array of messages in the provider's format.
   * @param options
   */
  public loadHistory(history?: HistoryMessage[], options?: any): void {
    if (!options?.preserveInput) this.currentUserInput = '';

    const version = ++this.historyRequestVersion;
    this.historyRequest?.unsubscribe();
    const genie = this.selectedAiChatGenie;
    if (history == null) {
      this.historyRequest = (this.yot.getDefaultAdapter() as HomegenieAdapter)
        .apiCall(`${genie.apiUrl}/History.Get`, undefined, {})
        .subscribe({
          next: (result) => {
            if (version !== this.historyRequestVersion || this.selectedAiChatGenie !== genie) return;
            if (!Array.isArray(result?.response)) {
              options?.error(new Error(result?.response?.Message || 'Chat history is not available yet.'));
              return;
            }
            this.loadHistory(result.response, {preserveInput: options?.preserveInput});
            options?.success();
          },
          error: (err) => {
            if (version !== this.historyRequestVersion || this.selectedAiChatGenie !== genie) return;
            options?.error(err);
          }
        });
      return;
    }
    if (!Array.isArray(history)) {
      options?.error(new Error('Invalid chat history response.'));
      return;
    }

    if (this.selectedAiChatGenie.interface === '@AI:IntentHandler') {
      this.messages = history.map(message => this.parseIntentHandlerMessage(message));
    } else {
      this.messages = history.map(this.transformHistoryMessage);
    }
  }

  public exportHistory(options?: {success: Function, error?: Function}): void {
    (this.yot.getDefaultAdapter() as HomegenieAdapter)
      .apiCall(`${this.selectedAiChatGenie.apiUrl}/History.Export`, undefined, {} /* this disables ws routing */)
      .subscribe({
        next: (result) => {
          options?.success(result.response);
        },
        error: (err) => {
          options?.error(err);
        }
      });
  }
  public importHistory(file: File, options?: {success: Function, error?: Function}): void {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const historyContent = JSON.parse(e.target.result as string);
        (this.yot.getDefaultAdapter() as HomegenieAdapter)
          .apiCall(`${this.selectedAiChatGenie.apiUrl}/History.Import`, historyContent, {} /* this disables ws routing */)
          .subscribe({
            next: (result) => {
              this.loadHistory(result.response);
              options?.success();
            },
            error: (err) => {
              options?.error(err);
            }
          });

      } catch (err) {
        options?.error("Invalid JSON file");
      }
    };
    reader.readAsText(file);
  }
  /**
   *
   * @param options
   */
  public clearHistory(options?: {success: Function, error?: Function}): void {
    (this.yot.getDefaultAdapter() as HomegenieAdapter)
      .apiCall(`${this.selectedAiChatGenie.apiUrl}/History.Clear`, undefined, {} /* this disables ws routing */)
      .subscribe({
        next: (result) => {
          this.messages = [];
          options?.success();
        },
        error: (err) => {
          options?.error(err);
        }
      });
  }
  public deleteMessage(messageIndex: number, options?: {success: Function, error?: Function}): void {
    (this.yot.getDefaultAdapter() as HomegenieAdapter)
      .apiCall(`${this.selectedAiChatGenie.apiUrl}/History.RemoveAt/${messageIndex}`, undefined, {} /* this disables ws routing */)
      .subscribe({
        next: (result) => {
          this.messages.splice(messageIndex, 1);
          options?.success();
        },
        error: (err) => {
          options?.error(err);
        }
      });
  }

  getAiChatGenieList(providerType: string): Subject<AiChatGenie[]> {
    const subject = new Subject<AiChatGenie[]>();
    const adapter = this.yot.getDefaultAdapter();
    adapter
      .system(SystemApi.Automation.Programs.Implements, providerType)
      .subscribe({
        next: (providers: AiChatGenie[]) => {
          // load translations for name
          adapter.system(SystemApi.Automation.Programs.List)
            .subscribe((programs: Program[]) => {

              providers.forEach(provider => {
                const p = programs.find(p => p.Address === provider.providerId);
                // translate Name and Description
                const titleKey = `${adapter.translationPrefix}.$options.${p.Address}.Title`;
                this.yot.translate.get(titleKey).subscribe((tr) => {
                  if (tr !== titleKey) {
                    provider.name = tr;
                  }
                });
                const descriptionKey = `${adapter.translationPrefix}.$options.${p.Address}.Description`;
                this.yot.translate.get(descriptionKey).subscribe((tr) => {
                  if (tr !== descriptionKey) {
                    p.Description = tr;
                  }
                });
                provider.description = p.Description;
                provider.module = {moduleId: DomainNames.HomeAutomation_HomeGenie_Automation + ':' + p.Address, adapterId: adapter.id};
              });
              this.aiChatGenies = [
// TODO: should check if providerType matches '@AI:IntentHandler' before adding the builtin chat bot
                {
                  providerId: 0,
                  interface: '@AI:IntentHandler',
                  apiUrl: '',
                  options: null,
                  name: 'builtin_control_chatbot',
                  description: 'builtin_chatbot_description',
                  module: null
                },
                ...providers
              ];
              subject.next(this.aiChatGenies);
              subject.complete();
            });
        },
        error: err => {
          subject.error(err);
        }
      });
    return subject;
  }

  /**
   * Helper function to parse a single message from the IntentHandler format.
   * Extracts the user command or the model's answer.
   * @param message The raw message from the history.
   * @returns A clean message object for display.
   */
  private parseIntentHandlerMessage(message: HistoryMessage): ChatMessage {
    const rawText = (message.parts || []).map(p => p.text).join('\n');
    let displayText = '';

    if (message.role === 'user') {
      // Per i messaggi dell'utente, estrai solo il testo dopo "--- USER COMMAND ---"
      displayText = this.extractUserCommand(rawText);
    } else if (message.role === 'model') {
      // Per i messaggi del modello, fai il parsing del JSON e prendi il campo "answer"
      displayText = this.extractModelAnswer(rawText);
    }

    return {
      author: message.role,
      text: displayText,
      createdAt: message.createdAt,
      metadata: message.metadata
    };
  }

  /**
   * Extracts the user command text from the complex user prompt string.
   * @param rawText The full text from the user message part.
   * @returns The user's command or the raw text if the marker is not found.
   */
  private extractUserCommand(rawText: string): string {
    const marker = '--- USER COMMAND ---';
    const markerIndex = rawText.indexOf(marker);

    if (markerIndex !== -1) {
      // Prendi il testo dopo il marcatore e rimuovi spazi e a capo
      return rawText.substring(markerIndex + marker.length).trim();
    }

    // Fallback nel caso in cui il formato cambi o sia inaspettato
    return rawText;
  }

  /**
   * Extracts the friendly answer from the model's JSON response string.
   * @param rawText The full JSON string from the model message part.
   * @returns The answer text or an error message if parsing fails.
   */
  private extractModelAnswer(rawText: string): string {
    /*
    // DEPRECATED CODE
    try {
      // Tenta di fare il parsing del testo come un oggetto JSON
      const parsedJson = JSON.parse(rawText);
      // Ritorna il valore della proprietà "answer" se esiste, altrimenti una stringa vuota
      return parsedJson.answer || '';
    } catch (error) {
      // Se il parsing fallisce, significa che il testo non era un JSON valido.
      // Potrebbe essere una risposta di testo semplice o un errore. Lo mostriamo così com'è.
      console.warn('Could not parse model message as JSON. Displaying raw text.', rawText);
    }*/
    return rawText;
  }

  /**
   * Adds a new message to the current chat session.
   * This is used for new messages typed by the user.
   * @param author The author of the message ('user' or 'ai').
   * @param text The message content.
   * @param options
   */
  public addMessage(author: 'user' | 'ai', text: string, options?: {send: boolean, success: Function, error?: Function}): void {
    if (!author || !text) {
      return;
    }
    this.messages.push({ author, text });
    if (author === 'user' && this.selectedAiChatGenie?.providerId === 0) {
      const interpretedCount = this.voiceControlService.parse(text, {
        onModuleCommand(module: YotModule, command: string, group: string, value?: any) {
          module.control(command, value).subscribe({
            next: () =>{
              let apiCall = '/api/';
              const dp = module.id.split(':');
              dp.forEach((a, i) => {
                apiCall += a + (((dp.length >= 2 && i == 1) || (dp.length === 2 && i === 0) || (dp.length - 1 === i)) ? '/' : ':');
              });
              if (value) {
                apiCall = `${apiCall}${command}/${value}`;
              } else {
                apiCall = `${apiCall}${command}`;
              }
            },
            error: (err) => {
              //console.error(err);
            }
          });
        }
      });
      let aiReply = 'builtin_chatbot_command_sent';
      if (interpretedCount === 0) {
        aiReply = 'builtin_chatbot_command_error';
      }
      this.yot.translate.get(aiReply).subscribe((tr) => {
        aiReply = tr;
      });
      this.addMessage('ai', aiReply);
      setTimeout(() => options?.success(aiReply));
      this.voiceControlStatus = VoiceControlStatus.Idle;
      return;
    }
    if (options?.send) {
      this.voiceControlStatus = VoiceControlStatus.ProcessingInput;
      (this.yot.getDefaultAdapter() as HomegenieAdapter)
        .apiCall(`${this.selectedAiChatGenie.apiUrl}/Prompt.Submit`, `${text}`, {} /* this disables ws routing */)
        .subscribe({
          next: (result) => {
            const aiReply = result.response?.ResponseValue;
            this.addMessage('ai', aiReply);
            options?.success(aiReply);
            this.voiceControlStatus = VoiceControlStatus.Idle;
          },
          error: (err) => {
            options?.error(err);
            this.voiceControlStatus = VoiceControlStatus.Idle;
          }
        });
    }
  }

  public cancelMessage() {
    (this.yot.getDefaultAdapter() as HomegenieAdapter)
      .apiCall(`${this.selectedAiChatGenie.apiUrl}/Prompt.Cancel`, undefined, {} /* this disables ws routing */)
      .subscribe({
        next: (result) => {
          this.voiceControlStatus = VoiceControlStatus.Idle;
        },
        error: (err) => {
          this.voiceControlStatus = VoiceControlStatus.Idle;
        }
      });
  }

  /**
   * Clears the entire chat session.
   */
  public clearChat(): void {
    this.messages = [];
    this.currentUserInput = '';
  }

  public listen(): void {
    this.voiceControlService.listen();
  }

  /**
   * A private helper method to transform a message from the history format
   * to our internal ChatMessage format.
   * @param historyMsg A single message from the history array.
   * @returns A ChatMessage object.
   */
  private transformHistoryMessage(historyMsg: HistoryMessage): ChatMessage {
    return {
      author: historyMsg.role === 'model' ? 'ai' : 'user',
      text: (historyMsg.parts || []).map(p => p.text).join('\n'),
      createdAt: historyMsg.createdAt,
      metadata: historyMsg.metadata
    };
  }

  hasHistory() {
    return this.messages.length > 0;
  }
}
