  static FunctionNameValidator(this: BlockDefinition, inputText: string) {
    if (/^[\p{L}0-9_]+$/u.test(inputText)) {
      // If the text is valid we have to return it, just how validators work.
      this.setWarningText(undefined);
      return inputText;
    } else {
      // This sets the warning.
      this.setWarningText(HomegenieWorkspace.InputNotValidMessage2);
      // You may or may not want to return this. You can return different
      // text so that it displays something different, or you can return
      // null to negate the user's changes.
      //return null;
      return inputText;
    }
  }

  static ApiCommandValidator(this: BlockDefinition, inputText: string) {
    if (/^(?!.*\.\.)(?:\p{L}|[0-9])(?:[\p{L}0-9.]*(?:\p{L}|[0-9]))?$/u.test(inputText)) {
      this.setWarningText(undefined);
      return inputText;
    } else {
      this.setWarningText(HomegenieWorkspace.InputNotValidMessage1);
      return inputText;
    }
  }

  static DomainOrParamNameValidator(this: BlockDefinition, inputText: string) {
    if (/^(?!.*\.\.)(?:\p{L}|[0-9])(?:[\p{L}0-9.]*(?:\p{L}|[0-9]))?$/u.test(inputText)) {
      this.setWarningText(undefined);
      return inputText;
    } else {
      this.setWarningText(HomegenieWorkspace.InputNotValidMessage1);
      return inputText;
    }
  }

  static BlocklyInitialized = false;

  constructor(workspaceReadyCallback: Function, private adapter: HomegenieAdapter, private blocklyDiv: HTMLElement, darkTheme: boolean) {

    this.updateTranslations(() => {
      if (!HomegenieWorkspace.BlocklyInitialized) {
        HomegenieWorkspace.BlocklyInitialized = true;
        this.initializeBlocklyWorkspace();
      }

      let lang = this.adapter.yot.translate.currentLang;
      if (lang === 'zh-cn') lang = 'zh-hans'; // hans = simplified, hant = traditional
      window['Blockly'] = Blockly;
      zuix.using('script', './assets/editor/blockly/msg/' + lang + '.js', (e, b, c) => {
        // this is called even if an error occurred while loading the language `.js`
        this.createWorkspace(darkTheme);
        workspaceReadyCallback(this.workspace);
      });
    });

  }

