    Blockly.Blocks['thermostat_setpoint'] = {
      // default values
      defaultData: {
        value: 20,
        min: 10,
        max: 38,
        unit: 'C',
        precision: 0.5
      },
      init: function() {
        const typeDropDown = new FieldDropdown(() => [
          [host.workspace_toolbox_control_thermostat_setpoint_heating, 'Heating'],
          [host.workspace_toolbox_control_thermostat_setpoint_heating_eco, 'HeatingEconomy'],
          [host.workspace_toolbox_control_thermostat_setpoint_cooling, 'Cooling'],
          [host.workspace_toolbox_control_thermostat_setpoint_cooling_eco, 'CoolingEconomy']
        ]);
        const fieldDropDown = new FieldDropdown(() =>
          converter.temperature().list().map(u => [u.unit, u.unit]));
        const t = this.defaultData;
        this.fieldSlider = new FieldSlider();
        this.appendDummyInput()
          .appendField(host.workspace_toolbox_control_thermostat_setpoint_label)
          .appendField(typeDropDown, 'TYPE')
          .appendField('⇢')
          .appendField(this.fieldSlider, 'SETPOINT')
          .appendField('°')
          .appendField(fieldDropDown, 'UNIT');
        this.setNextStatement(true);
        this.setPreviousStatement(true);
        this.setColour(25);
        this.setTooltip(host.workspace_toolbox_control_thermostat_setpoint_tooltip);
        setTimeout(() => {
          const id = this.id;
          if (!this.data) {
            this.fieldSlider.setValue(t.value);
            fieldDropDown.setValue(t.unit);
            fieldDropDown.setValue(conversionUnit);
          } else {
            this.onchange({type: 'change', name: 'UNIT', blockId: id, oldValue: this.data, newValue: this.data});
          }
        });
      },
      onchange: function(ev) {
        if (ev.blockId === this.id && ev.type === 'change' && ev.name === 'UNIT') {
          const min = converter.temperature(this.defaultData.min)
            .from(this.defaultData.unit).to(ev.newValue).value;
          const max = converter.temperature(this.defaultData.max)
            .from(this.defaultData.unit).to(ev.newValue).value;
          let value = this.fieldSlider.getValue();
          value = converter.temperature(value)
            .from(ev.oldValue).to(ev.newValue).value;
          this.fieldSlider.setMin(min);
          this.fieldSlider.setMax(max);
          this.fieldSlider.setPrecision((max - min < 40) ? 0.5 : 1)
          this.fieldSlider.setValue(value);
          this.data = ev.newValue;
        }
      }
    };

