import {Component, EventEmitter, Input, OnInit, Output} from '@angular/core';
import {RecordingFolder} from "../../../widget-data";
import {HomegenieAdapter} from "../../../../adapters/home-genie/homegenie-adapter";
import {Module, ModuleType} from "../../../../services/yot/module";
import {VideoPlayerComponent} from "../../video-player.component";

@Component({
  selector: 'app-recording-list',
  templateUrl: './recording-list.component.html',
  styleUrls: ['./recording-list.component.scss']
})
export class RecordingListComponent implements OnInit {

  @Input()
  module: Module;

  @Input()
  active = false;

  @Input()
  host: VideoPlayerComponent = null;

  @Output()
  folderSelected = new EventEmitter<RecordingFolder>();

  dayRecordingFolders: RecordingFolder[] = [];

  isMenuOpen = false;

  ngOnInit() {
    this.refresh();
  }

  isRecording() {
    // TODO: use method from `host`
    return this.isContinuousRecordingActive()
      || this.module?.field('NVR.Status.Recording')?.value === '1';
  }
  isContinuousRecordingActive() {
    // TODO: use method from `host`
    return this.module?.field('NVR.ContinuousRecording')?.value === 'On';
  }
  get isRecordingEnabled(): boolean {
    return this.host?.isVideoInput() && this.host?.hasVideoSourceURL();
  }

  onSelect(folder: RecordingFolder) {
    this.folderSelected.emit(folder);
  }

  // Helper per formattare i secondi in HH:mm:ss
  formatDuration(seconds: number): string {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    // Aggiunge lo zero iniziale se necessario
    const pad = (n: number) => n < 10 ? '0' + n : n;
    return `${pad(h)}:${pad(m)}:${pad(s)}`;
  }

  // Helper per formattare i bytes in GB o MB
  formatBytes(bytes: number): string {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }


  refresh() {
    const homegenieAdapter = this.module.getAdapter() as HomegenieAdapter;
    const hgm = homegenieAdapter.getModule(this.module.id);
    homegenieAdapter.apiCall(`HomeAutomation.HomeGenie/NVR/Recordings.Days/${encodeURIComponent(hgm.Domain)}/${encodeURIComponent(hgm.Address)}`)
      .subscribe({
        next: (data) => {
          this.dayRecordingFolders = data.response.map((r) => ({
            _startTime: new Date(r.StartTime),
            _endTime: new Date(r.EndTime),
            ...r
          }));
        },
        error: err => {
          // TODO: ...
        }
      });
  }

  protected startContinuousRecording() {
    const homegenieAdapter = this.module.getAdapter() as HomegenieAdapter;
    const hgm = homegenieAdapter.getModule(this.module.id);
    homegenieAdapter.apiCall(`HomeAutomation.HomeGenie/NVR/Recordings.Start/${encodeURIComponent(hgm.Domain)}/${encodeURIComponent(hgm.Address)}`)
      .subscribe();
  }

  protected stopContinuousRecording() {
    const homegenieAdapter = this.module.getAdapter() as HomegenieAdapter;
    const hgm = homegenieAdapter.getModule(this.module.id);
    homegenieAdapter.apiCall(`HomeAutomation.HomeGenie/NVR/Recordings.Stop/${encodeURIComponent(hgm.Domain)}/${encodeURIComponent(hgm.Address)}`)
      .subscribe();
  }
}
