import {Component, Input, OnInit, ViewChild} from '@angular/core';
import {Scene} from "../../../services/yot/automation";
import {ControlFieldBase} from "../control-field-base";
import {SystemApi} from "../../../api/system-api";
import {MatSelect} from "@angular/material/select";

@Component({
  selector: 'app-scenario-select',
  templateUrl: './scenario-select.component.html',
  styleUrls: ['./scenario-select.component.scss']
})
export class ScenarioSelectComponent extends ControlFieldBase implements OnInit {
  @ViewChild('select')
  select: MatSelect;
  @Input()
  multiple: boolean = false;

  private _scenarios: Array<Scene> = [];
  get scenarios(): Array<Scene> {
    return this._scenarios;
  }

  ngOnInit(): void {
    super.ngOnInit();
    if (this.module) {
      this.module.getAdapter().system(SystemApi.Automation.Scenes.List).subscribe((res: Scene[]) => {
        this._scenarios = res;
      });
    }
  }

  reset() {
    super.reset();
    this.select.value = this.originalValue;
  }
}
