import {Component, Input, OnInit} from '@angular/core';
import {DynamicOptionsBase} from "../dynamic-options-base.component";
import {CMD} from "../../../services/yot/yot.service";
import {ModuleOptions, OptionField} from "../../../services/yot/module-options";

@Component({
  selector: 'app-module-options',
  templateUrl: './module-options.component.html',
  styleUrls: ['./module-options.component.scss']
})
export class ModuleOptionsComponent extends DynamicOptionsBase implements OnInit {
  showPanel: boolean[] = [];
  @Input()
  options: ModuleOptions[];

  ngOnInit() {
    if (this.options && this.options.length > 0) {
      this.optionsList.push(...this.options);
    }
    super.ngOnInit();
  }

  changed(f: OptionField) {
    return (this.changes.find((c) => c.field === f.field) != null);
  }
  programChanged(mo: ModuleOptions): number {
    return mo.items.filter((f) => this.changed(f)).length;
  }

  applyChanges() {
    //console.log('ModuleOptionsComponent::applyChanges', this.changes);
    if (this.changes.length > 0) {
      const changes: any = {};
      this.changes.forEach((c) => {
        changes[c.field.key] = c.value;
      });
      this.module.control(CMD.Options.Set, changes)?.subscribe((res) => {
        //console.log('ModuleOptionsComponent::applyChanges DONE');
      });
    }
  }

  togglePanel(index: number) {
    this.showPanel[index] = !this.showPanel[index];
    for (let i = 0; i < this.showPanel.length; i++) {
      if (i !== index) this.showPanel[i] = false;
    }
  }
}
