import { Injectable } from '@angular/core';

import { htmlToText } from 'html-to-text';
import {marked, Tokens} from 'marked';
import Code = Tokens.Code;
import Link = Tokens.Link;
import HTML = Tokens.HTML;
import Strong = Tokens.Strong;
import Em = Tokens.Em;
import Del = Tokens.Del;
import Codespan = Tokens.Codespan;
import Image = Tokens.Image;
import Blockquote = Tokens.Blockquote;
import Heading = Tokens.Heading;
import Paragraph = Tokens.Paragraph;

// 1. Create a plain instance of the base Renderer
const renderer = new marked.Renderer();
// COMPLETELY REMOVE code blocks and HTML
renderer.code = (code: Code) => '';
renderer.html = (html: HTML) => '';
// RENDER INLINE FORMATTING AS PLAIN TEXT
renderer.strong = (strong: Strong) => strong.text;
renderer.em = (em: Em) => em.text;
renderer.del = (del: Del) => del.text;
renderer.codespan = (codeSpan: Codespan) => codeSpan.text;
// RENDER LINKS AND IMAGES AS THEIR TEXT CONTENT
renderer.link = (href: Link) => href.text;
renderer.image = (image: Image) => image.text || '';
// OPTIONAL: Customize other elements if needed, otherwise default is fine
renderer.blockquote = (blockQuote: Blockquote) => blockQuote.text;
renderer.heading = (heading: Heading) => heading.text + '\n';
renderer.paragraph = (paragraph: Paragraph) => paragraph.text + '\n\n';

@Injectable({
  providedIn: 'root'
})
export class SpeechSynthesisService {
  private synth: SpeechSynthesis;

  private synthesisVoices: SpeechSynthesisVoice[] = [];
  public selectedSynthesisLanguage = '';
  public selectedSynthesisVoice: SpeechSynthesisVoice;
  public synthesisPitch = 1;
  public synthesisRate = 1;
  public synthesisVolume = 1;

  constructor() {
    this.synth = window.speechSynthesis;
  }

  speak(text: string, lang: string = 'en-US'): void {
    text = this.stripEmoji(text);
    if (!this.synth) return;
    if (this.synth.speaking) {
      //console.error('SpeechSynthesis.speak() already in progress.');
      //return;
      this.cancel();
    }
    if (text !== '') {
      const utterance = new SpeechSynthesisUtterance(text);

      this.selectedSynthesisVoice = null;
      for (let voice of this.synthesisVoices) {
        if  (voice.lang === this.selectedSynthesisLanguage) {
          this.selectedSynthesisVoice = voice;
        }
      }

      utterance.lang = this.selectedSynthesisLanguage;
      // set speech synthesis configuration

      utterance.voice = this.selectedSynthesisVoice;
      utterance.rate = this.synthesisRate;
      utterance.pitch = this.synthesisPitch;
      utterance.volume = this.synthesisVolume;
      this.synth.speak(utterance);
    }
  }

  getVoices(): SpeechSynthesisVoice[] {
    if (this.synth && this.synthesisVoices.length === 0) {
      this.synthesisVoices = this.synth.getVoices();

      //console.log(this.synthesisVoices);

      if (this.selectedSynthesisLanguage.length === 0) {
        this.selectedSynthesisLanguage = navigator.language;
      }
    }
    return this.synthesisVoices;
  }

  isSpeaking(): boolean {
    return this.synth?.speaking;
  }

  cancel(): void {
    this.synth?.cancel();
  }

  stripEmoji(text: string): string {
    // Preserve letters, numbers, punctuation and RTL text; remove whole emoji sequences.
    return (text || '')
      .replace(/[#*0-9]\uFE0F?\u20E3/gu, '')
      .replace(/\p{Regional_Indicator}{2}/gu, '')
      .replace(/\p{Extended_Pictographic}(?:[\uFE0E\uFE0F]|\p{Emoji_Modifier}|[\u{E0020}-\u{E007F}])*(?:\u200D\p{Extended_Pictographic}(?:[\uFE0E\uFE0F]|\p{Emoji_Modifier})*)*/gu, '')
      .replace(/[\uFE0E\uFE0F]|\p{Emoji_Modifier}/gu, '')
      .replace(/[ \t]+/g, ' ').trim();
  }

  async markdownToPlainText(markdownText: string): Promise<string> {
    if (!markdownText) {
      return Promise.resolve('');
    }
    const plainText = await marked.parse(markdownText, { renderer });
    return this.stripEmoji(htmlToText(plainText).replace(/[*\n]/g, ' '));
  }
}
