import {Component, Inject, OnDestroy, OnInit} from '@angular/core';
import {ApiResponse, HomegenieAdapter} from '../../homegenie-adapter';
import {MAT_DIALOG_DATA} from '@angular/material/dialog';
import {HomegenieApi, ResponseStatus} from '../../homegenie-api';
import {Subscription, timeout} from 'rxjs';
import {TranslateService} from '@ngx-translate/core';

enum SystemRestartStep {
  Error = -1,
  ConfirmPrompt,
  Restart,
  WaitingRestart,
  Restarted
}

@Component({
  selector: 'app-service-restart-dialog',
  templateUrl: './service-restart-dialog.component.html',
  styleUrls: ['./service-restart-dialog.component.scss']
})
export class ServiceRestartDialogComponent implements OnInit, OnDestroy {
  adapter: HomegenieAdapter;
  isLoading = false;
  errorMessage = '';
  SystemRestartStep = SystemRestartStep;
  currentStep = SystemRestartStep.ConfirmPrompt;
  serverBootProgress = 0;

  private subscriptions = new Subscription();
  private pollTimer: ReturnType<typeof setTimeout>;
  private deadlineTimer: ReturnType<typeof setTimeout>;
  private initialStartTime: number;
  private probePending = false;
  private destroyed = false;

  constructor(@Inject(MAT_DIALOG_DATA) data: {adapter: HomegenieAdapter},
              private translate: TranslateService) {
    this.adapter = data.adapter;
  }

  ngOnInit(): void {
    this.subscriptions.add(this.adapter.onModuleEvent.subscribe(({event}) => {
      if (this.currentStep !== SystemRestartStep.WaitingRestart || event.Domain !== 'HomeGenie.System') return;
      if (event.Property === 'SystemInfo.BootProgress') {
        const progress = Number(String(event.Value).replace(',', '.'));
        if (Number.isFinite(progress)) this.serverBootProgress = progress;
      }
      if (event.Property === 'HomeGenie.Status' && event.Value === 'STARTED') this.probeRestart();
    }));
  }

  ngOnDestroy(): void {
    this.destroyed = true;
    clearTimeout(this.pollTimer);
    clearTimeout(this.deadlineTimer);
    this.subscriptions.unsubscribe();
  }

  onSystemRestartClick(): void {
    if (this.currentStep !== SystemRestartStep.ConfirmPrompt) return;
    this.isLoading = true;
    this.currentStep = SystemRestartStep.Restart;
    // Compare process start times so a fast restart cannot be missed between events.
    this.subscriptions.add(this.adapter.apiCall(HomegenieApi.SystemConfig.System.Info, null, {}).pipe(timeout(5000)).subscribe({
      next: (result: ApiResponse) => {
        const start = Number(result.response?.Process?.StartTime);
        if (result.code !== 200 || !Number.isFinite(start) || start <= 0) {
          this.fail(this.translate.instant('error_occurred'));
          return;
        }
        this.initialStartTime = start;
        this.requestRestart();
      },
      error: error => this.fail(error.message)
    }));
  }

  private requestRestart(): void {
    this.subscriptions.add(this.adapter.apiCall(HomegenieApi.SystemConfig.Service.Restart, null, {}).pipe(timeout(10000)).subscribe({
      next: (result: ApiResponse) => {
        if (result.code === 200 && result.response?.Status === ResponseStatus.Ok && result.response.Message === 'RESTART') {
          this.beginWaiting();
        } else {
          this.fail(result.response?.Message || this.translate.instant('error_occurred'));
        }
      },
      // A disconnect may mean the process restarted before returning its acknowledgement.
      error: error => {
        if (error.status >= 400 && error.status < 500) this.fail(error.message);
        else this.beginWaiting();
      }
    }));
  }

  private beginWaiting(): void {
    if (this.destroyed) return;
    this.isLoading = false;
    this.currentStep = SystemRestartStep.WaitingRestart;
    this.deadlineTimer = setTimeout(() => this.fail(this.translate.instant('service_restart_timeout')), 180000);
    this.probeRestart();
  }

  private probeRestart(): void {
    if (this.destroyed || this.probePending || this.currentStep !== SystemRestartStep.WaitingRestart) return;
    clearTimeout(this.pollTimer);
    this.probePending = true;
    this.subscriptions.add(this.adapter.apiCall(HomegenieApi.SystemConfig.System.Info, null, {}).pipe(timeout(4000)).subscribe({
      next: (result: ApiResponse) => {
        const start = Number(result.response?.Process?.StartTime);
        if (result.code === 200 && Number.isFinite(start) && start > this.initialStartTime) {
          this.checkBootProgress();
        } else this.scheduleProbe();
      },
      error: () => this.scheduleProbe()
    }));
  }

  private checkBootProgress(): void {
    this.subscriptions.add(this.adapter.apiCall('HomeAutomation.HomeGenie/Config/System.GetBootProgress', null, {}).pipe(timeout(4000)).subscribe({
      next: (result: ApiResponse) => {
        if (this.destroyed || this.currentStep !== SystemRestartStep.WaitingRestart) return;
        const progress = Number(result.response);
        if (result.code === 200 && Number.isFinite(progress)) {
          this.serverBootProgress = progress;
          if (progress >= 100) {
            this.probePending = false;
            this.isLoading = false;
            this.currentStep = SystemRestartStep.Restarted;
            clearTimeout(this.deadlineTimer);
            return;
          }
        }
        this.scheduleProbe();
      },
      error: () => this.scheduleProbe()
    }));
  }

  private scheduleProbe(): void {
    this.probePending = false;
    if (!this.destroyed && this.currentStep === SystemRestartStep.WaitingRestart) {
      this.pollTimer = setTimeout(() => this.probeRestart(), 2000);
    }
  }

  private fail(message: string): void {
    if (this.destroyed) return;
    clearTimeout(this.pollTimer);
    clearTimeout(this.deadlineTimer);
    this.isLoading = false;
    this.errorMessage = message;
    this.currentStep = SystemRestartStep.Error;
  }
}
