import {Pipe, PipeTransform} from '@angular/core';
import {YotService} from "../services/yot/yot.service";
import * as moment from 'moment'; // Importa Moment.js
import 'moment/locale/ja'; // Esempio: importa locale giapponese se non usi un pack completo
import 'moment/locale/kn'; // Esempio: importa locale Kannada
import 'moment/locale/hi'; // Esempio: importa locale Hindi
import 'moment/locale/ar-sa'; // Esempio: importa locale Arabo per Arabia Saudita

@Pipe({ name: 'dataRangeFormatter' })
export class DataRangeFormatterPipe implements PipeTransform {

  constructor(private yot: YotService) {
    // Carica tutti i locale di Moment.js se non sono già stati caricati globalmente
    // Oppure carica solo quelli necessari qui (vedi import sopra)
  }

  transform(value: any, ...args): any {
    const currentLocale = this.yot.preferences.ui.language;

    // Moment.js non ha bisogno di mappature complesse come 'ja-JP' per 'ja'
    // Moment.js è intelligente e mappa 'kn' a 'kn-in' automaticamente, o 'hi' a 'hi-in'
    const momentLocale = currentLocale; // Moment.js gestisce i codici ISO direttamente

    // Applica il locale a Moment.js per tutte le operazioni di formattazione
    moment.locale(momentLocale);

    // DEBUG
    //console.log('Pipe transform - Value:', value, 'Args:', args, 'Locale UI:', currentLocale, 'Moment Locale:', moment.locale());


    if (args && args[1] === 'day_of_year') {
      return this.formatDayOfYear(value, args[2]); // Rimosso 'locales' dai parametri
    }
    if (args && args[1] === 'week_of_year') {
      return this.formatWeekRange(value, args[2]); // Rimosso 'locales' dai parametri
    }
    if (args && args[1] === 'year') {
      return this.formatYear(value); // Rimosso 'locales' dai parametri
    }

    return value;
  }

  private formatYear(year: number): string {
    // Moment.js usa il proprio locale impostato globalmente
    return moment().year(year).format('YYYY'); // 'YYYY' per l'anno completo, Moment.js lo localizza
  }

  private formatDayOfYear(dayOfYear: number, year: number = new Date().getFullYear()): string {
    const date = moment().year(year).dayOfYear(dayOfYear);
    // 'dddd' per il giorno della settimana completo, 'D' per il giorno, 'MMMM' per il mese completo
    const dateString = date.format('dddd D MMMM');

    // Moment.js si occupa della localizzazione dei numeri e delle maiuscole/minuscole
    return `${dateString} [${dayOfYear}]`;
  }

  private formatWeekRange(weekNo: number, year: number = new Date().getFullYear()): string {
    // Moment.js ha un supporto diretto per le settimane ISO (ISO Week)
    const startDate = moment().year(year).isoWeek(weekNo).startOf('isoWeek');
    const endDate = moment().year(year).isoWeek(weekNo).endOf('isoWeek');

    let dateString = '';

    if (startDate.year() !== endDate.year()) {
      // Caso: Cross-year (e.g., 29 Dec 2025 - 04 Jan 2026)
      dateString = `${startDate.format('D MMMM YYYY')} - ${endDate.format('D MMMM YYYY')}`;
    } else if (startDate.month() !== endDate.month()) {
      // Case: Cross-month (e.g., 28 Feb - 06 Mar 2026)
      dateString = `${startDate.format('D MMM')} - ${endDate.format('D MMMM YYYY')}`; // 'MMM' per mese abbreviato
    } else {
      // Case: Same month (e.g., 10 - 16 Jan 2026)
      dateString = `${startDate.format('D')} - ${endDate.format('D MMMM YYYY')}`;
    }

    // Moment.js gestisce già la capitalizzazione e i numeri locali
    return `${dateString} (${weekNo})`;
  }
}

