import {Component, ElementRef, Inject, ViewChild, OnInit} from '@angular/core';
import {Module, ModuleType} from "../../../services/yot/module";
import {YotService} from "../../../services/yot/yot.service";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {AvMediaItem, HomegenieUpnpApi} from "../../../adapters/home-genie/homegenie-upnp-api";
import {MatRadioChange} from "@angular/material/radio";
import {Subject} from "rxjs";

@Component({
  selector: 'app-media-server-dialog',
  templateUrl: './media-server-dialog.component.html',
  styleUrls: ['./media-server-dialog.component.scss']
})
export class MediaServerDialogComponent implements OnInit {
  @ViewChild('video', { static: false }) video!: ElementRef;

  module: Module;
  configuration: any;

  folders: AvMediaItem[] = [];

  renderers: Module[] = [];
  selectedRenderer: string;

  rootFolder: AvMediaItem = {Title: 'Root folder', Id: '0', Class: 'object.container', Creator: null};
  mediaItems: AvMediaItem[] = [];
  currentPath: AvMediaItem[] = [this.rootFolder];
  currentMedia: AvMediaItem;

  showPlayer = false;
  isLoading = false;

  constructor(
    public yot: YotService,
    @Inject(MAT_DIALOG_DATA) data: {module: Module, configuration: any}
  ) {
    this.module = data.module;
    this.configuration = data.configuration;
    this.renderers = this.getRenderers();
    this.selectedRenderer = this.configuration['renderer'];
    this.currentPath = this.configuration['currentPath'] || this.currentPath;
    this.yot.translate.get('root_folder')
      .subscribe((v) => {
        this.rootFolder.Title = v;
        this.currentPath = [this.rootFolder];
      });
  }

  ngOnInit() {
    this.mediaBrowse(this.getCurrentPath());
  }

  getMediaItemDetails(item: AvMediaItem) {
    const subject = new Subject<any>();
    this.isLoading = true;
    this.module.control(HomegenieUpnpApi.AvMedia.GetItem, item.Id)
      .subscribe({
        next: (res) => {
          const details = res.response?.item;
          item.Creator = null;
          item.Details = details;
          item.Resources = {
            image: '',
            video: {mp4: '', webm: '', mpeg: ''}
          }
          let thumbnailUrl = '';
          if (details) {
            if (item.Type === 'video' || item.Type === 'audio') {
              const resources = details.res;
              for (let k in resources) {
                const res = resources[k];
                const resourceText = res['#text'];

                if (item.Duration == null) {
                  item.Duration = res['@duration'] || res['duration'];
                }

                if (item.Info == null) {
                  if (item.Type === 'video') {
                    item.Info = res['@resolution'] || res['resolution'];
                  } else {
                    item.Info = (res['@sampleFrequency'] || res['sampleFrequency']) + ' Hz';
                  }
                }

                if (res['@protocolInfo']) {
                  const protocolInfo = res['@protocolInfo'];
                  if (protocolInfo.indexOf(':image/') > 0
                    || protocolInfo.indexOf('thumb:') > 0
                    || protocolInfo.indexOf(':poster:') > 0
                    || protocolInfo.indexOf(':fanart:') > 0) {
                    thumbnailUrl = resourceText;
                  } else if (item.MediaUrlBrowser == null && protocolInfo.indexOf(':video/webm') > 0) {
                    item.MediaUrlBrowser = resourceText;
                    //item.ProtocolInfo = protocolInfo;
                  } else if (item.MediaUrlBrowser == null && protocolInfo.indexOf(':video/mp4') > 0) {
                    item.MediaUrlBrowser = resourceText;
                    //item.ProtocolInfo = protocolInfo;
                  }
                  if (item.MediaUrl == null && (protocolInfo.indexOf(':video/') > 0 || protocolInfo.indexOf(':audio/') > 0)) {
                    item.MediaUrl = resourceText;
                    item.ProtocolInfo = protocolInfo;
                  }
                } else if (res['content'] && res['protocolInfo']) {
                  const protocolInfo = res['protocolInfo'];
                  const content = res['content'];
                  if (protocolInfo.indexOf(":DLNA.ORG_PN=JPEG_TN") > 0 && thumbnailUrl === '') {
                    thumbnailUrl = content;
                  } else if (protocolInfo.indexOf(":DLNA.ORG_PN=JPEG_LRG") > 0) {
                    thumbnailUrl = content;
                  }
                }
              }
            } else if (item.Type === 'image') {
              item.Info = null;
              const resources = details.res;
              for (let k in resources) {
                const res = resources[k];
                const resourceText = res['#text'];
                if (item.Duration == null) {
                  item.Duration = res['@size'] || res['size'];
                }
                if (item.Info == null) {
                  item.Info = res['@resolution'] || res['resolution'];
                }

                if (res['@protocolInfo']) {
                  const protocolInfo = res['@protocolInfo'];
                  if (item.MediaUrl == null && protocolInfo.indexOf(':image/') > 0) {
                    item.MediaUrl = resourceText;
                  } else if (protocolInfo.indexOf(':image/') > 0 || protocolInfo.indexOf('thumb:') > 0 || protocolInfo.indexOf(':poster:') > 0 || protocolInfo.indexOf(':fanart:') > 0) {
                    thumbnailUrl = resourceText;
                  }
                } if (res['content'] && res['protocolInfo']) {
                  const protocolInfo = res['protocolInfo'];
                  const content = res['content'];
                  if (protocolInfo.indexOf(':DLNA.ORG_PN=JPEG_SM') > 0 && thumbnailUrl === '') {
                    thumbnailUrl = content;
                  } else if (protocolInfo.indexOf(':DLNA.ORG_PN=JPEG_TN') > 0&& thumbnailUrl === '') {
                    thumbnailUrl = content;
                  } else if (protocolInfo.indexOf(':DLNA.ORG_PN=JPEG_LRG') > 0) {
                    item.MediaUrl = content;
                    if (res['size']) {
                      item.Duration = res['size'];
                    }
                    if (res['resolution']) {
                      item.Info = res['resolution'];
                    }
                  }
                }
              }
            }
            item.Duration = item.Duration?.replace('.000', '');
            // TODO: check @size if size is greater than @500Kb do not consider as a valid thumbnail
            item.CoverImage = thumbnailUrl;
          }
          this.isLoading = false;
          subject.next(item);
          subject.complete();
        }
      });
    return subject;
  }

  onFolderSelected(item: AvMediaItem) {
    this.showPlayer = false;
    const ci = this.currentPath.indexOf(item);
    if (ci != -1) {
      this.currentPath.splice(ci);
    }
    this.currentPath.push(item);
    this.configuration['currentPath'] = this.currentPath;
    this.folders = [];
    this.mediaItems = [];
    this.mediaBrowse(item);
  }

  onMediaItemSelected(item: AvMediaItem) {
    this.currentMedia = item;
    if (this.selectedRenderer == null) {
      this.showPlayer = true;
      //setTimeout(() => {
      //  const video = this.video.nativeElement;
      //}, 100);
    } else {
      this.isLoading = true;
      const mediaRenderer = this.yot.getModule(this.selectedRenderer);
      const metaData = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>" +
        "<DIDL-Lite xmlns=\"urn:schemas-upnp-org:metadata-1-0/DIDL-Lite/\" xmlns:dc=\"http://purl.org/dc/elements/1.1/\" xmlns:sec=\"http://www.sec.co.kr/\" xmlns:upnp=\"urn:schemas-upnp-org:metadata-1-0/upnp/\">\n" +
        "<item id=\"f-0\" parentID=\"0\" restricted=\"0\">" +
        "<dc:title>" + item.Title + "</dc:title>" +
        "<dc:creator>" + item.Creator + "</dc:creator>" +
        "<upnp:class>" + item.Class + "</upnp:class>" +
        "<res protocolInfo=\"" + item.ProtocolInfo + "\" sec:URIType=\"public\">" + item.MediaUrl + "</res>" +
        "</item>" +
        "</DIDL-Lite>";
      mediaRenderer
          .control(HomegenieUpnpApi.AvMedia.SetUri, `${encodeURIComponent(item.MediaUrl)}/${encodeURIComponent(metaData)}`)
          .subscribe((res) => {
            mediaRenderer.control(HomegenieUpnpApi.AvMedia.Play)
              .subscribe((res) => {
                // Play successful
                this.isLoading = false;
              });
        });
    }
  }

  onSelectedRendererChange(e: MatRadioChange) {
    this.selectedRenderer = e.value;
    this.configuration['renderer'] = e.value;
  }

  private getRenderers() {
    return this.yot.modules
      .filter((m) => m.type === ModuleType.MediaReceiver);
  }

  private getCurrentPath() {
    return this.currentPath[this.currentPath.length - 1];
  }

  private mediaBrowse(folder: AvMediaItem) {
    this.isLoading = true;
    this.module
      .control(HomegenieUpnpApi.AvMedia.Browse, folder.Id)
      .subscribe({
        next: (res) => {
          if (res.response && (res.response as AvMediaItem[]).forEach) {
            (res.response as AvMediaItem[]).forEach((item) => {
              if (AvMediaItem.isFolder(item)) {
                this.folders.push(item);
              } else {
                if (item.Class.startsWith('object.item.videoItem') || item.Class.startsWith('object.item.audioItem')) {
                  item.Type = item.Class.startsWith('object.item.videoItem') ? 'video' : 'audio';
                } else if (item.Class.startsWith('object.item.imageItem')) {
                  item.Type = 'image';
                }
                this.mediaItems.push(item);
                this.getMediaItemDetails(item);
              }
            });
          }
          this.isLoading = false;
        },
        error: (err) => {
          // TODO: ....
        }
      });
  }
}
