import {Component, EventEmitter, Input, OnInit, Output} from "@angular/core";
import {MatSnackBar} from "@angular/material/snack-bar";

import {Module, ModuleField} from "../../services/yot/module";
import {OptionField, OptionFieldTypeId} from "../../services/yot/module-options";
import {YotService} from "../../services/yot/yot.service";

export class FieldChangeEvent {
  field: ModuleField;
  value: any;
}

@Component({
  selector: '-control-field-base',
  template: 'no-ui'
})
export class ControlFieldBase implements OnInit {
  translationPrefix: string;
  @Input()
  module: Module;
  @Input()
  data: OptionField;
  @Output()
  fieldChange: EventEmitter<FieldChangeEvent> = new EventEmitter();
  @Output()
  requestModal: EventEmitter<any> = new EventEmitter();
  @Input()
  multiple: boolean = false;

  protected originalValue: any;

  constructor(
    protected _snackBar: MatSnackBar,
    public yot: YotService
  ) { }

  private _description = '';
  get description(): string {
    return this._description;
  }
  get value(): any {
    return this.data.field && this.data.field.value ? this.data.field.value : this.default;
  }
  get default(): string {
    return ControlFieldBase.getOptionFieldDefaultValue(this.data);
  }

  ngOnInit(): void {
    if (this.module) {
      this.translationPrefix = this.module.getAdapter()?.translationPrefix || '';
    }
    this._description = this.data.description;
    if (this.data.field) {
      const key = `${this.translationPrefix}.$options.${this.data.pid}.${this.data.field.key}`;
      this.yot.translate.get(key).subscribe((res) => {
        if (res !== key) {
          this._description = res;
        }
      });
      this.originalValue = this.value;
    }
  }

  onFieldChange(e): void {
    this.fieldChange.emit({ field: this.data.field, value: e.value });
  }

  onRequestModal(e: any) {
    this.requestModal.emit({ field: this.data.field, value: e.value });
  }

  cancelModal(): void {}
  saveModal(): void {}

  reset() {
    if (this.data.field) {
      this.data.field.value = this.originalValue;
      this.fieldChange.emit({ field: this.data.field, value: this.originalValue });
    }
  }

  static getOptionFieldDefaultValue(o: OptionField) {
    // TODO: 'Slider' is currently the only field type providing a default value via type options
    // TODO: add a default option also for other fields (maybe?)
    switch (o.type.id) {
      case OptionFieldTypeId.Slider:
        return o.type.options[3] || o.type.options[0];
    }
    return '';
  }
}
