import {Component, Input, OnDestroy, OnInit} from '@angular/core';
import {FLD, YotService} from '../../services/yot/yot.service';
import {Module, ModuleType} from '../../services/yot/module';
import {PagesRoute} from "../../pages-route";
import {Dashboard} from "../../services/dashboard/dashboard";
import {SensorField} from "../../api/widgets/sensor-widget.api";
import {UtilsService} from "../../services/utils.service";

class GroupStats {
  public luminance: number | void;
  public temperature: number | void;
  public humidity: number | void;
  public watts: number | void;
  public operatingSwitches: number | void;
  public operatingLights: number | void;
}

@Component({
  selector: 'app-dashboard-list-item',
  templateUrl: './dashboard-list-item.component.html',
  styleUrls: ['./dashboard-list-item.component.scss']
})
export class DashboardListItemComponent implements OnInit, OnDestroy {
  @Input()
  dashboard: Dashboard;

  stats: GroupStats = new GroupStats();

  Route = PagesRoute;

  get selected(): boolean {
    const ds = this.yot.dashboardService;
    return ds.getCurrentDashboard() && ds.getCurrentDashboard().name === this.dashboard.name;
  }

  private updateTimeout = null;

  constructor(public yot: YotService, private utils: UtilsService) { }

  ngOnInit(): void {
    this.updateTimeout = setInterval(() => {
      this.update();
    }, 1000);
  }
  ngOnDestroy(): void {
    clearInterval(this.updateTimeout);
  }

  private update(): void {
    let modules = this.dashboard.widgets.filter((w) => w.module).map((w) => this.yot.getModuleByRef(w.module));
    modules = modules
      .sort((m1, m2) => m1.id > m2.id ? 1 : m1.id < m2.id ? -1 : 0)
      .filter(function(item, pos, ary) {
      return !pos || item != ary[pos - 1];
    });
    this.stats.luminance = this.getAverageValue(modules, SensorField.Luminance);
    this.stats.temperature = this.getAverageValue(modules, SensorField.Temperature);
    this.stats.humidity = this.getAverageValue(modules, SensorField.Humidity);
    this.stats.watts = this.getTotalValue(modules, SensorField.Meter.Watts);
    this.stats.operatingSwitches = this.getDeviceTypeCount(modules, [ModuleType.Switch]);
    this.stats.operatingLights = this.getDeviceTypeCount(modules, [ModuleType.Light, ModuleType.Dimmer, ModuleType.Color]);
  }

  private getAverageValue(modules: Module[], fieldName: string): number | void {
    let averageValue = 0;
    let count = 0;
    modules.forEach((m) => {
      const field = m?.field(fieldName);
      if (field && field.value != null) {
        averageValue += this.utils.getFloatValue(field.value);
        count++;
      }
    });
    if (count > 0) {
      return (averageValue / count);
    }
  }

  private getTotalValue(modules: Module[], fieldName: string): number | void {
    let totalValue = null;
    modules.forEach((m) => {
      const field = m?.field(fieldName);
      if (field && field.value != null) {
        totalValue += this.utils.getFloatValue(field.value);
      }
    });
    return totalValue;
  }

  private getMostRecentValue(modules: Module[], fieldName: string): number | void {
    // TODO: ...
  }

  private getDeviceTypeCount(modules: Module[], deviceTypes: string[]): number | void {
    return modules.filter((m) => deviceTypes.indexOf(m?.type) >= 0 && m?.field(FLD.Status.Level) && +m?.field(FLD.Status.Level).value > 0).length;
  }

}
