import {Component, Input, OnInit} from '@angular/core';
import {HomegenieAdapter, ResponseCode} from "../homegenie-adapter";
import {MatDialog} from "@angular/material/dialog";
import {HomegenieApi} from "../homegenie-api";
import {HomegenieZigbeeApi} from "../homegenie-zigbee-api";
import {
  ZigbeeDeviceManagerDialogComponent
} from "./zigbee-device-manager-dialog/zigbee-device-manager-dialog.component";
import {
  ActionConfirmDialogComponent,
  ActionConfirmDialogConfig
} from "../../../components/dialogs/action-confirm-dialog/action-confirm-dialog.component";
import {MatSelectChange} from "@angular/material/select";

@Component({
  selector: 'app-zigbee-setup-form',
  templateUrl: './zigbee-setup-form.component.html',
  styleUrls: ['./zigbee-setup-form.component.scss']
})
export class ZigbeeSetupFormComponent implements OnInit {
  @Input()
  adapter: HomegenieAdapter;

  serialPorts: { value: string, content: string }[] = [];

  portName = '/dev/ttyACM0';
  flowControl = '0'; // None = 0, RTS/CTS = 1, XON/XOFF = 2
  driverName = 'conbee';

  statusCheckInterval;
  isLoading = false;
  isOnline = false;

  constructor(
    public dialog: MatDialog
  ) {
  }

  ngOnInit(): void {
    this.statusCheckInterval = setInterval(() => {
      if (this.isLoading) return;
      this.adapter.apiCall(HomegenieApi.Config.Interfaces.Status)
        .subscribe((res) => {
          // TODO: !!! create enum for 'HomeAutomation.ZigBee' !!
          // TODO: !!! create enum for 'HomeAutomation.ZigBee' !!
          const interfaceStatus = res.response.find((i) => i.Domain === 'HomeAutomation.ZigBee');
          const wasOnline = this.isOnline;
          this.isOnline = interfaceStatus && interfaceStatus.IsConnected === 'True';
          if (!wasOnline && this.isOnline) {
            this.adapter.connect().subscribe((res) => {
              this.isLoading = false;
            }, (err) => {
              // TODO: report error
              console.log(err);
              this.isLoading = false;
            });
          } else {
            this.isLoading = false;
          }
        }, (err) => {
          // TODO: report error
          console.log(err);
          this.isLoading = false;
        });
    }, 2000);
    this.loadPorts();
  }
  ngOnDestroy() {
    if (this.statusCheckInterval) {
      clearInterval(this.statusCheckInterval);
    }
  }

  onPortChange(e): void {
    const command = HomegenieZigbeeApi.Options.Set.Port
      .replace('{{portName}}', encodeURIComponent(this.portName));
    this.isLoading = true;
    this.adapter.apiCall(command)
      .subscribe((res) => {
        if (res.code === ResponseCode.Success) {
          console.log('ZigBee Set Port', this.portName, res);
        } else {
          // TODO: ... log error
        }
        this.isLoading = false;
      });
  }
  onFlowControlChange($event: MatSelectChange) {
    const command = HomegenieZigbeeApi.Options.Set.FlowControl
      .replace('{{flowControl}}', encodeURIComponent(this.flowControl));
    this.isLoading = true;
    this.adapter.apiCall(command)
      .subscribe((res) => {
        if (res.code === ResponseCode.Success) {
          console.log('ZigBee Set FlowControl', this.flowControl, res);
        } else {
          // TODO: ... log error
        }
        this.isLoading = false;
      });
  }
  onDriverChange($event: MatSelectChange) {
    const command = HomegenieZigbeeApi.Options.Set.Driver
      .replace('{{driverName}}', encodeURIComponent(this.driverName));
    this.isLoading = true;
    this.adapter.apiCall(command)
      .subscribe((res) => {
        if (res.code === ResponseCode.Success) {
          console.log('ZigBee Set Driver', this.driverName, res);
        } else {
          // TODO: ... log error
        }
        this.isLoading = false;
      });
  }
  onDeviceManagerButtonClick(e): void {
    const dialogRef = this.dialog.open(ZigbeeDeviceManagerDialogComponent, {
      // height: '400px',
      // width: '600px',
      maxWidth: '800px',
      disableClose: true,
      data: {adapter: this.adapter}
    });
    dialogRef.afterClosed().subscribe(() => {
      this.adapter.yot.saveConfiguration();
    });
  }

  loadPorts(): void {
    this.adapter.apiCall(HomegenieApi.Config.Interfaces.Configure.Hardware.SerialPorts)
      .subscribe((res) => {
        if (res.code === ResponseCode.Success && res.response && res.response.length > 0) {
          this.serialPorts = res.response;
        }
        this.adapter.apiCall(HomegenieZigbeeApi.Options.Get.Port).subscribe((res2) => {
          if (res2.code === ResponseCode.Success) {
            this.portName = res2.response.ResponseValue;
          } else {
            // TODO: ... log error
          }
        });
      });
    this.adapter.apiCall(HomegenieZigbeeApi.Options.Get.Driver).subscribe((res2) => {
      if (res2.code === ResponseCode.Success) {
        this.driverName = res2.response.ResponseValue || "conbee";
      } else {
        // TODO: ... log error
      }
    });
  }

  onSoftResetButtonClick(event: MouseEvent) {
    const dialogRef = this.dialog.open(ActionConfirmDialogComponent, {
      width: '320px',
      disableClose: false,
      data: {
        // TODO: add translations
        title: 'Confirm soft reset?',
        // TODO: add translations
        message: `All nodes will be removed from the controller.`
      } as ActionConfirmDialogConfig
    });
    dialogRef.afterClosed().subscribe((confirm) => {
      if (confirm) {
        this.isLoading = true;
        this.adapter.apiCall('HomeAutomation.ZigBee/0/Controller.SoftReset/')
          .subscribe((res) => {
            this.adapter.reloadModules()
              .subscribe((mods) => this.isLoading = false);
          });
      }
    });
  }
}
