import {Component, EventEmitter, Input, OnInit, Output} from '@angular/core';
import {HomegenieApi, Program, ResponseStatus} from "../../homegenie-api";
import {ApiResponse, HomegenieAdapter} from "../../homegenie-adapter";

export class SetupSystemConfiguration {
  includeDemo = true;
  configureGPIO = false;
  configureX10 = false;
  configureZWave = false;
  configureZigBee = false;
  configureVoiceRecognizer = false;
  configureVoiceSynthesizer = false;
  configureManually = false;
  restoreBackup: any = false;
  restoreProgramList: Array<Program> = [];
  restoreSystemInfo: {SystemName: string, RequirePassword: boolean, ServiceHost: string, ServicePort: string, Interfaces: any[]};
  packagesToInstall: string[] = [];
}

@Component({
  selector: 'app-restore-backup',
  templateUrl: './restore-backup.component.html',
  styleUrls: ['./restore-backup.component.scss']
})
export class RestoreBackupComponent implements OnInit {
  @Input()
  adapter: HomegenieAdapter;
  @Input()
  config = new SetupSystemConfiguration();
  @Output()
  backupFileLoaded = new EventEmitter<SetupSystemConfiguration>();

  isLoading = false;
  errorMessage = '';

  uploadedFiles: Array<File> = [];

  constructor() { }

  ngOnInit(): void {
    if (this.config.restoreBackup) {
      this.uploadedFiles = [ this.config.restoreBackup ];
    }
  }

  onBackupFileSelected() {
    this.config.restoreSystemInfo = null;
    this.config.restoreProgramList = [];
    if (this.uploadedFiles.length > 0) {
      this.config.restoreBackup = this.uploadedFiles[0];
      this.restoreBackupFile(this.uploadedFiles[0]);
    } else {
      this.config.restoreBackup = null;
      this.backupFileLoaded.emit(this.config);
    }
  }

  private loadBackupProgramList() {
    this.adapter.apiCall(HomegenieApi.SystemConfig.System.ConfigurationRestoreStep1)
      .subscribe((ar: ApiResponse) => {
        this.isLoading = false;
        if (ar.response === null) {
          this.uploadedFiles = [];
          // Invalid backup file
          this.adapter.yot.notify('Error', 'Not a valid backup file.');
        } else {
          this.config.restoreProgramList = ar.response;
          this.backupFileLoaded.emit(this.config);
        }
      }, (error) => {
        this.errorMessage = error.message;
        this.isLoading = false;
      });
  }
  private restoreBackupFile(file: File) {
    this.isLoading = true;
    let formData:FormData = new FormData();
    formData.append('uploadFile', file, file.name);
    this.adapter.apiCall(HomegenieApi.SystemConfig.System.ConfigurationRestore(file.name), formData)
      .subscribe((ar: ApiResponse) => {
        if (ar.response?.Status === ResponseStatus.Ok) {
          this.config.restoreSystemInfo = JSON.parse(ar.response.Message);
          this.loadBackupProgramList();
        } else {
          this.uploadedFiles = [];
          this.isLoading = false;
          // Invalid backup file
          this.adapter.yot.notify('Error', 'Not a valid backup file.');
        }
      }, (error) => {
        this.errorMessage = error.message;
        this.uploadedFiles = [];
        this.isLoading = false;
      });
  }
}
