import {NgModule} from '@angular/core';
import {RouterModule, Routes} from '@angular/router';
import {SetupPageComponent} from './pages/setup-page/setup-page.component';
import {DashboardPageComponent} from './pages/dashboard-page/dashboard-page.component';
import {ProgramEditorComponent} from './pages/automation/program-editor/program-editor.component';
import {PreferencesPageComponent} from "./pages/preferences-page/preferences-page.component";
import {PagesRoute} from "./pages-route";
import {SchedulerPageComponent} from "./pages/scheduler-page/scheduler-page.component";
import {AutomationPageComponent} from "./pages/automation-page/automation-page.component";
import {MaintenancePageComponent} from "./pages/maintenance-page/maintenance-page.component";
import {CanDeactivateGuard} from "./services/can-deactivate-guard.service";
import {WidgetsPageComponent} from "./pages/widgets-page/widgets-page.component";
import {WidgetEditorComponent} from "./pages/automation/widget-editor/widget-editor.component";

const routes: Routes = [
  { path: PagesRoute.HomePage, component: DashboardPageComponent },
  { path: `${PagesRoute.HomePage}/:name`, component: DashboardPageComponent },
  { path: PagesRoute.SetupPage, component: SetupPageComponent },
  { path: PagesRoute.PreferencesPage, component: PreferencesPageComponent },
  { path: PagesRoute.MaintenancePage, component: MaintenancePageComponent },
  { path: PagesRoute.SchedulerPage, component: SchedulerPageComponent},
  {
    path: PagesRoute.AutomationPage,
    component: AutomationPageComponent,
    canDeactivate: [CanDeactivateGuard]
  },
  {
    path: `${PagesRoute.AutomationPage}/:aid/:pid`,
    component: ProgramEditorComponent,
    canDeactivate: [CanDeactivateGuard]
  },
  {
    path: PagesRoute.WidgetsPage,
    component: WidgetsPageComponent,
    canDeactivate: [CanDeactivateGuard]
  },
  {
    path: `${PagesRoute.WidgetsPage}/:path/:name`,
    component: WidgetEditorComponent,
    canDeactivate: [CanDeactivateGuard]
  },
  { path: '**', redirectTo: PagesRoute.HomePage }
];

@NgModule({
  imports: [RouterModule.forRoot(routes)],
  exports: [RouterModule]
})
export class AppRoutingModule { }
