import * as Blockly from 'blockly';

export class CustomCategory extends Blockly.ToolboxCategory {
  /**
   * Constructor for a custom category.
   * @override
   */
  constructor(categoryDef, toolbox, opt_parent) {
    super(categoryDef, toolbox, opt_parent);
  }
  /** @override */
  addColourBorder_(colour){
    this.rowDiv_.style.backgroundColor = colour;
  }
  /** @override */
  setSelected(isSelected){
    // We do not store the label span on the category, so use getElementsByClassName.
    const labelDom = this.rowDiv_.getElementsByClassName('blocklyTreeLabel')[0] as HTMLElement;
    const style = this.rowDiv_.style;
    if (isSelected) {
      // Change the background color of the div to white.
      style.backgroundColor = 'white';
      // Set the colour of the text to the colour of the category.
      labelDom.style.color = this.colour_;
      // icon style
      (this.iconDom_ as HTMLElement).style.color = this.colour_;
    } else {
      // Set the background back to the original colour.
      style.backgroundColor = this.colour_;
      // Set the text back to white.
      labelDom.style.color = 'white';
      // icon style
      (this.iconDom_ as HTMLElement).style.color = 'white';
    }
    // This is used for accessibility purposes.
    Blockly.utils.aria.setState(/** @type {!Element} */ (this.htmlDiv_),
      Blockly.utils.aria.State.SELECTED, isSelected);
  }
  /** @override */
  createIconDom_() {
    const icon = document.createElement('div');
    icon.className = 'material-icons';
    icon.innerHTML = this.toolboxItemDef_['icon'];
    icon.style.width = '24px';
    icon.style.height = '24px';
    icon.style.color = 'white';
    icon.style.opacity = '0.7';
    icon.style.fontSize = '22px';
    icon.style.marginLeft = '5px';
    return icon;
  }
}
