import {Component, EventEmitter, Input, OnInit, Output} from '@angular/core';
import {Module, ModuleField} from "../../services/yot/module";
import {ModuleOptions} from "../../services/yot/module-options";
import {CMD, YotService} from "../../services/yot/yot.service";
import {DynamicControlComponent} from "../controls/dynamic-control/dynamic-control.component";

@Component({
  selector: '-dynamic-options-base',
  template: 'no-ui'
})
export class DynamicOptionsBase implements OnInit {
  @Input()
  module: Module;
  @Output()
  changesUpdate = new EventEmitter<any[]>();

  @Output()
  modalRequest = new EventEmitter<boolean>();

  modalComponent: DynamicControlComponent = null;

  changes: { field: ModuleField, value: any }[] = [];

  optionsList: ModuleOptions[] = [];
  translationPrefix: string;

  isLoading = false;

  enableModalEdit = false;

  get isChanged(): boolean {
    return this.changes.length > 0;
  }

  constructor(
    protected yot: YotService
  ) { }

  ngOnInit(): void {
    if (this.module && this.module.getAdapter()) {
      this.isLoading = true;
      this.translationPrefix = this.module.getAdapter().translationPrefix;
      // populate module features list
      this.module.control(CMD.Options.Get).subscribe((res: ModuleOptions[]) => {
        if (this.module.type === 'program') {
          this.optionsList[0] = {...this.optionsList[0], ...res as any};
        } else {
          this.optionsList = this.optionsList || [];
          this.optionsList.push(...res);
        }
        setTimeout(() => {
          this.optionsList.forEach((o) => {
            this.translateModuleOption(o);
          });
          this.isLoading = false;
        });
      }, (err) => {
        // TODO: handle error
        this.isLoading = false;
      });
    } else {
      // TODO: log this exception
    }
  }

  cancelModal(): void {
    this.modalComponent?.controlField?.cancelModal();
    this.modalComponent = null;
    this.enableModalEdit = false;
  }
  saveModal(): void {
    this.modalComponent?.controlField?.saveModal();
    this.modalComponent = null;
    this.enableModalEdit = false;
  }
  onRequestModal(dynamicControl: DynamicControlComponent, enable: boolean) {
    this.modalComponent = enable ? dynamicControl : null;
    this.enableModalEdit = enable;
    this.modalRequest.emit(enable);
  }

  applyChanges(): void {
    throw new Error('Not implemented!');
  }

  onFieldChange(o: DynamicControlComponent, e): void {
    if (!e) {
      console.warn(o, e);
      return;
    }
    if (e.field.value === e.value) {
      this.changes = this.changes.filter((c) => c.field.key !== e.field.key);
    } else {
      let change = this.changes.find((c) => c.field.key === e.field.key);
      if (change) {
        change.value = e.value;
      } else {
        this.changes.push(e);
      }
    }
    this.changesUpdate.emit(this.changes);
  }

  protected translateModuleOption(o: ModuleOptions) {
    const titleKey = `${this.translationPrefix}.$options.${o.id}.Title`;
    this.yot.translate.get(titleKey).subscribe((tr) => {
      if (tr !== titleKey) {
        o.name = tr;
      }
    });
    const descriptionKey = `${this.translationPrefix}.$options.${o.id}.Description`;
    this.yot.translate.get(descriptionKey).subscribe((tr) => {
      if (tr !== descriptionKey) {
        o.description = tr;
      }
    });
  }
}
