import {Component, OnChanges, OnDestroy, OnInit, SimpleChanges} from '@angular/core';
import {ModuleField} from '../../services/yot/module';
import {WidgetBaseComponent} from "../widget-base.component";
import {WidgetActionRequestAction} from "../common-parts/widget-actions-menu/widget-actions-menu.component";

export class SensorFieldData {
  field: ModuleField;
  unit: any;
}

export class SensorData {
  public sensors: SensorFieldData[];
  public system?: ModuleField[];
}

@Component({
  selector: 'app-sensor',
  templateUrl: './sensor.component.html',
  styleUrls: ['./sensor.component.scss']
})
export class SensorComponent extends WidgetBaseComponent implements OnInit, OnDestroy, OnChanges {
  sensor: SensorFieldData;
  currentIndex = -1;
  private _direction = 1;
  get direction(): number {
    return this._direction;
  };
  set direction(n: number) {
    this._direction = n;
    this.showNext();
  }

  private refreshTimeout: any = null;

  get lastUpdateTimestamp(): number {
    if (!this.sensor) return 0;
    let lastUpdateTimestamp = 0;
    const f = this.sensor.field;
    const fieldTimestamp = new Date(f.timestamp).getTime();
// TODO: create utility function "IsSensorField(....)" also applies to `homegenie-adapter.ts`
    if ((f.key.startsWith('Status.')
      || f.key.startsWith('Sensor.')
      || f.key.startsWith('Meter.')
      || f.key.startsWith('System.')
      || f.key.startsWith('StatusWidget.')
      || f.key.startsWith('Receiver.'))
      && fieldTimestamp > lastUpdateTimestamp) {
        lastUpdateTimestamp = fieldTimestamp;
    }
    return lastUpdateTimestamp;
  }

  get sensorsCount(): number {
    if (!this.data || !this.data.sensors) return 0;
    if (!this.sensor) {
      this.sensor = this.data.sensors[0];
    }
    return this.data.sensors.length;
  }

  ngOnInit(): void {
    super.ngOnInit();
    this.showNext();
  }
  ngOnDestroy(): void {
    this.stopTimeout();
  }
  ngOnChanges(changes: SimpleChanges) {
    // changes.prop contains the old and the new value...
    if (changes.options && changes.options.currentValue.data && changes.options && JSON.stringify(changes.options.currentValue.data.sensors) !== JSON.stringify(this.data.sensors)) {
      console.log(changes);
    }
  }

  onSensorFieldClick(sensor) {
    this.widgetActionRequest.emit({action: WidgetActionRequestAction.showLogs, data: {field: sensor.field.key}});
  }

  private startTimeout(): void {
    clearTimeout(this.refreshTimeout);
    this.refreshTimeout = setTimeout(this.showNext.bind(this), 5000);
  }
  private stopTimeout(): void {
    clearTimeout(this.refreshTimeout);
  }
  private showNext(): void {
    if (this.sensorsCount === 0) return;
    if (this._direction > 0 && this.currentIndex < this.data.sensors.length - 1) {
      this.currentIndex++;
    } else if (this._direction < 0 && this.currentIndex > 0) {
      this.currentIndex--;
    } else {
      this.currentIndex = this._direction > 0 ? 0 : this.sensorsCount - 1;
    }
    this.sensor = this.data.sensors[this.currentIndex];
    if (this.sensorsCount > 1) {
      this.startTimeout();
    }
  }
}
