import {Component, Inject, OnInit, ViewChild} from '@angular/core';
import {HomegenieAdapter} from "../../homegenie-adapter";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {Subject} from "rxjs";
import {HomegenieZigbeeApi} from "../../homegenie-zigbee-api";
import {ZigbeeDeviceManagerComponent} from "../zigbee-device-manager/zigbee-device-manager.component";

@Component({
  selector: 'app-zigbee-device-manager-dialog',
  templateUrl: './zigbee-device-manager-dialog.component.html',
  styleUrls: ['./zigbee-device-manager-dialog.component.scss']
})
export class ZigbeeDeviceManagerDialogComponent implements OnInit {
  @ViewChild('deviceManagerComponent')
  deviceManagerComponent: ZigbeeDeviceManagerComponent;

  adapter: HomegenieAdapter;

  uiMode = 'list';

  addedNodeId = '';
  addNodeTime = 0;

  nodeAddInterval;

  constructor(@Inject(MAT_DIALOG_DATA) data) {
    this.adapter = data.adapter;
  }

  ngOnInit(): void {
  }

  onAddNewNodeClick() {
    this.uiMode = 'node_add';
    clearInterval(this.nodeAddInterval);
    this.addNodeTime = 60;
    this.nodeAddInterval = setInterval(() => this.addNodeTime > 0 && this.addNodeTime--, 1000);
    this.addNode().subscribe({
      next: (res) => {
        this.addedNodeId = res.response.Message;
        this.uiMode = 'node_add_done';
        this.deviceManagerComponent.refresh();
        clearInterval(this.nodeAddInterval);
      },
      error: (err) => {
        this.adapter.yot.notify('Add node error', err.message);
        this.uiMode = 'list';
        clearInterval(this.nodeAddInterval);
      }
    });
  }


  addNode(): Subject<any> {
    return this.adapter.apiCall(HomegenieZigbeeApi.Master.Controller.NodeAdd);
  }

  removeNode(): Subject<any> {
    return this.adapter.apiCall(HomegenieZigbeeApi.Master.Controller.NodeRemove);
  }

}
