import {Directive, HostListener, Input} from '@angular/core';

@Directive({selector: '[regExpFilter]'})
export class RegExpFilterInputDirective {

  @Input()
  regExpFilter: any;

  @HostListener('keydown',['$event']) onKeyDown(event: any) {
    let k=event.target.value + event.key;
    if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Backspace','Tab','Alt',
      'Shift','Control','Enter','Delete','Meta'].includes(event.key)) return;
    let re = new RegExp(this.regExpFilter);
    if(!re.test(k)) event.preventDefault();
  }
}
