import {GeolocationAdapter, LocationInfo} from "../geolocation-adapter";
import {Subject} from "rxjs";
import {HomegenieAdapter} from "./homegenie-adapter";
import {HomegenieApi} from "./homegenie-api";

export class HomegenieGeolocationAdapter implements GeolocationAdapter {

  constructor(private hg: HomegenieAdapter) {}

  getLocationCoordinates(locationName: string): Subject<LocationInfo> {
    const locationSubject = new Subject<LocationInfo>();
    this.hg.apiCall(HomegenieApi.SystemConfig.Location.GeoCode(locationName))
      .subscribe((res) => {
        const pos = res.response[0].geometry.location;
        locationSubject.next({
          name: locationName,
          latitude: pos.lat,
          longitude: pos.lng
        });
        locationSubject.complete();
      }, (err) => locationSubject.error(err));
    return locationSubject;
  }

  lookup(coordinates: {lng: number, lat: number}): Subject<LocationInfo> {
    const locationSubject = new Subject<LocationInfo>();
    this.hg.apiCall(HomegenieApi.SystemConfig.Location.Lookup(`${coordinates.lat},${coordinates.lng}`))
      .subscribe((res) => {
console.log(res)
        let locationName = '?';
        if (res.response.plus_code.compound_code) {
          locationName = res.response.plus_code.compound_code
            .split(' ').splice(1).join(' ');
        }
        locationSubject.next({
          name: locationName,
          latitude: coordinates.lat,
          longitude: coordinates.lng
        })
        locationSubject.complete();
      }, (err) => locationSubject.error(err));
    return locationSubject;
  }

  search(locationFilter: string): Subject<string[]> {
    const locationListSubject = new Subject<string[]>();
    this.hg.apiCall(HomegenieApi.SystemConfig.Location.Search(locationFilter))
      .subscribe((res) => {
        locationListSubject.next(res.response.map((r) => r.description));
        locationListSubject.complete();
      }, (error) => locationListSubject.error(error));
    return locationListSubject;
  }

}
