import {Component, Input, OnInit} from '@angular/core';
import {MatDialog} from "@angular/material/dialog";
import {ProgramsPackagerDialogComponent} from "../programs-packager-dialog/programs-packager-dialog.component";
import {HomegenieAdapter} from "../homegenie-adapter";
import {FileSelectDialogComponent} from "../../../components/dialogs/file-select-dialog/file-select-dialog.component";
import {HomegenieApi} from "../homegenie-api";
import {NavigationService} from "../../../services/navigation.service";
import {Subject} from "rxjs";

export enum PackageStatusEnum {
  Installed,
  Partial,
  NotInstalled
}

@Component({
  selector: 'app-packages-manager',
  templateUrl: './packages-manager.component.html',
  styleUrls: ['./packages-manager.component.scss']
})
export class PackagesManagerComponent implements OnInit {
  @Input()
  adapter: HomegenieAdapter;

  PackageStatus = PackageStatusEnum;

  packages: any[]; // TODO: create class for type Package and PackageItem
  repositories: string[];
  selectedRepository: string;

  selectedPackage: any;
  selectedPackagePrograms: any[];
  selectedPackageDependencies: any[];

  get isLoading(): boolean {
    return this.navigationService.isLoading;
  }

  constructor(private dialog: MatDialog, private navigationService: NavigationService) { }

  ngOnInit(): void {
    //this.refresh();
  }

  onCreatePackageClick() {
    const dialogRef = this.dialog.open(ProgramsPackagerDialogComponent, {
      disableClose: true,
      data: {
        adapter: this.adapter
      }
    });
    dialogRef.afterClosed().subscribe((packageData) => {
      if (packageData) {
        this.selectedRepository = packageData.repository;
        this.refresh()
          .subscribe(() => {
            this.selectedPackage = this.packages.find((pkg) =>
              pkg.packageId === packageData.packageId
              && pkg.repository === packageData.repository);
            this.setCurrentPackage(this.selectedPackage);
          });
      }
    });
  }

  onPackageInstall(pkg: any) {
    this.navigationService.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Config.Packages.Install(pkg.repository, pkg.id))
      .subscribe((res) => {
        console.log('Package Install', res);
        this.navigationService.isLoading = false;
        this.refresh();
      }, (err) => {
        // TODO: report error
        this.navigationService.isLoading = false;
      });
  }

  onPackageUninstall(pkg: any) {
    this.navigationService.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Config.Packages.Uninstall(pkg.repository, pkg.id))
      .subscribe((res) => {
        console.log('Package Uninstall', res);
        this.navigationService.isLoading = false;
        this.refresh();
      }, (err) => {
        // TODO: report error
        this.navigationService.isLoading = false;
      });
  }

  onPackageSelected(pkg: any) {
    if (this.selectedPackage === pkg) {
      this.setCurrentPackage(null);
    } else {
      this.setCurrentPackage(pkg);
    }
  }

  onEditPackageClick(pkg: any) {
    this.dialog.open(ProgramsPackagerDialogComponent, {
      disableClose: true,
      data: {
        adapter: this.adapter,
        package: pkg
      }
    });
  }

  onUploadPackageClick() {
    const dialogRef = this.dialog.open(FileSelectDialogComponent, {
      data: {
        accept: 'application/zip, .zip'
      }
    });
    dialogRef.afterClosed().subscribe((files) => {
      if (files && files.length > 0) {
        this.uploadPackageFile(files[0])
      }
    });
  }

  refresh(): Subject<void> {
    const subject = new Subject<void>();
    this.navigationService.isLoading = true;
    this.adapter.loadPrograms().subscribe({
      next: () => {

        this.adapter.apiCall('HomeAutomation.HomeGenie/Config/Packages.List')
          .subscribe((res) => {
            this.packages = res.response;
            this.repositories = [];
            this.packages.map((p) => {
              if (!this.repositories.includes(p.repository)) {
                this.repositories.push(p.repository);
              }
            });
            if (!this.repositories.includes(this.selectedRepository)) {
              this.selectedRepository = this.repositories[0];
            }
            this.packages.map((pkg) => {
              if (this.selectedPackage && pkg.repository === this.selectedPackage.repository && pkg.id === this.selectedPackage.id) {
                this.setCurrentPackage(pkg);
              }
              let localInstalledCount = 0;
              const localPrograms = pkg.programs
                .filter(p => p.repository === pkg.repository && p.packageId === pkg.id);
              localPrograms.forEach((p) => {
                if (p.installed) {
                  localInstalledCount++;
                }
              });
              let requireInstalledCount = 0;
              const requirePrograms = pkg.programs
                .filter(p => p.repository !== pkg.repository || p.packageId !== pkg.id);
              requirePrograms.forEach((p) => {
                if (p.installed) {
                  requireInstalledCount++;
                }
              });
              if (localInstalledCount === localPrograms.length && requireInstalledCount === requirePrograms.length) {
                pkg.status = PackageStatusEnum.Installed;
              } else if (localInstalledCount > 0) {
                pkg.status = PackageStatusEnum.Partial;
              } else {
                pkg.status = PackageStatusEnum.NotInstalled;
              }
            });
            this.navigationService.isLoading = false;
            subject.next();
            subject.complete();
          }, (err) => {
            this.navigationService.isLoading = false;
            // TODO: report error
            subject.error(err);
          });

      },
      error: (err) => {
        this.navigationService.isLoading = false;
        // TODO: report error
        subject.error(err);
      }
    });

    // TODO: get Control Groups list and Schedules list
    return subject;
  }

  getRepositoryPackages() {
    return this.packages ? this.packages.filter((p) => p.repository === this.selectedRepository) : [];
  }

  private setCurrentPackage(pkg: any) {
    if (pkg) {
      this.selectedPackage = pkg;
      this.selectedPackagePrograms = pkg.programs.filter((p) => p.repository === pkg.repository && p.packageId === pkg.id);
      this.selectedPackageDependencies = pkg.programs.filter((p) => p.repository !== pkg.repository || p.packageId !== pkg.id);
    } else {
      this.selectedPackage = null;
      this.selectedPackagePrograms = [];
      this.selectedPackageDependencies = [];
    }
  }

  private uploadPackageFile(file: File) {
    this.navigationService.isLoading = true;
    let formData:FormData = new FormData();
    formData.append('uploadFile', file, file.name);
    this.adapter.apiCall(HomegenieApi.Config.Packages.Upload(file.name), formData)
      .subscribe((ar: any) => {
        let pkg = ar.response;
        if (pkg && pkg.id) {
          this.setCurrentPackage(pkg);
        }
        this.refresh()
          .subscribe(() => {
            this.selectedRepository = pkg.repository;
            this.navigationService.isLoading = false;
          });
      }, (error) => {
        // TODO: report error
        console.log(error)
        this.navigationService.isLoading = false;
      }
    );
  }

  getPackageStatusColor(status: PackageStatusEnum) {
    return (status === this.PackageStatus.Installed ? 'mat-primary' :
      (status === this.PackageStatus.Partial ? 'mat-warn' : 'translucent'));
  }
}
