import {Component, Input, OnInit} from '@angular/core';
import {Module, ModuleType} from "../../../services/yot/module";
import {SystemApi} from "../../../api/system-api";
import {DashboardLayoutEventValue} from "../../../services/dashboard/dashboard.service";
import {YotService} from "../../../services/yot/yot.service";

@Component({
  selector: 'app-module-info',
  templateUrl: './module-info.component.html',
  styleUrls: ['./module-info.component.scss']
})
export class ModuleInfoComponent implements OnInit {
  @Input()
  module: Module;

  name: string;
  description: string;
  type: string;

  moduleTypes: any[];
  ModuleType = ModuleType;
  currentView = 0;

  get hasErrors(): boolean {
    return !this.name || !this.type;
  }
  get isChanged(): boolean {
    return this.name !== this.module.name
      || this.description !== this.module.description
      || this.type !== this.module.type;
  }

  constructor(private yot: YotService) { }

  ngOnInit(): void {
    this.name = this.module.name;
    this.description = this.module.description;
    this.type = this.module.type;
    if (this.type === ModuleType.Program) {
      this.moduleTypes = [{
        name: 'Program',
        value: ModuleType.Program,
        disabled: true
      }];
    } else {
      this.moduleTypes = Object.keys(ModuleType).filter((t) => {
        return ModuleType[t] !== ModuleType.Program ? t : undefined;
      }).map((k) => ({
        name: k,
        value: ModuleType[k]
      }));
    }
  }

  apply() {
    this.module.name = this.name;
    this.module.description = this.description;
    if (this.module.type !== this.type) {
      this.module.type = this.type;
      // refresh dashboard
      const yot = this.yot;
      if (yot) {
        const dashboard = yot.dashboardService
          .getCurrentDashboard();
        if (dashboard) {
          dashboard.widgets.map((w) => {
            if (yot.getModuleByRef(w.module) === this.module) {
              w.type = this.module.getWidgetData().type;
            }
          });
          yot.dashboardService.layoutEvents
            .next(DashboardLayoutEventValue.LayoutRefresh);
        }
      }
    }
    const adapter = this.module.getAdapter();
    adapter.system(SystemApi.Modules.Info.Set, {
      module: this.module,
      name: this.name,
      description: this.description,
      type: this.type
    }).subscribe((res) => {
      adapter.yot.saveConfiguration();
    }, (err) => {
      adapter.yot.notify('Error', err.message);
    });
  }
}
