import {Component, Inject, OnDestroy, OnInit} from '@angular/core';
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {HomegenieAdapter} from "../../homegenie-adapter";
import {NavigationService} from "../../../../services/navigation.service";

@Component({
  selector: 'app-device-manager-dialog',
  templateUrl: './device-manager-dialog.component.html',
  styleUrls: ['./device-manager-dialog.component.scss']
})
export class DeviceManagerDialogComponent implements OnInit, OnDestroy {
  adapter: HomegenieAdapter;
  houseCodes: string[];
  constructor(@Inject(MAT_DIALOG_DATA) data, private navigationService: NavigationService) {
    this.adapter = data.adapter;
    this.houseCodes = data.houseCodes;
  }

  ngOnInit(): void {
  }
  ngOnDestroy() {
    this.navigationService.isLoading = true;
    this.adapter.reloadModules()
      .subscribe(() => this.navigationService.isLoading = false);
  }
}
