import {Component, ElementRef, OnDestroy, OnInit, ViewChild} from '@angular/core';
import {Subscription} from "rxjs";
import {ControlFieldBase} from "../control-field-base";

@Component({
  selector: 'app-event-capture',
  templateUrl: './event-capture.component.html',
  styleUrls: ['./event-capture.component.scss']
})
export class EventCaptureComponent extends ControlFieldBase implements OnInit, OnDestroy {
  @ViewChild('inputElement') inputElement: ElementRef;
  isCapturing = false;

  private moduleEventsSubscription: Subscription;

  ngOnInit() {
    super.ngOnInit();
    // subscribe to YOT events stream
    this.moduleEventsSubscription = this.yot.onModuleEvent.subscribe((e) => {
      if (!this.isCapturing) return;
      const field = e.event;
      if (field.key === 'Receiver.RawData') {
        this.isCapturing = false;
        this._snackBar.dismiss();
        this.inputElement.nativeElement.value = field.value;
        this.fieldChange.emit({ field: this.data.field, value: field.value });
      }
    });
  }

  ngOnDestroy(): void {
    // unsubscribe YOT events stream
    this.moduleEventsSubscription && this.moduleEventsSubscription.unsubscribe();
    this._snackBar.dismiss();
  }

  onCaptureClick(): void {
    // translations
    let textCapturingRawData = 'capturing_receiver_raw_data_events';
    this.yot.translate.get(textCapturingRawData)
      .subscribe((tr) => textCapturingRawData = tr);
    let textStop = 'stop';
    this.yot.translate.get(textStop)
      .subscribe((tr) => textStop = tr);
    // start capturing
    this.isCapturing = true;
    const snackBarRef = this._snackBar.open(textCapturingRawData, textStop, {
      duration: 10000
    });
    snackBarRef.onAction().subscribe(() => {
      this.isCapturing = false;
    });
    snackBarRef.afterDismissed().subscribe(() => {
      this.isCapturing = false;
    });
  }

  onTextFieldChange(e): void {
    this.fieldChange.emit({ field: this.data.field, value: e.target.value });
  }

  reset() {
    super.reset();
    this.inputElement.nativeElement.value = this.originalValue;
  }
}
