export enum ThermostatMode {
  Off = 'Off',
  Heat = 'Heat',
  HeatEconomy = 'HeatEconomy',
  Cool = 'Cool',
  CoolEconomy = 'CoolEconomy',
  Auto = 'Auto'
}

export enum ThermostatFanMode {
  Off = 'Off',
  OnLow = 'OnLow',
  Circulate = 'Circulate',
  AutoLow = 'AutoLow'
}

export enum ThermostatOperatingState {
  Idle = 'Idle',
  Heating = 'Heating',
  PendingHeat = 'PendingHeat',
  Cooling = 'Cooling',
  PendingCool = 'PendingCool'
}

export class ThermostatCommand {
  static Mode = {
    Set: 'Thermostat.ModeSet',
    Get: 'Thermostat.ModeGet'
  };
  static SetPoint = {
    Set: 'Thermostat.SetPointSet',
    Get: 'Thermostat.SetPointGet'
  };
  static FanMode = {
    Set: 'Thermostat.FanModeSet'
  };
  static FanState = {
    Get: 'Thermostat.FanStateGet'
  };
  static OperatingState = {
    Get: 'Thermostat.OperatingStateGet'
  };
}
export class ThermostatField {
  static Mode = 'Thermostat.Mode';
  static FanMode = 'Thermostat.FanMode';
  static OperatingState = 'Thermostat.OperatingState';
  static SetPoint = {
    Heating: 'Thermostat.SetPoint.Heating',
    HeatingEconomy: 'Thermostat.SetPoint.HeatingEconomy',
    Cooling: 'Thermostat.SetPoint.Cooling',
    CoolingEconomy: 'Thermostat.SetPoint.CoolingEconomy'
  }
}
