export const INTERFACE_STATISTICS_PROVIDER = '@Statistics:Provider';
export const INTERFACE_STATISTICS_STORAGE = '@Statistics:Storage';

export class TimeRange {
  public value: number;
  public label?: string;
  public refreshMs?: number;
}

// default settings for added series
// TODO: maybe refactor to ChartSerieOptions
export class HgChartOptions {
  public storage: string = '';
  public type = 'line';
  public lineTension = 0;
  public borderWidth = 1;
  public pointRadius = 1;
  public fill = false;
  public hidden = false;
}

export interface ChartProvider {
  name?: string;
  interface: string;
  apiUrl: string;
  options?: any;
  providerId?: number;
}

export interface ChartProviderSettings {
  id: number,
  title?: string,
  legend?: boolean,
  provider?: ChartProvider,
  dataApi?: string,
  scale: string,
  type: ChartType,
  colors?: string[],
  labels?: string[],
  filters?: string[],
  options?: any,
  refreshMs?: number,
  browsing?: boolean
}

export const DEFAULT_CHART_PROVIDER: ChartProvider = {
  interface: INTERFACE_STATISTICS_PROVIDER,
  apiUrl: 'Statistics.Providers/DataMonitor'
};

