import {Component, Input, OnInit} from '@angular/core';
import {Group, HomegenieAdapter} from "../homegenie-adapter";
import {GroupModulesDialogComponent} from "../group-modules-dialog/group-modules-dialog.component";
import {Module} from "../../../services/yot/module";
import {
  ModuleSettingsDialogComponent
} from "../../../components/dialogs/module-settings-dialog/module-settings-dialog.component";
import {
  ModuleStatisticsDialogComponent
} from "../../../components/dialogs/module-statistics-dialog/module-statistics-dialog.component";
import {
  ModuleSchedulingDialogComponent
} from "../../../components/dialogs/module-scheduling-dialog/module-scheduling-dialog.component";
import {
  ModuleEventsDialogComponent
} from "../../../components/dialogs/module-events-dialog/module-events-dialog.component";
import {MatDialog} from "@angular/material/dialog";
import {Subject} from "rxjs";
import {HomegenieApi, ModuleReference, ResponseStatus} from "../homegenie-api";
import {moveItemInArray} from "@angular/cdk/drag-drop";
import {
  ActionConfirmDialogComponent,
  ActionConfirmDialogConfig
} from "../../../components/dialogs/action-confirm-dialog/action-confirm-dialog.component";
import {UiMode, YotService} from "../../../services/yot/yot.service";
import {
  WidgetActionRequest,
  WidgetActionRequestAction
} from "../../../widgets/common-parts/widget-actions-menu/widget-actions-menu.component";
import {
  AddDashboardDialogComponent
} from "../../../components/dialogs/add-dashboard-dialog/add-dashboard-dialog.component";
import {DashboardWidget} from "../../../services/dashboard/dashboard";
import {PagesRoute} from "../../../pages-route";
import {Router} from "@angular/router";
import {NavigationService} from "../../../services/navigation.service";
import {ModuleEditDialogComponent} from "../../../components/dialogs/module-edit-dialog/module-edit-dialog.component";

@Component({
  selector: 'app-modules-groups',
  templateUrl: './modules-groups.component.html',
  styleUrls: ['./modules-groups.component.scss']
})
export class ModulesGroupsComponent {
  @Input()
  adapter: HomegenieAdapter;

  selectedGroup: Group;
  selectedGroupModules: Array<{ module: Module, reference: ModuleReference }[]> = [];
  selectedModule: Module;
  modulesGroups: Group[] = [];

  get widgetPreview(): DashboardWidget {
    const m = this.selectedModule;
    if (m == null) return;
    const data = m.getWidgetData();
    return data ? {
      type: data.type,
      module: {adapterId: this.adapter.id, moduleId: m.id},
      data
    } : null;
  }

  get selectedGroupIndex(): number {
    let group: Group;
    if (this.selectedGroup) {
      group = this.modulesGroups.find((g) => g.Name === this.selectedGroup.Name);
      this.selectedGroup = group;
    }
    return this.modulesGroups.indexOf(group);
  }

  constructor(
    private dialog: MatDialog,
    private yot: YotService,
    private navigationService: NavigationService,
    private router: Router
  ) { }

  onGroupSelected(e) {
    this.selectedGroup = e.value;
    this.showAddModulesTip();
  }
  onListDrop(e) {
    moveItemInArray(this.selectedGroup.Modules, e.previousIndex, e.currentIndex);
    moveItemInArray(this.selectedGroupModules[this.selectedGroupIndex], e.previousIndex, e.currentIndex);
    this.updateGroup(this.selectedGroup);
  }

  onEditGroupClick(group?) {
    if (!group) {
      group = new Group();
    }
    const dialogRef = this.dialog.open(GroupModulesDialogComponent, {
      panelClass: 'dialog-no-padding',
      width: '100%',
      minWidth: '320px',
      maxWidth: '576px',
      disableClose: false,
      data: {
        adapter: this.adapter,
        group: {...group},
        groupNames: this.adapter.groups.map((g) => g.Name).filter((g) => g !== group.Name),
        mode: !group.Name ? UiMode.Add : UiMode.Edit
      }
    });
    dialogRef.afterClosed().subscribe((g: Group) => {
      if (g) {
        if (!group.Name) {
          // add new group
          this.addGroup(g);
        } else {
          // updated existsing group
          if (g.Name !== group.Name) {
            // rename group first
            this.renameGroup(group, g.Name, () => {
              this.updateGroup(g);
            });
          } else {
            this.updateGroup(g);
          }
        }
      }
    })
  }

  onGroupRemoveClick(group: Group) {
    if (group == null) return;
    this.yot.translate.get(['confirm_group_removal', 'group_removal_message'], {name: group.Name})
      .subscribe((res) => {
        const dialogRef = this.dialog.open(ActionConfirmDialogComponent, {
          width: '320px',
          disableClose: false,
          data: {
            title: res['confirm_group_removal'],
            message: res['group_removal_message'],
          } as ActionConfirmDialogConfig
        });
        dialogRef.afterClosed().subscribe((confirm) => {
          if (confirm) {
            this.deleteGroup(group);
          }
        });
      });
  }

  onCreateDashboardClick(e) {
    const dialogRef = this.dialog.open(AddDashboardDialogComponent, {
      disableClose: false,
      data: this.selectedGroup.Name
    });
    dialogRef.afterClosed().subscribe((dashboardName) => {
      if (dashboardName) {
        this.navigationService.isLoading = true;
        const dashboard = this.yot.dashboardService.addDashboard(dashboardName);
        // add widgets from current group to the newly created dashboard
        this.selectedGroupModules[this.selectedGroupIndex].forEach((m) => {
          const widgetData =  m.module.getWidgetData();
          if (widgetData) {
            dashboard.addWidget(widgetData.type, m.module, widgetData);
          } else {
            // TODO: !!!
            console.log('Could not get widget data for', m);
          }
        });
        this.yot.saveConfiguration().subscribe((res) => {
          this.navigationService.isLoading = false;
          this.yot.translate.get(['operation_successful', 'created_group_dashboard'])
            .subscribe((res) => {
              this.yot.notify(res['operation_successful'], res['created_group_dashboard'], {
                duration: 20000,
                data: {
                  action: "open",
                  onAction: () => {
                    this.navigationService.isLoading = true;
                    this.router.navigate([PagesRoute.HomePage, dashboardName])
                      .then((res) => {
                        this.navigationService.isLoading = false;
                      });
                  }
                }
              });
            });
        });
      }
    });
  }

  onWidgetActionRequest(request: WidgetActionRequest, moduleRef?: ModuleReference): void {
    if (request.action === WidgetActionRequestAction.removeWidget && moduleRef) {
      moduleRef = this.selectedGroup.Modules.find((mr) => mr.Domain === moduleRef.Domain && mr.Address == moduleRef.Address);
      const refIndex = this.selectedGroup.Modules.indexOf(moduleRef);
      if (refIndex >= 0) {
        this.selectedGroup.Modules.splice(refIndex, 1);
        this.updateGroup(this.selectedGroup);
      }
      return;
    }
    let dialogComponent;
    let dialogWidth = '576px';
    // TODO: add enum for dialog names (see `widget-actions-menu.component.ts`)
    switch (request.action) {
      case WidgetActionRequestAction.showSettings:
        dialogComponent = ModuleSettingsDialogComponent;
        break;
      case WidgetActionRequestAction.showStatistics:
        dialogComponent = ModuleStatisticsDialogComponent;
        dialogWidth = '960px';
        break;
      case WidgetActionRequestAction.showSchedule:
        dialogComponent = ModuleSchedulingDialogComponent;
        break;
      case WidgetActionRequestAction.showLogs:
        dialogComponent = ModuleEventsDialogComponent;
        break;
      case WidgetActionRequestAction.showEdit:
        dialogComponent = ModuleEditDialogComponent;
        break;
    }
    if (dialogComponent) {
      const dialogRef = this.dialog.open(dialogComponent, {
        panelClass: 'dialog-no-padding',
        width: '100%',
        minWidth: '280px',
        maxWidth: dialogWidth,
        disableClose: false,
        data: {module: this.selectedModule, options: this.selectedModule.getWidgetData()}
      });
    }
  }

  refreshGroupsList() {
    this.modulesGroups = this.adapter.groups.slice();
    this.navigationService.isLoading = true;
    this.getGroupList().subscribe(() => {
      this.navigationService.isLoading = false;
      this.showAddModulesTip();
    }, () => {
      this.navigationService.isLoading = false;
    });
  }

  moduleWidgetToggle(gm: any): void {
    if (this.selectedModule === gm.module) {
      this.selectedModule = null;
    } else {
      this.selectedModule = gm.module;
    }
  }

  private addGroup(g: Group) {
    this.navigationService.isLoading = true;
    const done = () => {
      this.navigationService.isLoading = false;
    }
    this.adapter.apiCall(HomegenieApi.Config.Groups.Add, g.Name)
      .subscribe((res) => {
        if (res.response.Status === ResponseStatus.Error) {
          this.adapter.yot.notify(res.response.Status, res.response.Message);
          done();
        } else {
          this.adapter.apiCall(HomegenieApi.Config.Groups.Save, [g])
            .subscribe((res) => {
              this.getGroupList().subscribe(() => {
                this.selectedGroup = this.modulesGroups.find((group) => group.Name === g.Name);
                this.showAddModulesTip();
                done();
              }, () => {
                done();
              });
            }, (err) => {
              this.adapter.yot.notify('Error', err.message);
              done();
            });
        }
      }, (err) => {
        this.adapter.yot.notify('Error', err.message);
        done();
      });
  }
  private renameGroup(g: Group, newName, callback) {
    this.navigationService.isLoading = true;
    const done = () => {
      this.navigationService.isLoading = false;
      if (callback) callback();
    }
    if (g.Name !== newName) {
      this.adapter.apiCall(HomegenieApi.Config.Groups.Rename(g.Name), newName)
        .subscribe((res) => {
          if (res.response.Status === ResponseStatus.Error) {
            this.adapter.yot.notify(res.response.Status, res.response.Message);
          } else {
            g.Name = newName;
          }
          this.getGroupList().subscribe(() => {
            done();
          }, (err) => {
            done();
            this.adapter.yot.notify('Error', err.message);
          });
        }, (err) => {
          done();
          this.adapter.yot.notify('Error', err.message);
        });
    } else {
      done();
    }
  }
  private updateGroup(g: Group) {
    this.navigationService.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Config.Groups.Save, [g])
      .subscribe((res) => {
        this.getGroupList().subscribe(() => {
          this.navigationService.isLoading = false;
        }, () => {
          this.navigationService.isLoading = false;
        });
      }, (err) => {
        this.adapter.yot.notify('Error', err.message);
        this.navigationService.isLoading = false;
      });
  }
  private deleteGroup(g: Group) {
    this.navigationService.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Config.Groups.Delete, g.Name)
      .subscribe((res) => {
        console.log('Save successful', res);
        this.getGroupList().subscribe(() => {
          this.navigationService.isLoading = false;
        }, () => {
          this.navigationService.isLoading = false;
        });
      }, (err) => {
        this.adapter.yot.notify('Error', err.message);
        this.navigationService.isLoading = false;
      });
  }

  private getGroupList(): Subject<any> {
    const subject = new Subject();
    this.adapter.reloadModules().subscribe({
      next: (res) => {
        this.modulesGroups = this.adapter.groups; //res.response;
        this.modulesGroups.forEach((g) => {
          g.Modules = g.Modules.filter((mr) => {
            const m = this.adapter.getModuleByRef(mr);
            if (m && mr.Domain !== 'HomeGenie.UI.Separator') {
              return mr;
            }
          });
        });
        this.modulesGroups.map((group, i) => {
          this.selectedGroupModules[i] = group.Modules.filter((mr) => {
            const m = this.adapter.getModuleByRef(mr);
            if (m) {
              return mr;
            }
          }).map((mr) => ({
            module: this.adapter.getModuleByRef(mr),
            reference: mr
          }));
        });
        if (this.selectedGroupIndex < 0) {
          this.selectedGroup = this.modulesGroups[0];
        }
        subject.next(null);
        subject.complete();
      },
      error: (err) => {
        // TODO: notify error
        subject.error(err);
      }
    });
    return subject;
  }

  private showAddModulesTip() {
    if (this.selectedGroup && this.selectedGroup.Modules.length === 0) {
      setTimeout(() => {
        this.yot.translate.get('include_modules_tip').subscribe((title) => {
          this.yot.tooltip(title, {
            panelClass: 'custom-snackbar-hg-groups',
            horizontalPosition: "end",
            verticalPosition: "top",
            duration: 2000
          });
        });
      }, 1000);
    }
  }
}
