import {
  Component,
  ElementRef,
  Input,
  OnDestroy,
  OnInit,
  QueryList,
  ViewChild,
  ViewChildren
} from '@angular/core';
import {YotService} from '../../services/yot/yot.service';
import {ActivatedRoute, NavigationEnd, NavigationStart, Router} from '@angular/router';
import {Subscription} from 'rxjs';
import {Dashboard, DashboardWidget} from '../../services/dashboard/dashboard';
import {MatDialog} from '@angular/material/dialog';
import {DragDrop, DragRef, DragRefConfig} from "@angular/cdk/drag-drop";
import {
  ModuleSettingsDialogComponent
} from "../../components/dialogs/module-settings-dialog/module-settings-dialog.component";
import {
  ModuleStatisticsDialogComponent
} from "../../components/dialogs/module-statistics-dialog/module-statistics-dialog.component";
import {
  ModuleSchedulingDialogComponent
} from "../../components/dialogs/module-scheduling-dialog/module-scheduling-dialog.component";
import {
  ModuleEventsDialogComponent
} from "../../components/dialogs/module-events-dialog/module-events-dialog.component";
import {PagesRoute} from "../../pages-route";
import {
  WidgetActionRequest,
  WidgetActionRequestAction
} from "../../widgets/common-parts/widget-actions-menu/widget-actions-menu.component";
import {WidgetType} from "../../api/widgets/widget-type";
import {DashboardLayoutEventValue} from "../../services/dashboard/dashboard.service";
import {NavigationService, UiEvents} from "../../services/navigation.service";
import {HomegenieAdapter} from "../../adapters/home-genie/homegenie-adapter";
import {ModuleEditDialogComponent} from "../../components/dialogs/module-edit-dialog/module-edit-dialog.component";
import {MatBottomSheet} from "@angular/material/bottom-sheet";
import {LightsBottomSheetComponent} from "./bottom-sheets/lights-bottom-sheet/lights-bottom-sheet.component";
import {ProgramsBottomSheetComponent} from "./bottom-sheets/programs-bottom-sheet/programs-bottom-sheet.component";
import {Module} from "../../services/yot/module";
import {ShuttersBottomSheetComponent} from "./bottom-sheets/shutters-bottom-sheet/shutters-bottom-sheet.component";
import {PlayFxConfig} from "zuix-dist";

@Component({
  selector: 'app-dashboard-page',
  templateUrl: './dashboard-page.component.html',
  styleUrls: ['./dashboard-page.component.scss']
})
export class DashboardPageComponent implements OnInit, OnDestroy {
  @ViewChildren('widgetRef', { read: ElementRef })
  itemElements: QueryList<ElementRef>;

  @ViewChild('container', {static: false}) dashboardContainer: ElementRef<HTMLElement>;
  @Input()
  dashboard: Dashboard = null;

  WidgetType = WidgetType;

  private layoutArrangeRequest = null;
  private dragElements: DragRef[] = [];
  private isDragEnabled = false;

  private readonly routeParamSubscription: Subscription;
  private readonly routeEventSubscription: Subscription;
  private readonly uiEventsSubscription: Subscription;
  private readonly widgetAddEventSubscription: Subscription;
  private readonly widgetRemoveEventSubscription: Subscription;
  private readonly layoutEventSubscription: Subscription;
  private readonly bottomSheetRequestedSubscription: Subscription;

  private readonly dragStartDelay = 300;
  private startArrangeTimeout: any = null;
  private dashboardChanged = false;
  private startDragPoint: {x: number, y: number};
  private scrollToEndTimeout;

  private arrangedWidgets: DashboardWidget[];

  private resizeObserver: ResizeObserver;
  private subscriptions = new Subscription();

  private observeItems(elements: QueryList<ElementRef>): void {
    this.resizeObserver.disconnect();
    elements.forEach((elementRef: ElementRef, index: number) => {
      const element = elementRef.nativeElement;
      this.resizeObserver.observe(element);
    });
  }

  constructor(
    public dialog: MatDialog,
    public yot: YotService,
    public navigationService: NavigationService,
    private matBottomSheet: MatBottomSheet,
    private dragDrop: DragDrop,
    private activatedRoute: ActivatedRoute,
    private router: Router
  ) {
    this.routeParamSubscription = this.activatedRoute.params.subscribe(params => {
      this.navigationService.isLoading = true;
      const name = params['name'];
      if (name) {
        const dashboard = this.yot.dashboardService.getDashboard(name);
        if (dashboard) {
          if (this.dashboard == null) {
            this.setCurrentDashboard(dashboard);
          }
          this.dashboard = dashboard;
          this.navigationService.isLoading = false;
          return;
        }
      }
      const ds = this.yot.dashboardService;
      if (this.dashboard == null) {
        // set the first dashboard as the default one
        const dashboard =
          ds.getDashboard(this.yot.preferences.ui.dashboard)
          || ds.dashboards[0];
        if (dashboard) {
          this.router.navigate([ PagesRoute.HomePage, dashboard.name])
            .then(() => this.navigationService.isLoading = false);
        } else {
          this.navigationService.isLoading = false;
          if (this.isConfigured()) {
            setTimeout(() => {
              this.yot.translate.get('add_new_dashboard').subscribe((tr) => {
                this.yot.tooltip(tr, {
                  panelClass: 'custom-snackbar-dashboard-menu',
                  horizontalPosition: 'start',
                  verticalPosition: 'top',
                  duration: 2000
                });
              });
            }, 300);
          }
        }
      }
    });
    this.routeEventSubscription = this.router.events.subscribe(event => {
      if (event instanceof NavigationStart) {
        this.navigationService.showToolbar();
        return;
      }
      if (event instanceof NavigationEnd) {
        this.setCurrentDashboard(this.dashboard);
      }
    });
    this.bottomSheetRequestedSubscription = this.yot.dashboardService.onBottomSheetRequested.subscribe((id) => {
      switch (id) {
        case 'scene-playback':
          this.openProgramsBottomSheet();
          break;
        case 'lights-control':
          this.openLightsBottomSheet();
          break;
        case 'shutters-control':
          this.openShuttersBottomSheet();
          break;
      }
    });
    this.widgetAddEventSubscription = this.yot.dashboardService.onDashboardWidgetAdded.subscribe((dw) => {
      this.requestLayout();
      // scroll to the newly added widget
      if (this.dashboard ===  dw.dashboard && this.dashboardContainer) {
        clearTimeout(this.scrollToEndTimeout);
        this.scrollToEndTimeout = setTimeout(() => {
          this.yot.saveConfiguration();
          const layoutItems = this.dashboardContainer.nativeElement
            .querySelectorAll('.layout-item');
          const newWidget = layoutItems[layoutItems.length - 1];
          newWidget.scrollIntoView({ behavior: "smooth", block: "end" });
        }, 500);
      }
    });
    this.widgetRemoveEventSubscription = this.yot.dashboardService.onDashboardWidgetRemoved.subscribe((dw) => {
      this.requestLayout();
      this.yot.saveConfiguration();
    });
    this.layoutEventSubscription = this.yot.dashboardService.layoutEvents.subscribe((event) => {
      switch (event) {
        case DashboardLayoutEventValue.ArrangeStart:
          // Store initial arrangement
          this.arrangedWidgets = this.yot.dashboardService.getCurrentDashboard().widgets.slice();
          this.dashboardChanged = false;
          this.enableDrag();
          break;
        case DashboardLayoutEventValue.ArrangeDone:
          if (this.isDragEnabled) {
            this.disableDrag();
            // Save new widgets arrangement
            if (this.dashboardChanged) {
              this.yot.dashboardService.getCurrentDashboard().widgets = this.arrangedWidgets;
              this.yot.saveConfiguration();
            }
          }
          break;
        case DashboardLayoutEventValue.LayoutRefresh:
          this.requestLayout();
          break;
      }
    });
    this.uiEventsSubscription = this.navigationService.drawerEvents.subscribe((e) => {
      if (e.event === UiEvents.DrawerState || e.event === UiEvents.DrawerMode) {
        setTimeout(() => this.requestLayout(), 250);
      }
    });
  }

  ngOnInit(): void {
    this.navigationService
      .appMenuChange.next('dashboard');
  }

  ngOnDestroy(): void {
    if (this.resizeObserver) {
    this.resizeObserver
      .disconnect();
    }
    this.subscriptions.unsubscribe();

    if (this.bottomSheetRequestedSubscription) {
      this.bottomSheetRequestedSubscription.unsubscribe();
    }
    if (this.widgetAddEventSubscription) {
      this.widgetAddEventSubscription.unsubscribe();
    }
    if (this.widgetRemoveEventSubscription) {
      this.widgetRemoveEventSubscription.unsubscribe();
    }
    if (this.layoutEventSubscription) {
      this.layoutEventSubscription.unsubscribe();
    }
    if (this.uiEventsSubscription) {
      this.uiEventsSubscription.unsubscribe();
    }
    if (this.routeParamSubscription) {
      this.routeParamSubscription.unsubscribe();
    }
    if (this.routeEventSubscription) {
      this.routeEventSubscription.unsubscribe();
    }
    this.navigationService
      .appMenuChange.next('');
    this.disableDrag();
    clearTimeout(this.startArrangeTimeout);
    clearTimeout(this.scrollToEndTimeout);
    // reset card color to original theme
    this.yot
      .dashboardService
      .setDashboardCardColor();
  }

  onResize(e) {
    const drag = this.isDragEnabled;
    if (this.isDragEnabled) {
      this.disableDrag();
    }
    this.requestLayout();
    if (drag) {
      this.enableDrag();
    }
  }

  onImportDashboardsClick() {
    this.navigationService.isLoading = true;
    (this.yot.getDefaultAdapter() as HomegenieAdapter)
      .importDashboards().subscribe(() => {
        const dashboard = this.yot.dashboardService.dashboards[0];
        if (dashboard) {
          this.yot.saveConfiguration().subscribe((config) => {
            this.router.navigate([ PagesRoute.HomePage, dashboard.name])
              .then(() => this.navigationService.isLoading = false);
          });
        } else {
          this.navigationService.router.navigate([PagesRoute.SetupPage]).then(() => {
            this.navigationService.isLoading = false;
          });
        }
      });
  }

  onWidgetActionRequest(widget: DashboardWidget, request: WidgetActionRequest): void {
    if (request.action === WidgetActionRequestAction.removeWidget) {
      this.yot.dashboardService
        .removeDashboardWidget(this.dashboard.name, widget);
      return;
    }
    if (request.action === WidgetActionRequestAction.startRowToggle) {
      widget.configuration = widget.configuration || {};
      widget.configuration.startRow = !widget.configuration.startRow;
      this.requestLayout();
      setTimeout(() => this.requestLayout(), 200);
      this.yot.saveConfiguration();
      return;
    }
    if (request.action === WidgetActionRequestAction.requestLayout) {
      this.requestLayout();
      return;
    }
    let dialogComponent;
    let dialogWidth = '576px';
    let customOptions = {};
    switch (request.action) {
      case WidgetActionRequestAction.showEdit:
        dialogComponent = ModuleEditDialogComponent;
        break;
      case WidgetActionRequestAction.showSettings:
        dialogComponent = ModuleSettingsDialogComponent;
        break;
      case WidgetActionRequestAction.showStatistics:
        dialogComponent = ModuleStatisticsDialogComponent;
        dialogWidth = '960px';
        customOptions = {
          dashboard: this.dashboard
        };
        break;
      case WidgetActionRequestAction.showSchedule:
        dialogComponent = ModuleSchedulingDialogComponent;
        break;
      case WidgetActionRequestAction.showLogs:
        dialogComponent = ModuleEventsDialogComponent;
        break;
    }
    if (dialogComponent) {
      const module = this.yot.getModuleByRef(widget.module);
      const dialogRef = this.dialog.open(dialogComponent, {
        panelClass: 'dialog-no-padding',
        width: '100%',
        minWidth: '280px',
        maxWidth: dialogWidth,
        disableClose: false,
        data: {module, ...request.data, ...customOptions}
      });
      dialogRef.afterClosed()
        .subscribe((nextAction: WidgetActionRequest) => {
          if (nextAction) {
            this.onWidgetActionRequest(widget, nextAction);
          }
        });
    }
  }

  enableDrag(): void {
    if (this.isDragEnabled || !this.dashboardContainer) return;
    this.isDragEnabled = true;
    let lastSwapTimestamp = new Date().getTime();
    this.requestLayout();
    const container = this.dashboardContainer.nativeElement;
    const placeholder = container.querySelector('div.placeholder') as HTMLElement;
    let startDragIndex = -1;
    container.childNodes.forEach((item: HTMLElement, i) => {
      if (item['style'] && item.firstElementChild && item.firstElementChild.firstElementChild) {
        const view = item.firstElementChild.firstElementChild;
        view.classList.add('drag-no-input');
        const dr = this.dragDrop.createDrag(item, {
          dragStartThreshold: 0
        } as DragRefConfig);
        dr.dragStartDelay = this.dragStartDelay;
        dr.started.subscribe((e) => {
          const dragElement = e.source.getRootElement();
          dragElement.classList.add('dragging', 'topmost');
          dragElement.classList.remove('transition');
          dragElement.firstElementChild.querySelector('mat-card')
            ?.classList.add('mat-elevation-z12');
          if (placeholder) {
            placeholder.style.width = dragElement.clientWidth + 'px';
            placeholder.style.height = dragElement.clientHeight + 'px';
            placeholder.classList.add('layout-item');
            placeholder.style.transform = dragElement.style.transform;
            placeholder.style.display = 'block';
          }
          const translate = DashboardPageComponent.getTranslateValues(dragElement);
          // store initial position of element into DragRef.data prop
          const cp = dr.getFreeDragPosition();
          dr.data = { x: translate.x, y: translate.y, scrollTop: container.scrollTop, startScrollY: window.scrollY, cp };
          // place the placeholder right before the dragged element
          container.insertBefore(placeholder, dragElement);
          startDragIndex = Array.from(container.children).indexOf(dragElement) - 1;
        });

        dr.constrainPosition = (p, dr) => {
          const cp = dr.getFreeDragPosition();
          const delta = { x: cp.x - dr.data.cp.x, y: cp.y - dr.data.cp.y };
          dr.data.cp = cp;
          const dragElement = dr.getRootElement();
          const hitResult = this.hitTestObject(dragElement, container.children, 0.4);
          // auto-scroll when element is dragged out of viewport bounds
          let offsetY = hitResult.bounds.top;
          if (offsetY < 0 && delta.y < 0) {
            // element hit top
            window.scrollTo({
              left: 0,
              top: window.scrollY + (offsetY / 5),
              // behavior: 'smooth' <-- won't work with this enabled
            });
          } else {
            // element hit bottom
            offsetY = hitResult.bounds.bottom - window.innerHeight; // - cb.bottom;
            if (offsetY > 0 && delta.y > 0) {
              window.scrollTo({
                left: 0,
                top: window.scrollY + (offsetY / 5),
                // behavior: 'smooth' <-- won't work with this enabled
              });
            }
          }
          // re-arrange element position while dragging
          if (hitResult.percentage > 0) {
            const now = new Date().getTime();
            if (now - lastSwapTimestamp > 300) {
              lastSwapTimestamp = now;
              const hitElement = hitResult.element;
              const elementList = Array.from(container.children);
              const di = elementList.indexOf(hitElement);
              const ti = elementList.indexOf(placeholder);
              if ((delta.x > 0 || delta.y > 0) && di > ti) {
                container.insertBefore(placeholder, hitElement.nextSibling);
              } else if ((delta.x < 0 || delta.y < 0) && di < ti) {
                container.insertBefore(placeholder, hitElement);
              }
              this.requestLayout();
            }
          }
          // adjust element vertical position if viewport scrolled
          p.y = p.y + (window.scrollY - dr.data.startScrollY) - (dr.data.scrollTop - container.scrollTop) - this.startDragPoint.y;
          p.x = p.x - this.startDragPoint.x;
          return p;
        };

        dr.ended.subscribe((e) => {
          const dragElement = e.source.getRootElement();
          const placeholder = container.querySelector('div.placeholder') as HTMLElement;
          if (placeholder && placeholder.classList.contains('layout-item')) {
            container.insertBefore(dragElement, placeholder);
            placeholder.classList.remove('layout-item', 'transition');
            placeholder.style.display = 'none';
            const ti = Array.from(container.children).indexOf(placeholder);
            if (startDragIndex !== ti - 1) {
              this.arrayItemMove(this.arrangedWidgets, startDragIndex, ti - 1)
              this.dashboardChanged = true;
            }
          }
          dragElement.classList.remove('dragging');
          setTimeout(() => {
            dragElement.firstElementChild.querySelector('mat-card')
              ?.classList.remove('mat-elevation-z12');
            dragElement.classList.remove('topmost');
          }, 175);
          this.onResize(e);
          this.checkArrangeStop({currentTarget: dragElement});
        });
        this.dragElements.push(dr);
      }
    });
  }
  disableDrag(): void {
    this.dragElements.forEach((dr, i) => {
      // TODO: maybe it's better to unsubscribe dragRef events also
      dr.getRootElement().firstElementChild.firstElementChild.classList.remove('drag-no-input');
      dr.dispose();
    });
    this.dragElements.length = 0;
    this.requestLayout();
    this.isDragEnabled = false;
  }

  isConfigured() {
    return this.yot.getAdapters().length > 0 && this.yot.getDefaultAdapter().isConfigured;
  }

  checkArrangeStart(e: PointerEvent) {
    if (!this.yot.dashboardService.isDragSortEnabled) return;
    const widgetContainer = e.currentTarget as HTMLElement;
    this.startDragPoint = {
      x: e.clientX - widgetContainer.getBoundingClientRect().x,
      y: e.clientY - widgetContainer.getBoundingClientRect().y
    }
    clearTimeout(this.startArrangeTimeout);
    this.startArrangeTimeout = setTimeout(() => {
      widgetContainer.firstElementChild.firstElementChild
        .classList.add('mat-elevation-z6', 'draggable');
    }, this.dragStartDelay);
    this.yot.dashboardService.layoutEvents
      .next(DashboardLayoutEventValue.ArrangeStart);
  }
  cancelArrangeStart() {
    clearTimeout(this.startArrangeTimeout);
  }
  checkArrangeStop(e: any) {
    if (!this.yot.dashboardService.isDragSortEnabled) return;
    const widgetContainer = e.currentTarget as HTMLElement;
    widgetContainer.firstElementChild.firstElementChild
      .classList.remove('mat-elevation-z6', 'draggable');
    clearTimeout(this.startArrangeTimeout);
    setTimeout(() => {
      this.yot.dashboardService.layoutEvents
        .next(DashboardLayoutEventValue.ArrangeDone);
    });
  }

  openShuttersBottomSheet(): void {
    const modules = this.getShutterModules();
    const sheetRef = this.matBottomSheet.open(ShuttersBottomSheetComponent, {
      data: {
        modules,
        dashboard: this.dashboard
      },
      panelClass: 'sheet-no-padding'
      // hasBackdrop: true,
      // disableClose: false,
    });
    sheetRef.afterDismissed().subscribe((result) => {
      // TODO: ...
    });
  }
  openLightsBottomSheet(): void {
    const modules = this.getLightModules();
    const sheetRef = this.matBottomSheet.open(LightsBottomSheetComponent, {
      data: {
        modules,
        dashboard: this.dashboard
      },
      panelClass: 'sheet-no-padding'
    });
    sheetRef.afterDismissed().subscribe((result) => {
      // TODO: ...
    });
  }
  openProgramsBottomSheet(): void {
    const adapter = (this.yot.getDefaultAdapter() as HomegenieAdapter);
    const programs = this.dashboard.config.programs
      ?.filter((mr) => {
        return adapter.programs.find((p) => p.IsEnabled && `HomeAutomation.HomeGenie.Automation:${p.Address}` === mr.moduleId)
      }).map((mr) => this.yot.getModuleByRef(mr)) || [];
    const sheetRef = this.matBottomSheet.open(ProgramsBottomSheetComponent, {
      data: {
        programs,
        dashboard: this.dashboard
      },
      panelClass: 'sheet-no-padding'
      // hasBackdrop: true,
      // disableClose: false,
    });
    sheetRef.afterDismissed().subscribe((result) => {
      // TODO: ...
    });
  }

  getShutterModules(): Module[] {
    return this.dashboard?.widgets
      ?.filter((w) => w.type === WidgetType.Shutter)
      .map((w) => this.yot.getModuleByRef(w.module)) || [];
  }
  hasShutterWidgets(): boolean {
    return this.getShutterModules().length > 0;
  }

  getLightModules(): Module[] {
    return this.dashboard?.widgets
      ?.filter((w) => w.type === WidgetType.Color || w.type === WidgetType.Light)
      .map((w) => this.yot.getModuleByRef(w.module)) || [];
  }
  hasLightWidgets(): boolean {
    return this.getLightModules().length > 0;
  }

  private setCurrentDashboard(dashboard) {
    this.dashboard = dashboard;
    this.yot.dashboardService.setCurrentDashboard(dashboard);
    this.requestLayout({ disableTransition: true });
    this.navigationService.showToolbar();
    if (dashboard && dashboard.widgets.length === 0) {
      setTimeout(() => {
        this.yot.translate.get('add_widget').subscribe((tr) => {
          this.yot.tooltip(tr, {
            panelClass: 'custom-snackbar-dashboard-menu',
            horizontalPosition: "start",
            verticalPosition: "top",
            duration: 2000
          });
        });
      }, 1000);
    }
    if (dashboard?.name && dashboard?.name !== this.yot.preferences.ui.dashboard) {
      this.yot.preferences.ui.dashboard = dashboard.name;
      this.yot.savePreferences();
    }
    if (dashboard) {

      if (this.resizeObserver) {
        this.resizeObserver
          .disconnect();
      }
      this.subscriptions.unsubscribe();

      setTimeout(() => {

        this.resizeObserver = new ResizeObserver((entries) => {
          /*
          this.ngZone.run(() => {
            for (const entry of entries) {
              const { width, height } = entry.contentRect;
            }
          });
          //*/
          this.requestLayout();
        });
        const items = this.itemElements.toArray();
        items.push(this.dashboardContainer);
        this.observeItems(items as any);

        const changesSub = this.itemElements.changes.subscribe((newList: QueryList<ElementRef>) => {
          this.observeItems(newList);
        });
        this.subscriptions.add(changesSub);

      }, 100);
    }

    // page transition effect
    zuix.$(this.dashboardContainer?.nativeElement)
      .addClass('animate__fadeIn')
      .playAnimation({
        onEnd: ($el, classQueue) => {
          $el.removeClass('animate__fadeIn');
        }
      } as PlayFxConfig,);
  }

  private static isLayoutItem(item: HTMLElement) {
    return item.classList && item.classList.contains('layout-item') && !item.classList.contains('dragging');
  }
  private requestLayout(opts?: { disableTransition: boolean }) {
    clearTimeout(this.layoutArrangeRequest);
    this.layoutArrangeRequest = setTimeout(this.layoutArrange.bind(this, opts));
  }
  private transitionEndHandler = (e) => {
    if (DashboardPageComponent.isLayoutItem(e.target as HTMLElement)) {
      e.target.removeEventListener('transitionend', this.transitionEndHandler);
      e.target.classList.remove('transition');
    }
  };
  private layoutArrange(opts?: { disableTransition: boolean }) {
    if (!this.dashboardContainer) return;
    this.yot.dashboardService.layoutEvents
      .next(DashboardLayoutEventValue.LayoutStart);
    const centerGap: number[] = [];
    let cx = 0; let cy = 0;
    let row = 0;
    let rowHeight = 0;
    const container = this.dashboardContainer.nativeElement;
    const initialHeight = container.offsetHeight;
    // measure available space for centering rows
    cx = 0; cy = 0; row = 0; rowHeight = 0;
    container.childNodes.forEach((item: HTMLElement) => {
      if (DashboardPageComponent.isLayoutItem(item)) {

        if (cx === 0) {
          centerGap[row] = 0;
        }

        const startNewRow = item.firstElementChild?.classList.contains('dashboard-start-row');
        const needsNewLine = startNewRow || (cx > 0 && cx + item.offsetWidth >= container.offsetWidth);
        if (needsNewLine) {
          centerGap[row] = container.offsetWidth - cx; // Centratura riga precedente
          cx = 0;
          cy += rowHeight;
          rowHeight = item.offsetHeight;
          row++;
        } else if (rowHeight < item.offsetHeight) {
          rowHeight = item.offsetHeight;
        }
        cx += item.offsetWidth;
      }
    });
    // center last row
    centerGap[row] = container.offsetWidth - cx;
    // arrange
    const totalHeight = cy + rowHeight;
    const cb = container.getBoundingClientRect();
    const FAB_HEIGHT = 88;
    const availableHeight = window.innerHeight - cb.top - FAB_HEIGHT;
    let verticalOffset = 0;

    if (totalHeight < availableHeight) {
      verticalOffset = (availableHeight - totalHeight) / 2;
      container.style.height = (availableHeight + FAB_HEIGHT - 1) + 'px';
    } else {
      verticalOffset = 0;
      container.style.height = (totalHeight + FAB_HEIGHT - 1) + 'px';
    }

    row = 0; cx = 0; cy = 0; rowHeight = 0;

    container.childNodes.forEach((item: HTMLElement) => {
      if (DashboardPageComponent.isLayoutItem(item)) {
        const startNewRow = item.firstElementChild?.classList.contains('dashboard-start-row');
        const needsNewLine = startNewRow || (cx > 0 && cx + item.offsetWidth >= container.offsetWidth);
        if (needsNewLine) {
          cx = 0;
          cy += rowHeight;
          rowHeight = item.offsetHeight;
          row++;
        } else if (rowHeight < item.offsetHeight) {
          rowHeight = item.offsetHeight;
        }

        if (!opts || !opts.disableTransition === true) {
          item.addEventListener('transitionend', this.transitionEndHandler);
          item.classList.add('transition');
        }

        const offsetX = cx + (centerGap[row] / 2);
        const offsetY = cy + verticalOffset;
        item.style.transform = `translate(${offsetX}px, ${offsetY}px)`;
        cx += item.offsetWidth;
      }
    });

    if (initialHeight != container.offsetHeight) {
      setTimeout(() => { this.requestLayout(); }, 100);
    } else {
      this.yot.dashboardService.layoutEvents
        .next(DashboardLayoutEventValue.LayoutDone);
    }
  }


  // FlowPacking Algorithm with Block Centering and Forced Separation (Clearance Block)

  private layoutArrangeFlowPacking(opts?: { disableTransition: boolean }) {
    if (!this.dashboardContainer) return;
    this.yot.dashboardService.layoutEvents.next(DashboardLayoutEventValue.LayoutStart);

    const container = this.dashboardContainer.nativeElement;
    const containerWidth = container.offsetWidth;
    const initialHeight = container.offsetHeight;
    const gap = 16; // Margine tra gli elementi
    const itemFullWidthThreshold = containerWidth * 0.95; // Soglia per considerare un elemento Full Width

    const allItems: HTMLElement[] = [];
    container.childNodes.forEach(item => {
      if (DashboardPageComponent.isLayoutItem(item as HTMLElement)) {
        allItems.push(item as HTMLElement);
      }
    });

    if (allItems.length === 0) {
      this.yot.dashboardService.layoutEvents.next(DashboardLayoutEventValue.LayoutDone);
      return;
    }

    // --- Inizializzazione Griglia ---
    const NUM_GRID_COLUMNS = 12;
    const smallestWidgetWidth = allItems[0].offsetWidth;
    if (smallestWidgetWidth <= 0) { /* ... fallback ... */ return; }

    const totalColumnSpace = containerWidth - (NUM_GRID_COLUMNS - 1) * gap;
    const baseColumnWidth = totalColumnSpace / NUM_GRID_COLUMNS;

    const columnBottoms = Array(NUM_GRID_COLUMNS).fill(0);

    // Registri per i posizionamenti:
    // 1. Definitivo: Tutti gli elementi piazzati
    const elementPositionsFinal: { item: HTMLElement, x: number, y: number, w: number, h: number }[] = [];
    // 2. Temporaneo: Elementi del blocco corrente in attesa di centratura
    let currentLayoutBlockElements: { item: HTMLElement, x: number, y: number, w: number, h: number }[] = [];

    let currentBlockMaxWidth = 0; // Larghezza totale del blocco corrente per la centratura
    let maxTotalHeight = 0; // Altezza massima finale del contenitore

    // Funzione helper per piazzare e centrare un blocco di elementi
    const finalizeCurrentBlock = (isFinal: boolean = false) => {
      if (currentLayoutBlockElements.length === 0) return;

      // Calcola l'offset di centratura per il blocco che è appena terminato
      const blockCenteringOffset = Math.max(0, (containerWidth - currentBlockMaxWidth) / 2);

      // Applica il centraggio a tutti gli elementi del blocco e li sposta nel registro definitivo
      currentLayoutBlockElements.forEach(p => {
        const finalPos = { ...p, x: p.x + blockCenteringOffset };
        elementPositionsFinal.push(finalPos);

        // Applica la trasformazione finale (qui la centratura del blocco avviene)
        if (!opts || !opts.disableTransition === true) {
          p.item.addEventListener('transitionend', this.transitionEndHandler);
          p.item.classList.add('transition');
        }
        p.item.style.transform = `translate(${finalPos.x}px, ${finalPos.y}px)`;
      });

      // Reset per il prossimo blocco
      currentLayoutBlockElements = [];
      currentBlockMaxWidth = 0;

      // Se non è l'ultima riga, la Y massima è l'altezza più alta raggiunta dal layout, che è già in maxTotalHeight
    };

    // --- 1. Bin Packing (Riempimento e Raggruppamento per Blocchi) ---
    allItems.forEach((item) => {
      const itemW = item.offsetWidth;
      const itemH = item.offsetHeight;

      let maxCurrentLayoutHeight = 0;
      columnBottoms.forEach(h => maxCurrentLayoutHeight = Math.max(maxCurrentLayoutHeight, h));

      // --- GESTIONE FULL WIDTH (FORZATURA LINE BREAK E CENTRATURA DEL BLOCCO SOPRA) ---
      if (itemW >= itemFullWidthThreshold) {

        // 1. FINALIZZA il blocco precedente (lo centra e applica la trasformazione)
        finalizeCurrentBlock();

        // 2. POSIZIONAMENTO del blocco Full-Width (Forza sotto tutto)
        const startY = maxCurrentLayoutHeight + gap;
        const fullWidthCenteringOffset = Math.max(0, (containerWidth - itemW) / 2);

        const finalFullWidthPos = { item: item, x: fullWidthCenteringOffset, y: startY, w: itemW, h: itemH };
        elementPositionsFinal.push(finalFullWidthPos);

        // Applica la trasformazione immediata
        if (!opts || !opts.disableTransition === true) {
          item.addEventListener('transitionend', this.transitionEndHandler);
          item.classList.add('transition');
        }
        item.style.transform = `translate(${finalFullWidthPos.x}px, ${finalFullWidthPos.y}px)`;

        // 3. RESET per il layout (Packing) successivo
        const newBottom = startY + itemH + gap;
        columnBottoms.fill(newBottom); // Tutte le colonne ripartono da sotto il blocco full width
        maxTotalHeight = newBottom;

        return; // Passa all'elemento successivo
      }

      // --- LOGICA BIN PACKING STANDARD (Per elementi non Full-Width) ---

      const itemColumns = Math.max(1, Math.round(itemW / (baseColumnWidth + (gap/NUM_GRID_COLUMNS))));
      let bestColumnGroupIndex = -1;
      let minMaxColumnHeight = Infinity;

      // ... (Logica di ricerca del gruppo di colonne più corto, identica al tuo codice originale) ...
      for (let startCol = 0; startCol <= NUM_GRID_COLUMNS - itemColumns; startCol++) {
        let maxColHeightInGroup = 0;
        for (let k = 0; k < itemColumns; k++) {
          maxColHeightInGroup = Math.max(maxColHeightInGroup, columnBottoms[startCol + k]);
        }
        if (maxColHeightInGroup < minMaxColumnHeight) {
          minMaxColumnHeight = maxColHeightInGroup;
          bestColumnGroupIndex = startCol;
        }
      }

      // ... (Fallbacks) ...

      // Calcola le posizioni X e Y (temporanee, non centrate)
      const yPos = minMaxColumnHeight;
      const xPos = (bestColumnGroupIndex * (baseColumnWidth + gap));

      // Aggiungi al blocco temporaneo
      currentLayoutBlockElements.push({ item, x: xPos, y: yPos, w: itemW, h: itemH });

      // Aggiorna l'altezza di tutte le colonne che l'elemento ha coperto
      const newBottom = yPos + itemH + gap;
      for (let k = 0; k < itemColumns; k++) {
        columnBottoms[bestColumnGroupIndex + k] = newBottom;
      }

      // Aggiorna la larghezza e l'altezza massima (per il blocco e il contenitore)
      currentBlockMaxWidth = Math.max(currentBlockMaxWidth, xPos + itemW);
      maxTotalHeight = Math.max(maxTotalHeight, newBottom);
    });

    // --- 2. Centratura e Applicazione Finale ---
    finalizeCurrentBlock(true); // Finalizza l'ultimo blocco di elementi

    // --- 3. Gestione del Contenitore ---
    const finalMaxHeight = maxTotalHeight - gap; // Rimuove il gap finale (se esiste)

    // ... (Logica di regolazione altezza container e requestLayout) ...
    const totalHeight = finalMaxHeight;
    const cb = container.getBoundingClientRect();
    if (totalHeight < (window.innerHeight - cb.top)) {
      container.style.height = (window.innerHeight - cb.top) + 'px';
    } else {
      container.style.height = totalHeight + 'px';
    }

    if (initialHeight != container.offsetHeight) {
      setTimeout(() => { this.requestLayout(); }, 100)
    } else {
      this.yot.dashboardService.layoutEvents.next(DashboardLayoutEventValue.LayoutDone);
    }
  }


  private hitTestObject(target: HTMLElement, objectList: HTMLCollectionOf<any>, hitPercentageMin: number): any {
    const container = this.dashboardContainer.nativeElement;
    const placeholder = container.querySelector('div.placeholder') as HTMLElement;
    const bounds = target.getBoundingClientRect();
    if (hitPercentageMin == null) hitPercentageMin = 0.25; //default minimum hit percentage
    const hitOffset = 5;
    const hitPercentageMax = {
      element: null,
      percentage: 0,
      bounds
    };
    for (let j = 0; j < objectList.length; j++) {
      if (target === objectList[j] || placeholder === objectList[j] || !DashboardPageComponent.isLayoutItem(objectList[j]))
        continue;
      const compareBounds = objectList[j].getBoundingClientRect();
      if (!(bounds.right <= compareBounds.left+hitOffset || bounds.left >= compareBounds.right-hitOffset ||
        bounds.bottom <= compareBounds.top+hitOffset || bounds.top >= compareBounds.bottom-hitOffset)) {
        const collisionOffsetX = bounds.width * hitPercentageMin;
        const collisionOffsetY = bounds.height * hitPercentageMin;
        const hitsMinPercentage = !(bounds.right < compareBounds.left+collisionOffsetX || bounds.left > compareBounds.right-collisionOffsetX ||
          bounds.bottom < compareBounds.top+collisionOffsetY || bounds.top > compareBounds.bottom-collisionOffsetY);
        if (hitsMinPercentage) {
          const overlapX = Math.max(0, Math.min(bounds.right, compareBounds.right) - Math.max(bounds.left, compareBounds.left));
          const overlapY = Math.max(0, Math.min(bounds.bottom, compareBounds.bottom) - Math.max(bounds.top, compareBounds.top));
          const overlapArea = overlapX * overlapY;
          if (overlapArea > hitPercentageMax.percentage) {
            hitPercentageMax.percentage = overlapArea;
            hitPercentageMax.element = objectList[j];
          }
        }
      }
    }
    return hitPercentageMax;
  }

  /**
   * Gets computed translate values
   * @param {HTMLElement} element
   * @returns {Object}
   */
  private static getTranslateValues(element) {
    const style = window.getComputedStyle(element);
    const matrix = style['transform'];

    // No transform property. Simply return 0 values.
    if (matrix === 'none') {
      return {
        x: 0,
        y: 0,
        z: 0
      };
    }

    // Can either be 2d or 3d transform
    const matrixType = matrix.includes('3d') ? '3d' : '2d';
    const matrixValues = matrix.match(/matrix.*\((.+)\)/)[1].split(', ');

    // 2d matrices have 6 values
    // Last 2 values are X and Y.
    // 2d matrices does not have Z value.
    if (matrixType === '2d') {
      return {
        x: +matrixValues[4],
        y: +matrixValues[5],
        z: 0
      };
    }

    // 3d matrices have 16 values
    // The 13th, 14th, and 15th values are X, Y, and Z
    if (matrixType === '3d') {
      return {
        x: +matrixValues[12],
        y: +matrixValues[13],
        z: +matrixValues[14]
      };
    }
  }

  private arrayItemMove(arr, old_index, new_index): any {
    if (new_index >= arr.length) {
      let k = new_index - arr.length + 1;
      while (k--) {
       arr.push(undefined);
      }
    }
    arr.splice(new_index, 0, arr.splice(old_index, 1)[0]);
    return arr;
  }
}
