import {Component, OnInit} from '@angular/core';
import {Adapter} from "../../adapters/adapter";
import {YotService} from "../../services/yot/yot.service";
import {NavigationService} from "../../services/navigation.service";

@Component({
  selector: 'app-maintenance-page',
  templateUrl: './maintenance-page.component.html',
  styleUrls: ['./maintenance-page.component.scss']
})
export class MaintenancePageComponent implements OnInit {

  isLoading = false;
  selectedAdapter: Adapter;

  constructor(public yot: YotService, protected navigationService: NavigationService) {
    this.selectedAdapter = this.yot.getDefaultAdapter();
  }

  ngOnInit(): void {
    this.navigationService.toolbarTitle.emit('maintenance');
  }
}
