import {Component, OnInit, Input, Output, EventEmitter} from '@angular/core';
import { ViewChild, ElementRef, HostListener } from '@angular/core';
import { Module } from '../../../services/yot/module'
import {HomegenieAdapter} from "../../../adapters/home-genie/homegenie-adapter";

@Component({
  selector: 'app-nvr-browser',
  templateUrl: './nvr-browser.component.html',
  styleUrls: ['./nvr-browser.component.scss']
})
export class NvrBrowserComponent implements OnInit {

  @ViewChild('timelineTrack') timelineTrackElement: ElementRef;

  @Input()
  module: Module;

  @Input()
  set folder(value: string) {
    this._folder = value;
    this.refresh();
  }
  get folder(): string {
    return this._folder;
  }

  @Input()
  playerPosition: number;

  @Output()
  itemSelected: EventEmitter<any> = new EventEmitter();

  @Output()
  updated: EventEmitter<any> = new EventEmitter();

  @Output()
  zoomed: EventEmitter<any> = new EventEmitter();

  private _folder: string = this.getTodayDateString();

  // --- VIEWPORT STATE ---
  readonly SECONDS_IN_DAY = 86400; // 24 * 60 * 60
  viewStartSec: number = 0;        // Inizio della vista corrente (default 00:00)
  viewEndSec: number = 86400;      // Fine della vista corrente (default 24:00)

  // Array per la griglia del tempo dinamica
  timeTicks: { percent: number, label: string }[] =[];

  // Variabili per il Drag (Pan)
  isDragging: boolean = false;
  wasDragMoved: boolean = false;
  lastMouseX: number = 0;

  dayRecordings: any[];

  selectedRec: any;

  thumbnail = {
    visible: false,
    url: '',
    time: '',
    summary: '',
    top: '0px',
    left: '0px'
  };
  hideThumbnailTimeout = null;

  constructor() { }

  ngOnInit(): void {
    this.generateTimeGrid(); // Inizializza la griglia all'avvio
  }

  // ==========================================
  // DRAG & PAN (Spostamento Orizzontale)
  // ==========================================
  onMouseDown(e: MouseEvent) {
    this.isDragging = true;
    this.lastMouseX = e.clientX;
  }

  @HostListener('window:mouseup')
  onMouseUp() {
    this.isDragging = false;
    setTimeout(() => {
      this.wasDragMoved = false;
    });
  }

  onMouseMove(e: MouseEvent) {
    if (!this.isDragging) return;

    this.wasDragMoved = true;

    const deltaX = e.clientX - this.lastMouseX;
    this.lastMouseX = e.clientX;

    const trackWidth = this.timelineTrackElement.nativeElement.clientWidth;
    const viewDuration = this.viewEndSec - this.viewStartSec;
    const secondsPerPixel = viewDuration / trackWidth;

    const deltaSec = deltaX * secondsPerPixel;

    this.shiftViewport(-deltaSec);
  }

  shiftViewport(deltaSec: number) {
    let newStart = this.viewStartSec + deltaSec;
    let newEnd = this.viewEndSec + deltaSec;

    if (newStart < 0) {
      newEnd -= newStart;
      newStart = 0;
    }
    if (newEnd > this.SECONDS_IN_DAY) {
      newStart -= (newEnd - this.SECONDS_IN_DAY);
      newEnd = this.SECONDS_IN_DAY;
    }

    this.viewStartSec = Math.max(0, newStart);
    this.viewEndSec = Math.min(this.SECONDS_IN_DAY, newEnd);
    this.generateTimeGrid();
  }

  // ==========================================
  // ZOOM (Rotellina del Mouse)
  // ==========================================
  onWheel(e: WheelEvent) {
    e.preventDefault(); // Impedisce lo scroll della pagina intera

    const trackRect = this.timelineTrackElement.nativeElement.getBoundingClientRect();
    const mouseX = e.clientX - trackRect.left; // Posizione X del mouse sulla barra
    const mousePercent = mouseX / trackRect.width; // Es. 0.5 se il mouse è al centro

    const viewDuration = this.viewEndSec - this.viewStartSec;

    // A che ora esatta punta il cursore del mouse in questo momento?
    const timeUnderCursor = this.viewStartSec + (mousePercent * viewDuration);

    // Zoom IN (-10%) o Zoom OUT (+10%)
    const zoomFactor = e.deltaY > 0 ? 1.1 : 0.9;
    let newDuration = viewDuration * zoomFactor;

    // Limiti di zoom: min 1 minuto, max 24 ore
    newDuration = Math.max(60, Math.min(this.SECONDS_IN_DAY, newDuration));

    // Ricalcola start ed end mantenendo immobile l'orario sotto il cursore
    let newStart = timeUnderCursor - (newDuration * mousePercent);
    let newEnd = newStart + newDuration;

    // Controllo bordi 0 e 24h
    if (newStart < 0) {
      newStart = 0;
      newEnd = newDuration;
    }
    if (newEnd > this.SECONDS_IN_DAY) {
      newEnd = this.SECONDS_IN_DAY;
      newStart = this.SECONDS_IN_DAY - newDuration;
    }

    this.viewStartSec = newStart;
    this.viewEndSec = newEnd;
    this.generateTimeGrid();
    this.zoomed.emit({newStart, newEnd});
  }

// ==========================================
// GENERAZIONE GRIGLIA DINAMICA
// ==========================================
  generateTimeGrid() {
    this.timeTicks =[];
    const duration = this.viewEndSec - this.viewStartSec;

    // Decide ogni quanti secondi mettere una tacca in base allo zoom
    let stepSec = 3600; // Default: 1 ora
    if (duration <= 600) stepSec = 60;          // Zoom < 10 min -> tacche ogni minuto
    else if (duration <= 3600) stepSec = 300;   // Zoom < 1 ora -> tacche ogni 5 min
    else if (duration <= 14400) stepSec = 1800; // Zoom < 4 ore -> tacche ogni 30 min
    else if (duration <= 43200) stepSec = 3600; // Zoom < 12 ore -> tacche ogni 1 ora
    else stepSec = 14400;                       // Zoom totale -> tacche ogni 4 ore

    // Trova il primo multiplo di stepSec visibile
    let firstTick = Math.ceil(this.viewStartSec / stepSec) * stepSec;

    for (let t = firstTick; t <= this.viewEndSec; t += stepSec) {
      const percent = ((t - this.viewStartSec) / duration) * 100;

      // Formatta HH:mm
      const hours = Math.floor(t / 3600).toString().padStart(2, '0');
      const mins = Math.floor((t % 3600) / 60).toString().padStart(2, '0');

      this.timeTicks.push({ percent, label: `${hours}:${mins}` });
    }
  }

  getTodayDateString(): string {
    const now = new Date();
    const year = now.getFullYear();
    // getMonth() starts from 0
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const day = now.getDate().toString().padStart(2, '0');

    return `${year}${month}${day}`;
  }

  // Calcola lo stile CSS per ogni segmento
  getSegmentStyle(rec: any, progressMs?: number): { [key: string]: string } {
    if (!this.folder) return null;
    // --- PREPARAZIONE DEI DATI ASSOLUTI ---
    const clipStartTime: Date = rec._startTime;
    const clipEndTime: Date = progressMs ? new Date(clipStartTime.getTime() + progressMs) : rec._endTime;

    // --- RICOSTRUZIONE DELLA DATA DI INIZIO DELLA TIMELINE DA this.folder ---
    // Estrai l'anno, il mese e il giorno dalla stringa 'YYYYMMDD/HHMMSS'
    const year = parseInt(this.folder.substring(0, 4), 10);
    const month = parseInt(this.folder.substring(4, 6), 10) - 1; // Mesi in JS sono 0-11
    const day = parseInt(this.folder.substring(6, 8), 10);

    // Crea l'oggetto Date per la mezzanotte del giorno visualizzato
    const timelineDayStart = new Date(year, month, day, 0, 0, 0, 0);
    const timelineDayStartMs = timelineDayStart.getTime();

    // --- CALCOLO LINEARE USANDO MILLISECONDI (il più robusto) ---

    // 1. Calcola l'offset in secondi della clip rispetto all'inizio del giorno della timeline.
    const clipStartOffsetSeconds = (clipStartTime.getTime() - timelineDayStartMs) / 1000;

    // 2. La durata in secondi è già corretta.
    const durationSeconds = (clipEndTime.getTime() - clipStartTime.getTime()) / 1000;

    // 3. La durata della VISTA deve comunque gestire il cross-midnight.
    let viewEnd = this.viewEndSec;
    if (viewEnd < this.viewStartSec) {
      viewEnd += 86400;
    }
    const viewDuration = viewEnd - this.viewStartSec;

    if (viewDuration <= 0) return { 'display': 'none' };

    // 4. Calcola la posizione relativa della clip.
    const relativeStart = clipStartOffsetSeconds - this.viewStartSec;

    const leftPercent = (relativeStart / viewDuration) * 100;
    const widthPercent = (durationSeconds / viewDuration) * 100;

    // Ottimizzazione
    if (leftPercent > 100 || (leftPercent + widthPercent) < 0) {
      return { 'display': 'none' };
    }

    return {
      'left.%': leftPercent.toFixed(4),
      'width.%': widthPercent.toFixed(4),
      'display': 'block'
    };
  }

  onSegmentClick(rec: any, offset: number): void {
    if (!this.wasDragMoved)
    {
      this.selectedRec = rec;
      this.itemSelected.emit({recording: rec, offset});
    }
  }

  showThumbnail(event: MouseEvent, rec: any) {
    // 1. Calcola l'offset temporale in base alla posizione del mouse
    const segmentDiv = event.currentTarget as HTMLElement;
    const rect = segmentDiv.getBoundingClientRect();

    // Posizione del mouse relativa all'inizio del segmento (in pixel)
    const mouseX = event.clientX - rect.left;

    // Percentuale di progressione all'interno del segmento
    const progressPercent = mouseX / rect.width;

    // Durata totale del segmento in secondi
    const durationSeconds = (rec._endTime.getTime() - rec._startTime.getTime()) / 1000;

    // Offset in secondi da passare all'API
    const offsetSeconds = Math.floor(progressPercent * durationSeconds);

    // Calcola l'ora esatta per il tooltip
    const previewTime = new Date(rec._startTime.getTime() + (offsetSeconds * 1000));

    // 2. Chiama l'API per l'URL della thumbnail (qui usiamo la cache)
    // Assumiamo che tu abbia un metodo `getThumbnailUrl` nel tuo servizio/adapter
    const hgm = (this.module.getAdapter() as HomegenieAdapter).getModule(this.module.id);
    this.thumbnail.url = `/api/HomeAutomation.HomeGenie/NVR/Recordings.Thumbnail/${encodeURIComponent(hgm.Domain)}/${encodeURIComponent(hgm.Address)}/${rec.FolderName}/${offsetSeconds}`;

    // 3. Imposta le proprietà per mostrare la thumbnail
    this.thumbnail.visible = true;
    this.thumbnail.time = previewTime.toLocaleTimeString();
    this.thumbnail.summary = rec.MediaSummary;

    // 4. Posiziona la thumbnail sopra la timeline
    const trackRect = (event.currentTarget as HTMLElement).parentElement.getBoundingClientRect();
    this.thumbnail.left = `${event.clientX - trackRect.left}px`;
    this.thumbnail.top = `-${100}px`; // Esempio: 100px sopra la barra

    clearTimeout(this.hideThumbnailTimeout);
    this.hideThumbnailTimeout = setTimeout(() => {
      this.hideThumbnail();
    }, 2500);
  }

  // Il mouse esce dal segmento
  hideThumbnail() {
    this.thumbnail.visible = false;
    this.thumbnail.url = ''; // Resetta l'url per evitare flickering
  }

  // Stile dinamico per il contenitore della thumbnail
  getThumbnailStyle() {
    return {
      'top': this.thumbnail.top,
      'left': this.thumbnail.left,
      'transform': 'translateX(-50%)' // Centra la preview sul cursore
    };
  }

  refresh() {
    const homegenieAdapter = this.module?.getAdapter() as HomegenieAdapter;
    const hgm = homegenieAdapter?.getModule(this.module.id);
    if (homegenieAdapter && hgm) {
      homegenieAdapter.apiCall(`HomeAutomation.HomeGenie/NVR/Recordings.List/${encodeURIComponent(hgm.Domain)}/${encodeURIComponent(hgm.Address)}/${this.folder}`)
        .subscribe({
          next: (data) => {
            const todayRecordings = data.response.map((r) => ({
              _startTime: new Date(r.StartTime),
              _endTime: new Date(r.EndTime),
              ...r
            }));
            this.dayRecordings = todayRecordings;
            this.updated.emit(this.dayRecordings);
          },
          error: err => {
            // TODO: ...
          }
        });
    }
  }

  resetTimeBar() {
    this.viewStartSec = 0;
    this.viewEndSec = 86400;
  }
}
