export class ZxWidget extends HTMLElement {
  private container = document.createElement('div');
  private context: ComponentContext;
  private loadGeneration = 0;
  private eventSubscriptions: Subscription[] = [];
  private showSettingsCallback = null;
  private configureCallback = null;

  constructor(props) {
    super();
    const s = this.container.style;
//    s.display = 'flex';
    s.overflow = 'hidden';
//    s.alignItems = 'center';
//    s.justifyContent = 'center';
    s.height = '100%';
    this.attachShadow({mode: 'closed'})
      .append(this.container);

    const loadComponent = this.attributes.getNamedItem('load');
    if (loadComponent) {
      const parentComponent = zuix.$(this).parent('[z-load]');
      zuix.context(parentComponent, (ctx) => {
        const module = zuix.runScriptlet('context.options().module', parentComponent, parentComponent);
        let options = this.attributes.getNamedItem('options');
        options = zuix.runScriptlet(`(${options.value})`, parentComponent, parentComponent);
        let componentId = loadComponent.value;
        if (!componentId.startsWith('/') && componentId.indexOf('://') === -1) {
          componentId = `/widgets/${componentId}`;
        }
        this.load(componentId, module, options);
      });
    }

  }
  connectedCallback() {
    // TODO:  ...
  }
  disconnectedCallback() { this.unload(); }
  public load(componentId: string, module:  Module, options: any, yot?: YotService) {
    this.unload();
    const generation = this.loadGeneration;
    this.container.innerHTML = '';
    if (yot) {
      this.container
        .classList.add(`${yot.preferences.ui.theme === 'dark' ? 'dark' : 'light'}-theme`);
    }
    try {
      zuix.loadComponent(this.container, componentId, null, {
        container: this.shadowRoot as any,
        ...options,
        controllerMembers: {
          get boundModule(): Module {
            return module;
          },
          configure: () => {
            return (this.configureCallback && this.configureCallback());
          },
          showSettings: () => {
            this.showSettingsCallback && this.showSettingsCallback();
          },
          subscribe: (f: ModuleField, handler): Subscription => {
            const subject: any = (typeof f.events === 'function') ? f.events() : f.events;
            const subscription = subject.subscribe((field) => {
              handler(field);
            });
            this.eventSubscriptions.push(subscription);
            return subscription;
          },
          apiCall: (apiMethod: string, postData?: any, opts?: any): Subject<ApiResponse> => {
            const subject = new Subject<ApiResponse>();
            let adapter = (module?.getAdapter() as HomegenieAdapter);
            if (!adapter) {
              // fallback to YoT default adapter if available
              adapter = (yot?.getDefaultAdapter() as HomegenieAdapter);
            }
            adapter?.apiCall(apiMethod, postData, opts)
              .subscribe({
                next: (res) => {
                  if (typeof res.response === 'string' && res.response.startsWith('ey')) {
                    try {
                      const decoded = atob(res.response);
                      res.response = JSON.parse(decoded);
                    } catch (e) {
                      // 3. Fallback: se fallisce il parsing (es. è un'immagine o altro binario
                      // che per caso iniziava con 'ey'), lasciamo la stringa originale.
                    }
                  }
                  subject.next(res);
                },
                error: (err) => {
                  subject.error(err);
                },
                complete: () => {
                  subject.complete();
                }
              });
            return subject;
          },
          translate: (k: string) => {
            return yot?.translate.get(`WIDGETS.${k}`);
          }
        },
        ready: (ctx) => {
          if (generation !== this.loadGeneration) { zuix.unload(ctx); return; }
          this.context = ctx;
          if (options?.css) {
            ctx.style(options.css);
          }
          if (typeof options?.ready === 'function') {
            options?.ready(ctx);
          }

        },
        error: (err) => {
          if (generation !== this.loadGeneration) return;
          if (typeof options?.error === 'function') {
            options?.error(err);
          }
          //throw err; <-- this will break zuix.js loader at some point
          // --> A timeout prevents this by throwing the exception outside the zuix.js loader context
          if (options?.suppressGlobalError) return;
          setTimeout(() => {
            throw err;
          });
        }
      } as any);
    } catch (error) {
      if (typeof options?.error === 'function') options.error(error);
      if (!options?.suppressGlobalError) console.error('ERROR-CHECK-#1', error);
    }
  }
  public unload() {
    this.loadGeneration++;
    this.eventSubscriptions.forEach((sub) => sub.unsubscribe());
    this.eventSubscriptions = [];
    if (this.context) {
      // unload and dispose context
      zuix.unload(this.context);
      this.context = undefined;
    }
  }

  setConfigureCallback(callback: () => void) {
    this.configureCallback = callback;
  }

  setSettingsCallback(callback: () => void) {
    this.showSettingsCallback = callback;
  }
}
if (customElements.get('zx-widget') === undefined) {
  customElements.define('zx-widget', ZxWidget);
}

