import {Subject} from 'rxjs';

export class LocationInfo {
  name = 'Rome, RM, Italia';
  latitude = 41.9027835;
  longitude = 12.4963655;
}

export interface GeolocationAdapter {
  // get location names matching a given filter
  search(locationFilter: string): Subject<string[]>;
  // get location name by coordinates
  lookup(coordinates: any): Subject<LocationInfo>;
  // get coordinates given a location name
  getLocationCoordinates(locationName: string): Subject<LocationInfo>;
}
