import {Component, OnInit, ViewChild} from '@angular/core';
import {WidgetBaseComponent} from "../widget-base.component";
import {MatSliderChange} from "@angular/material/slider";
import {CMD, FLD} from "../../services/yot/yot.service";
import * as moment from "moment";
import {ActivityStatusComponent} from "../common-parts/activity-status/activity-status.component";
import {HomegenieZwaveApi} from "../../adapters/home-genie/homegenie-zwave-api";
import {HomegenieAdapter} from "../../adapters/home-genie/homegenie-adapter";
import {
  TextInputDialogComponent,
  TextInputDialogConfig
} from "../../components/dialogs/text-input-dialog/text-input-dialog.component";

export class ShutterFeatures {
  public level: boolean;
}

@Component({
  selector: 'app-shutter',
  templateUrl: './shutter.component.html',
  styleUrls: ['./shutter.component.scss']
})
export class ShutterComponent extends WidgetBaseComponent implements OnInit {
  @ViewChild(ActivityStatusComponent)
  private activityStatus: ActivityStatusComponent;

  isLoading = false;

  calibrationParameter: string;

  private readonly GENERIC_ERROR_MESSAGE = 'Error issuing command';

  get features(): ShutterFeatures {
    return super.features;
  }
  get statusText(): string {
    const level = this.module.field(FLD.Status.Level);
    let status = 'Closed';
    if (this.level === 100) {
      status = 'Open';
    } else if (this.level > 0) {
      status = this.level + '%';
    } else if (level && level.value) {
      status += ' ' + moment(level.timestamp).fromNow();
    }
    return status;
  }
  get level(): number {
    let l = null;
    const level = this.module.field(FLD.Status.Level);
    if (level?.value != null) {
      l = Math.round(this.utils.getFloatValue(level.value) * 100);
    }
    return l;
  }

  private pendingSetLevelRequest = null;
  set level(n: number) {
    if (this.isLoading) {
      clearTimeout(this.pendingSetLevelRequest);
      this.pendingSetLevelRequest = setTimeout(() => {
        this.level = n;
      }, 50);
      return;
    }
    const subject = this.module?.control(CMD.Control.Level, n);
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => this.isLoading = false,
        error: (err) => {
          this.activityStatus.setError(this.GENERIC_ERROR_MESSAGE);
          this.isLoading = false;
        }
      });
    }
  }

  get levelStep(): number {
    return +this.module.field('Widget.Preference.LevelStep')?.value;
  }

  ngOnInit() {
    super.ngOnInit();
    const shutterCalibration = this.module.field("ZWaveNode.Calibration");
    if (shutterCalibration) {
      this.calibrationParameter = shutterCalibration.value;
    }
  }

  onSliderInput(e: MatSliderChange) {
    this.level = e.value;
  }
  onSliderPointerUp(e: PointerEvent) {
    const levelHome = this.module.field("Widget.Preference.HomeLevel");
    const autoHome = this.module.field("Widget.Preference.AutoHome");
    if (levelHome && autoHome && autoHome.value === "true") {
      setTimeout(() => this.level = +levelHome.value);
    }
  }

  onOpenButtonClick($event: MouseEvent) {
    if (this.isLoading) return;
    const subject = this.module?.control(CMD.Control.On);
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => this.isLoading = false,
        error: (err) => {
          this.activityStatus.setError(this.GENERIC_ERROR_MESSAGE);
          this.isLoading = false;
        }
      });
    }
  }

  onCloseButtonClick($event: MouseEvent) {
    if (this.isLoading) return;
    const subject = this.module?.control(CMD.Control.Off);
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => this.isLoading = false,
        error: (err) => {
          this.activityStatus.setError(this.GENERIC_ERROR_MESSAGE);
          this.isLoading = false;
        }
      });
    }
  }

  onCalibrationMenuOpened() {
    const calibrationField = this.module.field("ZWaveNode.Calibration");
    this.calibrationParameter = calibrationField ? calibrationField.value : '';
  }

  openCalibrationSettings() {
    const dialogRef = this.yot.dialog.open(TextInputDialogComponent, {
      disableClose: false,
      data: {
        title: this.calibrationParameter ? 'ZWAVE.edit_calibration_parameter' : 'ZWAVE.calibration_parameter_not_set',
        label: 'ZWAVE.calibration_parameter_number',
        placeholder: 'enter_number',
        value: this.calibrationParameter,
        pattern: '^(0|[1-9][0-9]*)$',
        patternError: 'Invalid number entered'
      } as TextInputDialogConfig
    });
    dialogRef.afterClosed().subscribe((parameterNumber) => {
      if (parameterNumber) {
        this.isLoading = true;
        this.module.control(CMD.Options.Set, {['ZWaveNode.Calibration']: parameterNumber}).subscribe((res) => {
          this.calibrationParameter = parameterNumber;
          this.isLoading = false;
          this.calibrateDevice(parameterNumber);
        });
      }
    });
  }

  calibrateDevice(parameterNumber: string) {
    const hg = (this.module.getAdapter() as HomegenieAdapter);
    // Currently only Z-Wave is supported
    const command = HomegenieZwaveApi.Config.Parameter.Set
      .replace('{{nodeId}}', hg.getModulePath(this.module))
      .replace('{{parameterId}}', parameterNumber)
      .replace('{{parameterValue}}', '1');
    this.isLoading = true;
    hg.apiCall(command).subscribe((res) => {
      this.isLoading = false;
    });
  }
}
