import {Component, OnDestroy, OnInit} from '@angular/core';
import {FLD} from "../../services/yot/yot.service";
import * as moment from 'moment';
import {Subscription} from "rxjs";
import {SystemApi} from "../../api/system-api";
import {WidgetBaseComponent} from "../widget-base.component";
import {WidgetActionRequestAction} from "../common-parts/widget-actions-menu/widget-actions-menu.component";


@Component({
  selector: 'app-action-button',
  templateUrl: './action-button.component.html',
  styleUrls: ['./action-button.component.scss']
})
export class ActionButtonComponent extends WidgetBaseComponent implements OnInit, OnDestroy {
  isLoading = false;

  statusText = '';

  private statusEventSubscription: Subscription;

  ngOnInit(): void {
    super.ngOnInit();
    if (this.module) {
      const programStatus = this.module.field(FLD.Program.Status);
      if (programStatus) {
        this.statusText = programStatus.value + ' &nbsp; <span class="translucent">' + moment(programStatus.timestamp).fromNow() + '</span>';
        this.statusEventSubscription = programStatus.events().subscribe((f) => {
          setTimeout(() => {
            this.statusText = programStatus.value + ' &nbsp; <span class="translucent">' + moment(programStatus.timestamp).fromNow() + '</span>';
          });
        });
      }
    }
  }
  ngOnDestroy(): void {
    if (this.statusEventSubscription) {
      this.statusEventSubscription.unsubscribe();
    }
  }

  onProgramButtonClick(e): void {
    if (e.target.tagName.toLowerCase() === 'mat-icon') return; // hit the menu button
    // TODO: action-button options should be set via module-options, replace this static 'group' field with a customizable option field
    const dashboard = this.yot.dashboardService.getCurrentDashboard();
    let group;
    if (dashboard) {
      group = dashboard.name;
    }
    const subject = this.module?.getAdapter()?.system(SystemApi.Automation.Programs.Toggle, {
      module: this.module,
      // TODO: this should reflect the modules group name where this HG module is located or it should be at least a program option (better)
      group
    });
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => {
          this.isLoading = false;
        },
        error: (err) => {
          console.log('error', err);
          this.isLoading = false;
        }
      });
    }
  }
}
