import {Component, ViewChild} from '@angular/core';
import {CMD, FLD} from '../../services/yot/yot.service';
import {ColorPickerDialogComponent} from "../../components/dialogs/color-picker-dialog/color-picker-dialog.component";
import {Color} from "@iplab/ngx-color-picker";
import {WidgetBaseComponent} from "../widget-base.component";
import {ActivityStatusComponent} from "../common-parts/activity-status/activity-status.component";
import * as moment from 'moment';

export class GenericSwitchFeatures {
  public color: boolean;
  public dimming: boolean;
}

@Component({
  selector: 'app-generic-switch',
  templateUrl: './generic-switch.component.html',
  styleUrls: ['./generic-switch.component.scss']
})
export class GenericSwitchComponent extends WidgetBaseComponent {
  @ViewChild(ActivityStatusComponent)
  private activityStatus: ActivityStatusComponent;

  defaultConfiguration = {
    colorPresets: ['#428828', '#EF531F', '#886A28', '#43AAA4']
  };
  colorPresetsCount = 4;
  currentPreset = -1;

  isLoading = false;

  private readonly GENERIC_ERROR_MESSAGE = 'Error issuing command';

  get features(): GenericSwitchFeatures {
    return super.features;
  }

  get statusText(): string {
    const level = this.module.field(FLD.Status.Level);
    let status = 'off';
    this.yot.translate.get(status).subscribe((tr) => status = tr);
    if (this.level === 100) {
      status = 'on';
      this.yot.translate.get(status).subscribe((tr) => status = tr);
    } else if (this.level > 0) {
      status = this.level + '%';
    }
    if (level && level.value) {
      status += ' <span class="translucent mat-small" style="margin-left: 6px">' + moment(level.timestamp).fromNow() + '</span>';
    }
    return status;
  }

  get level(): number {
    let l = null;
    const level = this.module.field(FLD.Status.Level);
    if (level && level.value) {
      l = Math.round(this.utils.getFloatValue(level.value) * 100);
    }
    return l;
  }
  private pendingSetLevelRequest = null;
  set level(n: number) {
    if (this.isLoading) {
      clearTimeout(this.pendingSetLevelRequest);
      this.pendingSetLevelRequest = setTimeout(() => {
        this.level = n;
      }, 50);
      return;
    }
    const subject = this.module?.control(CMD.Control.Level, n);
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => this.isLoading = false,
        error: (err) => {
          this.activityStatus.setError(this.GENERIC_ERROR_MESSAGE);
          this.isLoading = false;
        }
      });
    }
  }

  private _color = '#550a55';
  get color(): string {
    const hsvField = this.module.field(FLD.Status.ColorHsb);
    if (hsvField) {
      let hsv = hsvField.value.split(',').map(v => +v);
      const h = hsv[0] * 360;
      const s = hsv[1] * 100;
      const v = hsv[2] * 100;
      if (hsv[3]) {
        this.colorTransition = hsv[3] + 's';
      }
      const c = new Color();
      c.setHsva(h, s, v, 1);
      this._color = c.toHexString();
    }
    return this._color;
  }
  private pendingSetColorRequest = null;
  set color(c: string) {
    if (this.isLoading) {
      clearTimeout(this.pendingSetColorRequest);
      this.pendingSetColorRequest = setTimeout(() => {
        this.color = c;
      }, 50);
      return;
    }
    const color = Color.from(c);
    const hsv = color.getHsva();
    const h = hsv.hue / 360.0;
    const s = hsv.saturation / 100.0;
    const v = hsv.value / 100.0;
    const transition = 0.4; // 400ms color transition duration
    const options = `${h},${s},${v},${transition}`;
    const subject = this.module?.control(CMD.Control.ColorHsb, options);
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => {
          this._color = c;
          this.isLoading = false;
        },
        error: (err) => {
          this.activityStatus.setError(this.GENERIC_ERROR_MESSAGE);
          this.isLoading = false;
        }
      });
    }
  }
  colorTransition = '400ms';

  onOnButtonClick(e): void {
    if (this.isLoading) return;
    const subject = this.module?.control(CMD.Control.On);
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => this.isLoading = false,
        error: (err) => {
          this.activityStatus.setError(this.GENERIC_ERROR_MESSAGE);
          this.isLoading = false;
        }
      });
    }
  }
  onOffButtonClick(e): void {
    if (this.isLoading) return;
    const subject = this.module?.control(CMD.Control.Off);
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => this.isLoading = false,
        error: (err) => {
          this.activityStatus.setError(this.GENERIC_ERROR_MESSAGE);
          this.isLoading = false;
        }
      });
    }
  }
  onToggleButtonClick(e: MouseEvent) {
    if (this.isLoading) return;
    const subject = this.module?.control(CMD.Control.Toggle);
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => this.isLoading = false,
        error: (err) => {
          this.activityStatus.setError(this.GENERIC_ERROR_MESSAGE);
          this.isLoading = false;
        }
      });
    }
  }

  onColorClick() {
    this.currentPreset = -1;
    if (this.level === 0 && this.color !== this._color) {
      this.color = this._color;
      return;
    }
    this.pickColor();
  }

  onPresetColorClick(presetIndex: number) {
    const preset = this.configuration.colorPresets[presetIndex];
    if (this.currentPreset !== presetIndex) {
      // select and set current preset
      this.currentPreset = presetIndex;
      this.color = preset;
      return;
    }
    this.pickColor((color) => {
      this.configuration.colorPresets[presetIndex] = color.toHexString(true);
      this.save();
    });
  }

  onSliderInput(e: any) {
    this.level = e.value;
  }

  invertColor(color: string): string {
    const c = Color.from(color);
    const rgba = c ? c.getRgba() : {red:255, green:255, blue: 255};
    return (rgba.red * 0.299 + rgba.green * 0.587 + rgba.blue * 0.114) > 186
      ? '#000000'
      : '#FFFFFF';
  }

  private pickColor(callback?: Function) {
    const currentColor = this._color;
    const dialogRef = this.dialog.open(ColorPickerDialogComponent, {
      // height: '400px',
      width: '100%',
      minWidth: '300px',
      maxWidth: '300px',
      disableClose: false,
      data: {
        module: this.module,
        color: this._color,
        callback: (color: Color) => {
          this.color = color.toHexString(true);
        }
      }
    });
    dialogRef.afterClosed().subscribe((color: Color) => {
      if (color && currentColor === color.toHexString(true)) {
        // color was not changed, just return
        return;
      }
      if (!color) {
        // restore current color if user canceled the dialog
        color = Color.from(currentColor);
      }
      this.color = color.toHexString(true);
      if (callback) callback(color);
    });
  }
}
