import { AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';

/**
 * Validatore che controlla se il nome esiste già.
 * @param existingNames Array di nomi che non possono essere usati.
 */
export function duplicateNameValidator(existingNames: string[]): ValidatorFn {
  return (control: AbstractControl): ValidationErrors | null => {

    if (!control.value) {
      return null; // Lascia che 'required' gestisca l'errore se il campo è vuoto
    }

    const nameToCheck = control.value.toLowerCase();

    const isDuplicate = existingNames?.some(name => name.toLowerCase() === nameToCheck);

    // Se duplicato, restituisce l'oggetto di errore. Altrimenti, restituisce null.
    return isDuplicate ? { 'duplicateName': true } : null;
  };
}
