import {Component, Input, OnInit} from '@angular/core';
import {Module, ModuleField} from "../../../services/yot/module";
import {Subscription} from "rxjs";
import {FLD} from "../../../services/yot/yot.service";
import {SensorField} from "../../../api/widgets/sensor-widget.api";
import {ZwaveApi} from "../../../api/zwave-api";

@Component({
  selector: 'app-activity-status',
  templateUrl: './activity-status.component.html',
  styleUrls: ['./activity-status.component.scss']
})
export class ActivityStatusComponent implements OnInit {
  @Input()
  module: Module;
  @Input()
  statusText: string;
  @Input()
  showLoading: boolean;
  errorText = '';
  isLedActive = false;

  get meterWatts(): ModuleField {
    return this.module.field(SensorField.Meter.Watts);
  }
  get statusBattery(): ModuleField{
    return this.module.field(FLD.Status.Battery);
  }
  get isSleeping(): boolean {
    const sleepingMode = this.module.field(ZwaveApi.fields.SleepingStatus);
    return sleepingMode && +sleepingMode.value === 1
  }

  private ledTimeout: any = null;
  private eventSubscription: Subscription;

  constructor() { }

  ngOnInit(): void {
    this.eventSubscription = this.module.events.subscribe((e) => {
      if (e.key === FLD.Status.Error) {
        this.setError(e.value);
      }
      this.blinkLed();
    });
  }
  ngOnDestroy(): void {
    if (this.eventSubscription) {
      this.eventSubscription.unsubscribe();
    }
  }

  public setError(message: string): void {
    this.errorText = message;
    this.blinkLed();
  }

  private blinkLed(): void {
    if (this.isLedActive && this.errorText.length > 0) return;
    clearTimeout(this.ledTimeout);
    this.isLedActive = true;
    this.ledTimeout = setTimeout(() => {
      this.isLedActive = false;
      this.errorText = '';
    }, this.errorText.length > 0 ? 1000 : 100);
  }
}
