import {Injectable} from '@angular/core';
import {MediaMatcher} from "@angular/cdk/layout";
import {Subject} from "rxjs";

@Injectable({
  providedIn: 'root'
})
export class LayoutService {

  private smallScreenMatcher: MediaQueryList;

  private dockAction = new Subject<boolean>();
  dockAction$ = this.dockAction.asObservable();

  triggerDock(isDocked: boolean) {
    this.dockAction.next(isDocked);
  }

  constructor(
    public mediaMatcher: MediaMatcher
  ) {
    this.smallScreenMatcher = this.mediaMatcher.matchMedia('(max-width: 500px)');
  }

  get isSmallScreen(): boolean {
    return this.smallScreenMatcher.matches;
  }

  contextualHelpLink: string = "";
}
