import {Component, EventEmitter, Input, OnInit, Output} from '@angular/core';
import {LocationInfo} from "../../../geolocation-adapter"
import {Observable, of} from "rxjs";
import {catchError, map} from "rxjs/operators";
import {HomegenieAdapter} from "../../homegenie-adapter";
import {LocationDialogComponent} from "../location-picker-dialog/location-dialog.component";

@Component({
  selector: 'app-location-picker',
  templateUrl: './location-picker.component.html',
  styleUrls: ['./location-picker.component.scss']
})
export class LocationPickerComponent implements OnInit {
  @Input()
  adapter: HomegenieAdapter;
  @Input()
  showMap = false;
  @Input()
  locationInfo = new LocationInfo();
  @Input()
  hideMapButton = false;
  @Output()
  locationChange = new EventEmitter<LocationInfo>();

  static apiLoaded = false;
  apiLoadedObservable: Observable<boolean>;
  googleMap: google.maps.Map;
  locationMarker: google.maps.LatLngLiteral;

  LocationPickerComponent = LocationPickerComponent;

  locationFilteredOptions = [];

  constructor() {
  }

  ngOnInit(): void {
    if (!LocationPickerComponent.apiLoaded) {
      let _k_e_y = 'AIza'; _k_e_y += 'SyCSSM'; _k_e_y += 'sdcyihg'; _k_e_y += 'UsHWYCwGcGXBSNu1kWgCGQ';
      const a = 'aps';
      const b = '.goo';
      const c = 'gleapis';
      const d = '.com/ma';
      this.apiLoadedObservable = this.adapter.yot.http.jsonp('https://m' + a + b + c + d + 'ps/api/js?key=' + _k_e_y, 'callback')
        .pipe(
          map(() => true),
          catchError(() => of(false)),
        );
      this.apiLoadedObservable
        .subscribe(loaded => LocationPickerComponent.apiLoaded = loaded);
    }
  }

  onGoogleMapInit(map: google.maps.Map) {
    this.locationMarker = {
      lat: this.locationInfo.latitude,
      lng: this.locationInfo.longitude
    }
    this.googleMap = map;
    map.setCenter(this.locationMarker);
  }
  onGoogleMapClick(event: google.maps.MapMouseEvent) {
    this.setLocationCoords(event.latLng.toJSON(), false);
  }

  onLocationButtonClick(e) {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position: any /* Position */) => {
          const pos = {
            lat: position.coords.latitude,
            lng: position.coords.longitude,
          };
          this.setLocationCoords(pos);
        }, (err) => {
          this.adapter.yot.notify("Error", err.message);
        });
    } else {
      this.adapter.yot.notify("Error", "Browser geolocation is not enabled.");
    }
  }

  onLocationPickClick() {
    this.adapter.yot.dialog.open(LocationDialogComponent, {
      data: {adapter: this.adapter, locationInfo: this.locationInfo},
    }).afterClosed().subscribe((newLocation) => {
      if (newLocation) {
        this.locationChange.emit(newLocation);
      }
    });
  }

  onLocationFieldChange(e: any) {
    this.getAutocompleteResults(e.target.value);
  }

  onLocationAutoCompleteSelect(e: any) {
    this.locationInfo.name = e.option.value;
    this.adapter.geolocation.getLocationCoordinates(this.locationInfo.name)
      .subscribe((info) => {
        this.setLocationCoords({lat: info.latitude, lng: info.longitude});
      });
  }

  setLocationCoords(latLng: google.maps.LatLngLiteral, centerMap?: boolean) {
    this.locationMarker = latLng;
    this.adapter.geolocation.lookup(latLng)
      .subscribe((info) => {
        this.locationInfo = info;
        this.locationChange.next(info);
      });
    if (centerMap !== false && this.googleMap) {
      this.googleMap.setCenter(latLng);
    }
  }

  private getAutocompleteResults(filter: string): void {
    this.adapter.geolocation.search(filter)
      .subscribe((locationList) => {
        this.locationFilteredOptions = locationList;
      });
  }
}
