import {Component, Inject} from '@angular/core';
import {HomegenieAdapter} from "../homegenie-adapter";
import {MAT_DIALOG_DATA, MatDialogRef} from "@angular/material/dialog";
import {HomegenieApi, SchedulerItem} from "../homegenie-api";

@Component({
  selector: 'app-scheduler-wizard-dialog',
  templateUrl: './scheduler-wizard-dialog.component.html',
  styleUrls: ['./scheduler-wizard-dialog.component.scss']
})
export class SchedulerWizardDialogComponent {

  adapter: HomegenieAdapter;
  schedulerItem: SchedulerItem;
  scheduleList: any;

  isLoading = false;

  get isNew(): boolean {
    return (this.schedulerItem == null || (this.schedulerItem.Name != null && this.schedulerItem.Name.length > 0)) === false;
  }

  constructor(@Inject(MAT_DIALOG_DATA) data: {adapter: HomegenieAdapter, scheduleName?: string, scheduleList?: any},
              private dialogRef: MatDialogRef<SchedulerWizardDialogComponent>) {
    this.adapter = data.adapter;
    this.scheduleList = data.scheduleList;
    if (data.scheduleName) {
      this.isLoading = true;
      this.adapter.apiCall(HomegenieApi.Automation.Scheduling.Get(data.scheduleName))
        .subscribe({
          next: (res) => {
            this.schedulerItem = res.response;
            this.isLoading = false;
          },
          error: (err) => {
            const yot = this.adapter.yot;
            yot.translate.get('error_occurred')
              .subscribe((tr) => {
                yot.notify(tr, err.message);
              });
            this.isLoading = false;
            this.dialogRef.close();
          }
        });
    } else {
      this.schedulerItem = new SchedulerItem();
    }
  }

  applyChanges() {
    // Update schedule item
    if (this.schedulerItem.Data?.action?.type === 'none') {
      this.schedulerItem.Script = '';
    }
    // 'Data' is stored as a string field containing a JSON object
///*
    const template = this.schedulerItem.Data.action.template;
    if (template) {
      const clean = (cfg) => {
        delete cfg.id;
        delete cfg.script;
        if (cfg.config) {
          Object.keys(cfg.config).map((key: string) => {
            cfg.config[key] = cfg.config[key].value;
          });
        }
        if (cfg.commands && cfg.commands.length > 0) {
          cfg.commands.forEach((command) => {
            delete command.uuid;
            delete command.script;
          });
        }
      };
      clean(template.forEach);
      clean(template.forStart);
      clean(template.forEnd);
    }
//*/
    this.schedulerItem.Data = JSON.stringify(this.schedulerItem.Data);
    this.adapter.apiCall(HomegenieApi.Automation.Scheduling.Update(this.schedulerItem.Name), this.schedulerItem)
      .subscribe({
        next: (res) => {
          this.dialogRef.close(this.schedulerItem);
        },
        error: (err) => console.log(err)
      });
  }
}
