import {Component, Input, OnDestroy, OnInit} from '@angular/core';
import {YotService} from "../../../services/yot/yot.service";
import {MatDialog} from "@angular/material/dialog";
import {BackupDialogComponent} from "./backup-dialog/backup-dialog.component";
import {ApiResponse, HomegenieAdapter} from "../homegenie-adapter";
import {RestoreDialogComponent} from "./restore-dialog/restore-dialog.component";
import {FactoryResetDialogComponent} from "./factory-reset-dialog/factory-reset-dialog.component";
import {ServiceRestartDialogComponent} from "./service-restart-dialog/service-restart-dialog.component";
import {HomegenieApi, ResponseStatus} from "../homegenie-api";
import {LocationDialogComponent} from "./location-picker-dialog/location-dialog.component";
import {ServiceDialogComponent} from "./service-dialog/service-dialog.component";
import {LoggingDialogComponent} from "./logging-dialog/logging-dialog.component";
import {concat, Subject} from "rxjs";
import {Router} from "@angular/router";
import {UpdateFileDialogComponent} from "./update-file-dialog/update-file-dialog.component";
import {UpdateInstallDialogComponent} from "./update-install-dialog/update-install-dialog.component";
import {UpdateNotesDialogComponent} from "./update-notes-dialog/update-notes-dialog.component";

@Component({
  selector: 'app-homegenie-maintenance',
  templateUrl: './homegenie-maintenance.component.html',
  styleUrls: ['./homegenie-maintenance.component.scss']
})
export class HomegenieMaintenanceComponent implements OnInit, OnDestroy {
  @Input()
  adapter: HomegenieAdapter;

  systemInfo: any = {};
  isLoading = false;

  private refreshInterval;
  private dialog: MatDialog;

  private _processUptime = 0;
  get processUptime() {
    return this._processUptime;
  }

  get updateReleaseInfo(): any {
    return this.adapter.updatesList[0];
  }

  constructor(public yot: YotService, private router: Router) {
    this.dialog = yot.dialog;
  }

  ngOnInit(): void {
    this.loadSystemSettings();
  }
  ngOnDestroy(): void {
    clearInterval(this.refreshInterval);
  }

  onLocationSettingsClick() {
    let locationInfo = {};
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.SystemConfig.Location.Get)
      .subscribe({
        next: (l) => {
          locationInfo = l.response;
          this.dialog.open(LocationDialogComponent, {
            data: {adapter: this.adapter, locationInfo},
          }).afterClosed().subscribe((newLocation) => {
            if (newLocation) {
              this.adapter
                .apiCall(HomegenieApi.SystemConfig.Location.Set, newLocation)
                .subscribe();
              this.systemInfo.Configuration.Location = newLocation;
            }
          });
        },
        complete: () => this.isLoading = false
      });
  }
  onLoggingSettingsClick() {
    this.dialog.open(LoggingDialogComponent, {
      minWidth: 260,
      data: {adapter: this.adapter, systemInfo: this.systemInfo},
    });
  }
  onServiceSettingsClick() {
    this.dialog.open(ServiceDialogComponent, {
      data: {adapter: this.adapter, systemInfo: this.systemInfo},
    }).afterClosed().subscribe((result) => {
      if (result) {
        const newConfig = result.serviceConfiguration;
        const actualConfig = {...this.systemInfo.Configuration.Service};
        const apiCalls: Array<Subject<ApiResponse>> = [];
        if (newConfig.Host != actualConfig.Host) {
          apiCalls.push(this.adapter.apiCall(HomegenieApi.SystemConfig.HttpService.SetHostHeader(newConfig.Host)));
        }
        if (newConfig.Port != actualConfig.Port) {
          apiCalls.push(this.adapter.apiCall(HomegenieApi.SystemConfig.HttpService.SetPort(newConfig.Port)));
        }
        if (newConfig.AuthPassword !== actualConfig.AuthPassword || (newConfig.AuthPassword && result.newPassword)) {
          if (newConfig.AuthPassword && result.newPassword) {
            // TODO: do not send as clear-data, encrypt!
            apiCalls.push(this.adapter.apiCall(HomegenieApi.SystemConfig.Security.SetPassword(result.newPassword)));
          } else if (!newConfig.AuthPassword) {
            apiCalls.push(this.adapter.apiCall(HomegenieApi.SystemConfig.Security.ClearPassword));
          }
        }
        concat(...apiCalls)
          .subscribe({
            next: console.log,
            error: (err) => console.log(err),
            complete: () => this.loadSystemSettings()
          });
      }
    });
  }
  onSystemRestartClick() {
    this.dialog.open(ServiceRestartDialogComponent, {
      disableClose: true,
      data: {adapter: this.adapter}
    }).afterClosed().subscribe(() => this.loadSystemSettings());
  }

  onBackupSelected() {
    this.dialog.open(BackupDialogComponent, {
      disableClose: false,
      data: {adapter: this.adapter}
    });
  }
  onRestoreSelected() {
    this.dialog.open(RestoreDialogComponent, {
      disableClose: true,
      data: {adapter: this.adapter}
    });
  }
  onFactoryResetSelected() {
    this.dialog.open(FactoryResetDialogComponent, {
      disableClose: true,
      data: {adapter: this.adapter}
    }).afterClosed().subscribe((reload) => {
      if (reload) {
        this.adapter.isConfigured = false;
        this.router.navigate([ '/' ])
          .then((res) => {
            // TODO: show some tip message (maybe)
          });
      }
    });
  }

  onUpdateCheckClick() {
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.SystemConfig.UpdateManager.Check)
      .subscribe({
        next: (ar) => {
          if (!ar.response || ar.response.Status === ResponseStatus.Error) {
            console.log('ERROR', ar);
            // TODO: report error
          }
        },
        error: (err) => {
          console.log(err);
          // TODO: report error
        },
        complete: () => this.isLoading = false
      });
  }

  onUpdateInstallClick() {
    if (this.hasSignificantReleaseNote()) {
      this.showReleaseNoteDialog();
    } else {
      this.installUpdate();
    }
  }

  onUpdateFileClick() {
    const dialogRef = this.dialog.open(UpdateFileDialogComponent, {
      disableClose: true,
      data: {
        adapter: this.adapter
      }
    });
    dialogRef.afterClosed().subscribe((installed) => {
      if (installed) {
        location.reload();
      }
    });
  }

  private hasSignificantReleaseNote(): boolean {
    const note = this.updateReleaseInfo?.ReleaseNote;
    return !!note && note.trim().length > 0;
  }

  private showReleaseNoteDialog() {
    const dialogRef = this.dialog.open(UpdateNotesDialogComponent, {
      data: this.updateReleaseInfo
    });
    dialogRef.afterClosed().subscribe((installUpdate) => {
      if (installUpdate) {
        this.installUpdate();
      }
    });
  }

  private installUpdate() {
    const dialogRef = this.dialog.open(UpdateInstallDialogComponent, {
      disableClose: true,
      data: {
        adapter: this.adapter,
        releaseInfo: this.updateReleaseInfo,
        systemInfo: this.systemInfo,
      }
    });
    dialogRef.afterClosed().subscribe((installed) => {
      if (installed) {
        location.reload();
      }
    });
  }

  private loadSystemSettings() {
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.SystemConfig.System.Info)
      .subscribe({
        next: (ar) => {
          if (ar.response) {
            this.systemInfo = ar.response;
            const updateUptime = () =>
              this._processUptime = new Date().getTime() - this.systemInfo.Process.StartTime;
            updateUptime();
            this.refreshInterval = setInterval(updateUptime, 60000);
          }
          this.isLoading = false;
        },
        error: (err) => this.isLoading = false
      });
  }
}
