import {Component, EventEmitter, Input, OnDestroy, OnInit, Output} from '@angular/core';
import { CdkDragDrop, moveItemInArray } from '@angular/cdk/drag-drop';
import {
  ScriptTemplate,
  ScriptTemplateConfig,
  TemplateCommand
} from "../scheduler-wizard-script/scheduler-wizard-script.component";
import {KeyValue} from "@angular/common";
import {Scene} from "../../../services/yot/automation";
import {HomegenieAdapter} from "../homegenie-adapter";
import {SystemApi} from "../../../api/system-api";
import {MatSnackBar} from "@angular/material/snack-bar";
import {
  ColorPickerDialogComponent
} from "../../../components/dialogs/color-picker-dialog/color-picker-dialog.component";
import {Color} from "@iplab/ngx-color-picker";
import {MatDialog} from "@angular/material/dialog";

@Component({
  selector: 'app-scheduler-wizard-script-option',
  templateUrl: './scheduler-wizard-script-option.component.html',
  styleUrls: ['./scheduler-wizard-script-option.component.scss']
})
export class SchedulerWizardScriptOptionComponent implements OnInit, OnDestroy {
  @Input()
  adapter: HomegenieAdapter;
  @Input()
  templateConfig: ScriptTemplate;
  @Input()
  codeTemplates = new Array<ScriptTemplate>();
  @Output()
  optionChanged = new EventEmitter<any>();

  scenarioList: Scene[];

  // Preserve original property order
  originalOrder = (a: KeyValue<string,any>, b: KeyValue<string,any>): number => {
    return 0;
  }

  drop(event: CdkDragDrop<TemplateCommand[]>) {
    moveItemInArray(this.templateConfig.commands, event.previousIndex, event.currentIndex)
    this.optionChanged.next(null);
  }

  get boundModulesTemplates() {
    return this.codeTemplates.filter(c => c.script.indexOf('.boundModules') !== -1);
  }
  get standardTemplates() {
    return this.codeTemplates.filter(c => c.script.indexOf('.boundModules') === -1);
  }

  isCapturing: boolean;
  remoteCaptureInputField: HTMLTextAreaElement;
  remoteCaptureFieldIndex: number = -1;

  constructor(protected _snackBar: MatSnackBar, private dialog: MatDialog) { }

  ngOnInit(): void {
    // populate Scenario list for 'program-select' type
    this.adapter.system(SystemApi.Automation.Scenes.List)
      .subscribe((list: any) => this.scenarioList = list);
    // fix old schedule item version (before 2025-10)
    this.compatFixTemplate(this.templateConfig);
  }
  ngOnDestroy() {
    this.optionChanged.complete();
    this._snackBar.dismiss();
  }

  onTemplateCommandAdd(commandTemplate: ScriptTemplate) {
    this.templateConfig.commands = this.templateConfig.commands || [];
    const config: any = {};
    if (commandTemplate.config != null) {
      const key = Object.keys(commandTemplate.config)[0];
      if (key) {
        config[key] = commandTemplate.config[key].value;
      }
    }
    this.templateConfig.commands.push({
      id: commandTemplate.id,
      config,
      useEventValue: false
    });
    this.optionChanged.next(null);
  }

  onTemplateCommandDelete(position: number) {
    this.templateConfig.commands.splice(position, 1);
  }

  onTemplateValueChange(command: TemplateCommand, kv: KeyValue<string, ScriptTemplateConfig>) {
    command.config[kv.key] = kv.value;
    this.optionChanged.next(null);
  }

  private getTemplateId(template: ScriptTemplate): string {
    let actionId: string | null = template.id;
    const oldField: string | null = template.script;
    if (oldField && (!actionId)) {
      actionId = oldField
        .replace(".js", "")
        .replace(/\./g, "_")
        .replace(/-/g, "_");
    }
    template.id = "";
    template.script = "";
    return actionId ?? "";
  }

  private compatFixTemplate(template: ScriptTemplate) {
    const actionId = this.getTemplateId(template);
    if (actionId) {
      const command = new TemplateCommand();
      command.id = actionId;
      command.config = template.config;
      template.commands = [command];
      delete template.id;
      delete template.script;
      delete template.config;
      this.optionChanged.next(null);
    }
  }

  getTemplateConfig(id: string, key: string): ScriptTemplateConfig {
    return this.codeTemplates
      .find((t) => t.id === id).config[key];
  }

  onCaptureClick(fieldIndex: number, captureField: HTMLTextAreaElement, command: TemplateCommand, kv: KeyValue<string, ScriptTemplateConfig>): void {
    this.remoteCaptureInputField = captureField;
    this.remoteCaptureFieldIndex = fieldIndex;
    // translations
    let textCapturingRawData = 'capturing_receiver_raw_data_events';
    this.adapter.yot.translate.get(textCapturingRawData)
      .subscribe((tr) => textCapturingRawData = tr);
    let textStop = 'stop';
    this.adapter.yot.translate.get(textStop)
      .subscribe((tr) => textStop = tr);

    // start capturing

    // subscribe to YOT events stream
    const moduleEventsSubscription = this.adapter.yot.onModuleEvent.subscribe((e) => {
      if (!this.isCapturing) return;
      const field = e.event;
      if (field.key === 'Receiver.RawData') {
        this.isCapturing = false;
        this._snackBar.dismiss();
        this.remoteCaptureInputField.value += field.value + '\n';
        setTimeout(() => {
          this.remoteCaptureInputField.focus();
          const endPosition = this.remoteCaptureInputField.value.length;
          this.remoteCaptureInputField.selectionStart = endPosition;
          this.remoteCaptureInputField.selectionEnd = endPosition;
          // update command value
          command.config[kv.key] = this.remoteCaptureInputField.value;
          this.optionChanged.next(null);
        }, 0);
      }
    });

    this.isCapturing = true;
    const snackBarRef = this._snackBar.open(textCapturingRawData, textStop, {
      duration: 10000
    });
    snackBarRef.onAction().subscribe(() => {
      this.isCapturing = false;
      // unsubscribe YOT events stream
      moduleEventsSubscription.unsubscribe();
    });
    snackBarRef.afterDismissed().subscribe(() => {
      this.isCapturing = false;
      // unsubscribe YOT events stream
      moduleEventsSubscription.unsubscribe();
    });

  }


  private pickColor(color: string, callback?: Function) {
    const currentColor = color;
    const dialogRef = this.dialog.open(ColorPickerDialogComponent, {
      // height: '400px',
      width: '100%',
      minWidth: '300px',
      maxWidth: '300px',
      disableClose: false,
      data: {
        module: null,
        color,
        callback: (color: Color) => {
//          this.color = color.toHexString(true);
        }
      }
    });
    dialogRef.afterClosed().subscribe((color: Color) => {
      if (color && currentColor === color.toHexString(true)) {
        // color was not changed, just return
        return;
      }
      if (!color) {
        // restore current color if user canceled the dialog
        color = Color.from(currentColor);
      }
//      this.color = color.toHexString(true);
      if (callback) callback(color);
    });
  }

  onColorClick(command: TemplateCommand, kv: KeyValue<string, any>) {
    this.pickColor(kv.value, (color: Color) => {
      kv.value = color.toHexString(true);
      this.onTemplateValueChange(command, kv)
    });
  }
}
