  protected getTopMediaCards(limit = 30): MediaCardData[] {
    return [...this.mediaCardList]
      .filter(m => (m.voteCount || 0) > 50 && (m.vote || 0) > 0)
      .sort((a, b) => (b.vote || 0) - (a.vote || 0))
      .slice(0, limit);
  }
  protected getFavoriteMediaCards(): MediaCardData[] {
    return Object.keys(this.mediaStatistics).map(k => this.mediaStatistics[k])
      .filter((s) => s.favorite)
      .map((s) => this.mediaCardList.find((mc) => mc.id === s.id))
      .filter((mc) => mc != null);
  }
  getContinueWatchingList(): MediaCardData[] {
    if (!this.mediaStatistics || Object.keys(this.mediaStatistics).length === 0) {
      return [];
    }

    const watchingList: MediaCardData[] = [];
    this.mediaCardList.forEach(media => {
      if (this.mediaContext.mediaData?.id === media.id) {
        const itemWithDate = {
          ...media,
          _lastViewed: now()
        };
        watchingList.push(itemWithDate);
        return;
      }
      const stats = this.mediaStatistics[media.id];
      const duration = this.getSeconds(media.duration);
      if (stats && duration > 0) {
        const percentage = (stats.position / duration) * 100;
        if ((percentage > 5 && percentage < 95)) {
          const itemWithDate = {
            ...media,
            _lastViewed: stats.timestamp || 0
          };
          watchingList.push(itemWithDate);
        }
      }
    });
    return watchingList
      .sort((a: any, b: any) => b._lastViewed - a._lastViewed)
      .slice(0, 20); // Limitiamo a 20 per non intasare
  }

