  protected onSelectedRendererChange(renderer: string) {
    this.selectedRenderer = renderer;
    this.configuration['renderer'] = renderer;

    this.mediaRendererModule = null;
    if (this.selectedRenderer) {
      this.mediaRendererModule = this.yot.getModule(this.selectedRenderer);
      this.pollMediaRenderer();
      this.highlightCurrentMedia();
    }
    this._playerContext.mediaRenderer = this.mediaRendererModule;
    this.navigationLevel = NavigationLevel.CAROUSEL;
  }


  protected loadCurrentMedia(): void {

    if (this.isPlayingTrailer || this.isBuffering) {
      this.closePreviewPlayer();
    }

    // reset controls bar state
    this.playerNavigationLevel = PlayerNavigationLevel.CONTROLS;
    this.playerNavigationLevelTop_Selected = PlayerNavigationLevelAction_Top.EXIT;
    this.playerNavigationLevelControl_Selected = PlayerNavigationLevelAction_Control.PLAY_PAUSE;
    this.playerNavigationSeeking = false;

    clearTimeout(this.autoPlayTimeout);
    this._playerContext.mediaData = this.currentMedia;
    this._playerContext.playerDuration = 0;
    this._playerContext.playerTime = 0;

    const stat: MediaStatistics = this.mediaStatistics[this.currentMedia.id];
    const item = this.upnpMediaFiles.find((media) => media.Id === this.currentMedia.id);
    const lastWatchedPosition = stat?.position;

    if (this.selectedRenderer == null) {

      this.uiMode = 'play';
      this.showPlayInfo();

    } else {

      this.isLoading = true;
      //const mediaRenderer = this.yot.getModule(this.selectedRenderer);
      const mediaRenderer = this.mediaRendererModule;
      const metaData = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>" +
        "<DIDL-Lite xmlns=\"urn:schemas-upnp-org:metadata-1-0/DIDL-Lite/\" xmlns:dc=\"http://purl.org/dc/elements/1.1/\" xmlns:sec=\"http://www.sec.co.kr/\" xmlns:upnp=\"urn:schemas-upnp-org:metadata-1-0/upnp/\">\n" +
        "<item id=\"f-0\" parentID=\"0\" restricted=\"0\">" +
        "<dc:title>" + item.Title + "</dc:title>" +
        "<dc:creator>" + item.Creator + "</dc:creator>" +
        "<upnp:class>" + item.Class + "</upnp:class>" +
        "<res protocolInfo=\"" + item.ProtocolInfo + "\" sec:URIType=\"public\">" + item.MediaUrl + "</res>" +
        "</item>" +
        "</DIDL-Lite>";
      mediaRenderer
        .control(HomegenieUpnpApi.AvMedia.SetUri, `${encodeURIComponent(item.MediaUrl)}/${encodeURIComponent(metaData)}`)
        .subscribe((res) => {

          const play = () => {
            mediaRenderer.control(HomegenieUpnpApi.AvMedia.Play)
              .subscribe((res) => {
                // Play successful
                this.carouselComponent?.setPage(this.filteredMediaCardList.indexOf(this.currentMedia));
              });
          };

          if (lastWatchedPosition) {

            setTimeout(() => {
              this.playerSeekTime(lastWatchedPosition).subscribe({
                next: () => {
                  play();
                }
              })
            },  1000);

          } else {

            play();

          }

        });
    }
  }

