  private async buildMediaCardList(): Promise<void> {
    this.isScanning = true;

    this.mediaCardList = await firstValueFrom(this.yot.storage.get(`media-cards@${this.module.id}`)) as MediaCardData[] | null;

    let cacheImages = false;
    if (!this.mediaCardList || this.mediaCardList.length === 0) {
      cacheImages = true;
    }

    if (!this.mediaCardList || this.mediaCardList?.length === 0) {
      const mediaCardPromises = this.upnpMediaFiles.map(async (item) => {
        const movieDbData = this.getMediaData(item);
        let title = item.Title;
        if (!title) {
          title = movieDbData?.name;
        }
        const detail = await this.getMovieDetail(movieDbData.id);
        const description = movieDbData?.overview;
        return {
          id: item.Id,
          title,
          description,
          releaseDate: movieDbData?.release_date || movieDbData?.first_air_date,
          duration: item.Duration,
          genreIdList: movieDbData?.genre_ids,
          genreList: this.getGenreList(movieDbData?.genre_ids),
//          originCountry: movieDbData?.origin_country,
          originalName: movieDbData?.original_title || movieDbData?.original_name,
          originalLanguage: movieDbData?.original_language,
          mediaUrl: item.MediaUrl,
          mediaUrlBrowser: item.MediaUrlBrowser,
          poster: this.getPosterPath(item),
          backdrop: this.getBackdropPath(item),
          posterData: null,
          backdropData: null,
          vote: movieDbData?.vote_average,
          voteCount: movieDbData?.vote_count,
          popularity: movieDbData?.popularity,
          detail
        } as MediaCardData;
      });

      this.mediaCardList = await Promise.all(mediaCardPromises);
    }

    this.genreList = this.genreList.map((genre) => {
      genre.movies = this.mediaCardList.filter((f) => f.genreIdList && f.genreIdList.indexOf(genre.id) !== -1);
      genre.movies.sort((a, b) => {
        return a.vote > b.vote ? -1 : 1;
      });
      return genre;
    }).filter((g) => g.movies.length > 0);


    if (cacheImages) {
      await this.downloadImagesSequentially();
      this.yot.storage.set(`media-cards@${this.module.id}`, this.mediaCardList)
        .subscribe((res) => {
          // reset scan status
          this.scanStatus.downloadedImage = null;
        });
    }


    this.isScanning = false;
  }

  private async downloadImagesSequentially() {

    for (const item of this.mediaCardList) {

      // --- PUNTO DI CONTROLLO FLUSSO ---
      // Se l'utente ha premuto Stop, usciamo subito dal ciclo.
      if (!this.isScanning) {
        this.scanStatus.message = 'scan_status_operation_interrupted';
        break;
      }


      // Cast profile pictures
      const profileImageRequests = [];
      item.detail?.credits?.cast.filter((person) => person.profile_path).map((person) => {
        profileImageRequests.push(this.downloadAndConvert(`https://image.tmdb.org/t/p/w500/${person.profile_path}`, 'profile', person));
      });


      // Scarichiamo Poster e Backdrop (possiamo farli in parallelo per il singolo item)
      // Usiamo Promise.allSettled per evitare che se fallisce uno si blocchi tutto
      await Promise.allSettled([
        this.downloadAndConvert(item.poster, 'poster', item),
        this.downloadAndConvert(item.backdrop, 'backdrop', item),
        ...profileImageRequests
      ]);
    }
  }

  private async downloadAndConvert(url: string | undefined, type: 'poster' | 'backdrop' | 'profile', item: MediaCardData | any) {
    if (!url || !this.isScanning) return;

    this.scanStatus.message = 'scan_status_downloading_media';

    try {
      // Usiamo il metodo via Canvas invece di HttpClient
      this.scanStatus.message = `scan_status_downloading_media ${type} (${item.title})`;

      const base64String = await this.urlToBase64ViaCanvas(url);

      this.scanStatus.downloadedImage = base64String;

      if (type === 'poster') {
        item.posterData = base64String;
      } else if (type === 'profile') {
        item.profileData = base64String;
      } else {
        item.backdropData = base64String;
      }
    } catch (error) {
      //console.warn(`Skip immagine ${type} per ${item.title}: CORS o errore rete.`);

      this.scanStatus.message = 'Error: ' + JSON.stringify(error);

    }
  }
  private urlToBase64ViaCanvas(url: string): Promise<string> {
    return new Promise((resolve, reject) => {
      const img = new Image();

      // 1. Chiedi CORS
      img.crossOrigin = 'Anonymous';

      // 2. TRUCCO: Aggiungi un timestamp per bypassare la cache del browser
      // Se l'URL ha già parametri usa '&', altrimenti '?'
      const sep = url.includes('?') ? '&' : '?';
      img.src = `${url}${sep}avoidCache=${new Date().getTime()}`;

      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;

        const ctx = canvas.getContext('2d');
        if (!ctx) { reject('No context'); return; }

        ctx.drawImage(img, 0, 0);

        try {
          const dataURL = canvas.toDataURL('image/jpeg', 0.8);
          resolve(dataURL);
        } catch (err) {
          reject('CORS Error: Tainted Canvas');
        }
      };

      img.onerror = (e) => reject('Image load error');
    });
  }





  private TheMovieDbApiKey = ['6ff', '8995', 'ed47a', '272d36', '920d3709', 'fda564'].join('');
