  private getMediaFolder(folder: AvMediaItem): Subject<AvMediaItem[]> {
    const subject = new Subject<AvMediaItem[]>();
    this.isLoading = true; // Nota: questo farà "flickerare" il loading nel loop, ma va bene per ora

    this.module
      .control(HomegenieUpnpApi.AvMedia.Browse, folder.Id)
      .subscribe({
        next: (res) => {
          this.isLoading = false;
          // Emettiamo l'array e completiamo subito il subject
          // Assumiamo che res.response sia l'array corretto
          const resultList = (res.response as AvMediaItem[]) || [];

          if (resultList.forEach) {
            resultList.forEach((item) => {
              if (item.Class.startsWith('object.item.videoItem') || item.Class.startsWith('object.item.audioItem')) {
                item.Type = item.Class.startsWith('object.item.videoItem') ? 'video' : 'audio';
              } else if (item.Class.startsWith('object.item.imageItem')) {
                item.Type = 'image';
              }
            });
          }

          subject.next(resultList);
          subject.complete();
        },
        error: (err) => {
          this.isLoading = false;
          subject.error(err);
        }
      });
    return subject;
  }

