    let result = item?.MovieDbData?.results.find((r) => r.poster_path && (r.title?.toLowerCase().endsWith(item.Title.toLowerCase()) || r.original_title?.toLowerCase().endsWith(item.Title.toLowerCase())) && (r.media_type === 'movie' || r.media_type === 'tv') && (!year || r.release_date.startsWith(year)));
