  protected playerSeekTime(ts): Subject<any> {
    const subject = new Subject();
    if (this._playerContext.mediaRenderer == null) {
      const player = this.mainPlayer.nativeElement;
      player.currentTime = ts;
      setTimeout(() => {
        subject.next(ts);
        subject.complete();
        player.play();
      }, 100);
    } else {
      // UPnP media seek
      this.isLoading = true;
      this._playerContext.mediaRenderer?.control(`AvMedia.Seek/${this.formatSeconds(ts)}`)
        .subscribe({
          next: (res) => {

            this.mediaContext.playerTime = ts;
            setTimeout(() => this.isLoading = false, 2000);

            subject.next(ts);
            subject.complete();

          },
          error: (err) => {
            this.isLoading = false;

            subject.error(err);
          }
        });
    }
    return subject;
  }

  protected playerSeekTargetTime = 0;
  protected playerSeekIncrement = 1;
  protected playerSeekTimeRelative(ts) {

    // 1. FIX RESET: Se l'utente preme un tasto, annulla qualsiasi reset pendente
    // Questo risolve il caso limite della "velocità appiccicosa" o reset improvviso
    clearTimeout(this.playerCommandTimeout);

    // Inizializzazione (se siamo a riposo)
    if (this.playerSeekTargetTime <= 0) {
      this.playerSeekTargetTime = this.mediaContext.playerTime;
    }

    // Incremento e Accelerazione
    this.playerSeekTargetTime += (ts * this.playerSeekIncrement);
    if (this.playerSeekIncrement < 20) {
      this.playerSeekIncrement += 0.5;
    }

    // 3. CLAMPING (Ottimo, inseriscilo qui)
    // Assicuriamoci che il target non esca dai bordi PRIMA di inviarlo
    if (this.playerSeekTargetTime < 0) {
      this.playerSeekTargetTime = 0;
    }
    // Assumendo che playerDuration sia disponibile e > 0
    if (this.mediaContext.playerDuration > 0 && this.playerSeekTargetTime > this.mediaContext.playerDuration) {
      this.playerSeekTargetTime = this.mediaContext.playerDuration;
    }

    // Gestione Buffering (La tua logica originale)
    if (this.isBuffering || this.isLoading) {
      // Nota: qui playerCommandTimeout viene riusato per il retry, va bene
      // perché abbiamo fatto clearTimeout all'inizio della funzione.
      this.playerCommandTimeout = setTimeout(() => {
        this.playerSeekTimeRelative(0);
      }, 200);
      return;
    }

    const dest = this.playerSeekTargetTime;

    this.playerSeekTime(dest).subscribe({
      next: (res) => {
        if (this.playerSeekTargetTime !== dest) {
          // L'utente ha premuto ancora mentre aspettavamo, recuperiamo il gap
          //this.playerSeekTimeRelative(dest - this.playerSeekTargetTime);
          this.playerSeekTimeRelative(0);
        } else {
          // Reset differito
          this.playerCommandTimeout = setTimeout(() => {
            this.playerSeekTargetTime = 0;
            this.playerSeekIncrement = 1;
          }, 300);
        }
        this.mediaContext.playerTime = dest;
      }
    });
  }

