  /**
   * Calcola la posizione CSS (0% - 100%) del pallino guida
   */
  getGuideDotPosition(): string {
    if (this.mediaContext.playerDuration === 0) return '0%';

    // 1. Calcolo percentuale (0-100)
    let targetTime = this.playerSeekTargetTime;
    targetTime = Math.max(0, Math.min(targetTime, this.mediaContext.playerDuration));
    const percent = (targetTime / this.mediaContext.playerDuration) * 100;

    // 2. FORMULA DI COMPENSAZIONE (Per pallino da 20px)
    // Al 0%:   0% + 10px - 0px = 10px (Bordo sinistro dentro)
    // Al 50%:  50% + 10px - 10px = 50% (Perfettamente al centro)
    // Al 100%: 100% + 10px - 20px = 100% - 10px (Bordo destro dentro)

    // Nota: 10px è metà larghezza pallino, 20px è larghezza intera
    return `calc(${percent}% + (10px - 20px * ${percent / 100}))`;
  }



