import {Injectable} from '@angular/core';
import {Subject} from 'rxjs';

@Injectable()
export class LocalVoiceCaptureService {
  readonly audioReady = new Subject<Blob>();
  readonly errors = new Subject<unknown>();
  recording = false;
  starting = false;
  processing = false;
  private generation = 0;
  private stream: MediaStream;
  private context: AudioContext;
  private source: MediaStreamAudioSourceNode;
  private processor: ScriptProcessorNode;
  private silence: GainNode;
  private chunks: Float32Array[] = [];
  private frames = 0;
  get supported(): boolean { return window.isSecureContext && !!navigator.mediaDevices?.getUserMedia; }

  async start(): Promise<void> {
    if (this.recording || this.starting || this.processing) return;
    const generation = ++this.generation;
    this.starting = true;
    try {
      if (!this.supported) throw new Error('Microphone requires HTTPS or localhost.');
      const stream = await navigator.mediaDevices.getUserMedia({audio: {channelCount: 1, echoCancellation: true, noiseSuppression: true}});
      if (generation !== this.generation) { stream.getTracks().forEach(track => track.stop()); return; }
      this.stream = stream;
      this.context = new AudioContext();
      await this.context.resume();
      if (generation !== this.generation) return;
      this.source = this.context.createMediaStreamSource(stream);
      this.processor = this.context.createScriptProcessor(4096, 1, 1);
      this.silence = this.context.createGain();
      this.silence.gain.value = 0;
      this.chunks = []; this.frames = 0; this.recording = true; this.starting = false;
      const maxFrames = this.context.sampleRate * 60;
      this.processor.onaudioprocess = event => {
        if (!this.recording) return;
        const data = event.inputBuffer.getChannelData(0);
        const chunk = data.slice(0, maxFrames - this.frames);
        this.chunks.push(chunk); this.frames += chunk.length;
        if (this.frames >= maxFrames) void this.stop();
      };
      this.source.connect(this.processor); this.processor.connect(this.silence); this.silence.connect(this.context.destination);
    } catch (error) { if (generation === this.generation) { this.cancel(); this.errors.next(error); } }
  }

  async stop(): Promise<void> {
    if (!this.recording) return;
    const generation = this.generation, sampleRate = this.context.sampleRate;
    const samples = new Float32Array(this.frames);
    let offset = 0;
    for (const chunk of this.chunks) { samples.set(chunk, offset); offset += chunk.length; }
    this.recording = false; this.processing = true; this.releaseMicrophone(); this.chunks = [];
    try {
      if (!samples.length) throw new Error('No audio recorded.');
      const offline = new OfflineAudioContext(1, Math.ceil(samples.length * 16000 / sampleRate), 16000);
      const buffer = offline.createBuffer(1, samples.length, sampleRate); buffer.copyToChannel(samples, 0);
      const source = offline.createBufferSource(); source.buffer = buffer; source.connect(offline.destination); source.start();
      const rendered = await offline.startRendering();
      if (generation !== this.generation) return;
      this.processing = false;
      this.audioReady.next(this.encodeWav(rendered.getChannelData(0)));
    } catch (error) { if (generation === this.generation) { this.processing = false; this.errors.next(error); } }
  }

  cancel(): void {
    ++this.generation; this.recording = false; this.starting = false; this.processing = false;
    this.releaseMicrophone(); this.chunks = []; this.frames = 0;
  }
  private releaseMicrophone(): void {
    if (this.processor) { this.processor.onaudioprocess = null; this.processor.disconnect(); }
    this.source?.disconnect(); this.silence?.disconnect();
    this.stream?.getTracks().forEach(track => track.stop());
    if (this.context && this.context.state !== 'closed') void this.context.close().catch(() => {});
    this.stream = null; this.context = null; this.processor = null; this.source = null; this.silence = null;
  }
  private encodeWav(samples: Float32Array): Blob {
    const buffer = new ArrayBuffer(44 + samples.length * 2), view = new DataView(buffer);
    const text = (offset: number, value: string) => { for (let i = 0; i < value.length; i++) view.setUint8(offset + i, value.charCodeAt(i)); };
    text(0, 'RIFF'); view.setUint32(4, buffer.byteLength - 8, true); text(8, 'WAVE'); text(12, 'fmt ');
    view.setUint32(16, 16, true); view.setUint16(20, 1, true); view.setUint16(22, 1, true);
    view.setUint32(24, 16000, true); view.setUint32(28, 32000, true); view.setUint16(32, 2, true); view.setUint16(34, 16, true);
    text(36, 'data'); view.setUint32(40, samples.length * 2, true);
    samples.forEach((sample, i) => { const value = Math.max(-1, Math.min(1, sample)); view.setInt16(44 + i * 2, Math.round(value * (value < 0 ? 32768 : 32767)), true); });
    return new Blob([buffer], {type: 'audio/wav'});
  }
}
