import {Input, Component, OnInit, OnDestroy} from '@angular/core';
import {HomegenieApi, Program} from "../../adapters/home-genie/homegenie-api";
import {YotService} from "../../services/yot/yot.service";
import {HomegenieAdapter} from "../../adapters/home-genie/homegenie-adapter";
import {Module,ModuleField} from "../../services/yot/module";
import {Subscription} from "rxjs";
import {NavigationService} from "../../services/navigation.service";
import {PagesRoute} from "../../pages-route";
import {AutomanData} from "../components-extras.module";
import {
  ModuleSettingsDialogComponent
} from "../../components/dialogs/module-settings-dialog/module-settings-dialog.component";
import {MatDialog} from "@angular/material/dialog";

@Component({
  selector: 'app-automation-program-control',
  templateUrl: './automation-program-control.component.html',
  styleUrls: ['./automation-program-control.component.scss']
})
export class AutomationProgramControlComponent implements OnInit, OnDestroy {

  @Input()
  automanData: AutomanData;

  @Input()
  program: Program;

  programModule: Module;
  programStatus: string;

  automanMessage: ModuleField;
  automanProgress: ModuleField;
  automanStatus: ModuleField;


  automanFields: Array<ModuleField> = [];

  protected adapter: HomegenieAdapter;

  private moduleSubscription: Subscription;

  get isRunning(): boolean {
    return this.programStatus === 'Running' || this.programStatus === 'Background';
  }
  get isStopping(): boolean {
    return this.programStatus === 'Stopping';
  }
  get isCompiling(): boolean {
    return this.programStatus === 'Compile';
  }

  get hasConfigurationOptions(): boolean {
    return this.program?.IsEnabled
      && (this.programModule?.fields.find((f) => f.key.startsWith('ConfigureOptions.'))) != null;
  }

  constructor(
    private yot: YotService,
    private navigationService: NavigationService,
    private dialog: MatDialog
  ) {
    //
  }

  ngOnInit(): void {
    this.adapter = this.yot.getDefaultAdapter() as HomegenieAdapter;
    if (this.automanData) {
      this.adapter.loadPrograms().subscribe({
        next: (programs) => {

          const pid = this.automanData.program_id;
          this.program = programs.find((p) => p.Address === +pid);

          this.moduleSubscription = this.yot.onModuleEvent.subscribe((data) => {
            this.checkDynamicField();
            if (data.module?.id === this.programModule?.id && data.event?.key === 'Program.Status') {
              this.programStatus = data.event.value;
              if (this.programStatus === 'Removed') {
                this.program = null;
              }
            }
          });

          this.checkDynamicField();
        },
        error: (err) => { }
      });

    }
  }
  ngOnDestroy(): void {
    this.moduleSubscription?.unsubscribe();
  }

  onStartButtonClick() {
    this.navigationService.isLoading = true;
    this.adapter
      .apiCall(HomegenieApi.Automation.Programs.Run(this.program.Address))
      .subscribe(() => {
        this.navigationService.isLoading = false;
      }, err => {
        // TODO: ..
      });
  }
  onStopButtonClick() {
    this.navigationService.isLoading = true;
    this.adapter
      .apiCall(HomegenieApi.Automation.Programs.Break(this.program.Address))
      .subscribe(() => {
        this.navigationService.isLoading = false;
      }, err => {
        // TODO: ...
      });
  }
  onDisableButtonClick() {
    this.navigationService.isLoading = true;
    this.adapter
      .apiCall(HomegenieApi.Automation.Programs.Disable(this.program.Address))
      .subscribe(() => {
        this.navigationService.isLoading = false;
      }, err => {
        // TODO: ...
      });
  }

  private checkDynamicField() {
    this.program = this.adapter.programs.find((p) => p.Address === this.program?.Address);
    if (this.program) {
      if (this.programModule == null) {
        const pm = this.adapter.getModule(this.program as any);
        if (pm) {
          this.programModule = this.yot.getModule(this.adapter.getModuleId(pm));
        }
      }
      if (this.programModule) {
        if (!this.automanProgress) this.automanProgress = this.programModule.field('Automan.Program.Progress');
        if (!this.automanMessage) this.automanMessage = this.programModule.field('Automan.Program.Message');
        if (!this.automanStatus) this.automanStatus = this.programModule.field('Automan.Program.Status');
        const statusField = this.programModule.field('Program.Status');
        if (statusField) {
          this.programStatus = statusField.value;
        }
      }
      const af = this.programModule?.fields.filter((f) => f.key.startsWith('Automan.'));
      if (af && af.length != this.automanFields.length) {
        this.automanFields = [...af];
      }
    }
  }

  protected onEditButtonClick() {
    this.navigationService.router.navigate([
      PagesRoute.AutomationPage,
      this.adapter.id,
      this.program.Address
    ]).then(() => {
      // TODO: ..
    });
  }

  protected onSettingsButtonClick() {
    this.programModule.description = this.program.Description;
    // translate Name and Description
    const titleKey = `${this.adapter.translationPrefix}.$options.${this.program.Address}.Title`;
    this.yot.translate.get(titleKey).subscribe((tr) => {
      if (tr !== titleKey) {
        this.programModule.name = tr;
      }
    });
    const descriptionKey = `${this.adapter.translationPrefix}.$options.${this.program.Address}.Description`;
    this.yot.translate.get(descriptionKey).subscribe((tr) => {
      if (tr !== descriptionKey) {
        this.programModule.description = tr;
      }
    });
    const dialogRef = this.dialog.open(ModuleSettingsDialogComponent, {
      panelClass: 'dialog-no-padding',
      width: '100%',
      minWidth: '280px',
      maxWidth: '576px',
      disableClose: false,
      data: {module: this.programModule, options: this.programModule.getWidgetData()}
    });
  }
}
