import {Component, Input, OnDestroy, OnInit} from '@angular/core';
import {HomegenieAdapter, Module} from "../../homegenie-adapter";
import {SystemApi} from "../../../../api/system-api";
import {Subscription} from "rxjs";

@Component({
  selector: 'app-device-manager',
  templateUrl: './device-manager.component.html',
  styleUrls: ['./device-manager.component.scss']
})
export class DeviceManagerComponent implements OnInit, OnDestroy {
  @Input()
  adapter: HomegenieAdapter;
  @Input()
  houseCodes: string[];

  modules: Module[] = [];

  isLoading = false;

  moduleEventSubscription: Subscription;

  moduleTypes: {name, value}[] = [
    {name: '-', value: 'Generic'},
    {name: 'Switch', value: 'Switch'},
    {name: 'Light', value: 'Light'},
    {name: 'Dimmer', value: 'Dimmer'},
    {name: 'Shutter', value: 'Shutter'},
    {name: 'DoorLock', value: 'DoorLock'},
    {name: 'Motion detector', value: 'Sensor'},
    {name: 'Door/Window sensor', value: 'DoorWindow'}
  ];

  private readonly InterfaceDomain = 'HomeAutomation.X10';

  constructor() {}

  ngOnInit(): void {
    this.modules = this.adapter.modules
      .filter((m) => m.Domain === this.InterfaceDomain && m.Address !== 'RF');
    // reload modules from server
    this.reloadModules();
    this.moduleEventSubscription = this.adapter.yot.onModuleEvent.subscribe((e) => {
      if (e.module.id.startsWith(this.InterfaceDomain + ':')) {
        this.reloadModules();
      }
    });
  }
  ngOnDestroy() {
    if (this.moduleEventSubscription) {
      this.moduleEventSubscription.unsubscribe();
    }
  }

  onTypeValueChange(module: Module, value: string) {
    module.DeviceType = value;
    this.updateModule(module);
  }

  onModuleNameChange(module: Module) {
    this.updateModule(module);
  }

  private reloadModulesTimeout;
  private reloadModules() {
    clearTimeout(this.reloadModulesTimeout);
    this.isLoading = true;
    this.reloadModulesTimeout = setTimeout(() => {
      this.adapter.reloadModules()
        .subscribe(() => {
          this.modules = this.adapter.modules
            .filter((m) => m.Domain === this.InterfaceDomain && m.Address !== 'RF');
          this.isLoading = false;
        });
    }, 500);
  }

  private updateModule(module: Module) {
    this.isLoading = true;
    this.adapter.system(SystemApi.Modules.Info.Set, {
      module: this.adapter.getModuleByRef({
        Domain: module.Domain,
        Address: module.Address
      }),
      name: module.Name,
      description: module.Description,
      type: module.DeviceType
    }).subscribe((res) => {
      //this.adapter.yot.saveConfiguration();
      this.isLoading = false;
    }, (err) => {
      this.isLoading = false;
      this.adapter.yot.notify('Error', err.message);
    });
  }
}
