import {Component, Inject, ViewChild} from '@angular/core';
import {DynamicOptionsBase} from "../../forms/dynamic-options-base.component";
import {Module} from "../../../services/yot/module";
import {YotService} from "../../../services/yot/yot.service";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";

@Component({
  selector: 'app-module-scheduling-dialog',
  templateUrl: './module-scheduling-dialog.component.html',
  styleUrls: ['./module-scheduling-dialog.component.scss']
})
export class ModuleSchedulingDialogComponent {
  @ViewChild('optionsHandler', {static: false})
  optionsHandler: DynamicOptionsBase;

  module: Module;

  selectedDate = new Date();

  constructor(
    public yot: YotService,
    @Inject(MAT_DIALOG_DATA) data: {module: Module}
  ) {
    this.module = data.module;
  }

  onDateChanged(e) : void {
    this.selectedDate = e.value;
  }

  onApplyClick(e) {
    if (this.optionsHandler && this.optionsHandler.isChanged) {
      this.optionsHandler.applyChanges();
    }
  }
}
