  downloadCommandBusy = false;
  downloadCommandError = '';
  private downloadCommandRequest: Subscription;
  controlModelDownload(command: 'DownloadStart' | 'DownloadCancel' | 'DownloadPause' | 'DownloadResume'): void {
    if (this.downloadCommandBusy || !this.selectedModule) return;
    const adapter = this.selectedModule.getAdapter() as HomegenieAdapter;
    if (!adapter || typeof adapter.apiCall !== 'function') return;
    this.downloadCommandBusy = true; this.downloadCommandError = '';
    this.downloadCommandRequest = adapter.apiCall(`${this.selectedModule.id.replace(':', '/')}/${command}`, null, {})
      .pipe(timeout(15000)).subscribe({
        next: result => {
          this.downloadCommandBusy = false;
          if (result.code !== 200 || result.response?.Status === 1 || String(result.response?.Status).toLowerCase() === 'error') {
            this.downloadCommandError = result.response?.ResponseValue || result.response?.Message || this.yot.translate.instant('error_occurred');
            return;
          }
          const state = command === 'DownloadResume' ? 'Downloading' : command === 'DownloadPause' ? 'Paused' : command === 'DownloadStart' ? 'Requested' : 'Pending';
          this.selectedModule.field('Status.Download', state);
        }, error: error => { this.downloadCommandBusy = false; this.downloadCommandError = error?.message || String(error); }
      });
  }

