  /**
   * Helper to get the program name from the system context
   * based on the address extracted from the URL.
   */
  protected getEditingProgramName(): string {
    const address = this.getEditingProgramAddress();
    if (address) {
      // We look for the module in the Automation domain with that specific address
      const program = this.yot.getModuleByRef({
        adapterId: this.yot.getDefaultAdapter().id,
        moduleId: `HomeAutomation.HomeGenie.Automation:${address}`
      });
      return program?.name || "";
    }
    return "";
  }
  /**
   * Detects if the user is currently in the Automation Program Editor.
   * Works with: /automation/localhost:4200/1003 OR /automation/1003
   */
  isProgramEditorOpen(): boolean {
    return this.getEditingProgramAddress() !== null;
  }
  /**
   * Gets the module type of the program currently open in the editor.
   * Returns: "CSharp", "Javascript", "Python", "Visual" or null.
   */
  getEditingProgramType(): string | null {
    const address = this.getEditingProgramAddress();
    if (address) {
      const program = (this.yot.getDefaultAdapter() as HomegenieAdapter)
        .programs.find((p) => p.Address === +address);
      return program?.Type || null;
    }
    return null;
  }
  /**
   * Validates if the generated code language matches the current editor's program type.
   * Case-insensitive comparison to handle "CSharp" vs "csharp".
   */
  isProgramCompatible(message: MessageViewState): boolean {
    if (!message.programCode) return false;

    // Get current type from editor (e.g., "CSharp", "Javascript")
    const currentType = this.getEditingProgramType()?.toLowerCase();
    // Get generated type from AI (e.g., "csharp", "javascript")
    const generatedType = message.programCode.language?.toLowerCase();

    if (!currentType || !generatedType) return false;

    // Direct comparison of normalized strings
    return currentType === generatedType;
  }

  /**
   * Extracts the Program Address (PID) from the URL.
   */
  getEditingProgramAddress(): string | null {
    const currentUrl = window.location.href;
    // Regex: matches /automation/ followed optionally by a host:port part, then the ID
    // It captures the last numeric part of the URL after /automation/
    const match = currentUrl.match(/\/automation\/(?:[^/]+\/)?(\d+)$/);
    if (match && match[1]) {
      return match[1];
    }
    return null;
  }

