import { Injectable, NgZone } from '@angular/core';

const INITIAL_DELAY = 400;
const REPEAT_RATE = 100;

interface ButtonState {
  pressed: boolean;
  nextTrigger: number;
  isRepeating: boolean;
}


@Injectable({ providedIn: 'root' })
export class GamepadService {

  private haveEvents = 'ongamepadconnected' in window;
  private controllers: Record<number, Gamepad> = {};

  private buttonsState: { [key: string]: ButtonState } = {};

  constructor(private ngZone: NgZone) {
    window.addEventListener("gamepadconnected", (e) => this.connect(e));
    window.addEventListener("gamepaddisconnected", (e) => this.disconnect(e));

    // Start polling
    this.updateStatus();
  }

  connect(e: GamepadEvent) {
    this.controllers[e.gamepad.index] = e.gamepad;
  }

  disconnect(e: GamepadEvent) {
    delete this.controllers[e.gamepad.index];
  }

  updateStatus() {
    this.scanGamepads();
    // Loop a 60fps (outside Angular Zone for performance)
    this.ngZone.runOutsideAngular(() => {
      requestAnimationFrame(() => this.updateStatus());
    });
  }

  scanGamepads() {
    const gamepads = navigator.getGamepads ? navigator.getGamepads() : [];

    for (const gp of gamepads) {
      if (!gp) continue;

      // STANDARD MAPPING (Xbox / Standard Gamepad)
      // 0: A (Enter)
      // 1: B (Esc/Back)
      // 12: D-Pad Su
      // 13: D-Pad Giù
      // 14: D-Pad Sx
      // 15: D-Pad Dx

      this.checkButton(gp, 0, 'Enter');
      this.checkButton(gp, 1, 'Escape');
      this.checkButton(gp, 12, 'ArrowUp');
      this.checkButton(gp, 13, 'ArrowDown');
      this.checkButton(gp, 14, 'ArrowLeft');
      this.checkButton(gp, 15, 'ArrowRight');
    }
  }

  checkButton(gp: Gamepad, btnIndex: number, keyName: string) {
    const isPressed = gp.buttons[btnIndex]?.pressed;
    const cacheKey = `${gp.index}-${btnIndex}`;
    const now = Date.now();

    let state = this.buttonsState[cacheKey];
    if (!state) {
      state = { pressed: false, nextTrigger: 0, isRepeating: false };
      this.buttonsState[cacheKey] = state;
    }

    if (isPressed) {
      if (!state.pressed) {
        this.simulateKey(keyName);
        state.pressed = true;
        state.isRepeating = false;
        state.nextTrigger = now + INITIAL_DELAY;
      }
      else if (now >= state.nextTrigger) {
        this.simulateKey(keyName);
        state.isRepeating = true;
        state.nextTrigger = now + REPEAT_RATE;
      }
    } else {
      state.pressed = false;
      state.isRepeating = false;
    }
  }

  simulateKey(key: string) {
    const keyCodes: { [id: string]: number } = {
      'ArrowUp': 38, 'ArrowDown': 40, 'ArrowLeft': 37, 'ArrowRight': 39,
      'Enter': 13, 'Escape': 27, 'Tab': 9
    };

    const event = new KeyboardEvent('keydown', {
      key: key,
      code: key,
      bubbles: true,
      cancelable: true,
      view: window,
      keyCode: keyCodes[key] || 0
    } as KeyboardEventInit);

    // Patch for keyCode legacy
    Object.defineProperty(event, 'keyCode', { get: () => keyCodes[key] || 0 });
    Object.defineProperty(event, 'which', { get: () => keyCodes[key] || 0 });

    const target = (document.activeElement as HTMLElement) || document.body;
    const cancelled = !target.dispatchEvent(event);
    if (key === 'Enter' && target && typeof target.click === 'function') {
      target.click();
    }
  }
}
