import {Component, Inject, OnInit} from '@angular/core';
import {Notification} from "../../../services/notification.service";
import {MAT_DIALOG_DATA, MatDialog, MatDialogRef} from "@angular/material/dialog";
import {HomegenieAdapter, Program} from "../../../adapters/home-genie/homegenie-adapter";
import {HomegenieApi} from "../../../adapters/home-genie/homegenie-api";
import {YotService} from "../../../services/yot/yot.service";
import {
  ModuleSettingsDialogComponent
} from "../../../components/dialogs/module-settings-dialog/module-settings-dialog.component";
import {Dashboard, DashboardWidget} from "../../../services/dashboard/dashboard";
import {MatOptionSelectionChange} from "@angular/material/core";

@Component({
  selector: 'app-notifications-reader',
  templateUrl: './notifications-reader.component.html',
  styleUrls: ['./notifications-reader.component.scss']
})
export class NotificationsReaderComponent implements OnInit {

  isLoading = false;

  private _currentIndex = -1;
  get currentIndex(): number {
    return this._currentIndex;
  }
  get currentProgram(): Program {
    let cp: Program = {
      Name: '',
      Address: 0
    } as Program;
    const module = this.yot.getModuleByRef(this.notification.sender);
    if (module) {
      const adapter = (module.getAdapter() as HomegenieAdapter);
      const mr = adapter.getModuleReference(module);
      cp = adapter.programs.find((p) => p.Address === +mr.Address) || cp;
    }
    return cp;
  }

  set currentIndex(value: number) {
    this._currentIndex = value;
    this.notification = this.notificationsList[this._currentIndex] || new Notification();
    this.dashboardSelection = [];
    const widget: DashboardWidget = this.notification.data?.widget;
    if (widget) {
      this.dashboardSelectionDisabled = this.yot.dashboardService.dashboards
        .filter((d) =>
          (!this.notification.data.addedToDashboards || this.notification.data.addedToDashboards.indexOf(d) === -1)
          && d.widgets.find((w) => w.type === widget.type && w.module.moduleId === widget.module.moduleId && w.module.adapterId === widget.module.adapterId));
      this.dashboardSelection = this.notification.data.addedToDashboards || [];
    }
    // replace variables in message body
    if (this.notification.sender) {
      const m = this.yot.getModuleByRef(this.notification.sender);
      this.notification.message = this.notification.message.replace(/\{\{module_name}}/ig, m.name);
    }
    this.isLoading = true;
    setTimeout(() => this.isLoading = false);
  }

  private readonly notificationsList: Notification[] = [];
  get total(): number {
    return this.notificationsList.length;
  }
  get canGoNext(): boolean {
    return this.currentIndex < this.notificationsList.length - 1;
  }
  get canGoPrevious(): boolean {
    return this.currentIndex > 0;
  }
  notification: Notification;

  dashboardSelection: Dashboard[] = [];
  dashboardSelectionDisabled: Dashboard[] = [];

  constructor (
    @Inject(MAT_DIALOG_DATA) data,
    public yot: YotService,
    private dialogRef: MatDialogRef<NotificationsReaderComponent>,
    private dialog: MatDialog
  ) {
    this.notificationsList = data.notifications;
    dialogRef.afterClosed().subscribe((res) => {
      if (res) {
        switch (res.request) {
          case 'program_configure':
            this.dialog.open(ModuleSettingsDialogComponent, {
              panelClass: 'dialog-no-padding',
              width: '100%',
              minWidth: '320px',
              maxWidth: '576px',
              disableClose: false,
              data: {module: this.yot.getModuleByRef(this.notification.sender)}
            });
            break;
          case 'module_configure':
            this.dialog.open(ModuleSettingsDialogComponent, {
              panelClass: 'dialog-no-padding',
              width: '100%',
              minWidth: '320px',
              maxWidth: '576px',
              disableClose: false,
              data: {module: this.notification.data.module}
            });
            break;
        }
      }
    });
  }

  ngOnInit(): void {
    this.goNext();
  }

  goNext() {
    this.currentIndex++;
    this.notification.read = true;
  }
  goPrevious() {
    this.currentIndex--;
  }

  request(req: string) {
    return {request: req, sender: this.notification.sender};
  }

  onProgramDisableClick() {
    const module = this.yot.getModuleByRef(this.notification.sender);
    const adapter = (module.getAdapter() as HomegenieAdapter);
    const mr = adapter.getModuleReference(module);
    this.isLoading = true;
    adapter
      .apiCall(HomegenieApi.Automation.Programs.Disable(+mr.Address))
      .subscribe({
        next: (res) => {
          adapter.yot.notificationService
            .reloadPrograms.next();
          this.isLoading = false;
        },
        error: (err) => {
          console.log(err);
          this.isLoading = false;
        }
      });
  }

  onDashboardSelectionChange(selectionChange: MatOptionSelectionChange<Dashboard>) {
    const dashboard = selectionChange.source.value;
    const widget: DashboardWidget = this.notification.data.widget;
    if (selectionChange.source.selected) {
      dashboard.widgets
        .push(widget);
      this.yot.dashboardService
        .onDashboardWidgetAdded.next({ dashboard, widget });
    } else {
      dashboard.widgets = dashboard.widgets
        .filter((dw) => dw !== widget);
      this.yot.dashboardService
        .onDashboardWidgetRemoved.next({ dashboard, widget });
    }
    setTimeout(() => {
      this.notification.data.addedToDashboards = [...this.dashboardSelection];
    });
  }
}
