import {Component, Inject, OnInit} from '@angular/core';
import {MAT_DIALOG_DATA, MatDialogRef} from "@angular/material/dialog";
import {HomegenieAdapter} from "../../homegenie-adapter";
import * as moment from "moment/moment";
import {HomegenieApi} from "../../homegenie-api";

@Component({
  selector: 'app-backup-dialog',
  templateUrl: './backup-dialog.component.html',
  styleUrls: ['./backup-dialog.component.scss']
})
export class BackupDialogComponent implements OnInit {
  adapter: HomegenieAdapter;

  constructor(@Inject(MAT_DIALOG_DATA) data: {adapter: HomegenieAdapter, file: any},
              private dialogRef: MatDialogRef<BackupDialogComponent>) {
    this.adapter = data.adapter;
  }

  ngOnInit(): void {
    this.adapter.apiCall(HomegenieApi.SystemConfig.System.ConfigurationBackup, null, {
      responseType: 'blob'
    }).subscribe((ar) => {
        this.dialogRef.close();
        const a = document.createElement('a')
        const objectUrl = URL.createObjectURL(ar.response)
        a.href = objectUrl
        a.download = `homegenie_backup_${moment().format('YYYYMMDD_HHmmss')}.zip`;
        a.click();
        URL.revokeObjectURL(objectUrl);
      });
  }
}
