import {Component, Input, NgZone, OnChanges, OnDestroy} from '@angular/core';
import {DashboardWidget} from '../../../services/dashboard/dashboard';
import {WidgetType} from '../../../api/widgets/widget-type';
import {WidgetActionRequest, WidgetActionRequestAction} from '../../../widgets/common-parts/widget-actions-menu/widget-actions-menu.component';

import {YotService} from '../../../services/yot/yot.service';
import {ModuleSettingsDialogComponent} from '../../../components/dialogs/module-settings-dialog/module-settings-dialog.component';
import {ModuleStatisticsDialogComponent} from '../../../components/dialogs/module-statistics-dialog/module-statistics-dialog.component';
import {ModuleSchedulingDialogComponent} from '../../../components/dialogs/module-scheduling-dialog/module-scheduling-dialog.component';
import {ModuleEventsDialogComponent} from '../../../components/dialogs/module-events-dialog/module-events-dialog.component';
import {ModuleEditDialogComponent} from '../../../components/dialogs/module-edit-dialog/module-edit-dialog.component';

/** In-memory widget instance: the standard widget controls never persist its configuration. */
@Component({
  selector: 'app-widget-preview',
  template: `
    <div class="preview">
      <app-custom-widget *ngFor="let widget of widgets" [widget]="widget" [options]="widgetOptions"
                         (widgetActionRequest)="onWidgetActionRequest($event)"></app-custom-widget>
    </div>
    <div *ngIf="error" role="alert" class="error">
      <span>{{ error }}</span><button mat-button (click)="reload()">{{ 'retry' | translate }}</button>
    </div>
  `,
  styles: [`:host{display:block;margin:12px 0}.preview{display:flex;justify-content:center;max-width:100%;overflow:auto;padding:4px}.error{color:var(--warn-color,#ef5350);padding:8px;white-space:pre-wrap;overflow-wrap:anywhere}`]
})
export class WidgetPreviewComponent implements OnChanges, OnDestroy {
  @Input() code: {html: string, css: string, js: string};
  widgets: DashboardWidget[] = [];
  widgetOptions: any;
  error = '';
  private source = '';
  private generation = 0;
  private identity = 'chat-preview-' + Date.now() + '-' + Math.random().toString(36).slice(2);
  constructor(private zone: NgZone, private yot: YotService) {}

  ngOnChanges() {
    const source = JSON.stringify(this.code);
    if (source !== this.source) { this.source = source; this.reload(); }
  }

  reload() {
    const version = ++this.generation;
    const previousConfiguration = this.widgets[0]?.configuration;
    const previousId = previousConfiguration?.componentId;
    const componentId = this.identity + '-' + version;
    this.error = '';
    const report = (e: any) => this.zone.run(() => {
      if (version === this.generation) this.error = e?.message || String(e);
    });
    try {
      const controller = zuix.controller((this.code.js || 'function(cp) { cp.create = function() {}; }') as any,
        {componentId: '/widgets/' + componentId, error: report} as any);
      this.widgetOptions = {
        componentId, html: this.code.html, css: this.code.css || false, controller,
        temporary: true, suppressGlobalError: true, error: report,
        hideRemoveOption: true, hideStartNewRowOption: true,
        ready: () => { if (previousId) zuix.removeCachedComponent('/widgets/' + previousId); }
      };
      this.widgets = [new DashboardWidget(WidgetType.CustomWidget, undefined, undefined,
        {...previousConfiguration, componentId})];
    } catch (e) { this.widgets = []; report(e); }
  }

  ngOnDestroy() { this.generation++; }

  onWidgetActionRequest(request: WidgetActionRequest) {
    const module = this.yot.getModuleByRef(this.widgets[0]?.module);
    if (!module) return;
    let component;
    let maxWidth = '576px';
    switch (request.action) {
      case WidgetActionRequestAction.showSettings: component = ModuleSettingsDialogComponent; break;
      case WidgetActionRequestAction.showStatistics: component = ModuleStatisticsDialogComponent; maxWidth = '960px'; break;
      case WidgetActionRequestAction.showSchedule: component = ModuleSchedulingDialogComponent; break;
      case WidgetActionRequestAction.showLogs: component = ModuleEventsDialogComponent; break;
      case WidgetActionRequestAction.showEdit: component = ModuleEditDialogComponent; break;
    }
    if (component) this.yot.dialog.open(component, {
      panelClass: 'dialog-no-padding', width: '100%', minWidth: '280px', maxWidth,
      data: {module, options: module.getWidgetData()}
    });
  }
}
