import {Component, OnDestroy, OnInit} from '@angular/core';
import {Adapter} from "../../adapters/adapter";
import {YotService} from "../../services/yot/yot.service";
import {NavigationService} from "../../services/navigation.service";
import {HomegenieApi} from "../../adapters/home-genie/homegenie-api";
import {HomegenieAdapter} from "../../adapters/home-genie/homegenie-adapter";
import {FileSelectDialogComponent} from "../../components/dialogs/file-select-dialog/file-select-dialog.component";
import {
  TextInputDialogComponent,
  TextInputDialogConfig
} from "../../components/dialogs/text-input-dialog/text-input-dialog.component";
import {PagesRoute} from "../../pages-route";
import {DashboardWidget} from "../../services/dashboard/dashboard";
import {WidgetType} from "../../api/widgets/widget-type";
import {WidgetCodeType} from "../automation/widget-editor/widget-editor.component";
import {Subscription} from "rxjs";

@Component({
  selector: 'app-widgets-page',
  templateUrl: './widgets-page.component.html',
  styleUrls: ['./widgets-page.component.scss']
})
export class WidgetsPageComponent implements OnInit,OnDestroy {

  selectedAdapter: Adapter;

  widgetsList: any[];

  getWidget(componentId: string) {
    return {
      type: WidgetType.CustomWidget,
      module: undefined,
      data: {
        componentId
      }
    } as DashboardWidget;
  }
  getWidgetOptions(componentId: string) {
    return {
      disableMenu: true,
      componentId
    };
  }

  private widgetEventSubscription: Subscription;

  constructor(public yot: YotService, protected navigationService: NavigationService) {
    this.selectedAdapter = this.yot.getDefaultAdapter();
  }

  ngOnInit(): void {
    this.refresh();
    this.navigationService.toolbarTitle.emit('custom_widgets');

    this.yot.layoutService.contextualHelpLink = 'https://homegenie.it/server/programming/widgets/';

    this.widgetEventSubscription = this.yot.onWidgetUpdated.subscribe({
      next: (widget) => {
        setTimeout(() => {
          this.refresh();
        }, 500);
      }
    });
  }
  ngOnDestroy(): void {
    this.widgetEventSubscription?.unsubscribe();
  }

  onWidgetAddClick($event: MouseEvent) {
    this.yot.translate.get(['add_new_widget', 'enter_widget_path', 'only_lowercase_letters_numbers_hyphens_path']).subscribe((res) => {
      const dialogRef = this.yot.dialog.open(TextInputDialogComponent, {
        disableClose: false,
        data: {
          title: res['add_new_widget'],
          description: res['enter_widget_path'],
          label: 'path',
          placeholder: 'enter_path',
          pattern: '^[\\p{Ll}\\p{Lo}\\d]+(?:[/-][\\p{Ll}\\p{Lo}\\d]+)*$',
          patternError: res['only_lowercase_letters_numbers_hyphens_path'],
          existingNames: this.widgetsList,
          value: ''
        } as TextInputDialogConfig
      });
      dialogRef.afterClosed().subscribe((name) => {
        if (name && name.length > 1) {
          this.navigationService.isLoading = true;
          (this.yot.getDefaultAdapter() as HomegenieAdapter).apiCall(HomegenieApi.Config.Widgets.Add(name))
            .subscribe((res) => {
              const path = name.substring(0, name.lastIndexOf('/'));
              name = name.substring(name.lastIndexOf('/') + 1);
              // route to edit new widget
              this.navigationService.router.navigate([
                PagesRoute.WidgetsPage,
                path,
                name
              ]).then(() => {
                this.navigationService.isLoading = false;
              });
            });
        }
      });
    });
  }

  onWidgetImportClick($event: MouseEvent) {
    const dialogRef = this.yot.dialog.open(FileSelectDialogComponent, {
      width: '340px',
      disableClose: false,
      data: {
        accept: 'application/zip, .zip'
      }
    });
    dialogRef.afterClosed().subscribe((filesList) => {
      if (filesList) {
        this.uploadWidgetFile(filesList[0]);
      }
    });
  }

  private uploadWidgetFile(file: File) {
    this.navigationService.isLoading = true;
    let formData:FormData = new FormData();
    formData.append('uploadFile', file, file.name);
    const  options = {};
    this.yot.http
      .post(`/api/${HomegenieApi.Config.Widgets.Import}`, formData, options)
      .subscribe((res: any) => {
        this.navigationService.isLoading = false;
        this.refresh();
      }, err => this.operationError(err));
  }

  private operationError(err) {
    const yot = this.yot;
    yot.translate.get('error_occurred')
      .subscribe((tr) => {
        yot.notify(tr, err.message);
      });
    this.navigationService.isLoading = false;
  }

  private refresh() {
    (this.selectedAdapter as HomegenieAdapter)
      ?.apiCall(HomegenieApi.Config.Widgets.List)
      .subscribe((apiResponse) => this.widgetsList = apiResponse.response as string[]);
  }
}
