import {Component, Input, OnDestroy, OnInit} from '@angular/core';
import {HomegenieAdapter, ResponseCode} from '../homegenie-adapter';
import {MatDialog} from '@angular/material/dialog';
import {HomegenieApi} from '../homegenie-api';
import {HomegenieZwaveApi} from '../homegenie-zwave-api';
import {
  ZwaveManagerDialogComponent
} from "../../../components-extras/zwave/zwave-manager-dialog/zwave-manager-dialog.component";
import {
  ActionConfirmDialogComponent,
  ActionConfirmDialogConfig
} from "../../../components/dialogs/action-confirm-dialog/action-confirm-dialog.component";

@Component({
  selector: 'app-zwave-setup-form',
  templateUrl: './zwave-setup-form.component.html',
  styleUrls: ['./zwave-setup-form.component.scss']
})
export class ZwaveSetupFormComponent implements OnInit, OnDestroy {
  get isOnline(): boolean {
    return this._isOnline;
  }
  get isReady(): boolean {
    return this.adapter.zwaveAdapter.isReady && !this.isLoading;
  }

  set isOnline(value: boolean) {
    this._isOnline = value;
  }
  @Input()
  adapter: HomegenieAdapter;

  serialPorts: { value: string, content: string }[] = [];

  portName = '/dev/ttyACM0';

  statusCheckInterval;
  isLoading = false;
  private _isOnline = false;

  constructor(
    public dialog: MatDialog
  ) {
  }

  ngOnInit(): void {
    this.statusCheckInterval = setInterval(() => {
      if (this.isLoading) return;
      this.adapter.apiCall(HomegenieApi.Config.Interfaces.Status)
        .subscribe((res) => {
          // TODO: !!! create enum for 'HomeAutomation.ZWave' !!
          // TODO: !!! create enum for 'HomeAutomation.ZWave' !!
          const interfaceStatus = res.response.find((i) => i.Domain === 'HomeAutomation.ZWave');
          const wasOnline = this._isOnline;
          this._isOnline = interfaceStatus && interfaceStatus.IsConnected === 'True';
          if (!wasOnline && this._isOnline) {
            this.adapter.connect().subscribe((res) => {
              this.isLoading = false;
            }, (err) => {
              // TODO: report error
              console.log(err);
              this.isLoading = false;
            });
          } else {
            this.isLoading = false;
          }
        }, (err) => {
          // TODO: report error
          console.log(err);
          this.isLoading = false;
        });
    }, 2000);
    this.loadPorts();
  }
  ngOnDestroy() {
    if (this.statusCheckInterval) {
      clearInterval(this.statusCheckInterval);
    }
  }

  onPortChange(e): void {
    const command = HomegenieZwaveApi.Options.Set.Port
      .replace('{{portName}}', encodeURIComponent(this.portName));
    this.adapter.apiCall(command)
      .subscribe((res) => {
        if (res.code === ResponseCode.Success) {
          console.log('ZWave Set Port', this.portName, res);
        } else {
          // TODO: ... log error
        }
      });
  }
  onDeviceManagerButtonClick(e): void {
    const dialogRef = this.dialog.open(ZwaveManagerDialogComponent, {
      // height: '400px',
      // width: '600px',
      maxWidth: '800px',
      disableClose: true,
      data: this.adapter
    });
    dialogRef.afterClosed().subscribe(() => {
      this.adapter.yot.saveConfiguration();
    });
  }

  loadPorts(): void {
    this.adapter.apiCall(HomegenieApi.Config.Interfaces.Configure.Hardware.SerialPorts)
      .subscribe((res) => {
        if (res.code === ResponseCode.Success && res.response && res.response.length > 0) {
          this.serialPorts = res.response;
        }
        this.adapter.apiCall(HomegenieZwaveApi.Options.Get.Port).subscribe((res2) => {
          if (res2.code === ResponseCode.Success) {
            this.portName = res2.response.ResponseValue;
          } else {
            // TODO: ... log error
          }
        });
      });
  }

  onHealNetworkButtonClick($event: MouseEvent) {
    this.isLoading = true;
    this.adapter.zwaveAdapter.healNetwork().subscribe(() => this.isLoading = false);
  }

  onHardResetButtonClick($event: MouseEvent) {
    const dialogRef = this.dialog.open(ActionConfirmDialogComponent, {
      width: '320px',
      disableClose: false,
      data: {
        // TODO: add translations (see also ZigBee form)
        title: 'Confirm hard reset?',
        // TODO: add translations (see also ZigBee form)
        message: `All nodes will be removed from the controller.`
      } as ActionConfirmDialogConfig
    });
    dialogRef.afterClosed().subscribe((confirm) => {
      if (confirm) {
        this.isLoading = true;
        this.adapter.zwaveAdapter
          .hardReset().subscribe(() => this.isLoading = false);
      }
    });
  }
}
