export function moduleHttpLoaderFactory(http: HttpClient): ModuleTranslateLoader {
  const baseTranslateUrl = './assets/i18n';
  const options: IModuleTranslationOptions = {
    modules: [
      {baseTranslateUrl},
      {moduleName: 'widgets', baseTranslateUrl},
      {moduleName: 'homegenie', baseTranslateUrl},
      {moduleName: 'notify', baseTranslateUrl},
      {moduleName: 'zwave', baseTranslateUrl},
      {moduleName: 'zigbee', baseTranslateUrl},
      {moduleName: 'module', baseTranslateUrl},
      {moduleName: 'blockly', baseTranslateUrl},
    ],

    // TODO: manually increment version number to prevent
    //       caching of translation files when modified
    version: 42
  };
  return new ModuleTranslateLoader(http, options);
}

