import {Component, ElementRef, OnDestroy, OnInit, ViewChild} from '@angular/core';
import {WidgetBaseComponent} from "../widget-base.component";
import {ZxWidget} from "../widgets.module";
import {
  CustomWidgetSettingsDialogComponent
} from "./custom-widget-settings-dialog/custom-widget-settings-dialog.component";
import {ModuleReference, ModuleType} from "../../services/yot/module";
import {
  WidgetActionRequest,
  WidgetActionRequestAction
} from "../common-parts/widget-actions-menu/widget-actions-menu.component";
import {MatDialogRef} from "@angular/material/dialog";
import {DashboardLayoutEventValue} from "../../services/dashboard/dashboard.service";
import {ComponentContext} from "zuix-dist";

const DefaultSizeOptions = ['', 'small', 'medium', 'big'];

@Component({
  selector: 'app-custom-widget',
  templateUrl: './custom-widget.component.html',
  styleUrls: ['./custom-widget.component.scss']
})
export class CustomWidgetComponent extends WidgetBaseComponent implements OnInit, OnDestroy {
  @ViewChild('container')
  container: HTMLDivElement;
  @ViewChild('widget', {static: false})
  widgetElement: ElementRef;

  isCustomWidget: boolean;

  sizeOptions = DefaultSizeOptions;

  controller: any;

  private isConfigureDialogOpen = false;

  private destroyed = false;
  private loadTimer: ReturnType<typeof setTimeout>;
  private _componentId = '';
  get componentId(): string {
    return this._componentId;
  }
  set componentId(value: string) {
    if (this.destroyed) return;
    clearTimeout(this.loadTimer);
    const disableMenu = this.options.disableMenu;
    this._componentId = value?.trim();
    if (value) {
      let cid = this._componentId;
      if (!cid.startsWith('/') && cid.indexOf('://') === -1) {
        cid = '/widgets/' + cid;
      }
      const options = {
        css: this.options.css,
        html: this.options.html,
        controller: this.options.controller,
        suppressGlobalError: this.options.suppressGlobalError,
        ready: (ctx: ComponentContext) => {
          this.ngZone.run(() => {
            this.controller = ctx.controller();
            if (this.dialogRef) {
              this.dialogRef.componentInstance.configure(this.controller);
            }
            if (typeof this.options.ready === 'function') {
              this.options.ready(ctx);
            }

            this.options.disableMenu = disableMenu;

            this.applyCustomWidgetConfig();
            this.changeDetector.markForCheck();
          });
        },
        error: this.options.error,
      };
      this.options.disableMenu = true;
      this.ngZone.runOutsideAngular(() => {
        this.loadTimer = setTimeout(() => {
          if (this.destroyed) return;
          try {

            const w = (this.widgetElement?.nativeElement as ZxWidget);
            w.setConfigureCallback(() => {
              if (this.isConfigureDialogOpen) return;
              this.isConfigureDialogOpen = true;
              const dialogRef = this.configure(this.controller);
              dialogRef.afterClosed().subscribe((config) => {
                this.isConfigureDialogOpen = false;
                if (!this.destroyed) this.controller?.refresh && this.controller.refresh();
              });
              return dialogRef;
//              this.widgetActionRequest.emit({ action: WidgetActionRequestAction.showCustomWidgetOptions });
            });

            w.setSettingsCallback(() => {
              this.widgetActionRequest.emit({ action: WidgetActionRequestAction.showSettings });
            });

            w?.load(cid, this.module, options, this.yot);

          } catch (e) {
            if (typeof this.options.error === 'function') this.options.error(e);
            if (!this.options.suppressGlobalError) console.log('Error loading component', cid, options, e);
          }
        });
      });
    } else {
      this.ngZone.runOutsideAngular(() => {
        this.loadTimer = setTimeout(() => {
          if (this.destroyed) return;
          (this.widgetElement?.nativeElement as ZxWidget)
            ?.unload();
        });
      });
    }
  }

  private dialogRef: MatDialogRef<CustomWidgetSettingsDialogComponent>;

  ngOnInit(): void {
    super.ngOnInit();
    this.init();
    this.componentId = this.configuration?.componentId;
  }
  ngOnDestroy() {
    this.destroyed = true;
    clearTimeout(this.loadTimer);
    this.dialogRef?.close();
    super.ngOnDestroy();
    this.ngZone.runOutsideAngular(() => {
      (this.widgetElement?.nativeElement as ZxWidget)
        ?.unload();
    });
    if (this.options.temporary) zuix.removeCachedComponent('/widgets/' + this.componentId);
  }

  init(): void {

    if (this.data?.componentId) {

      this.configuration = this.configuration || {
        componentId: this.data?.componentId,
        module: this.data?.module.moduleId
      };

    } else {

      this.configuration = this.configuration || {
        componentId: this.options?.componentId,
        module: this.options?.module ? new ModuleReference(this.options.module).moduleId : undefined
      };

    }

    this.module = this.yot.getModule(this.configuration?.module);
    if (this.widget) {
      this.widget.module = this.module ? new ModuleReference(this.module) : null;
    }
    this.isCustomWidget = !(this.module && this.module.type == ModuleType.Program && this.module.field('Widget.DisplayModule')?.value.substring(7) === this.configuration.componentId);
  }

  configure(controller?: any): MatDialogRef<CustomWidgetSettingsDialogComponent> {
    const applyConfig = (config) => {
      if (config && !this.destroyed) {
        this.module = this.yot.getModule(config.module);
        if (this.widget) {
          this.widget.module = this.module ? new ModuleReference(this.module) : null;
        }
        this.configuration = config;
        this.init();
        this.componentId = config.componentId;
        this.save();
        window.dispatchEvent(new Event('resize'));
      }
    };
    this.dialogRef = this.dialog.open(CustomWidgetSettingsDialogComponent, {
      panelClass: 'dialog-no-padding',
      width: '100%',
      minWidth: '280px',
      maxWidth: '576px',
      data: {
        controller,
        configuration: {...this.configuration},
        module: this.module,
        adapter: this.yot.getDefaultAdapter(),
        uiMode: (this.options.enableEdit ? 'edit' : ''),
        callback: (config) => {
          applyConfig(config);
        }
      }
    });
    this.dialogRef.afterClosed().subscribe((config: any) => {
      applyConfig(config);
      this.dialogRef = null;
    });
    return this.dialogRef;
  }

  onWidgetActionRequest(actionRequest: WidgetActionRequest): void {
    if (actionRequest.action === WidgetActionRequestAction.showCustomWidgetOptions) {
      this.configure(this.controller);
      return;
    } else if (actionRequest.action === WidgetActionRequestAction.showEdit) {
// TODO: ........... show module edit (IF HAS BOUND MODULE)
    }
    this.widgetActionRequest.emit(actionRequest);
  }

  save() {
    if (!this.options.temporary) super.save();
  }

  applyCustomWidgetConfig(controller?): void {
    if (controller) {
      this.controller = controller;
    }
    const controllerSettings = this.controller?.settings;
    this.sizeOptions = controllerSettings?.sizeOptions ?? DefaultSizeOptions;

    this.configuration = this.configuration || {};
    this.configuration.size = this.configuration?.size?.length > 0 ? this.configuration?.size : controllerSettings?.defaultSize;

    if (!this.options.temporary) this.yot.dashboardService.layoutEvents.emit(DashboardLayoutEventValue.LayoutRefresh);
  }
}
