import {Pipe, PipeTransform} from '@angular/core';
import {FLD, YotService} from "../services/yot/yot.service";
import {SensorField} from "../api/widgets/sensor-widget.api";
import {ModuleType} from "../services/yot/module";
import {Color} from "@iplab/ngx-color-picker";

@Pipe({ name: 'sensorValueFormatter' })
export class SensorValueFormatterPipe implements PipeTransform {

  constructor(private yot: YotService) {}

  transform(fieldValue: any, sensorFieldKey?: string, moduleType?: string, decimalDigits?: number): string {
    fieldValue = `${fieldValue}`;
    if (!decimalDigits) decimalDigits = 2;
    const v = parseFloat(fieldValue.replace(',', '.'));
    if ((sensorFieldKey === FLD.Status.Level && (moduleType === ModuleType.DoorWindow || moduleType === ModuleType.DoorLock))
      || sensorFieldKey === SensorField.DoorWindow) {
      return v > 0
        ? this.getText('door_open')
        : this.getText('door_closed');
    }
    if (sensorFieldKey === FLD.Status.Level) {
      if (v === 0) {
        return 'off';
      }
      if (v === 1) {
        return 'on';
      }
      const rounded = (Math.round(v * Math.pow(10, decimalDigits)) / Math.pow(10, decimalDigits));
      return rounded.toLocaleString() + ` (${Math.round(rounded * 100)}%)`;
    }
    if (sensorFieldKey === FLD.Status.ColorHsb) {
      let hsv = fieldValue.split(',').map((cv) => +cv);
      const h = hsv[0] * 360;
      const s = hsv[1] * 100;
      const v = hsv[2] * 100;
      // hsv[3] is color transition seconds
      const c = new Color();
      c.setHsva(h, s, v, 1);

      const size = 16;
      const html = `<span title="${fieldValue}" style="
            display: inline-block;
            width: ${size}px;
            height: ${size}px;
            background-color: ${c.toHexString()};
            border: 1px solid #ccc;
            border-radius: 4px;
            vertical-align: middle;1
         "></span>`;
      return html;
    }
    if (sensorFieldKey === SensorField.MotionDetect) {
      return +fieldValue > 0
        ? this.getText('detected')
        : this.getText('idle');
    }
    if (sensorFieldKey === SensorField.ObjectDetect) {
      return +fieldValue > 0
        ? this.getText('detected') + `&nbsp;(<span>${fieldValue}</span>)`
        : this.getText('idle');
    }
    if (sensorFieldKey === SensorField.ObjectDetectSubject) {
      return `<small class="translucent">${this.getText('data_object')}</small>`;
    }
    if (this.isValidJson(fieldValue)) {
      return `<small class="translucent">${this.getText('data_object')}</small>`;
    }
    if (sensorFieldKey === "HomeGenie.SecurityArmed") {
      if (fieldValue === 'Disarmed') {
        return this.getText('deactivated');
      }
      if (fieldValue === 'Armed') {
        return this.getText('activated');
      }
      if (fieldValue === 'Away') {
        return this.getText('WIDGETS.$alarm_system.arm_away');
      }
      if (fieldValue === 'Home') {
        return this.getText('WIDGETS.$alarm_system.arm_home');
      }
    }
    if (sensorFieldKey === 'HomeGenie.SecurityTriggered') {
      if (v === 0) {
        return this.getText('deactivated');
      }
      if (v === 1) {
        return this.getText('alarmed');
      }
    }
    // TODO: `Status.Tamper' -> tampered / normal
    // outputs as generic decimal value
    if (this.isNumber(fieldValue.toString().replace(',', '.'))) {
      if (typeof fieldValue === 'string') {
        fieldValue = +fieldValue.replace(',', '.');
      }

      // Conversion to preferred unit
      // TODO: remove hard-coded source unit and get it from >> ModuleField.unit <<
      let conversionUnit;
      let key = sensorFieldKey;
      if (key?.endsWith('.Temperature') || key?.indexOf('.Temperature.') !== -1) {
        key = SensorField.Temperature;
      }
      switch (key) {
        case SensorField.Temperature:
          conversionUnit = this.yot.preferences.units.temperature;
          if (conversionUnit === 'F') {
            // no decimals in this case
            decimalDigits = 0;
          }
          fieldValue = this.yot.converters
            .temperature(fieldValue)
            .from('C').to(conversionUnit).value;
          break;
        case SensorField.Humidity:
          decimalDigits = 1;
          break;
        case SensorField.Luminance:
          decimalDigits = 0;
          break;
        case SensorField.Meter.Watts:
          conversionUnit = this.yot.preferences.units.power;
          fieldValue = this.yot.converters
            .power(fieldValue)
            .from('W').to(conversionUnit).value;
          break;
        case SensorField.Meter.WattHours:
          conversionUnit = this.yot.preferences.units.energy;
          fieldValue = this.yot.converters
            .energy(fieldValue)
            .from('Wh').to(conversionUnit).value;
          break;
        case SensorField.Speed:
          conversionUnit = this.yot.preferences.units.speed;
          fieldValue = this.yot.converters
            .speed(fieldValue)
            .from('km/h').to(conversionUnit).value;
          break;
      }

      return (Math.round(fieldValue * Math.pow(10, decimalDigits)) / Math.pow(10, decimalDigits)).toLocaleString(this.yot.translate.currentLang,{
        minimumFractionDigits: 0,
        maximumFractionDigits: decimalDigits,
        useGrouping: true
      });
    }
    // default output as it is
    return fieldValue;
  }

  private isNumber(n): boolean {
    return !isNaN(parseFloat(n)) && !isNaN(+n)
  }
  private isValidJson(str) {
    if (typeof str !== 'string' || !str.trim()) {
      return false;
    }
    try {
      const result = JSON.parse(str);
      return !(typeof result !== 'object' || result === null);
    } catch (error) {
      return false;
    }
  }
  private getText(text: string) {
    this.yot.translate.get(text).subscribe(tr => {
      text = tr;
    });
    return `<span style="text-transform: capitalize">${text}</span>`;
  }
}
