import {Component, ViewChild} from '@angular/core';
import {WidgetBaseComponent} from "../widget-base.component";
import {ActivityStatusComponent} from "../common-parts/activity-status/activity-status.component";
import {
  ThermostatCommand,
  ThermostatFanMode,
  ThermostatField,
  ThermostatMode,
  ThermostatOperatingState
} from "../../api/widgets/thermostat-widget.api";
import {SensorField} from "../../api/widgets/sensor-widget.api";


export class ThermostatFeatures {
  cooling: boolean;
  heating: boolean;
  auto: boolean;
  ecoMode: boolean;
  fanMode: boolean
}

@Component({
  selector: 'app-thermostat',
  templateUrl: './thermostat.component.html',
  styleUrls: ['./thermostat.component.scss']
})
export class ThermostatComponent extends WidgetBaseComponent {
  @ViewChild(ActivityStatusComponent)
  private activityStatus: ActivityStatusComponent;

  private readonly economyFlag = 'Economy';

  Mode = ThermostatMode;
  FanMode = ThermostatFanMode;
  OperatingState = ThermostatOperatingState;

  isLoading = false;

  get features(): ThermostatFeatures {
    return super.features;
  }

  get statusText(): string {
    let label = this.currentMode;
    this.yot.translate.get(label.toLowerCase()).subscribe((tr) => {
      if (tr.toLowerCase() !== label.toLowerCase()) label = tr;
    });
    return label;
  }

  // 'Off' | 'Heat' | 'Cool' | 'Auto'
  get currentMode(): string {
    const mode = this.module.field(ThermostatField.Mode)
    if (mode && mode.value) {
      return mode.value; //.replace(this.economyFlag, '');
    }
    return 'N/A';
  }
  set currentMode(m: string) {
    if (m && m.length > 0) {
      const mode = this.module.field(ThermostatField.Mode);
      const currentMode = mode ? mode.value : ThermostatMode.Off;
      this.isLoading = true;
      this.module.control(ThermostatCommand.Mode.Set, m)
        .subscribe((res) => {
          this.isLoading = false;
        }, (err) => {
          this.activityStatus.setError('Error issuing command');
          // revert slider to previous value
          this.module.field(ThermostatField.Mode, null);
          requestAnimationFrame(() => {
            this.module.field(ThermostatField.Mode, currentMode);
          });
          this.isLoading = false;
        });
    }
  }
  get currentModePrefix(): string {
    return this.currentMode.replace(this.economyFlag, '');
  }
  set currentModePrefix(m: string) {
    this.currentMode = m;
  }

  get economyMode(): boolean {
    const mode = this.module.field(ThermostatField.Mode)
    if (mode && mode.value) {
      return mode.value.endsWith(this.economyFlag);
    }
  }
  set economyMode(eco: boolean) {
    this.currentMode = this.currentModePrefix + (eco ? this.economyFlag : '');
  }

  get setPointMax(): number {
    switch (this.yot.preferences.units.temperature) {
      case 'C':
        return 35;
      case 'F':
        return 95;
    }
    return 100;
  }
  get setPointMin(): number {
    switch (this.yot.preferences.units.temperature) {
      case 'C':
        return 5;
      case 'F':
        return 40;
    }
    return 0;
  }
  get setPointStep(): number {
    switch (this.yot.preferences.units.temperature) {
      case 'C':
        return .5;
      case 'F':
        return 1;
    }
    return .5;
  }
  get setPointC(): number {
    const setPoint = this.module.field(this.setPointField);
    if (setPoint) {
      return setPoint.value;
    }
    return 0;
  }
  get setPoint(): number {
    const setPoint = this.module.field(this.setPointField);
    if (setPoint) {
      let v = setPoint.value;
      // Thermostat API temperature parameter is internally always stored as C
      const unit = this.yot.preferences.units.temperature;
      if (unit !== 'C') {
        v = this.yot.converters.temperature(v).from('C').to(unit).value;
      }
      return v;
    }
    return 0;
  }
  set setPoint(v: number) {
    const mode = this.currentMode;
    if (mode.startsWith(ThermostatMode.Heat) || mode.startsWith(ThermostatMode.Cool)) {
      this.isLoading = true;
      // Thermostat API temperature parameter must be always passed as C
      const unit = this.yot.preferences.units.temperature;
      if (unit !== 'C') {
        v = this.yot.converters.temperature(v).from(unit).to('C').value;
      }
      const type = this.setPointField.substring(this.setPointField.lastIndexOf('.') + 1);
      this.module.control(ThermostatCommand.SetPoint.Set, `${type}/${v}`)
        .subscribe((res) => {
          this.isLoading = false;
        }, (err) => {
          this.activityStatus.setError('Error issuing command');
          this.isLoading = false;
        });
    }
  }
  get setPointField(): string {
    const mode = this.currentMode;
    switch (mode) {
      case ThermostatMode.Heat:
        return ThermostatField.SetPoint.Heating;
      case ThermostatMode.HeatEconomy:
        return ThermostatField.SetPoint.HeatingEconomy;
      case ThermostatMode.Cool:
        return ThermostatField.SetPoint.Cooling;
      case ThermostatMode.CoolEconomy:
        return ThermostatField.SetPoint.CoolingEconomy;
    }
  }

  get fanMode(): string {
    const mode = this.module.field(ThermostatField.FanMode);
    return mode ? mode.value : ThermostatFanMode.Off;
  }
  set fanMode(m: string) {
    if (m && m.length > 0) {
      const mode = this.module.field(ThermostatField.FanMode);
      const currentMode = mode ? mode.value : ThermostatFanMode.Off;
      this.isLoading = true;
      this.module.control(ThermostatCommand.FanMode.Set, m)
        .subscribe((res) => {
          this.isLoading = false;
        }, (err) => {
          this.activityStatus.setError('Command not implemented');
          // revert slider to previous value
          this.module.field(ThermostatField.FanMode, null);
          requestAnimationFrame(() => {
            this.module.field(ThermostatField.FanMode, currentMode);
          });
          this.isLoading = false;
        });
    }
  }


  get operatingState(): string {
    const state = this.module.field(ThermostatField.OperatingState);
    if (state) {
      return state.value;
    }
    return 'N/A';
  }
  get temperature(): number {
    const t = this.module.field(SensorField.Temperature);
    if (t) {
      return t.value;
    }
    return 0.0;
  }
}
