import {Component, ElementRef, Inject, OnDestroy, OnInit, ViewChild} from '@angular/core';
import {HomegenieAdapter, Program} from "../../homegenie-adapter";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {HomegenieApi} from "../../homegenie-api";
import {MatSelectionList} from "@angular/material/list";
import {MatCheckbox} from "@angular/material/checkbox";
import {Subscription} from "rxjs";
import {SetupSystemConfiguration} from "../restore-backup/restore-backup.component";
import {Router} from "@angular/router";
import {ClientConfigService} from "../../../../services/client-config.service";

enum RestoreStep {
  Error = -1,
  UploadBackup,
  SelectPrograms,
  BackupRestore
}

@Component({
  selector: 'app-restore-dialog',
  templateUrl: './restore-dialog.component.html',
  styleUrls: ['./restore-dialog.component.scss']
})
export class RestoreDialogComponent implements OnInit, OnDestroy {
  @ViewChild('matSelectionList') matSelectionList: MatSelectionList;
  @ViewChild('selectAllToggle') selectAllToggle: MatCheckbox;
  @ViewChild('messageBox') messageBox: ElementRef;

  adapter: HomegenieAdapter;
  isLoading = false;
  errorMessage = '';

  RestoreStep = RestoreStep;
  currentStep = RestoreStep.UploadBackup;
  progressMessage = '';

  config = new SetupSystemConfiguration();

  private moduleEventSubscription: Subscription;

  constructor(@Inject(MAT_DIALOG_DATA) data: {adapter: HomegenieAdapter}, private router: Router, private clientConfigService: ClientConfigService) {
    this.adapter = data.adapter;
  }

  ngOnInit(): void {
    this.moduleEventSubscription = this.adapter.onModuleEvent.subscribe((e) => {
      if (e.event.Domain === 'HomeGenie.BackupRestore' && e.event.Property === 'InstallProgress.Message') {
        this.progressMessage += e.event.Value + '\n';
        setTimeout(() =>
          this.messageBox.nativeElement.scrollTop = this.messageBox.nativeElement.scrollHeight
        );
      }
    });
  }
  ngOnDestroy() {
    this.moduleEventSubscription.unsubscribe();
  }


  onBackupFileLoaded(config: SetupSystemConfiguration) {
    this.config = config;
  }
  onRestoreNextClick() {
    if (this.config.restoreProgramList.length > 0) {
      this.currentStep = RestoreStep.SelectPrograms;
      setTimeout(() => {
        this.matSelectionList.selectAll();
        this.selectAllToggle.checked = true;
      });
    }
    else {
      this.currentStep = RestoreStep.BackupRestore;
      this.restore();
    }
  }

  onSelectAllClick() {
    this.selectAllToggle.checked ?
      this.matSelectionList.deselectAll() :
        this.matSelectionList.selectAll();
  }
  onSelectedProgramsChange() {
    this.matSelectionList.selectedOptions.selected.length === this.matSelectionList.options.length ?
      this.selectAllToggle.checked = true :
        this.selectAllToggle.checked = false;
  }
  onRestoreClick() {
    const selectedPrograms = this.matSelectionList.selectedOptions.selected
      .map(item => item.value);
    this.restore(selectedPrograms);
  }

  onRestoreCompleted() {
    this.router.navigate([ '/' ])
      .then((res) => {
        // TODO: show some tip message (maybe)
      });
  }

  private restore(programsList?: Array<Program>) {
    programsList = programsList || [];
    this.isLoading = true;
    this.currentStep = RestoreStep.BackupRestore;
    this.adapter.yot.dashboardService.removeAllDashboards();
    this.adapter.yot.modules = [];
    this.adapter.yot.saveConfiguration().subscribe((config) => {
      this.adapter.apiCall(HomegenieApi.SystemConfig.System.ConfigurationRestoreStep2(programsList))
        .subscribe((ar) => {
          // TODO: improve this!!
          this.adapter.disconnect().subscribe((res) => {
            this.adapter.importDashboards().subscribe(() => {
              this.clientConfigService.loadClientPreset('default')
                .subscribe(() => {
                  this.adapter.yot.saveConfiguration().subscribe((config) => {
                    console.log('Config saved', config);
                    this.isLoading = false;
                  });
                });
            }, (err) => {
              this.adapter.yot.notify('Error', err.message);
              this.isLoading = false;
            });
          });
        }, (error) => {
          this.errorMessage = error.message;
          this.currentStep = RestoreStep.Error;
          this.isLoading = false;
        });
    });
  }
}
