import {Component, Input, OnInit, ViewChild} from '@angular/core';
import {Module} from '../../../services/yot/module';
import {ControlFieldBase} from "../control-field-base";
import {MatSelect} from "@angular/material/select";
import {HomegenieAdapter} from "../../../adapters/home-genie/homegenie-adapter";

@Component({
  selector: 'app-module-select',
  templateUrl: './module-select.component.html',
  styleUrls: ['./module-select.component.scss']
})
export class ModuleSelectComponent extends ControlFieldBase implements OnInit {
  @ViewChild('select')
  select: MatSelect;
  @Input()
  multiple: boolean = false;

  get value(): string {
    return this.data.field && this.data.field.value ? this.data.field.value : '';
  }
  get modules(): Array<Module> {
    const availableModules = this.yot.modules.filter((m) => m.isOnline);

    // 1. Retrieve filters from options
    let fieldNames = '';
    if (this.data.type.options.length >= 3) {
      fieldNames = this.data.type.options[2] || '';
    }
    let typeNames = '';
    if (this.data.type.options.length >= 2) {
      typeNames = this.data.type.options[1] || '';
    }

    const hasFieldFilter = fieldNames.length > 0 && fieldNames !== 'any';
    const hasTypeFilter = typeNames.length > 0 && typeNames !== 'any';

    // If no filters are active, return an empty array (no modules match)
    if (!hasFieldFilter && !hasTypeFilter) {
      return [];
    }

    // 2. Filter using AND logic
    return availableModules.filter((m) => {
      let matchesType = true;
      let matchesField = true;

      // If the type filter is active, it must match
      if (hasTypeFilter) {
        matchesType = new RegExp(`,${m.type},`, 'i').test(`,${typeNames},`);
      }

      // If the field filter is active, the module must contain that field
      if (hasFieldFilter) {
        matchesField = m.fields.some((f) => new RegExp(`,${f.key},`, 'i').test(`,${fieldNames},`));
      }

      // Both conditions must be met (AND)
      return matchesType && matchesField;
    });
  }
  get selectedModule(): Module {
    return this.yot.getModule(this.select?.value);
  }

  reset() {
    super.reset();
    this.select.value = this.originalValue;
  }

  getModuleName(module: Module) {
    const adapter = module.getAdapter();
    if (adapter) {
      return (adapter as HomegenieAdapter).getModuleDisplayName(module);
    }
    return module.name;
  }
}
