import {ChangeDetectionStrategy, ChangeDetectorRef, Component, DoCheck, OnInit, SimpleChanges} from '@angular/core';
import {WidgetBaseComponent} from "../widget-base.component";
import {ModuleField} from "../../services/yot/module";
import {WeatherData} from "../../api/widgets/weather-widget.api";
import * as moment from 'moment';

@Component({
  selector: 'app-weather-forecast',
  templateUrl: './weather-forecast.component.html',
  styleUrls: ['./weather-forecast.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WeatherForecastComponent extends WidgetBaseComponent implements OnInit, DoCheck {

  private demoData = {} as WeatherData;


  get todayDate(): Date {
    return new Date();
  }

  get data(): WeatherData {
    if (super.data && super.data.location && super.data.location.name && super.data.location.country) {
      return super.data;
    }
    // else return static demo data
    return this.demoData;
  }

  ngOnInit() {
    super.ngOnInit();
    const forecastDate1 = moment().add(1,'days');
    const forecastDate2 = moment().add(2,'days');
    const forecastDate3 = moment().add(3,'days');
    this.demoData = {
      location: {
        name: new ModuleField('location', 'Somewhere'),
        country: new ModuleField('country', 'IT')
      },
      astronomy: {
        sunrise: new ModuleField('sunrise', '06:24'),
        sunset: new ModuleField('sunset', '17.32')
      },
      today: {
        date: new Date(),
        icon: new ModuleField('icon', '01d'),
        description: new ModuleField('desc', 'Clear day'),
        temperatureC: new ModuleField('tc', 22.44),
        pressureMb: new ModuleField('pmb', 3.2),
        wind: {
          speedKph: new ModuleField('speedKph', 13.1),
          direction: new ModuleField('direction', 'N/E')
        },
        precipitation: {
          rainMm: new ModuleField('rain', 2.1),
          snowMm: new ModuleField('snow', 12.2)
        }
      },
      forecast: [
        {
          timestamp: forecastDate1.unix()*1000,
          date: moment(forecastDate1).format('dddd'),
          description: new ModuleField('fdesc', 'Thunderstorms'),
          icon: new ModuleField('icon', '11d'),
          minC: new ModuleField('minc', 12.3),
          maxC: new ModuleField('maxc', 16.1),
          temperature: new ModuleField('', 22.4)
        },
        {
          timestamp: forecastDate2.unix()*1000,
          date: moment(forecastDate2).format('dddd'),
          description: new ModuleField('', 'Partly Cloudy'),
          icon: new ModuleField('', '10d'),
          minC: new ModuleField('', 12.3),
          maxC: new ModuleField('', 16.1),
          temperature: new ModuleField('', 15.2)
        },
        {
          timestamp: forecastDate3.unix()*1000,
          date: moment(forecastDate3).format('dddd'),
          description: new ModuleField('', 'Clear day'),
          icon: new ModuleField('', '01d'),
          minC: new ModuleField('', 12.3),
          maxC: new ModuleField('', 16.1),
          temperature: new ModuleField('', 14.2)
        }
      ]
    };
  }

  private lastCheck = new Date().getTime();
  ngDoCheck() {
    if (new Date().getTime() - this.lastCheck > 1000) {
      this.lastCheck = new Date().getTime();
      this.changeDetector.markForCheck();
    }
  }

  trackByFn(index, race) {
    return undefined;
  }
}
