import {Component, ElementRef, Inject, OnInit, ViewChild} from '@angular/core';
import {MAT_DIALOG_DATA, MatDialogRef} from "@angular/material/dialog";
import {MatSelectionList} from "@angular/material/list";

import {HomegenieApi} from "../homegenie-api";
import {Group, HomegenieAdapter} from "../homegenie-adapter";

@Component({
  selector: 'app-programs-packager-dialog',
  templateUrl: './programs-packager-dialog.component.html',
  styleUrls: ['./programs-packager-dialog.component.scss']
})
export class ProgramsPackagerDialogComponent implements OnInit {
  @ViewChild('programSelectionList', {static: true})
  programSelectionList: MatSelectionList;
  @ViewChild('requireSelectionList', {static: false})
  requireSelectionList: MatSelectionList;
  @ViewChild('groupSelectionList', {static: true})
  groupSelectionList: MatSelectionList;
  @ViewChild('scheduleSelectionList', {static: true})
  scheduleSelectionList: MatSelectionList;
  @ViewChild('downloadHelperLink', {static: true})
  downloadHelperLink: ElementRef;

  adapter: HomegenieAdapter;

  programsList: any[];

  packagePrograms: any[];
  packageRequires: any[];

  actualPrograms: any[];
  actualRequires: any[];
  actualGroups: any[] = [];
  actualSchedules: any[] = [];

  groupsList: Group[];
  schedulesList: any[];

  packageInfo = {
    repository: 'user',
    id: 'my-awesome-package',
    version: '1.0.0',
    description: '',
    programs: [],
    groups: [],
    schedules: []
  }

  // TODO: add ProgramBlock & co classes

  constructor(@Inject(MAT_DIALOG_DATA) data: { adapter: HomegenieAdapter, package?: any }, private dialogRef: MatDialogRef<ProgramsPackagerDialogComponent>) {
    this.adapter = data.adapter;
    if (data.package) {
      this.packageInfo = data.package;
    }
  }

  ngOnInit(): void {
    // TODO: use forkJoin !!!!!
    this.adapter.apiCall(HomegenieApi.Automation.Programs.List)
      .subscribe((res) => {
        this.programsList = res.response.map((p) => {
          // assign default PackageInfo values where data is missing
          const info = p.PackageInfo;
          if (!info.id) {
            const originalName = p.Name;
            const allowedInSlug = /[^\p{L}\d _\-.]/gu;
            info.id = originalName
              .toLowerCase()
              .trim()
              .replace(allowedInSlug, '-')
              .replace(/\s+/g, '-')
              .replace(/--+/g, '-')
              .replace(/^-+|-+$/g, '');
          }
          if (!info.version) {
            info.version = '1.0.0';
          }
          return p;
        });
        this.refreshPackagePrograms();
      });
    // get control groups list and schedules list
    this.adapter.apiCall(HomegenieApi.Config.Groups.List)
      .subscribe((res) => {
        this.groupsList = res.response;
        // refresh control groups
        const pi = this.packageInfo;
        this.actualGroups = this.groupsList
          .filter((g) => pi.groups.find(gr => gr.hid === g.Name));
      });
    this.adapter.apiCall(HomegenieApi.Automation.Scheduling.List)
      .subscribe((res) => {
        this.schedulesList = res.response;
        // refresh schedules
        const pi = this.packageInfo;
        this.actualSchedules = this.schedulesList
          .filter((s) => pi.schedules.find(ps => ps.hid === s.Name));
      });
  }

  doneClick() {
    const pi = this.packageInfo;
    const mapProgramFn = (p) => {
      const info = p.value.PackageInfo;
      return {
        repository: pi.repository,
        packageId: pi.id,
        packageVersion: pi.version,
        hid: p.value.Address,
        id: info.id,
        version: info.version,
        required: info.required
      };
    };
    // add selected programs to package
    const programs = this.programSelectionList.selectedOptions.selected.map(p => mapProgramFn(p));
    // add selected external requires
//console.log(this.requireSelectionList.selectedOptions.selected)
    programs.push(...(this.requireSelectionList.selectedOptions.selected.map((p) => ({
      hid: p.value.Address,
      ...p.value.PackageInfo
    }))));
    const groups = this.groupSelectionList.selectedOptions.selected.map(p => {
      return {
        hid: p.value.Name,
        id: 0,
        version: 0,
        required: false
      };
    });
    const schedules = this.scheduleSelectionList.selectedOptions.selected.map(p => {
      return {
        hid: p.value.Name,
        id: 0,
        version: 0,
        required: false
      };
    });
    const packageData = {
      ...this.packageInfo,
      programs,
      groups,
      schedules
    };
    this.adapter.yot.http
      .post('/api/HomeAutomation.HomeGenie/Config/Packages.Bundle', packageData, {
        responseType: 'blob'
      }).subscribe((blob) => {
        const fileName = `${this.packageInfo.id}-${this.packageInfo.version}.zip`;
        const link = this.downloadHelperLink.nativeElement;
        link.href = window.URL.createObjectURL(blob);
        link.download = fileName;
        link.click();
        this.dialogRef.close(packageData);
      });
  }

  onRepositoryIdChange(e: Event) {
    this.refreshPackagePrograms();
  }

  private refreshPackagePrograms() {
    const pi = this.packageInfo;
    // package programs
    this.packagePrograms = this.actualPrograms = this.programsList
      .filter((p) => p.PackageInfo.repository === pi.repository && p.PackageInfo.packageId === pi.id);
    const newPrograms = this.programsList
      .filter((p) => !p.PackageInfo || !p.PackageInfo.repository || !p.PackageInfo.packageId);
    this.packagePrograms.push(...newPrograms);
    // external requires
    this.packageRequires = this.programsList
      .filter((p) => (p.PackageInfo.repository !== pi.repository
        || p.PackageInfo.packageId !== pi.id) && p.PackageInfo.repository && p.PackageInfo.packageId);
    this.actualRequires = this.programsList
      .filter((p) => p.PackageInfo.repository !== pi.repository || p.PackageInfo.packageId !== pi.id)
      .filter((p) => pi.programs.find(pp => pp.id === p.PackageInfo.id && pp.repository === p.PackageInfo.repository && pp.packageId === p.PackageInfo.packageId));
  }
}
