import {Component, EventEmitter, Input, OnDestroy, OnInit, Output, ViewChild} from '@angular/core';
import {HomegenieAdapter, Program} from "../../../adapters/home-genie/homegenie-adapter";
import {NavigationService} from "../../../services/navigation.service";

import {MatDialog} from "@angular/material/dialog";
import {ActivatedRoute} from "@angular/router";
import {YotService} from "../../../services/yot/yot.service";
import {Observable, Subject, Subscription} from "rxjs";
import {HomegenieApi} from "../../../adapters/home-genie/homegenie-api";
import {CodeEditorComponent} from "@ngstack/code-editor";
import {VisualEditorComponent} from "../visual-editor/visual-editor.component";
import {
  ActionConfirmDialogComponent,
  ActionConfirmDialogConfig
} from "../../../components/dialogs/action-confirm-dialog/action-confirm-dialog.component";

@Component({
  selector: 'app-program-editor',
  templateUrl: './program-editor.component.html',
  styleUrls: ['./program-editor.component.scss']
})
export class ProgramEditorComponent implements OnInit, OnDestroy {
  @ViewChild('editorComponent', {static:false})
  editorComponent: CodeEditorComponent | VisualEditorComponent;

  @Input()
  adapter: HomegenieAdapter;
  @Input()
  program: Program;

  @Output()
  closeRequest = new EventEmitter<any>();

  isLoading = false;

  private activatedRouteSubscription: Subscription;

  constructor(private yot: YotService, private navigationService: NavigationService, private dialog: MatDialog, private route: ActivatedRoute) {
  }

  canDeactivate(): Observable<boolean> | boolean {
    if ((this.editorComponent as any)?.canUpdate) {
      // translations
      let textExitWithoutSaving = 'exit_without_saving';
      this.yot.translate.get(textExitWithoutSaving).subscribe((tr) => textExitWithoutSaving = tr);
      let textChangesWillBeLost = 'changes_will_be_lost';
      this.yot.translate.get(textChangesWillBeLost).subscribe((tr) => textChangesWillBeLost = tr);
      // show dialog
      const subject = new Subject<boolean>();
      const dialogRef = this.yot.dialog.open(ActionConfirmDialogComponent, {
        data: {
          title: textExitWithoutSaving,
          message: textChangesWillBeLost
        } as ActionConfirmDialogConfig
      });
      dialogRef.afterClosed().subscribe((confirm) => {
        subject.next(confirm === true);
        subject.complete();
      });
      return subject.asObservable();
    }
    return true;
  }

  ngOnInit(): void {
    if (!this.program) {
      this.program = new Program();
    }
    this.navigationService.drawer.close();
    this.navigationService
      .appMenuChange.next('program');

    this.activatedRouteSubscription = this.route.params.subscribe(params => {
      const adapterId = params['aid'];
      if (adapterId) {
        this.adapter = this.yot.getAdapter(adapterId) as HomegenieAdapter;
      }
      const pid = +params['pid'];
      if (pid && this.adapter) {
        this.refresh(pid);
      }
    });
  }
  ngOnDestroy() {
    if (this.activatedRouteSubscription) {
      this.activatedRouteSubscription.unsubscribe();
    }
    this.navigationService.drawer.open();
    this.navigationService
      .navigationToolbar.next({ title: '' });
    this.navigationService
      .appMenuChange.next('');
  }

  refresh(pid?: number) {
    if (pid) {
      this.isLoading = true;
      this.adapter.apiCall(HomegenieApi.Automation.Programs.Get(pid)).subscribe((res) => {
        this.program = res.response;
        this.isLoading = false;
        this.refresh();
      });
    }
    if (!this.program) return;
    this.navigationService
      .navigationToolbar.next({ title: this.program.Name });
  }
}
