import { Injectable, NgZone } from '@angular/core';
import { fromEvent, merge, Observable, Subject } from 'rxjs';
import { throttleTime } from 'rxjs/operators';

@Injectable({
  providedIn: 'root'
})
export class ActivityService {

  // Iscriviti a questo Observable per sapere quando l'utente è attivo
  public readonly activityDetected$: Observable<void>;

  private _activitySubject = new Subject<void>();

  constructor(private ngZone: NgZone) {
    this.activityDetected$ = this._activitySubject.asObservable();
    this.initListener();
  }

  private initListener() {
    const events = [
      'keydown', 'click', 'wheel', 'mousemove',
      'touchstart', 'touchmove', 'scroll', 'resize'
    ];

    // Creiamo flussi per ogni evento nativo
    const eventStreams = events.map(ev => fromEvent(document, ev));

    // Eseguiamo l'ascolto FUORI da Angular per non bloccare l'app
    this.ngZone.runOutsideAngular(() => {

      merge(...eventStreams).pipe(
        // FONDAMENTALE: Ignora eventi successivi per 500ms.
        // Se muovi il mouse per 1 secondo, emetterà solo 2 segnali invece di 60.
        throttleTime(500)
      ).subscribe(() => {
        // Rientriamo nella Zone di Angular per notificare la tua app
        this.ngZone.run(() => {
          this._activitySubject.next();
        });
      });

    });
  }
}
