import {WidgetType} from "../../api/widgets/widget-type";
import {Module, ModuleReference} from "../yot/module";
import {WidgetData} from "../../widgets/widget-data";

export class Dashboard {
  name: string;
  description: string;

  config: {
    theme: any,
    programs?: ModuleReference[]
  };

  widgets: DashboardWidget[];

  constructor() {
    this.widgets = [];
  }

  addWidget(widgetType: WidgetType, boundModule?: Module, data?: WidgetData, config?: any): DashboardWidget {
    const w = new DashboardWidget(widgetType, boundModule, data, config);
    this.widgets.push(w);
    return w;
  }
  removeWidget(widget: DashboardWidget) {
    const widgetIndex = this.widgets.indexOf(widget);
    this.widgets.splice(widgetIndex, 1);
  }
}

export class DashboardWidget {
  public type: WidgetType;
  public module: ModuleReference; // id of bound module (data source for this widget instance)
  public data?: any;
  public configuration?: any;

  constructor(t: WidgetType, m?: Module, data?: any, config?: any) {
    this.type = t;
    this.module = m ? new ModuleReference(m) : null;
    this.data = data;
    this.configuration = config;
  }
}
