import {EventEmitter, Injectable} from '@angular/core';
import {HttpClient} from "@angular/common/http";
import {Group, Module, ModuleReference} from "../adapters/home-genie/homegenie-api";
import {YotService} from "./yot/yot.service";
import {HomegenieAdapter} from "../adapters/home-genie/homegenie-adapter";

import {Module as YotModule} from "../services/yot/module";

const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
const SpeechGrammarList = window.SpeechGrammarList || window.webkitSpeechGrammarList;
const SpeechRecognitionEvent = window.SpeechRecognitionEvent || window.webkitSpeechRecognitionEvent;

@Injectable({
  providedIn: 'root'
})
export class VoiceControlService {
  listenStarted = new EventEmitter<void>();
  listenError = new EventEmitter<string>();
  listenEnded = new EventEmitter<string>();

  private lingoData = new LingoData();
  private language = 'en';

  private recognition: SpeechRecognition;
  private finalTranscript = '';
  private currentInput = '';

  private modules: Module[];
  private groups: Group[];

  private adapter: HomegenieAdapter;

  constructor(private http: HttpClient, private yot: YotService) {
    http.get(`assets/lingo/${this.language}.lingo.json`).subscribe({
      next: (lingo) => this.lingoData = lingo as LingoData,
      error: (err) => {
        // TODO: ...
        console.log(err);
      }
    });
    //
    if (SpeechRecognition) {
      const recognition = this.recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.onstart = () => {
        this.listenStarted.next();
      }
      recognition.onresult = (event: SpeechRecognitionEvent) => {
        let interim_transcript = '';
        if (typeof (event.results) == 'undefined') {
//          recognition.onend = null;
          recognition.stop();
          return;
        }
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            this.finalTranscript += event.results[i][0].transcript;
          } else {
            interim_transcript += event.results[i][0].transcript;
          }
        }
      }
      recognition.onerror = (err) => {
        this.listenError.next(err.error);
      }
      recognition.onend = () => {
        this.listenEnded.next(this.finalTranscript);
        this.finalTranscript = '';
      }
    }
  }

  setLanguage(lang) {
    this.http.get(`assets/lingo/${lang}.lingo.json`).subscribe({
      next: (lingo) => {
        this.lingoData = lingo as LingoData;
        this.language = lang;
        this.recognition.lang = lang;
      },
      error: (err) => {
        // try loading default
      }
    });
    this.adapter = (this.yot.getDefaultAdapter() as HomegenieAdapter);
    if (this.adapter) {
      this.groups = this.adapter.groups;
      this.modules = this.adapter.modules;
    }
  }
  getLanguage() {
    return this.language;
  }

  setData(modules: Module[], groups: Group[]) {
    this.modules = modules;
    this.groups = groups;
  }

  listen() {
    if (this.recognition) {
      this.recognition.start();
    } else {
      this.listenError.next('This browser does not support SpeechRecognition API');
    }
  }

  stop() {
    if (this.recognition) {
      this.recognition.abort();
    } else {
      this.listenError.next('This browser does not support SpeechRecognition API');
    }
  }

  parse(inputMessage: string, callback: InterpreterResultCallback): number {
    this.currentInput = inputMessage;
    let totalInterpretedCount = 0;
    let commandsFoundInPass = 0;
    do {
      commandsFoundInPass = this.interpretInput(callback);
      if (commandsFoundInPass > 0) {
        totalInterpretedCount += commandsFoundInPass;
      }
    } while (commandsFoundInPass > 0 && this.currentInput.trim().length > 2);
    return totalInterpretedCount;
  }

  private interpretInput(callback: InterpreterResultCallback) {
    let interpretedCount = 0;

    const commandObject = this.searchCommandMatchObject();
    if (!commandObject) {
      return 0;
    }
    const command = commandObject.Command;

    let targetModules: Module[] = [];
    let groupName = '';

    const specificModule = this.searchSpecificSubjectMatch();

    if (specificModule) {
      targetModules.push(specificModule);
    } else {
      const type = this.searchTypeMatch(false);
      if (type) {
        const types = type.split(',');
        groupName = this.searchGroupMatch(-1);
        const groupModules = this.getGroupModules(groupName);
        for (const module of groupModules) {
          if (types.some(t => module.DeviceType?.toLowerCase() === t.toLowerCase())) {
            targetModules.push(module);
          }
        }
      }
    }

    if (targetModules.length === 0) {
      return 0;
    }

    let value: number | string | object | undefined = undefined;
    if (commandObject.ExpectsValue != null && commandObject.ExpectsValue.length > 0) {
      value = this.searchArgumentValueMatch(commandObject);
    }

    for (const module of targetModules) {
      const yotModule = this.adapter.getModuleByRef(module as ModuleReference);
      callback.onModuleCommand(yotModule, command, groupName, value);
      interpretedCount++;
    }

    return interpretedCount > 0 ? 1 : 0;
  }

  private searchSpecificSubjectMatch(): Module | null {
    let result: Module | null = null;
    let currentMatch = new LingoMatch('', -1);

    const allModules = this.modules || [];
    for (const module of allModules) {
      let res = this.findMatchingInput(module.Name);
      if (res.StartIndex === -1 && module.Address) {
        res = this.findMatchingInput(module.Address);
      }
      if (res.StartIndex !== -1) {
        if (
          result === null ||
            res.Words.length > currentMatch.Words.length ||
            (res.Words.length === currentMatch.Words.length && res.StartIndex < currentMatch.StartIndex)
        ) {
          result = module;
          currentMatch = res;
        }
      }
    }

    if (result) {
      this.removeInputMatch(currentMatch);
    }
    return result;
  }

  private addType(type: LingoType): void {
    this.lingoData.Types.push(type);
  }

  private addCommand(command: LingoCommand): void {
    this.lingoData.Commands.push(command);
  }

  private searchTypeMatch(keepSentence: boolean): string {
    let result = '';
    let curmatch = new LingoMatch('', -1);
    for (let t of this.getTypes()) {
      for (let c = 0; c < t.Aliases.length; c++) {
        const res = this.findMatchingInput(t.Aliases[c]);
        if (res.StartIndex != -1 && (res.StartIndex < curmatch.StartIndex || curmatch.StartIndex == -1)) {
          result = t.Type;
          curmatch = res;
          //break;
        }
      }
    }
    if (!keepSentence && curmatch.StartIndex != -1) {
      this.removeInputMatch(curmatch);
    }
    return result;

  }

  private searchCommandMatchObject(): LingoCommand | null {
    let bestMatch: LingoMatch | null = null;
    let commandObject: LingoCommand | null = null;

    for (const cmd of this.getCommands()) {
      for (const alias of cmd.Aliases) {
        const match = this.findMatchingInput(alias);
        if (match.StartIndex !== -1) {
          if (!bestMatch || match.StartIndex < bestMatch.StartIndex) {
            bestMatch = match;
            commandObject = cmd;
          }
        }
      }
    }

    if (bestMatch && commandObject) {
      this.removeInputMatch(bestMatch);
      return commandObject;
    }
    return null;
  }

  private searchGroupMatch(limitIndex: number): string {
    if (this.groups == null || this.groups.length === 0)
      return '';
    let result = '';
    let curmatch = new LingoMatch('', -1);
    for (let g of this.groups) {
      const res = this.findMatchingInput(g.Name);
      if (res.StartIndex != -1 && (res.StartIndex < limitIndex || limitIndex == -1) && (res.StartIndex < curmatch.StartIndex || curmatch.StartIndex == -1)) {
        result = g.Name;
        curmatch = res;
        //break;
      }
    }
    if (curmatch.StartIndex != -1) {
      this.removeInputMatch(curmatch);
    }
    return result;

  }

  private searchArgumentValueMatch(commandObject: LingoCommand): string {
    let value: string = undefined;
    switch (commandObject.ExpectsValue) {
      case "number":
        value = this.SearchNumberValueMatch();
        break;
      case "color":
        // TODO: not implemented yet
        // value = this.SearchColorValueMatch();
        break;
    }
    return value;
  }

  private SearchNumberValueMatch(): string | undefined {
    const input = this.currentInput;
    let value: number | undefined = undefined;
    let matchFound: RegExpMatchArray | null = null;

    // Pattern 1: Search a number followed by '%' (ex. "75%", "100 %")
    const percentageRegex = /(\d+)\s*%/;
    matchFound = input.match(percentageRegex);

    if (matchFound) {
      value = parseInt(matchFound[1], 10);
    } else {
      // Pattern 2: Search just a number
      const numberRegex = /(\d+)/;
      matchFound = input.match(numberRegex);
      if (matchFound) {
        value = parseInt(matchFound[0], 10);
      }
    }

    if (value !== undefined) {
      if (value < 0) value = 0;
      if (value > 100) value = 100;
    }

    return value?.toString();
  }

  private removeInputMatch(wordsmatch: LingoMatch) {
    if (wordsmatch.StartIndex > -1 && wordsmatch.Words.length > 0) {
      const originalString = this.currentInput;
      const index = originalString.toLowerCase().indexOf(wordsmatch.Words.toLowerCase(), wordsmatch.StartIndex -1);
      if (index > -1) {
        this.currentInput = originalString.substring(0, index) + originalString.substring(index + wordsmatch.Words.length);
      }
    }
  }

  private findMatchingInput(words: string): LingoMatch {
    const wordsmatch = new LingoMatch(words, -1);
    if (words != null && words.trim() !== '') {
      const apostropheRegex = /['´`]/g;
      const normalizedInput = ` ${this.currentInput.toLowerCase().replace(apostropheRegex, ' ')} `;
      const normalizedWords = ` ${words.toLowerCase().replace(apostropheRegex, ' ')} `;
      const idx = normalizedInput.indexOf(normalizedWords);
      if (idx >= 0) {
        wordsmatch.StartIndex = idx;
        return wordsmatch;
      }
    }
    return wordsmatch;
  }

  private getCommands() {
    return this.lingoData.Commands;
  }

  private getTypes() {
    return this.lingoData.Types;
  }

  private getGroupModules(group: string) {
    let modules = new Array<Module>();
    if (!group == null || group === '') {
      if (this.modules != null)
        modules = this.modules;
    } else
      for (let g of this.groups) {
        if (g.Name.toLowerCase() === group.toLowerCase()) {
          modules = g.Modules as any;
          break;
        }
      }
    return modules;
  }


}

export class LingoCommand {
  public Command: string = '';
  public Aliases: string[] = [];
  public ExpectsValue: string = "";
}

export class LingoData {
  public Commands = new Array<LingoCommand>();
  public Types = new Array<LingoType>();
}

export class LingoType {
  public Type = '';
  public Aliases = new Array<string>();
}

export class LingoMatch {
  public Words: string;
  public StartIndex: number;

  constructor(words: string, idx: number) {
    this.Words = words;
    this.StartIndex = idx;
  }
}

export interface InterpreterResultCallback {
  onModuleCommand(module: YotModule, command: string, group: string, value?: any);
}
