import {Component, Input, OnDestroy, OnInit} from '@angular/core';
import {HomegenieAdapter} from "../homegenie-adapter";
import {SchedulerItem} from "../homegenie-api";
import {CodeModel} from "@ngstack/code-editor";
import {Color} from "@iplab/ngx-color-picker";
import {SystemApi} from "../../../api/system-api";
import {YotService} from "../../../services/yot/yot.service";

export class ScriptTemplate {
  enabled: boolean;
  id?: string; // TODO: deprecate
  script?: string; // TODO: deprecate
  config?: Map<string, ScriptTemplateConfig>; // TODO: deprecate
  commands: TemplateCommand[] = [];
}
export class ScriptTemplateConfig {
  type?: 'slider' | 'color' | 'select' | 'text' | 'textarea' | 'program-select';
  options?: Array<{id: string, value: any}>;
  value?: any;
  transform?: any;
}

export class ScheduleAction {
  forEachOccurrence = new ScriptTemplate();
  forStartOccurrence = new ScriptTemplate();
  forEndOccurrence = new ScriptTemplate();
  actionType: 'template' | 'script' | 'none' = 'template';
}
export class TemplateCommand {
  id: string;
  config: Map<string, ScriptTemplateConfig>;
  useEventValue: boolean;
}

export class ScriptTemplateOption {
  public index: number;
  public id: string;
  public value: string;
  public label: string;
  public transform: string;
  public toString(): string {
    return this.label;
  }
}

@Component({
  selector: 'app-scheduler-wizard-script',
  templateUrl: './scheduler-wizard-script.component.html',
  styleUrls: ['./scheduler-wizard-script.component.scss']
})
export class SchedulerWizardScriptComponent implements OnInit, OnDestroy {
  @Input()
  adapter: HomegenieAdapter;
  @Input()
  schedulerItem: SchedulerItem;


  theme = 'vs-dark'; // 'hc-black';
  codeModel: CodeModel = {
    language: 'javascript',
    uri: 'schedule-script-editor',
    value: ``,
    dependencies: [ ]
  };
  extraLib: monaco.IDisposable;
  options: monaco.editor.IStandaloneEditorConstructionOptions = {
    lineNumbers: 'on',
    contextmenu: true,
    fixedOverflowWidgets: true,
    cursorWidth: 2,
    cursorBlinking: 'expand',
    cursorSmoothCaretAnimation: 'on',
    cursorStyle: 'line',
    automaticLayout: true,
    readOnly: true,
    minimap: {
      enabled: false,
    },
    tabSize: 2
  };


  scheduleAction = new ScheduleAction();
  scheduleScript = {
    scriptForEach: '',
    scriptForStart: '',
    scriptForEnd: ''
  }
  codeTemplates = new Array<ScriptTemplate>();

  private readonly AutoGeneratedCode = `// auto-generated code from template
if (!$$.onPrevious() && $$.onNext()) {
  // this is start of a time slot

  //{start}//
} else if ($$.onPrevious() && !$$.onNext()) {
  // this is end of a time slot

  //{end}//
} else {
  // this is for any other single occurrence
  // and every minute within a time slot

  //{each}//
}
`;

  constructor(private yot: YotService) {
    this.theme = this.yot.preferences.ui.theme === 'light' ? 'vs' : 'vs-dark';
  }

  ngOnInit(): void {
    const action = JSON.parse(this.schedulerItem.Data).action;
    this.scheduleAction.actionType = action && action.type ? action.type : 'script';
    if (monaco) {
      this.theme = this.adapter.yot.preferences.ui.theme === 'light' ? 'vs' : 'vs-dark';
      // load API defs
      this.adapter.yot.http.get('assets/editor/homegenie-js-api.js', {responseType: 'text'})
        .subscribe((res) => {
          this.extraLib = monaco.typescript.javascriptDefaults.addExtraLib(res);
        });
      // load script code in editor
      this.codeModel.value = this.schedulerItem.Script;
      // set action type to 'none' if no script is loaded
      if (this.codeModel.value.length === 0) {
        this.scheduleAction.actionType = 'none';
      }
      // populate templates list
      this.adapter.system(SystemApi.Automation.Scheduling.Templates)
        .subscribe((templates: any) => {
          this.codeTemplates = templates;


          // apply compatibility patch for older version
          const patchActionTemplate = (t) => {
            if (t && t.script && t.script.endsWith('.js')) {
              t.id = t.script.replace('.js', '').replace('.', '_').replace('-', '_');
            } //else if (t && t.id == null) {
//              delete t.id;
//              delete t.config;
//            }
            delete t.script;
          };
          if (action && action.template) {
            patchActionTemplate(action.template.forEach);
            patchActionTemplate(action.template.forStart);
            patchActionTemplate(action.template.forEnd);
          }


          if (action && action.template) {
            this.scheduleAction.forEachOccurrence = action.template.forEach;
            this.scheduleAction.forStartOccurrence = action.template.forStart;
            this.scheduleAction.forEndOccurrence = action.template.forEnd;
          }
          this.loadTemplatesData();
        });
    }
  }
  ngOnDestroy() {
    if (this.extraLib) {
      this.extraLib.dispose();
    }
  }

  applyChanges(): void {
    this.updateEditorText();
    this.schedulerItem.Data.action = {
      type: this.scheduleAction.actionType,
      template: {
        forEach: this.getActionConfig(this.scheduleAction.forEachOccurrence),
        forStart: this.getActionConfig(this.scheduleAction.forStartOccurrence),
        forEnd: this.getActionConfig(this.scheduleAction.forEndOccurrence)
      }
    };
    this.schedulerItem.Script = this.codeModel.value;
  }

  private getActionConfig(ac: any): ScriptTemplateConfig {
    ac.config && Object.keys(ac.config).forEach((key) => {
      const c: ScriptTemplateConfig = ac.config[key];
      ac.config[key] = {
        type: c.type,
        value: c.value,
        transform: c.transform
      } as ScriptTemplateConfig;
    });
    return ac || {};
  }

  onCodeChanged(value) {
    if (this.scheduleAction.actionType === "script") {
      this.schedulerItem.Script = value;
    }
  }

  onActionTypeChange(e) {
    this.loadTemplatesData();
  }

  onTemplateOptionChanged() {
    this.loadTemplatesData();
  }

  updateEditorText() {
    if (this.scheduleAction.actionType === "script") {
      this.codeModel.value = this.schedulerItem.Script;
    } else if (this.scheduleAction.actionType === "template") {
      let code = this.AutoGeneratedCode;
      if (this.scheduleAction.forEachOccurrence.enabled) {
        code = code.replace('//{each}//', () => this.scheduleScript.scriptForEach);
      }
      if (this.scheduleAction.forStartOccurrence.enabled) {
        code = code.replace('//{start}//', () => this.scheduleScript.scriptForStart);
      }
      if (this.scheduleAction.forEndOccurrence.enabled) {
        code = code.replace('//{end}//', () => this.scheduleScript.scriptForEnd);
      }
      if (code !== this.AutoGeneratedCode) {
        this.schedulerItem.Script = this.codeModel.value = code;
      }
    }
    this.codeModel = {...this.codeModel};
  }

  private loadTemplatesData(): void {
    const render = (action) => {
      const template = this.codeTemplates.find((t) => t.id === action.id);
      action.script = template?.script;
      return action;
    };

    if (this.scheduleAction.forEachOccurrence) {
      this.scheduleScript.scriptForEach = '';
      this.scheduleAction.forEachOccurrence.commands?.map((command) => {
        const {id, script, config} = render(command);
        this.scheduleScript.scriptForEach += this.renderScriptTemplate(id, script, config) + '  ';
      });
    }
    if (this.scheduleAction.forStartOccurrence) {
      this.scheduleScript.scriptForStart = '';
      this.scheduleAction.forStartOccurrence.commands?.map((command) => {
        const {id, script, config} = render(command);
        this.scheduleScript.scriptForStart += this.renderScriptTemplate(id, script, config) + '  ';
      });
    }
    if (this.scheduleAction.forEndOccurrence) {
      this.scheduleScript.scriptForEnd = '';
      this.scheduleAction.forEndOccurrence.commands?.map((command) => {
        const {id, script, config} = render(command);
        this.scheduleScript.scriptForEnd += this.renderScriptTemplate(id, script, config) + '  ';
      });
    }

    // Update auto-generated script text
    this.updateEditorText();
  }

  private renderScriptTemplate(templateId: string, codeTemplate: string, cfg: Map<unknown, ScriptTemplateConfig>): string {
    const templateConfig = this.codeTemplates.find((t) => t.id === templateId)?.config;
    if (codeTemplate && templateConfig) {
      // replace template vars with current value
      Object.keys(cfg).forEach((k) => {
        let v = (cfg[k] !== Object(cfg[k])) ? cfg[k] : cfg[k].value;
        switch (templateConfig[k].transform) {
          case 'rgb:hsb':
            const color = Color.from(v);
            const hsv = color.getHsva();
            const h = hsv.hue / 360.0;
            const s = hsv.saturation / 100.0;
            const b = hsv.value / 100.0;
            const transition = 0.4; // 400ms color transition duration
            v = `${h},${s},${b},${transition}`;
            break;
          case 'multiline:array':
            const lines: string[] = v.split('\n');
            const processedLines = lines
              .map(line => line.trim())
              .filter(line => line.length > 0)
              .map(line => line.replace(/'/g, "\\'"))
              .map(escapedLine => `'${escapedLine}'`);
            const content = processedLines.join(',\n    ');
            v = `[\n    ${content}\n  ]`;
            break;
          case 'time:seconds':
            // no-transformation needed
          default:
            if (v && v.replace) v = v.replace('"', '\\"').replace("'", "\\'");
        }
        codeTemplate = codeTemplate.replace(`$${k}$`, v);
      });
    }
    return codeTemplate;
  }

}
