import {Component, ElementRef, OnDestroy, OnInit, ViewChild} from '@angular/core';
import {YotService} from "../../services/yot/yot.service";
import {SystemApi} from "../../api/system-api";
import {Schedule, ScheduleOccurrence} from "../../services/yot/automation";
import {Adapter} from "../../adapters/adapter";
import {
  ActionConfirmDialogComponent,
  ActionConfirmDialogConfig
} from "../../components/dialogs/action-confirm-dialog/action-confirm-dialog.component";
import {HomegenieAdapter} from "../../adapters/home-genie/homegenie-adapter";
import * as moment from "moment-timezone";
import {NavigationService} from "../../services/navigation.service";

@Component({
  selector: 'app-scheduler-page',
  templateUrl: './scheduler-page.component.html',
  styleUrls: ['./scheduler-page.component.scss']
})
export class SchedulerPageComponent implements OnInit, OnDestroy {
  @ViewChild('bottomBar', {static: true})
  bottomBarComponent: ElementRef;

  selectedAdapter: Adapter;

  scheduleList = {
    today: [] as Schedule[],
    others: [] as Schedule[],
    disabled: [] as Schedule[]
  };
  scheduleOccurrences = new Map<string, ScheduleOccurrence>();

  previewDate = new Date();
  solarTimes = {
    sunset: 0,
    noon: 0,
    sunrise: 0
  }

  get serverTime(): string {
    //(this.selectedAdapter as HomegenieAdapter).systemInfo.TimeZoneId
    const timeZoneId = this.serverTimeZone;
    return timeZoneId ? moment().tz(timeZoneId).format('dddd, D MMMM HH:mm') : moment().format('dddd, MMMM Do YYYY, h:mm a');
  }
  get serverTimeZone(): string {
    return (this.selectedAdapter as HomegenieAdapter).systemInfo?.TimeZoneId;
  }

  get isLoading(): boolean {
    return this.navigationService.isLoading;
  }

  constructor(public yot: YotService, protected navigationService: NavigationService) {
    this.selectedAdapter = this.yot.getDefaultAdapter();
    this.refreshScheduleList();
  }

  ngOnInit(): void {
    this.yot.layoutService.contextualHelpLink = 'https://homegenie.it/server/automation/scheduler/';
    this.navigationService.toolbarTitle.emit('scheduler');
  }
  ngOnDestroy(): void {
    this.yot.layoutService.contextualHelpLink = '';
  }

  onPreviewDateChange(e: any) {
    this.previewDate = e.value;
    this.refreshScheduleList();
  }

  onScheduleAddClick(event: MouseEvent) {
    this.selectedAdapter.editSchedule(null, this.scheduleList).subscribe((schedulerItem) => {
      if (schedulerItem) {
        this.refreshScheduleList();
      }
    });
  }

  onItemEditClick(s: Schedule) {
    this.selectedAdapter.editSchedule(s.name).subscribe((schedulerItem) => {
      if (schedulerItem) {
        this.refreshScheduleList();
      }
    });
  }
  onItemEnableClick(s: Schedule) {
    this.selectedAdapter.system(SystemApi.Automation.Scheduling.Enable, { id: s.id })
      .subscribe((res) => {
        this.refreshScheduleList();
      });
  }
  onItemDisableClick(s: Schedule) {
    this.selectedAdapter.system(SystemApi.Automation.Scheduling.Disable, { id: s.id })
      .subscribe((res) => {
        this.refreshScheduleList();
      });
  }
  onItemDeleteClick(s: Schedule) {
    this.yot.translate.get(['confirm_delete', 'confirm_delete_prompt'])
      .subscribe((res) => {
        const dialogRef = this.yot.dialog.open(ActionConfirmDialogComponent, {
          width: '320px',
          disableClose: false,
          data: {
            title: res['confirm_delete'],
            message: res['confirm_delete_prompt']
          } as ActionConfirmDialogConfig
        });
        dialogRef.afterClosed().subscribe((confirm) => {
          if (confirm) {
            this.selectedAdapter.system(SystemApi.Automation.Scheduling.Delete, { id: s.id })
              .subscribe((res) => {
                this.refreshScheduleList();
              });
          }
        });
      });
  }

  private refreshScheduleList(day?: Date) {
    if (!this.selectedAdapter) {
      return;
    }
    this.scheduleList.today = [];
    this.scheduleList.others = [];
    this.scheduleList.disabled = [];
    this.scheduleOccurrences.clear();

    // get scheduling list
    this.navigationService.setLoading(3);
    this.selectedAdapter.system(SystemApi.Automation.Scheduling.List).subscribe((list: Schedule[]) => {
      // build active schedules list for the current module
      const selectedDay = new Date(day ? day : this.previewDate);
      selectedDay.setHours(0, 0, 0, 0);
      this.navigationService.isLoading = false;
      this.selectedAdapter.system(SystemApi.Automation.Scheduling.ListOccurrences, {
        hourSpan: 24, startTimestamp: selectedDay.getTime()
      }).subscribe((occurrences: ScheduleOccurrence[]) => {
        occurrences.forEach((o) => this.scheduleOccurrences.set(o.id, o));
        this.scheduleList.today = list.filter((s) => {
          const scheduleOccurrence = this.scheduleOccurrences.get(s.id);
          if (scheduleOccurrence && scheduleOccurrence.occurs.length > 0) {
            return s;
          } else if (s.enabled) {
            this.scheduleList.others.push(s);
          } else {
            this.scheduleList.disabled.push(s);
          }
        });
        this.navigationService.isLoading = false;
        // get solar times
        this.selectedAdapter.system(SystemApi.Automation.Scheduling.SolarTimes, {
          hourSpan: 24, startTimestamp: selectedDay.getTime()
        }).subscribe((solarTimes: ScheduleOccurrence) => {
          if (solarTimes && solarTimes.occurs.length === 3) {
            this.solarTimes = {
              sunrise: solarTimes.occurs[0].from,
              noon: solarTimes.occurs[1].from,
              sunset: solarTimes.occurs[2].from
            }
          }
          this.navigationService.isLoading = false;
        }, (err) => {
          this.notifyError(err);
        });
      }, (err) => {
        this.notifyError(err);
      });
    }, (err) => {
      this.notifyError(err);
    });
  }

  private notifyError(err) {
    this.yot.translate.get('error_occurred').subscribe((title) => {
      this.yot.notify(title, err.message);
    });
    this.navigationService.setLoading(0);
  }
}
