import {Component, ElementRef, EventEmitter, OnDestroy, OnInit, Output, ViewChild} from '@angular/core';
import {VoiceControlService, InterpreterResultCallback} from "../../services/voice-control.service";
import {Module, ModuleType} from "../../services/yot/module";
import {Subscription} from "rxjs";
import {SystemApi} from "../../api/system-api";
import {YotService} from "../../services/yot/yot.service";
import {HomegenieAdapter, Program} from "../../adapters/home-genie/homegenie-adapter";
import {HomegenieApi} from "../../adapters/home-genie/homegenie-api";

export enum VoiceControlStatus {
  Idle,
  Listening,
  Error,
  CommandNotUnderstood
}
export const INTERFACE_INTENT_HANDLER = '@AI:IntentHandler';

@Component({
  selector: 'app-voice-control',
  templateUrl: './voice-control.component.html',
  styleUrls: ['./voice-control.component.scss']
})
export class VoiceControlComponent implements OnInit, OnDestroy {
  @ViewChild('speechInput', {static: true})
  speechInput: ElementRef<HTMLInputElement>;
  @Output()
  closeRequested = new EventEmitter<void>();

  status: VoiceControlStatus = VoiceControlStatus.Idle;
  VoiceControlStatus = VoiceControlStatus;
  errorMessage = '';
  isLoading = false;

  intentHandlers: any[] = [];
  selectedHandler: string = 'builtin';

  get language() { return this.voiceControlService.getLanguage(); }

  private listenSubscription: Subscription;
  private errorSubscription: Subscription;
  private endedSubscription: Subscription;

  private inputHandler = (_t: VoiceControlComponent): InterpreterResultCallback => ({
    onModuleCommand(module: Module, command: string, group: string, options?: any) {
      if (options == null) options = '';
// TODO: implement also "group" parameter (?)
      //console.log(module);
      const adapter = (module.getAdapter() as HomegenieAdapter);
// TODO: this code is repeat, add an utility function for it
      let isProgramMacro = false;
      if (module.type === ModuleType.Program) {
        const programModule = adapter.getModule(module.id);
        if (!programModule) return;
        const programWidget = adapter.getModuleWidget(programModule);
        if (programWidget === 'homegenie/generic/program') {
          isProgramMacro = true;
        }
      }
      const resultCallback = {
        next: (result) => {
          _t.isLoading = false;
        },
        error: (err) => {
          _t.isLoading = false;
        }
      };
      if (isProgramMacro) {
        // Program API command
        const programAddress = module.id.substring(module.id.lastIndexOf(HomegenieAdapter.yotAddressSeparator) + 1);
        adapter.apiCall(HomegenieApi.Automation.Command(command, programAddress))
          .subscribe(resultCallback);
      } else {
        // Module API command
        module
          .control(command, options)
          .subscribe(resultCallback);
      }
    }
  });

  constructor(private voiceControlService: VoiceControlService, private yot: YotService) {
    this.listenSubscription = voiceControlService
      .listenStarted.subscribe(() => {
        this.errorMessage = '';
        this.status = VoiceControlStatus.Listening;
      });
    this.errorSubscription = voiceControlService
      .listenError.subscribe((err) => {
        this.status = VoiceControlStatus.Error;
        this.errorMessage = `ERROR: ${err}`;
      });
    this.endedSubscription = voiceControlService
      .listenEnded.subscribe((sentence) => {
        this.speechInput.nativeElement.value = sentence;
        const interpretedCount = this.voiceControlService.parse(sentence, this.inputHandler(this));
        if (sentence && interpretedCount === 0) {
          this.errorMessage = 'command_not_understood';
        }
        this.status = VoiceControlStatus.Idle;
      });
  }

  ngOnInit(): void {
    this.getIntentHandlers();
  }
  ngOnDestroy() {
    this.voiceControlService.stop();
    this.listenSubscription.unsubscribe();
    this.errorSubscription.unsubscribe();
    this.endedSubscription.unsubscribe();
  }

  interpretInput(input: string) {
    this.errorMessage = '';
    this.isLoading = true;

    if (this.selectedHandler === 'builtin') {
      const interpretedCount = this.voiceControlService.parse(input, this.inputHandler(this));
      if (interpretedCount === 0) {
        this.errorMessage = 'command_not_understood';
        this.isLoading = false;
      }
    } else {
      const apiUrl = this.selectedHandler;
      (this.yot.getDefaultAdapter() as HomegenieAdapter)
        .apiCall(`${apiUrl}/Process/${input}`)
        .subscribe({
          next: (result) => {
            this.yot.notify('Response', result.response.answer, {
              duration: 10000
            });
            this.isLoading = false;
          },
          error: (err) => {
            this.errorMessage = `ERROR: ${err}`;
            this.isLoading = false;
          }
        });
    }
  }

  close() {
    this.closeRequested.next();
  }

  onListenButtonClick() {
    this.voiceControlService.listen();
  }

  getIntentHandlers() {
    const adapter = this.yot.getDefaultAdapter();
    adapter
      .system(SystemApi.Automation.Programs.Implements, INTERFACE_INTENT_HANDLER)
      .subscribe({
        next: (providers: any[]) => {

          // load translations for name
          adapter.system(SystemApi.Automation.Programs.List)
            .subscribe((programs: Program[]) => {

              providers.forEach(provider => {
                const p = programs.find(p => p.Address === provider.providerId);
                // translate Name and Description
                const titleKey = `${adapter.translationPrefix}.$options.${p.Address}.Title`;
                this.yot.translate.get(titleKey).subscribe((tr) => {
                  if (tr !== titleKey) {
                    //p.Name = tr;
                    provider.name = tr;
                  }
                });
                /*
                const descriptionKey = `${adapter.translationPrefix}.$options.${p.Address}.Description`;
                this.yot.translate.get(descriptionKey).subscribe((tr) => {
                  if (tr !== descriptionKey) {
                    p.Description = tr;
                  }
                });
                provider.program = p;
                */

              });

              this.intentHandlers = providers;
            });

          if (this.intentHandlers && this.intentHandlers.length > 0) {
            this.selectedHandler = this.intentHandlers[0].apiUrl;
          } else {
            this.selectedHandler = 'builtin';
          }
        }
      });
  }
  getSelectedHandlerName(): string {
    if (this.selectedHandler === 'builtin') {
      return 'builtin_simple_parser';
    }
    const handler = this.intentHandlers.find(h => h.apiUrl === this.selectedHandler);
    return handler ? handler.name : '';
  }
}
