import {Adapter} from '../../adapters/adapter';
import {Subject} from 'rxjs';
import {CMD} from './yot.service';
import {EventEmitter} from "@angular/core";

export class Module {
  private dataStore?: any = {};
  private _adapter?: Adapter;
  private lastIsOnlineCheckTs = 0;
  private lastOnlineCheckValue = true;
  adapterId: string;
  id: string; // id ::= '<domain>:<address>';
  type: string;
  name: string;
  description: string;
  fields: Array<ModuleField>;
  error: EventEmitter<any>;
  events: EventEmitter<ModuleField>;
  constructor(moduleData: Module | { id: string, type: string, name: string, description: string, fields?: Array<ModuleField>, adapterId?: string }) {
    this.adapterId = moduleData.adapterId;
    this.id = moduleData.id;
    this.type = moduleData.type;
    this.name = moduleData.name;
    this.description = moduleData.description;
    this.fields = new Array<ModuleField>();
    if (moduleData.fields) {
      moduleData.fields.map((f) => {
        const mf = new ModuleField(f.key, f.value, f.timestamp);
        this.fields.push(mf);
      });
    }
    this.error = new EventEmitter<any>();
    this.events = new EventEmitter<any>();
  }

  toJSON(): any {
    return {
      adapterId: this.adapterId,
      id: this.id,
      type: this.type,
      name: this.name,
      description: this.description,
      fields: this.fields,
    }
  }

  /**
   * Gets the module field matching the given key or set it if the 'value' parameter was passed.
   * @param key The field key identifier
   * @param value The value to set
   * @param timestamp The optional unix timestamp (UTC)
   */
  field?(key: string, value?: any, timestamp?: any): any | ModuleField | this {
    if (timestamp == null || timestamp < 1591898400000) { timestamp = Math.round(new Date().getTime()); }
    const field = this.fields.find((f) => key && f.key && f.key.toLowerCase() === key.toLowerCase());
    if (field && typeof value !== 'undefined') {
      if (this.fields == null) { this.fields = []; }
      if (field.timestamp === timestamp && field.value === value) {
        return this;
      }
      field.value = value;
      field.timestamp = timestamp;
      //
      this.events.emit(field);
      if (this.getAdapter()) {
        this.getAdapter().yot.onModuleEvent.next({ module: this, event: field});
      }
      return this;
    } else if (field == null && typeof value !== 'undefined') {
      const mf = new ModuleField(key, value, timestamp);
      this.fields.push(mf);
      //
      this.events.emit(mf);
      if (this.getAdapter()) {
        this.getAdapter().yot.onModuleEvent.next({ module: this, event: mf});
      }
      return this;
    }
    return field;
  }
  control(command: CMD, options?: any): Subject<any> {
    return this._adapter?.control(this, command, options);
  }
  /**
   * Gets the module data matching the given key or set it if the 'data' parameter was passed.
   * @param key The field key identifier
   * @param data The data to set
   */
  data?(key: string, data?: any): any {
    if (data) {
      this.dataStore[key] = data;
      return this;
    }
    return this.dataStore[key];
  }

  getAdapter?(): Adapter {
    return this._adapter;
  }
  getWidgetData() {
    return this._adapter && this._adapter.getWidgetData(this);
  }
  getIcon() {
    return this._adapter && this._adapter.getModuleIcon(this);
  }
  get isOnline(): boolean {
    const now = Date.now();
    if (now - this.lastIsOnlineCheckTs < 1000) {
      return this.lastOnlineCheckValue;
    }
    this.lastIsOnlineCheckTs = now;
    return this.lastOnlineCheckValue = (this._adapter && this._adapter.isModuleOnline(this));
  }

  set adapter(adapter: Adapter) {
    this._adapter = adapter;
    if (adapter) this.adapterId = adapter.id;
  }

  getStatsFields() {
    return this.fields.filter((f) =>
      f.key && (f.key.toLowerCase().startsWith('meter.')
      || f.key.toLowerCase().startsWith('sensor.')
      || f.key.toLowerCase().startsWith('system.')
      || f.key.toLowerCase().startsWith('statistics.')
      || f.key.toLowerCase().startsWith('status.')
      || f.key.toLowerCase().startsWith('energymonitor.'))
      && f.value && !isNaN(f.value.toString().replace(',', '.'))
    ).sort((a, b) =>
      new Date(a.timestamp).getTime() < new Date(b.timestamp).getTime() ? 1
        : new Date(a.timestamp).getTime() > new Date(b.timestamp).getTime() ? -1 : 0);
  }
}

export class ModuleType {
  static Dimmer = 'dimmer';
  static Color = 'color';
  static DoorLock = 'doorlock';
  static DoorWindow = 'doorwindow';
  static Generic = 'generic';
  static Light = 'light';
  static MediaReceiver = 'mediareceiver';
  static MediaTransmitter = 'mediatransmitter';
  static Program = 'program';
  static Sensor = 'sensor';
  static Switch = 'switch';
  static Shutter = 'shutter';
  static Motor = 'motor';
  static Thermostat = 'thermostat';
  static VideoInput = 'videoinput';
}

export class ModuleField {
  private readonly fieldEvent?: Subject<ModuleField>;

  key: string;
  timestamp = 0;

  private _value?: any;
  get value(): any {
    return this._value;
  }
  set value(v: any) {
    this._value = v;
    this.fieldEvent.next(this);
  }

  get decimalValue(): number {
    const rawValue = this._value;
    return (typeof rawValue === 'string')
      ? parseFloat(rawValue.replace(',', '.'))
      : rawValue;
  }

  get idle(): number {
    // idle time in days
    return (new Date().getTime() - new Date(this.timestamp).getTime()) / 86400000;
  }

  constructor(key?: string, value?: any, timestamp?: number) {
    this.fieldEvent = new Subject<ModuleField>();
    this.key = key;
    this.value = value;
    this.timestamp = timestamp;
  }

  toJSON(): any {
    return {
      key: this.key,
      timestamp: this.timestamp,
      value: this.value
    }
  }

  events?(): Subject<ModuleField> {
    return this.fieldEvent;
  };
}

export class ModuleReference {
  moduleId: string;
  adapterId: string;
  constructor(m: Module) {
    this.moduleId = m.id;
    this.adapterId = m.adapterId;
  }
}
