import {Component, Inject, ViewChild} from '@angular/core';
import {Module, ModuleType} from "../../../services/yot/module";
import {YotService} from "../../../services/yot/yot.service";
import {MAT_DIALOG_DATA, MatDialogRef} from "@angular/material/dialog";
import {DynamicOptionsBase} from "../../forms/dynamic-options-base.component";
import {ModuleOptions} from "../../../services/yot/module-options";

@Component({
  selector: 'app-module-settings-dialog',
  templateUrl: './module-settings-dialog.component.html',
  styleUrls: ['./module-settings-dialog.component.scss']
})
export class ModuleSettingsDialogComponent {
  @ViewChild('optionsHandler', {static: false})
  optionsHandler: DynamicOptionsBase;

  module: Module;
  options: ModuleOptions[];

  isFullScreen: boolean = false;
  private readonly FULLSCREEN_CLASS = 'fullscreen-dialog-panel';

  get moduleTypes(): string[] {
    return Object.keys(ModuleType);
  }

  constructor(
    public yot: YotService,
    public dialogRef: MatDialogRef<ModuleSettingsDialogComponent>,
    @Inject(MAT_DIALOG_DATA) data: {module: Module, options?: ModuleOptions[]}
  ) {
    this.module = data.module;
    this.options = data.options;
    if (this.module == null) {
      this.module = new Module({
        id: 'module-settings-dialog.component',
        type: 'config',
        name: 'Module Settings',
        description: 'Module Settings'
      });
    }
  }

  onApplyClick(e) {
    if (this.optionsHandler && this.optionsHandler.isChanged) {
      this.optionsHandler.applyChanges();
    }
  }

  toggleFullScreen(): void {
    this.isFullScreen = !this.isFullScreen;

    if (this.isFullScreen) {
      this.dialogRef.addPanelClass(this.FULLSCREEN_CLASS);
      this.dialogRef.updateSize('100vw', '100vh');
    } else {
      this.dialogRef.removePanelClass(this.FULLSCREEN_CLASS);
      this.dialogRef.updateSize();
    }
  }

  protected cancelModal() {
    this.optionsHandler?.cancelModal();
    if (this.isFullScreen) {
      this.toggleFullScreen();
    }
  }

  protected saveModal() {
    this.optionsHandler?.saveModal();
    if (this.isFullScreen) {
      this.toggleFullScreen();
    }
  }

  protected onModalRequest(modal: any) {
    this.dialogRef.disableClose = modal.value;
  }
}
