import {Component, Input, OnDestroy, OnInit, ViewChild} from '@angular/core';
import {UntypedFormBuilder, UntypedFormGroup, Validators} from '@angular/forms';
import {YotService} from 'src/app/services/yot/yot.service';
import {HomegenieAdapter, Program} from '../homegenie-adapter';
import {HomegenieApi, ModuleParameter} from '../homegenie-api';
import {
  ModuleSettingsDialogComponent
} from "../../../components/dialogs/module-settings-dialog/module-settings-dialog.component";
import {forkJoin, Subject, Subscription} from "rxjs";
import {ModulesGroupsComponent} from "../modules-groups/modules-groups.component";
import {MatTabChangeEvent} from "@angular/material/tabs";
import {PackagesManagerComponent} from "../packages-manager/packages-manager.component";
import {NavigationService} from "../../../services/navigation.service";

class ProgramsGroup {
  public name: string;
  public programs: Program[] = [];
}

@Component({
  selector: 'app-homegenie-setup',
  templateUrl: './homegenie-setup.component.html',
  styleUrls: ['./homegenie-setup.component.scss']
})
export class HomegenieSetupComponent implements OnInit, OnDestroy {
  @ViewChild('modulesGroupsComponent', {static: true})
  groupsComponent: ModulesGroupsComponent;
  @ViewChild('packagesManagerComponent', {static: true})
  packagesManagerComponent: PackagesManagerComponent;
  @Input()
  adapter: HomegenieAdapter;
  firstFormGroup: UntypedFormGroup;
  secondFormGroup: UntypedFormGroup;

  drivers: any[] = [];
  programsGroups: ProgramsGroup[] = [];

  packagesRepository: any;

  hasConfigureWarning(p: Program) : boolean {
    const programModule = this.adapter.getModule(`${p.Domain}${HomegenieAdapter.yotAddressSeparator}${p.Address}`);
    const configureWarning = programModule && programModule.Properties.filter((p) => p.Name === 'ConfigureStatus.Warning');
    if (configureWarning && configureWarning.length === 1) {
      return configureWarning[0].Value;
    }
    return false;
  }

  private notificationsSubscription: Subscription;

  constructor(private yot: YotService, private navigationService: NavigationService, private formBuilder: UntypedFormBuilder) {
  }

  ngOnInit(): void {
    this.firstFormGroup = this.formBuilder.group({
      firstCtrl: ['', Validators.required]
    });
    this.secondFormGroup = this.formBuilder.group({
      secondCtrl: ['', Validators.required]
    });
    this.onSelectedTabChange({index: 0} as any);
    this.notificationsSubscription = this.yot.notificationService.reloadPrograms.subscribe(() => {
      //this.adapter.loadPrograms();
      this.getProgramList();
    });
  }
  ngOnDestroy() {
    this.notificationsSubscription.unsubscribe();
  }

  onDriverEnabledChange(e: any, driver: any): void {
    this.navigationService.isLoading = true;
    this.adapter.apiCall(e.checked
      ? HomegenieApi.Config.Interfaces.Enable(driver.Domain)
      : HomegenieApi.Config.Interfaces.Disable(driver.Domain)
    ).subscribe((res) => {
      this.adapter.reloadModules().subscribe(() => {
        // TODO: might check and report if new modules where added after enabling the interface
        this.navigationService.isLoading = false;
      });
    }, (err) => {
      // TODO: handle err
      console.log(err);
      this.navigationService.isLoading = false;
    });
  }

  onProgramSelected(program: any) {
    const module = this.yot.getModule(`${program.Domain}${HomegenieAdapter.yotAddressSeparator}${program.Address}`, this.adapter.id);
    if (!module) {
      console.log('WARNING', 'No module associated with this program.');
      return;
    }
    // get translated text from associated program
    module.name = program.Name;
    module.description = program.Description;
    // Show Module/Program Options
    this.yot.dialog.open(ModuleSettingsDialogComponent, {
      panelClass: 'dialog-no-padding',
      width: '100%',
      minWidth: '320px',
      maxWidth: '576px',
      disableClose: false,
      data: {module}
    });
  }
  onSelectedTabChange(e: MatTabChangeEvent) {
    switch (e.index) {
      case 0:
        // system configuration tab was selected
        this.refreshConfiguration();
        break;
      case 1:
        // packages tab was selected
        this.packagesManagerComponent
          .refresh();
        break;
      case 2:
        // modules-groups tab was selected
        this.groupsComponent
          .refreshGroupsList();
        break;
    }
  }

  refreshConfiguration() {
    if (this.adapter) {
      this.navigationService.isLoading = true;
      forkJoin([this.getInterfaceList(), this.getProgramList()])
        .subscribe({
          next: (res) => this.navigationService.isLoading = false,
          error: (err) => {
            // TODO: handle err
            console.log(err);
            this.navigationService.isLoading = false;
          }
        });
    }
  }

  getInterfaceList(): Subject<any> {
    const subject = new Subject();
    this.navigationService.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Config.Interfaces.List)
      .subscribe((res) => {
        this.drivers = res.response;
        this.navigationService.isLoading = false;
        subject.next(this.drivers);
        subject.complete();
      }, (err) => {
        console.log(err);
        this.navigationService.isLoading = false;
        subject.error(err);
      });
    return subject;
  }

  getProgramList(): Subject<any> {
    const subject = new Subject();
    this.navigationService.isLoading = true;
    this.programsGroups = [];
    this.adapter.loadPrograms().subscribe({
      next: (programs) => {
        if (programs == null) {
          this.navigationService.isLoading = false;
          subject.error(new Error('Could not read programs list.'));
          return;
        }
        programs.filter((p) => {
          let hasOptions = false;
          const module = this.adapter.getModule({Domain: p.Domain, Address: `${p.Address}`});
          if (module) {
            hasOptions = module.Properties
              .filter((p: ModuleParameter) => p.Name.startsWith('ConfigureOptions.'))
              .length > 0;
          }
          const isConfigurable = p.IsRunning && hasOptions;
          if (isConfigurable) {
            // populate groups list
            let group = this.programsGroups
              .find((g) => g.name === p.Group);
            if (!group) {
              group = new ProgramsGroup();
              group.name = p.Group;
              group.programs = [];
              this.programsGroups.push(group);
            }
            group.programs.push(p);
            // translate Name and Description
            const titleKey = `${this.adapter.translationPrefix}.$options.${p.Address}.Title`;
            this.yot.translate.get(titleKey).subscribe((tr) => {
              if (tr !== titleKey) {
                p.Name = tr;
              }
            });
            const descriptionKey = `${this.adapter.translationPrefix}.$options.${p.Address}.Description`;
            this.yot.translate.get(descriptionKey).subscribe((tr) => {
              if (tr !== descriptionKey) {
                p.Description = tr;
              }
            });
          }
          return isConfigurable ? p : undefined;
        });
        this.programsGroups
          .sort((a,b) => (a.name > b.name) ? 1 : (a.name < b.name) ? -1 : 0);
        this.navigationService.isLoading = false;
        subject.next(this.programsGroups);
        subject.complete();
      },
      error: (err) => subject.error(err)
    });
    return subject;
  }
}
