import {Component, EventEmitter, Input, OnChanges, OnInit, Output, SimpleChanges} from '@angular/core';
import {MatSelectChange} from "@angular/material/select";
import {Module, ModuleField} from "../../../services/yot/module";
import {YotService} from "../../../services/yot/yot.service";
import {ChartDataWorkerConfig} from "../chart-data.worker";
import {
  HgChartOptions,
  INTERFACE_STATISTICS_STORAGE
} from "../chart.component";
import {SensorFieldFormatterPipe} from "../../../pipes/SensorFieldFormatterPipe";
import {SystemApi} from "../../../api/system-api";

@Component({
  selector: 'app-chart-series-input',
  templateUrl: './chart-series-input.component.html',
  styleUrls: ['./chart-series-input.component.scss']
})
export class ChartSeriesInputComponent implements OnInit, OnChanges {
  @Output()
  updated = new EventEmitter<ChartDataWorkerConfig>();
  @Input()
  config: ChartDataWorkerConfig;
  @Input()
  filters: string[];
  @Input()
  showModuleSelect = false;
  @Input()
  defaultField = '';
  @Input()
  defaultType = '';

  statisticsStorageList = [
    {
      apiUrl: 'HomeGenie.EventsLogger',
      name: 'Events Logger',
      description: 'events_logger_database'
    }
  ];

  private _statFields: ModuleField[] = [];
  get statsFields(): ModuleField[] {
    return this._statFields;
  }

  get selectedModule(): Module {
    return this.yot.getModule(this.config?.moduleId);
  }

  get availableModules(): Module[] {
    const modules = this.yot.modules.filter((m) => m.getStatsFields().length > 0);
    if (this.defaultField) {
      return modules.filter((m) => m.field(this.defaultField));
    }
    return modules;
  }

  constructor(private yot: YotService) {
  }

  ngOnInit(): void {
    this.filters = this.filters || [];
    this.config = this.config || new ChartDataWorkerConfig();
    // get statistics storage providers
    this.yot.getDefaultAdapter()
      .system(SystemApi.Automation.Programs.Implements, INTERFACE_STATISTICS_STORAGE)
      .subscribe({
        next: (providers: any[]) => {
          this.statisticsStorageList = providers.map((provider: any) => ({
            id: provider.providerId,
            name: provider.name,
            apiUrl: provider.apiUrl,
            description: provider.options?.description || provider.name,
          }));
        }
      });
    // set default data filter if none is set
    this.config.queryOptions.dataFilter = this.config.queryOptions.dataFilter || '';
    if (this.config.title === undefined) {
      this.resetTitle();
    }
    this.refreshFields();
  }
  ngOnChanges(changes: SimpleChanges) {
    // changes.prop contains the old and the new value...
    if (changes.config) {
      this.refreshFields();
    }
  }

  onFieldChange(e): void {
    this.config.queryOptions.field = e.value;
    this.resetTitle();
    this.updated.emit(this.config);
  }

  onFilterChange(e): void {
    this.config.queryOptions.dataFilter = e.value;
    this.updated.emit(this.config);
  }

  onModuleChange($event: MatSelectChange) {
    this.config.moduleId = $event.value;
    const m = this.yot.getModule(this.config.moduleId);
    this.config.title = m.name;
    this.refreshFields();
    this.config.queryOptions.field = this.defaultField || this._statFields[0]?.key;
    if (!this.defaultField) {
      this.resetTitle();
    }
    this.updated.emit(this.config);
  }

  onStorageChange($event: MatSelectChange) {
    this.config.chartOptions.storage = $event.value;
    this.refreshFields();
    this.updated.emit(this.config);
  }

  onFillCheckboxChange(e) {
    this.config.chartOptions = this.config.chartOptions || new HgChartOptions();
    this.config.chartOptions.fill = e.checked;
    this.updated.emit(this.config);
  }

  onLabelChange(e) {
    this.config.title = e.target.value;
    this.updated.emit(this.config);
  }

  onTypeChange(e: MatSelectChange) {
    const opts = this.config.chartOptions = this.config.chartOptions || new HgChartOptions();
    opts.type = e.value;
    this.updated.emit(this.config);
  }

  private resetTitle() {
    const key = this.config.queryOptions.field;
    if (key == null) return;
    const fieldFormatterPipe = new SensorFieldFormatterPipe();
    this.config.title = fieldFormatterPipe.transform(key);
    this.yot.translate.get(key)
      .subscribe({
        next: (res) => {
          if (res !== key) {
            this.config.title = res;
          }
        }
      });
  }

  private refreshFields() {
    const m = this.yot.getModule(this.config?.moduleId);
    if (m) {
      this._statFields = m.getStatsFields();
    }
  }

}
