@Component({
  selector: 'app-visual-editor',
  templateUrl: './visual-editor.component.html',
  styleUrls: ['./visual-editor.component.scss']
})
export class VisualEditorComponent implements OnInit, OnDestroy {
  @ViewChild('programInfo', {static: true})
  programInfo;
  @ViewChild('blocklyDiv', {static: true})
  blocklyDiv: ElementRef;

  @Input()
  adapter: HomegenieAdapter;
  @Input()
  program: Program;
  @Output()
  codeGenerated = new EventEmitter<string>();

  CodeType = SourceCodeType;
  Md5 = Md5;

  enablePreview = true;
  programWidgets: DashboardWidget[] = [];
  refreshWidgetsTimeout = null;
  captureCommandsEnabled: boolean;
  captureCommandsPause = -1; // -1 = none, 0 = mimic, <n> = pause in ms

  programErrors: any[] = [[], [], []];
  programChecksum = '';

  selectedTabIndex = 0;
  newLogEventsCount = 0;

  programModule: Module;
  programStatus: string;
  eventsLog: any[] = [];

  originalProgramData: string;

  workspace: WorkspaceSvg;
  codeGenerator: HomegenieCodeGenerator;

  isLoading = false;



  theme = 'hc-light'; // 'vs-dark' // 'hc-black' // 'vs' // 'hc-light'
  codeModel: CodeModel[] = [{
    language: 'csharp',
    uri: 'program-script-main',
    value: '',
    dependencies: [ ]
  }, {
    language: 'csharp',
    uri: 'program-script-setup',
    value: '',
    dependencies: [ ]
  }, {
    language: 'csharp',
    uri: 'program-script-context',
    value: '',
    dependencies: [ ]
  }];
  options: monaco.editor.IStandaloneEditorConstructionOptions = {
    lineNumbers: 'on',
    contextmenu: true,
    fixedOverflowWidgets: true,
    colorDecorators: true,
    cursorWidth: 2,
    cursorBlinking: 'expand',
    cursorSmoothCaretAnimation: 'on',
    cursorStyle: 'line',
    automaticLayout: true,
    minimap: {
      enabled: false,
    },
    tabSize: 2
  };



  get isChanged(): boolean {
    return this.originalProgramData !== JSON.stringify(this.program);
  }

  get canUpdate(): boolean {
    return (this.program.Name.length > 1 && this.isChanged);
  }

  get isRunning(): boolean {
    return this.programStatus === 'Running' || this.programStatus === 'Background';
  }

  get hasErrors(): boolean {
    if (!this.program) return false;
    let errors = false;
    const scriptErrors = this.program.ScriptErrors ? this.program.ScriptErrors : '[]';
    if (this.programModule) {
      const errorField = this.programModule.field('Runtime.Error');
      errors = (errorField && errorField.value && errorField.value.length > 0);
    }
    return !this.isRunning && (errors || scriptErrors !== '[]');
  }

  get programModules(): Module[] {
    return [...this.declaredModules, ...this.selectedModules];
  }
  get declaredModules(): Module[] {
    const modules: Module[] = this.adapter.modules.filter((m) => {
      const parentId = m.Properties.find(p => p.Name === 'VirtualModule.ParentId');
      if (parentId && this.program && parentId.Value === this.program.Address.toString()
        && (m.Domain !== this.program.Domain || m.Address !== this.program.Address.toString())) {
        return true;
      }
    }).map((m) => this.adapter.yot.getModule(this.adapter.getModuleId(m), this.adapter.id));
    const declaredModules = this.codeGenerator && this.codeGenerator.declaredModules.map((m) => {
      return this.adapter.getModuleByRef({Domain: m.Domain, Address: m.Address});
    }) || [];
    if (this.programModule) {
      return this.program && [...modules, this.programModule, ...declaredModules];
    }
    return this.program && [...modules, ...declaredModules];
  }
  private _selectedModules: Module[] = [];
  get selectedModules(): Module[] {
    this._selectedModules = this._selectedModules
      .filter((m) => this.declaredModules.find((m2) => m2.id === m.id) == null);
    return this._selectedModules;
  }

  get generatedCode(): { context: string, setup: string, main: string } {
    return {
      context: this.program.ScriptContext,
      setup: this.program.ScriptSetup,
      main: this.program.ScriptSource
    };
  }

  private modulesEventSubscription: Subscription;
  private moduleCommandSubscription: Subscription;
  private parameterSetSubscription: Subscription;
  private codeGenerateTimeout;
  private workspaceReadyCallback;

  @HostListener('document:keydown.control.s', ['$event'])
  onKeydownHandler(event: KeyboardEvent) {
    event.preventDefault();
    this.onBuildButtonClick(event);
  }

  constructor(private yot: YotService, private dialog: MatDialog) {
    this.theme = yot.preferences.ui.theme === 'light' ? 'vs' : 'vs-dark';
  }

  ngOnInit(): void {
    // subscribe to module events
    this.modulesEventSubscription = this.adapter.onModuleEvent.subscribe(({module, event}) => {
      if (this.programModules && this.programModules.includes(module)) {
        if (module === this.programModule) {
          switch (event.Property) {
            case 'Program.Status':
              this.programStatus = event.Value;
              if (this.programStatus === 'Running' || this.programStatus === 'Idle') {
//                this.refreshProgramWidgets();

                if (this.isChanged) {
                  this.yot.translate.get(['unsaved_changes', 'save_to_apply_program_changes']).subscribe((tr) => {
                    this.yot.notify(tr['unsaved_changes'], tr['save_to_apply_program_changes'], {
                      verticalPosition: 'bottom',
                      data: {action: undefined}
                    });
                  });
                }

              } else if (this.programStatus === 'Disabled' || this.programStatus === 'Enabled') {
                this.refresh(this.program.Address);
              }
              break;
            case 'Compiler.Warning':
//              this.adapter.yot
//                .notify("Compiler warning", event.Value);
              break;
            case 'Runtime.Error':
              if (event.Value.length > 0) {
                this.adapter.yot
                  .notify("Runtime error", event.Value);
              }
              break;
            case 'Program.Event':
              // TODO: handle 'MODULE_ADDED ' and 'MODULE_REMOVED ' events
              this.refreshProgramWidgets();
              break;
          }
          // TODO: ....
        }
        if (module && event.Property === 'Widget.DisplayModule') {
          // widget changed
          this.programWidgets.forEach((w) => {
            if (w.module && this.yot.getModuleByRef(w.module) === module) {
              w.type = module.getWidgetData().type;
            }
          });
        }
        // prepend event
        event.module = module;
        this.eventsLog = [event, ...this.eventsLog];
        if (this.selectedTabIndex !== 3) {
          this.newLogEventsCount++;
        }
      }
    });

    // subscribe to module commands events
    this.moduleCommandSubscription = this.adapter.onModuleCommand.subscribe(({module, command, options}) => {
      if (this.captureCommandsEnabled && this.isCaptureCommandAllowed(command)) {
        this.captureCommand(module, command, options);
      }
    });

    // subscribe to ParameterSet event
    this.parameterSetSubscription = this.adapter.onParameterSet.subscribe((e) => {
      if (this.captureCommandsEnabled) {
        this.captureCommand(e.module, "Config.ParameterSet", `${e.parameter}/${e.value}`);
      }
    });

    this.codeGenerator = new HomegenieCodeGenerator(this.adapter, 'homegenie-code-generator');
    this.workspaceReadyCallback = (w) => {
      this.workspace = w;
      this.workspace.addChangeListener((e) => {
        if (e.type === Blockly.Events.CHANGE || e.type === Blockly.Events.MOVE) {
          this.generateCode();
        }
      });
      if (this.program && this.program.Data) {
        const stateLoad = JSON.parse(this.program.Data);
        Blockly.serialization.workspaces.load(stateLoad, this.workspace);
        this.generateCode();
        this._refreshProgramWidgets().subscribe((res) => {
          this.isLoading = false;
        });
      } else {
        this.isLoading = false;
      }
    };
    this.refresh().subscribe((res) => {
      this.isLoading = true;
      if (this.workspace) {
        this.workspace.dispose();
      }
      new HomegenieWorkspace(
        this.workspaceReadyCallback,
        this.adapter,
        this.blocklyDiv.nativeElement,
        this.adapter.yot.preferences.ui.theme === 'dark'
      );
    }, (err) => console.log(err));

    this.yot.layoutService.contextualHelpLink = 'https://homegenie.it/server/automation/scenes/';
  }
  ngOnDestroy() {
    this.yot.layoutService.contextualHelpLink = '';

    if (this.modulesEventSubscription) {
      this.modulesEventSubscription.unsubscribe();
    }
    if (this.moduleCommandSubscription) {
      this.moduleCommandSubscription.unsubscribe();
    }
    if (this.parameterSetSubscription) {
      this.parameterSetSubscription.unsubscribe();
    }
    if (this.workspace) {
      this.workspace.dispose();
    }
  }

  onContextCodeChanged(code: string) {
    this.program.ScriptContext = code;
  }

  onBuildButtonClick(e) {
    this.isLoading = true;
    // clear trashcan content before saving
    this.workspace.trashcan.emptyContents();
    // update custom *Context* code
    this.program.ScriptContext = this.codeModel[SourceCodeType.ContextCode].value;
    this.adapter.apiCall(HomegenieApi.Automation.Programs.Compile, this.program)
      .subscribe((res) => {
        const compilerErrors: CompilerErrors[] = res.response;
        setTimeout(() => {
          this.program.ScriptErrors = JSON.stringify(compilerErrors);
          this.isLoading = false;
          this.setUnchanged();
        }, 500);
      }, () => {
        this.isLoading = false
      });
  }
  onRunButtonClick(e) {
    this.captureCommandsEnabled = false;
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Automation.Programs.Run(this.program.Address))
      .subscribe(() => {
        this.isLoading = false;
      });
  }
  onStopButtonClick(e) {
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Automation.Programs.Break(this.program.Address))
      .subscribe(() => {
        this.isLoading = false;
      });
    // TODO: ....
  }
  onEnableButtonClick(e) {
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Automation.Programs.Enable(this.program.Address))
      .subscribe((res) => {
        this.isLoading = false;
        this.refresh(this.program.Address);
      });
    // TODO: ...
  }
  onDisableButtonClick(e) {
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Automation.Programs.Disable(this.program.Address))
      .subscribe((res) => {
        this.isLoading = false;
        this.refresh(this.program.Address);
      });
    // TODO: ...
  }

  onTogglePreviewClick(e) {
    this.enablePreview = !this.enablePreview;
    if (!this.enablePreview) {
      this.captureCommandsEnabled = false;
    }
    this.refreshProgramWidgets();
  }

  onSelectModulesButtonClick(e) {
    const dialogRef = this.dialog.open(ModulesSelectDialogComponent, {
      width: '576px',
      minHeight: '280px',
      data: {
        adapter: this.adapter,
        declaredModules: this.declaredModules,
        selectedModules: this._selectedModules
      }
    });
    dialogRef.afterClosed().subscribe((modules: Module[]) => {
      if (modules) {
        this._selectedModules = modules;
        this.refreshProgramWidgets();
      }
    });
  }
  onCaptureCommandsButtonClick(e) {
    const dialogRef = this.dialog.open(CommandsCaptureDialogComponent, {
      data: {
        commandsPause: this.captureCommandsPause,
        captureEnabled: this.captureCommandsEnabled
      }
    });
    dialogRef.afterClosed().subscribe((data: any) => {
      if (data?.commandsPause != null) {
        this.lastCommandTs = 0;
        this.captureCommandsPause = data.commandsPause;
        this.captureCommandsEnabled = data.captureEnabled;
      }
    });
  }

  onCodeTabChanged(index: number) {
    if (index === 0) {
      // TODO: ...
      return;
    }
    if (index === 1) {
      setTimeout(() => {
        Blockly.svgResize(this.workspace);
        (this.workspace as any).scrollCenter();
      }, 10);
    }
    const ct = index - 1;
    if (/*ct === SourceCodeType.SetupCode || ct === SourceCodeType.MainCode ||*/ // <-- these two code block types are auto-generated
      ct === SourceCodeType.ContextCode) {
      // AUTOGENERATED (not editable with text code editor)
      //this.program.ScriptSetup = this.codeModel[SourceCodeType.SetupCode].value;
      // AUTOGENERATED (not editable with text code editor)
      //this.program.ScriptSource = this.codeModel[SourceCodeType.MainCode].value;
      // CUSTOM CODE
      this.program.ScriptContext = this.codeModel[SourceCodeType.ContextCode].value;
      //this.currentCodeModelType = ct;
// TODO: improve errors reporting
      //this.refreshProgramErrors();
      return;
    }
    // Log events
    if (index === EVENTS_LOG_TAB_INDEX) {
      this.newLogEventsCount = 0;
    }
  }

  onWidgetActionRequest(request: WidgetActionRequest, moduleRef?: ModuleReference): void {

    if (request.action === WidgetActionRequestAction.removeWidget && moduleRef) {
      return;
    }
    let dialogComponent;
    let dialogWidth = '576px';
    // TODO: add enum for dialog names (see `widget-actions-menu.component.ts`)
    switch (request.action) {
      case WidgetActionRequestAction.showSettings:
        dialogComponent = ModuleSettingsDialogComponent;
        break;
      case WidgetActionRequestAction.showStatistics:
        dialogComponent = ModuleStatisticsDialogComponent;
        dialogWidth = '960px';
        break;
      case WidgetActionRequestAction.showSchedule:
        dialogComponent = ModuleSchedulingDialogComponent;
        break;
      case WidgetActionRequestAction.showLogs:
        dialogComponent = ModuleEventsDialogComponent;
        break;
      case WidgetActionRequestAction.showEdit:
        dialogComponent = ModuleEditDialogComponent;
        break;
    }
    if (dialogComponent) {
      const module = this.adapter.yot.getModuleByRef(moduleRef);
      const dialogRef = this.dialog.open(dialogComponent, {
        panelClass: 'dialog-no-padding',
        width: '100%',
        minWidth: '280px',
        maxWidth: dialogWidth,
        disableClose: false,
        data: {module, options: module.getWidgetData()}
      });
    }

  }

  getCommandPauseText() {
    switch (this.captureCommandsPause) {
      case -1:
        return 'None';
      case 0:
        return 'As-is';
      default:
        return `${this.captureCommandsPause} ms`
    }
  }

  refresh(pid?: number): Subject<any> {
    const subject = new Subject();
    if (pid) {
      this.isLoading = true;
      this.adapter.apiCall(HomegenieApi.Automation.Programs.Get(pid)).subscribe((res) => {
        this.program = res.response;
        this.isLoading = false;
        this.refresh()
          .subscribe((res) => {
            subject.next(res);
            subject.complete();
          }, (err) => subject.error(err));
      });
    }
    if (this.program) {
      this.programModule = this.adapter.getModuleByRef(this.program as any);

      this.programChecksum = (Md5.hashStr(JSON.stringify({
        setup: this.program.ScriptSetup,
        source: this.program.ScriptSource,
        context: this.program.ScriptContext,
        data: this.program.Data
      })) as string).toUpperCase();

      this.isLoading = true;
      this._refreshProgramWidgets() // TODO: this should be refreshed automatically
        .subscribe((res) => {

          this.programModule = this.adapter.getModuleByRef(this.program as any); // || this.programModule;
          if (this.programModule) {
            const status = this.programModule.field('Program.Status');
            this.programStatus = status ? status.value : 'Disabled';
          }

  // TODO: ...
  //        this.refreshProgramErrors();

          this.isLoading = false;
          subject.next(this.program);
          subject.complete();
        }, (err) => {
          console.log(err);
          this.isLoading = false;
          subject.error(err);
        });


      //this.codeModel.map((cm) => cm.language = this.program.Type.toLowerCase());
      this.codeModel[SourceCodeType.SetupCode].value = this.program.ScriptSetup;
      this.codeModel[SourceCodeType.MainCode].value = this.program.ScriptSource;
      this.codeModel[SourceCodeType.ContextCode].value = this.program.ScriptContext;


      this.setUnchanged();
    }
    return subject;
  }

  refreshProgramWidgets() {
    clearTimeout(this.refreshWidgetsTimeout);
    this.refreshWidgetsTimeout = setTimeout(() => {
      this._refreshProgramWidgets().subscribe({
        next: (res) => {},
        error: (err) => {},
        complete: () => {}
      });
    }, 500);
  }

  private _refreshProgramWidgets(): Subject<any> {
    const subject = new Subject();
    this.adapter.reloadModules().subscribe((modules) => {
      const widgets: DashboardWidget[] = [];
      this.programModules.forEach((m) => {
        const data = m.getWidgetData();
        if (data) {
          widgets.push({
            type: data.type,
            module: {adapterId: m.adapterId, moduleId: m.id},
            data
          });
        }
      });
      this.programWidgets = [...widgets];
      subject.next(null);
      subject.complete();
      // work-around to force Blockly refresh since
      // it is not fitting the whole height sometimes
      if (this.workspace) {
        setTimeout(() => {
          Blockly.svgResize(this.workspace);
        }, 500);
      }
    }, (err) => {subject.error(err);});
    return subject;
  }

  private setUnchanged() {
    this.originalProgramData = JSON.stringify(this.program);
  }

  private generateCode() {
    if (this.codeGenerateTimeout) {
      clearTimeout(this.codeGenerateTimeout);
      this.codeGenerateTimeout = null;
    }
    this.codeGenerateTimeout = setTimeout(() => {
      this._generateCode();
    }, 250);
  }
  private _generateCode() {
    let modulesCheckBefore = '';
    this.programModules.map(m => modulesCheckBefore += `[${m.id}]`);
    const p = this.codeGenerator.workspaceToProgramCode(this.workspace);
    if (p.codeDeclarations) {
      p.codeDeclarations += '\n\n';
    }
    this.program.ScriptSource = p.codeDeclarations + p.custom + '\n\n' + p.code;
    if (p.setupDeclarations) {
      p.setupDeclarations += '\n\n';
    }
    this.program.ScriptSetup = p.setupDeclarations + p.setup;
    this.program.ScriptContext = this.codeModel[SourceCodeType.ContextCode].value;
    const stateLoad = Blockly.serialization.workspaces.save(this.workspace);
    this.program.Data = JSON.stringify(stateLoad);
    let modulesCheckAfter = '';
    this.programModules.map(m => modulesCheckAfter += `[${m.id}]`);
    const modulesChanged = (modulesCheckBefore !== modulesCheckAfter);
    if (modulesChanged) {
      this.refreshProgramWidgets();
    }
  }

  private lastCommandTs = 0;
  private currentCaptureBlock: any;
  private captureCommand(module: Module, command: string, options: string) {
    // get a reference to the program's MAIN block
    let stateLoad = null;
    try {
      stateLoad = JSON.parse(this.program.Data);
    } catch (e) {
      console.log('Error parsing workspace data ->', e, this.program.Data);
    }
    //const mainBlock = stateLoad?.blocks?.blocks?.find((b) => b.type == 'main_code');
    const bid = Blockly.getSelected()?.id || -1;
    const mainBlock = stateLoad?.blocks?.blocks?.find((b) => b.type.endsWith('_code') && b.id == bid)
        || this.currentCaptureBlock;
    let lastBlock = null;
    let lastModule = null;
    if (mainBlock) {
      setTimeout(() =>{
        this.workspace.getBlockById(mainBlock.id).select();
      });

      this.currentCaptureBlock = mainBlock;
      if (mainBlock.inputs) {
        lastBlock = mainBlock.inputs[Object.keys(mainBlock.inputs)[0]]?.block;
      }
      while (lastBlock) {
        if (lastBlock.type === 'module_select') {
          lastModule = lastBlock.fields.MODULE;
        }
        if (lastBlock.next) {
          lastBlock = lastBlock.next.block;
        } else {
          break;
        }
      }
    }


    let pauseBlock = null;
    if (this.captureCommandsPause !== -1 && this.lastCommandTs !== 0) {
      let pause = (this.captureCommandsPause / 1000);
      if (this.captureCommandsPause === 0) {
        pause = (new Date().getTime() - this.lastCommandTs) / 1000;
      }
      pauseBlock = {
        block: {
          id: Blockly.utils.idGenerator.genUid(),
          type: 'program_pause',
          inputs: {
            SECONDS: {
              shadow: {
                fields: {NUM: pause},
                id: Blockly.utils.idGenerator.genUid(),
                type: 'math_number'
              }
            }
          }
        }
      }
    }
    this.lastCommandTs = new Date().getTime();


    let newBlock = null;
    const id = Blockly.utils.idGenerator.genUid();
    switch (command) {
      case CMD.Control.Toggle:
        newBlock = {
          block: {
            id, type: 'control_toggle'
          }
        }
        break;
      case CMD.Control.On:
        newBlock = {
          block: {
            id, type: 'control_on'
          }
        }
        break;
      case CMD.Control.Off:
        newBlock = {
          block: {
            id, type: 'control_off'
          }
        }
        break;
      case CMD.Control.Level:
        newBlock = {
          block: {
            id, type: 'control_level',
            fields: {
              LEVEL: parseFloat(options) / 100
            }
          }
        }
        break;
      case CMD.Control.ColorHsb:
        const hsvd = options.split(',');
        const color = new Color()
          .setHsva(+hsvd[0] * 360, +hsvd[1] * 100, +hsvd[2] * 100, 1)
          .toHexString();
        const duration = +hsvd[3] > 0 ? +hsvd[3] : 0.5;
        newBlock = {
          block: {
            id, type: 'control_color',
            fields: {
              COLOR: color,
              DURATION: duration
            }
          }
        }
        break;
      default:
        newBlock = {
          block: {
            id, type: 'custom_command',
            fields: {
              COMMAND: command,
              OPTIONS: options
            }
          }
        }
      }

      if (lastModule !== module.id) {
        newBlock = {
          block: {
            id, type: 'module_select',
            fields: {
              MODULE: module.id
            },
            next: newBlock
          }
        }
      }

      if (pauseBlock) {
        pauseBlock.block.next = newBlock;
        newBlock = pauseBlock;
      }

      if (lastBlock) {

        lastBlock.next = newBlock;

      } else if (mainBlock && !mainBlock.inputs) {

        switch (mainBlock.type)
        {
          case 'custom_code':
            mainBlock.inputs = {
              CUSTOM: newBlock
            }
            break;
          case 'setup_code':
            mainBlock.inputs = {
              SETUP: newBlock
            }
            break;
          case 'main_code':
            mainBlock.inputs = {
              MAIN: newBlock
            }
            break;
        }

      } else {

        this.yot.notify("Program block required", "Select a 'Program' block where captured commands will be added.", {
          verticalPosition: 'bottom',
          data: {action: undefined}
        });
        this.lastCommandTs = 0;

      }

      if (stateLoad != null) {
        Blockly.serialization.workspaces.load(stateLoad, this.workspace);
        this._generateCode();
      }

  }

  private isCaptureCommandAllowed(command: string) {
    const ignoreList = ["AvMedia.Browse", "AvMedia.GetItem"];
    return ignoreList.indexOf(command) === -1;
  }
}
