import {Pipe, PipeTransform} from '@angular/core';
import {YotService} from "../services/yot/yot.service";

@Pipe({ name: 'domainNameFormatter' })
export class DomainNameFormatterPipe implements PipeTransform {

  constructor(private yot: YotService) {
  }

  transform(value: any, ...args): any {
    const parts = value.split('.');
    const lastTwo = parts.slice(-2);
    return lastTwo.join('.');
  }
}
