import {Component, OnInit} from '@angular/core';
import {WidgetBaseComponent} from "../widget-base.component";
import {MediaServerDialogComponent} from "../../components/dialogs/media-server-dialog/media-server-dialog.component";
import {MediaCenterDialogComponent} from "../../components/dialogs/media-center-dialog/media-center-dialog.component";

@Component({
  selector: 'app-media-server',
  templateUrl: './media-server.component.html',
  styleUrls: ['./media-server.component.scss']
})
export class MediaServerComponent extends WidgetBaseComponent implements OnInit {

  modelName: string;
  modelVersion: string;

  get lastUpdateTimestamp(): number {
    let lastUpdateTimestamp = 0;
    const f = this.module.field('UPnP.FriendlyName');
    if (f != null) {
      lastUpdateTimestamp = new Date(f.timestamp).getTime();
    }
    return lastUpdateTimestamp;
  }

  ngOnInit(): void {
    super.ngOnInit();
    this.modelName = this.module.field('UPnP.ModelName')?.value;
    this.modelVersion = this.module.field('UPnP.ModelNumber')?.value || this.module.field('UPnP.Version')?.value;
  }

  onMediaCenterButtonClick($event: Event): void {
    const dialogRef = this.dialog.open(MediaCenterDialogComponent, {
      maxWidth: '100vw',
      maxHeight: '100vh',
      height: '100%',
      width: '100%',
      hasBackdrop: false,
//      panelClass: 'full-screen-dialog',
      panelClass: ['dialog-no-padding', 'dialog-video-player'],
      enterAnimationDuration: '300ms',
      exitAnimationDuration: '500ms',
      disableClose: true,
      data: {
        configuration: {...this.configuration},
        module: this.module,
        hasLights: this.options.dashboardHasLights,
        hasPrograms: this.options.dashboardHasPrograms
      }
    });
    dialogRef.afterClosed().subscribe((config: string) => {
      if (config) {
        this.configuration = config;
        this.save();
      }
    });
    if ($event && $event.currentTarget) {
      ($event.currentTarget as HTMLElement).blur();
    }
  }

  onBrowseButtonClick($event: MouseEvent) {
    let dialogWidth = '576px';
    const dialogRef = this.dialog.open(MediaServerDialogComponent, {
      panelClass: 'dialog-no-padding',
      width: '100%',
      minWidth: '280px',
      maxWidth: dialogWidth,
      disableClose: true,
      enterAnimationDuration: '300ms',
      exitAnimationDuration: '300ms',
      data: {
        configuration: {...this.configuration},
        module: this.module
      }
    });
    dialogRef.afterClosed().subscribe((config: string) => {
      if (config) {
        this.configuration = config;
        this.save();
      }
    });
  }
}
