import {Injectable} from '@angular/core';
import {MatDialog} from "@angular/material/dialog";
import {
  NotificationsReaderComponent
} from "../components-extras/dialogs/notifications-reader/notifications-reader.component";
import {Subject} from "rxjs";
import {ModuleReference} from "./yot/module";
import {TranslateService} from "@ngx-translate/core";

export class Notification {
  title: string;
  message: string;
  sender: ModuleReference;
  date?: Date;
  lastDate?: Date;
  count? = 0;
  read?: boolean;
  options?: any[] = [];
  data? = {} as any;
  hasOption(optionId: string) {
    return this.options.find((o) => (o === optionId || o.startsWith(`${optionId}=`))) !== undefined;
  };
  getOption(optionId: string) {
    return this.options.find((o) => (o === optionId || o.startsWith(`${optionId}=`)));
  }
}

@Injectable({
  providedIn: 'root'
})
export class NotificationService {
  notifications: Notification[] = [];

  onNotificationAdded = new Subject<Notification>();

  disable = true;

  reloadPrograms = new Subject<void>();
  constructor(private dialog: MatDialog, private translate: TranslateService) { }

  addNotification(notification: Notification) {
    if (this.disable) return;
    let alreadyExist = this.notifications.find((n) => n.title === notification.title && n.message === notification.message && JSON.stringify(n.sender) === JSON.stringify(notification.sender) && this.deepCompare(n.data, notification.data));
    if (alreadyExist) {
      alreadyExist.count++;
      notification.lastDate = new Date();
      Object.assign(alreadyExist, notification);
    } else {
      notification.count = 1;
      notification.date = new Date();
      this.notifications.push(notification);
      if (notification.options.length) {
        new Audio('assets/audio/attention-sound.mp3').play();

        let translateKey = notification.getOption('translate');
        if (translateKey) {
          translateKey = translateKey.split('=')[1];
          this.translate.get(translateKey).subscribe((tr) => {
            if (tr !== translateKey) {
              notification.message = tr;
            }
          });
        }

      }
    }
    this.onNotificationAdded.next(notification);
  }

  openReader() {
    const dialogRef = this.dialog.open(NotificationsReaderComponent, {
      panelClass: 'dialog-no-padding',
      //width: '100%',
      minWidth: 360,
      minHeight: 284,
      disableClose: true,
      data: {
        notifications: this.notifications
      }
    });
    dialogRef.afterClosed().subscribe(({sender, request} = {}) => {
      this.notifications = this.notifications.filter(n => !n.read);
    });
  }

  get hasNotifications():boolean {
    return this.notifications && this.notifications.length > 0;
  }

  clearProgramNotifications(mr: ModuleReference) {
    this.notifications = this.notifications
      .filter((n) => n.sender.adapterId !== mr.adapterId || n.sender.moduleId !== mr.moduleId);
  }
  clearAll() {
    this.notifications = [];
  }

  private deepCompare (...args) {
    let i, l, leftChain, rightChain;

    function compare2Objects (x, y) {
      let p;

      // remember that NaN === NaN returns false
      // and isNaN(undefined) returns true
      if (isNaN(x) && isNaN(y) && typeof x === 'number' && typeof y === 'number') {
        return true;
      }

      // Compare primitives and functions.
      // Check if both arguments link to the same object.
      // Especially useful on the step where we compare prototypes
      if (x === y) {
        return true;
      }

      // Works in case when functions are created in constructor.
      // Comparing dates is a common scenario. Another built-ins?
      // We can even handle functions passed across iframes
      if ((typeof x === 'function' && typeof y === 'function') ||
        (x instanceof Date && y instanceof Date) ||
        (x instanceof RegExp && y instanceof RegExp) ||
        (x instanceof String && y instanceof String) ||
        (x instanceof Number && y instanceof Number)) {
        return x.toString() === y.toString();
      }

      // At last checking prototypes as good as we can
      if (!(x instanceof Object && y instanceof Object)) {
        return false;
      }

      if (x.isPrototypeOf(y) || y.isPrototypeOf(x)) {
        return false;
      }

      if (x.constructor !== y.constructor) {
        return false;
      }

      if (x.prototype !== y.prototype) {
        return false;
      }

      // Check for infinitive linking loops
      if (leftChain.indexOf(x) > -1 || rightChain.indexOf(y) > -1) {
        return false;
      }

      // Quick checking of one object being a subset of another.
      // todo: cache the structure of arguments[0] for performance
      for (p in y) {
        if (y.hasOwnProperty(p) !== x.hasOwnProperty(p)) {
          return false;
        }
        else if (typeof y[p] !== typeof x[p]) {
          return false;
        }
      }

      for (p in x) {
        if (y.hasOwnProperty(p) !== x.hasOwnProperty(p)) {
          return false;
        }
        else if (typeof y[p] !== typeof x[p]) {
          return false;
        }

        switch (typeof (x[p])) {
          case 'object':
          case 'function':

            leftChain.push(x);
            rightChain.push(y);

            if (!compare2Objects (x[p], y[p])) {
              return false;
            }

            leftChain.pop();
            rightChain.pop();
            break;

          default:
            if (x[p] !== y[p]) {
              return false;
            }
            break;
        }
      }

      return true;
    }

    if (arguments.length < 1) {
      return true; //Die silently? Don't know how to handle such case, please help...
      // throw "Need two or more arguments to compare";
    }

    for (i = 1, l = arguments.length; i < l; i++) {

      leftChain = []; //Todo: this can be cached
      rightChain = [];

      if (!compare2Objects(arguments[0], arguments[i])) {
        return false;
      }
    }

    return true;
  }
}
