import {Component, Inject} from '@angular/core';
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {marked} from 'marked';

@Component({
  selector: 'app-update-notes-dialog',
  templateUrl: './update-notes-dialog.component.html',
  styleUrls: ['./update-notes-dialog.component.scss']
})
export class UpdateNotesDialogComponent {
  releaseInfo: any = {};
  releaseNotesMarkup = '';

  constructor(@Inject(MAT_DIALOG_DATA) data) {
    this.releaseInfo = data;
    if (this.releaseInfo?.ReleaseNote) {
      let html = marked.parse(this.releaseInfo.ReleaseNote, {gfm: true}).toString();
      this.releaseNotesMarkup = this.addLinksTargetBlank(html);
    }
  }

  private addLinksTargetBlank(html: string): string {
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');
    const links = doc.querySelectorAll('a');
    links.forEach(link => {
      link.setAttribute('target', '_blank');
      link.setAttribute('rel', 'noopener noreferrer');
    });
    return doc.body.innerHTML;
  }
}
