import {Component, EventEmitter, Input, OnInit, Output} from '@angular/core';
import {Module, ModuleField} from "../../../services/yot/module";
import {YotService} from "../../../services/yot/yot.service";
import {HomegenieAdapter} from "../../../adapters/home-genie/homegenie-adapter";
import {MatSelectChange} from "@angular/material/select";
import {ChartDataWorkerConfig} from "../chart-data.worker";

@Component({
  selector: 'app-chart-series-info',
  templateUrl: './chart-series-info.component.html',
  styleUrls: ['./chart-series-info.component.scss']
})
export class ChartSeriesInfoComponent implements OnInit {
  @Output()
  selected = new EventEmitter<ChartDataWorkerConfig>();
  @Output()
  visibilityToggle = new EventEmitter<boolean>();
  @Input()
  config: ChartDataWorkerConfig;
  @Input()
  hideModule: boolean;
  @Input()
  hideParameter = false;

  selectedField: ModuleField;
  selectedModule: Module;
  filtersList = [];
  selectedFilter = "SavitzkyGolay";

  private _statFields: ModuleField[] = [];
  get statsFields(): ModuleField[] {
    return this._statFields;
  }

  constructor(private yot: YotService) { }

  ngOnInit(): void {
    (this.yot.getDefaultAdapter() as HomegenieAdapter)
      .apiCall('DataProcessing.Filters/List/Series')
      .subscribe({
        next: (res) => {
          this.filtersList = res.response;
        },
        error: () => this.selectedFilter = ''
      });
    this.selectedModule = this.yot.getModule(this.config.moduleId);
    if (this.selectedModule) {
      this.selectedField = this.selectedModule
        .field(this.config.queryOptions.field);
      this._statFields = this.selectedModule
        .getStatsFields();
    }
    this.selectedFilter = this.config.queryOptions.dataFilter;
  }

  onFieldChange(e): void {

  }

  onFilterChange(e): void {
    this.config.queryOptions.dataFilter = this.selectedFilter = e.value;

  }

  onModuleChange($event: MatSelectChange) {
    this.selectedModule = $event.value;
    this.selectedField = this.statsFields[0];
  }

  onSeriesInfoClick() {
    this.selected.emit(this.config);
  }

  onVisibilityToggle() {
    const toggled = !this.config.chartOptions.hidden;
    this.config.chartOptions.hidden = toggled;
    this.visibilityToggle.emit(toggled);
  }
}
