import {Component, Inject, OnDestroy, OnInit} from '@angular/core';
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {Module} from "../../../services/yot/module";
import {Color, ColorPickerControl} from "@iplab/ngx-color-picker";

@Component({
  selector: 'app-color-picker-dialog',
  templateUrl: './color-picker-dialog.component.html',
  styleUrls: ['./color-picker-dialog.component.scss']
})
export class ColorPickerDialogComponent implements OnInit, OnDestroy {

  color = '#550a55';
  compactControl = new ColorPickerControl();

  private readonly callback: Function;

  constructor(
    @Inject(MAT_DIALOG_DATA) data: { module: Module, color: string, callback: Function }
  ) {
    this.color = data.color;
    this.callback = data.callback;
  }

  ngOnInit(): void {
    this.compactControl.hidePresets();
    this.compactControl.hideAlphaChannel();
  }
  ngOnDestroy(): void {
    this.compactControl.reset();
  }

  onColorChange(c: any) {
    if (this.callback) {
      this.callback(this.getColor(c));
    }
  }

  getColor(c: any): Color {
    return Color.from(c);
  }
}
