import {Component, Inject} from '@angular/core';
import {ApiResponse, HomegenieAdapter} from "../../homegenie-adapter";
import {HomegenieApi} from "../../homegenie-api";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {NavigationService} from "../../../../services/navigation.service";

enum FactoryResetStep {
  Error = -1,
  ConfirmPrompt,
  FactoryReset
}

@Component({
  selector: 'app-factory-reset-dialog',
  templateUrl: './factory-reset-dialog.component.html',
  styleUrls: ['./factory-reset-dialog.component.scss']
})
export class FactoryResetDialogComponent {
  adapter: HomegenieAdapter;
  isLoading = false;
  errorMessage = '';

  FactoryResetStep = FactoryResetStep;
  currentStep = FactoryResetStep.ConfirmPrompt;

  constructor(@Inject(MAT_DIALOG_DATA) data: {adapter: HomegenieAdapter}, private navigationService: NavigationService) {
    this.adapter = data.adapter;
  }

  onFactoryResetClick() {
    this.isLoading = true;
    this.currentStep = FactoryResetStep.FactoryReset;
    this.adapter.apiCall(HomegenieApi.SystemConfig.System.ConfigurationReset)
      .subscribe({
        next: (ar: ApiResponse) => {
          this.adapter.yot.dashboardService
            .removeAllDashboards();
          this.adapter.yot.modules = [];
          this.adapter.yot
            .saveConfiguration()
            .subscribe((config) => {
              this.isLoading = false;
            });
          this.navigationService
            .toggleDrawerMode('over', false);
          this.adapter.yot
            .savePreferences();
        },
        error: (error) => {
          this.errorMessage = error.message;
          this.currentStep = FactoryResetStep.Error;
          this.isLoading = false;
        }
      });
  }
}
