import {Component, Input, OnInit} from '@angular/core';
import {HomegenieAdapter} from "../../homegenie-adapter";
import {HomegenieApi} from "../../homegenie-api";
import {SetupSystemConfiguration} from "../../homegenie-maintenance/restore-backup/restore-backup.component";

enum ConfigurationMode {
  Default = 'default',
  Manual = 'manual',
  RestoreBackup = 'default-restore'
}

@Component({
  selector: 'app-system-settings',
  templateUrl: './system-settings.component.html',
  styleUrls: ['./system-settings.component.scss']
})
export class SystemSettingsComponent implements OnInit {
  @Input()
  adapter: HomegenieAdapter;
  @Input()
  config = new SetupSystemConfiguration();

  ConfigurationMode = ConfigurationMode;
  selectedConfiguration = ConfigurationMode.Default;

  systemInfo: any = false;

  isLoading = false;
  canProceed = true;

  private defaultPackages = [ 'homegenie-base', 'homegenie-home', 'homegenie-ml-ai' ];

  constructor() {
    this.config.packagesToInstall = this.defaultPackages;
  }

  ngOnInit(): void {
    if (this.config.restoreBackup) {
      this.selectedConfiguration = ConfigurationMode.RestoreBackup;
    }
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.SystemConfig.System.Info)
      .subscribe((res) => {
        this.systemInfo = res.response;
        this.isLoading = false;
      });
  }

  onSelectedConfigurationChange() {
    this.canProceed = this.selectedConfiguration !== ConfigurationMode.RestoreBackup;
  }

  onBackupFileLoaded(config: SetupSystemConfiguration) {
    this.config = config;
    this.canProceed = config.restoreBackup != null;
  }


  configure(): SetupSystemConfiguration {
    const cfg = this.config;
    cfg.packagesToInstall = this.defaultPackages;
    cfg.configureManually = false;
    switch (this.selectedConfiguration) {
      case ConfigurationMode.Default:
        if (cfg.includeDemo) {
          cfg.packagesToInstall.push('homegenie-home-demo');
        }
        if (cfg.configureGPIO) {
          const runtimeMajor = +(this.systemInfo.Runtime.split('.')[0]);
          if (runtimeMajor > 4) {
            // Install .NET IoT libraries if runtime version is > 4
            cfg.packagesToInstall.push('homegenie-iot-net');
          } else {
            // Install RaspberrySharp.IO libraries
            cfg.packagesToInstall.push('homegenie-iot-sharp');
          }
        }
        if (cfg.configureX10) {
          cfg.packagesToInstall.push('homegenie-x10');
        }
        if (cfg.configureZWave) {
          cfg.packagesToInstall.push('homegenie-zwave');
        }
        if (cfg.configureZigBee) {
          //cfg.packagesToInstall.push('homegenie-zigbee');
        }
        cfg.restoreBackup = false;
        break;
      case ConfigurationMode.RestoreBackup:
        cfg.includeDemo = false;
        cfg.configureGPIO = false;
        cfg.configureVoiceRecognizer = false;
        cfg.configureVoiceSynthesizer = false;
        cfg.configureX10 = false;
        cfg.configureZigBee = false;
        cfg.configureZWave = false;
        cfg.configureZigBee = false;
        break;
      case ConfigurationMode.Manual:
        cfg.includeDemo = false;
        cfg.configureGPIO = false;
        cfg.configureVoiceRecognizer = false;
        cfg.configureVoiceSynthesizer = false;
        cfg.configureX10 = false;
        cfg.configureZigBee = false;
        cfg.configureZWave = false;
        cfg.configureZigBee = false;
        cfg.restoreBackup = false;
        cfg.configureManually = true;
        break;
    }
    this.toggleInterfaceDriver('HomeAutomation.X10', cfg.configureX10);
    this.toggleInterfaceDriver('HomeAutomation.ZWave', cfg.configureZWave);
    this.toggleInterfaceDriver('HomeAutomation.ZigBee', cfg.configureZigBee);
    this.toggleInterfaceDriver('Audio.VoiceRecognizer', cfg.configureVoiceRecognizer);
    this.toggleInterfaceDriver('Audio.VoiceSynthesizer', cfg.configureVoiceSynthesizer);
    return this.config;
  }

  private toggleInterfaceDriver(domain: string, enable: boolean): void {
    this.isLoading = true;
    this.adapter.apiCall(enable
      ? HomegenieApi.Config.Interfaces.Enable(domain)
      : HomegenieApi.Config.Interfaces.Disable(domain)
    ).subscribe((res) => {
      this.adapter.reloadModules().subscribe(() => {
        // TODO: might check and report if new modules where added after enabling the interface
        this.isLoading = false;
      });
    }, (err) => {
      // TODO: handle err
      console.log(err);
      this.isLoading = false;
    });
  }
}
