interface Point {
  X: number;
  Y: number;
  IsEmpty: boolean;
}
interface PoseResult {
  Index: number;
  Point: Point;
  Confidence: number;
}
type PoseArray = PoseResult[][];
const bodyParts = [
  "Nose",
  "Left Eye",
  "Right Eye",
  "Left Ear",
  "Right Ear",
  "Left Shoulder",
  "Right Shoulder",
  "Left Elbow",
  "Right Elbow",
  "Left Wrist",
  "Right Wrist",
  "Left Hip",
  "Right Hip",
  "Left Knee",
  "Right Knee",
  "Left Ankle",
  "Right Ankle",
  "Neck" // Added Neck here!
];

function drawBodySkeleton(
  canvas: HTMLCanvasElement,
  ctx: CanvasRenderingContext2D,
  poseData: PoseArray,
  cx: number,
  cy: number
): void {

  const skeletonConnections: [number, number][] = [
    [0, 1], [0, 2], [1, 3], [2, 4],  // Face
    [0, 17], //Nose to neck
    [5, 17],[6,17], //Shoulder to neck
    [5, 7], [6, 8], [5, 11], [6, 12], // Torso/Shoulders
    [7, 9], [8, 10], // Elbows/Wrists
    [11, 12], [11, 13], [12, 14],  // Hips
    [13, 15], [14, 16], // Knees/Ankles
  ];
  const skeletonConnectionsColors: string[] = [
    "pink", "pink", "pink", "pink",  // Face
    "yellow", //Nose to neck
    "#3B58E2", "#3B58E2", //Shoulder to neck
    "cyan", "cyan", "cyan", "cyan", // Torso/Shoulders
    "yellow", "yellow", // Elbows/Wrists
    "violet", "violet", "violet",  // Hips
    "purple", "purple", // Knees/Ankles
  ];

  ctx.strokeStyle = "cyan";
  ctx.lineWidth = 1.25;
  ctx.fillStyle = "deeppink"; // Style for the points


  for (const pose of poseData) {

    //Calculate neck position
    const leftShoulder = pose[5]?.Point;
    const rightShoulder = pose[6]?.Point;
    let neckX:number|undefined, neckY:number|undefined;

    if (leftShoulder && rightShoulder && !leftShoulder.IsEmpty && !rightShoulder.IsEmpty){
      neckX = (leftShoulder.X + rightShoulder.X) / 2;
      neckY = (leftShoulder.Y + rightShoulder.Y) / 2;
    }

    // Draw the Neck point
    if(neckX !== undefined && neckY !== undefined){
      ctx.beginPath();
      ctx.arc(neckX * cx, neckY * cy, 2, 0, 2 * Math.PI); // Draw a circle at the neck
      ctx.fill();
      ctx.closePath();
    }

    // Draw the neck point into pose array for connection
    pose[17] = {
      Index: 17,
      Point: {X: (neckX ? neckX : 0), Y: (neckY ? neckY : 0), IsEmpty: neckX === undefined || neckY === undefined},
      Confidence: (pose[5]?.Confidence || 0 + pose[6]?.Confidence || 0) / 2.0  //Average of shoulders.
    } as PoseResult

    // Disegna i punti del corpo
    for (const part of pose) {
      if (part && part.Point && !part.Point.IsEmpty && part.Confidence > 0.5) { // Check for valid part and confidence
        const { X, Y } = part.Point;

        //Draw circle
        ctx.beginPath();
        ctx.arc(X * cx, Y * cy, 1.5, 0, 2 * Math.PI); // Draw a circle at each point
        ctx.fill();
        ctx.closePath();
      }
    }

    // Disegna le linee dello scheletro
    let idx = 0;
    for (const connection of skeletonConnections) {
      const [startIndex, endIndex] = connection;
      const startPart = pose[startIndex];
      const endPart = pose[endIndex];

      // Check if parts are valid and, SPECIFICALLY, if neck is valid
      if (startPart && endPart && startPart.Point && endPart.Point && !startPart.Point.IsEmpty && !endPart.Point.IsEmpty && startPart.Confidence > 0.2 && endPart.Confidence > 0.2) {
        ctx.strokeStyle = skeletonConnectionsColors[idx];
        ctx.beginPath();
        ctx.moveTo(startPart.Point.X * cx, startPart.Point.Y * cy);
        ctx.lineTo(endPart.Point.X * cx, endPart.Point.Y * cy);
        ctx.stroke();
        ctx.closePath();
      }
      idx++;
    }
  }
}


interface HandKeypoint {
  Index: number; // Anche se l'array è ordinato, manteniamo il tipo per coerenza
  Point: Point;
  Confidence: number;
}
type HandPose = HandKeypoint[];
type HandPoseOutputArray = HandPose[];
function drawHandSkeleton(
  canvas: HTMLCanvasElement,
  ctx: CanvasRenderingContext2D,
  handPoseOutputData: HandPoseOutputArray, // Usa il nuovo tipo
  cx: number,
  cy: number,
  pointConfidenceThreshold: number = 0.25,
  lineConfidenceThreshold: number = 0.2
): void {

  // ----- Hand skelton (Indexes 0-20 MediaPipe) -----
  const HAND_CONNECTIONS: [number, number][] = [
    // Palm / Wrist
    [0, 1], [0, 5], [0, 9], [0, 13], [0, 17], // Wrist to finger bases
    [5, 9], [9, 13], [13, 17], // Across finger bases
    // Thumb
    [1, 2], [2, 3], [3, 4],
    // Index Finger
    [5, 6], [6, 7], [7, 8],
    // Middle Finger
    [9, 10], [10, 11], [11, 12],

    // Ring Finger
    [13, 14], [14, 15], [15, 16],
    // Pinky Finger
    [17, 18], [18, 19], [19, 20],
  ];

  // Colors
  const HAND_CONNECTION_COLORS: string[] = [
    // Palm / Wrist
    "white", "white", "white", "white", "white",
    "white", "white", "white",
    // Thumb
    "red", "red", "red",
    // Index Finger
    "lime", "lime", "lime",
    // Middle Finger
    "blue", "blue", "blue",
    // Ring Finger
    "yellow", "yellow", "yellow",
    // Pinky Finger
    "cyan", "cyan", "cyan",
  ];

  // Default styles
  ctx.lineWidth = 2;
  ctx.fillStyle = "orange";

  for (const handPose of handPoseOutputData) {

    // 1. Draw hand keypoints
    for (const keypoint of handPose) {
      // Controlla se il punto esiste, non è vuoto e ha confidenza sufficiente
      if (keypoint && keypoint.Point && !keypoint.Point.IsEmpty && keypoint.Confidence >= pointConfidenceThreshold) {
        const { X, Y } = keypoint.Point;

        // Disegna un piccolo cerchio per il punto chiave
        ctx.beginPath();
        ctx.arc(X * cx, Y * cy, 3, 0, 2 * Math.PI); // Raggio 3
        ctx.fill();
        ctx.closePath();
      }
    }

    // 2. Draw lines connections
    for (let i = 0; i < HAND_CONNECTIONS.length; i++) {
      const connection = HAND_CONNECTIONS[i];
      const [startIndex, endIndex] = connection;

      const startPointData = handPose[startIndex];
      const endPointData = handPose[endIndex];

      // Check if both points are valid
      if (startPointData && endPointData &&
        startPointData.Point && !startPointData.Point.IsEmpty && startPointData.Confidence >= lineConfidenceThreshold &&
        endPointData.Point && !endPointData.Point.IsEmpty && endPointData.Confidence >= lineConfidenceThreshold)
      {
        // Set connection color
        ctx.strokeStyle = HAND_CONNECTION_COLORS[i] || "white"; // Usa bianco come fallback

        // Draw line
        ctx.beginPath();
        ctx.moveTo(startPointData.Point.X * cx, startPointData.Point.Y * cy);
        ctx.lineTo(endPointData.Point.X * cx, endPointData.Point.Y * cy);
        ctx.stroke();
        ctx.closePath();
      }
    }
  }
}


