import {Component, Input, OnInit} from '@angular/core';
import {Schedule, ScheduleOccurrence} from "../../../services/yot/automation";
import {DynamicOptionsBase} from "../dynamic-options-base.component";
import {SystemApi} from "../../../api/system-api";
import {HomegenieAdapter} from "../../../adapters/home-genie/homegenie-adapter";

@Component({
  selector: 'app-module-scheduling',
  templateUrl: './module-scheduling.component.html',
  styleUrls: ['./module-scheduling.component.scss']
})
export class ModuleSchedulingComponent extends DynamicOptionsBase implements OnInit {
  @Input()
  previewDate = new Date();

  schedulerItems = [] as Schedule[];
  activeItems = [] as { index: number, oldValue: boolean, newValue: boolean }[];
  occurrences: ScheduleOccurrence[] = [];

  isLoading = false;

  private readonly TimeSpanHours = 24;
  private readonly TimeSpanMilliseconds = this.TimeSpanHours*60*60000;

  get isChanged(): boolean {
    return this.activeItems.filter((a) => a.oldValue !== a.newValue).length > 0;
  }
  get serverTimeZone(): string {
    return (this.module.getAdapter() as HomegenieAdapter).systemInfo?.TimeZoneId;
  }

  ngOnInit(): void {
    this.getSchedule();
  }

  onCheckBoxChange(e, i) {
    this.activeItems[i].newValue = e.checked;
  }

  applyChanges() {
    this.isLoading = true;
    const ms = {
      include: [],
      exclude: []
    };
    this.activeItems.map((c) => {
      if (c.oldValue !== c.newValue) {
        const item = this.schedulerItems[c.index];
        if (c.newValue === true) {
          ms.include.push(item.id);
        } else {
          ms.exclude.push(item.id);
        }
      }
    });
    this.module.getAdapter()
      .system(SystemApi.Automation.Scheduling.ModuleUpdate, {
        module: this.module,
        scheduling: ms
      }).subscribe((res) => {
        // successfully applied
        this.isLoading = false;
      }, (err) => {
        // TODO: handle error
        console.log(err);
        this.isLoading = false;
      });
  }

  getScheduleOccurrence(s: Schedule): ScheduleOccurrence {
    return this.occurrences.find((o) => s.id === o.id);
  }

  refreshOccurrences(day?: Date): void {
    this.isLoading = true;
    const selectedDay = new Date(day ? day : this.previewDate);
    selectedDay.setHours(0, 0, 0, 0);
    this.module.getAdapter().system(SystemApi.Automation.Scheduling.ListOccurrences, {
      hourSpan: this.TimeSpanHours, startTimestamp: selectedDay.getTime()
    }).subscribe((res) => {
      this.occurrences = res;
      this.isLoading = false;
    }, (err) => {
      // TODO: handle error
      this.isLoading = false;
    });
  }

  private getSchedule() {
    this.isLoading = true;
    // get scheduling list
    const adapter = this.module.getAdapter();
    adapter.system(SystemApi.Automation.Scheduling.List, {
      enabled: true,
      type: this.module.type // filter by module type
    }).subscribe((res: Schedule[]) => {
      this.schedulerItems = res;
      // build active schedules list for the current module
      this.schedulerItems.forEach((s, i) => {
        const isIncluded = s.boundModules.indexOf(this.module) >= 0;
        this.activeItems[i] = { index: i, oldValue: isIncluded, newValue: isIncluded };
      })
      this.isLoading = false;
      this.refreshOccurrences();
    }, (err) => {
      // TODO: handle error
      this.isLoading = false;
    });
  }
}
