import {
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnDestroy,
  OnInit,
  Output,
  ViewChild,
  isDevMode,
  HostListener
} from '@angular/core';
import {MediaStatistics} from "../dialogs/media-center-dialog/media-center-dialog.component";
import * as moment from "moment";
import {animate, style, transition, trigger} from "@angular/animations";

export class MediaCardData {
  public id: string;
  public title: string;
  public description: string;
  public releaseDate: string;
  public duration: string;

  public detail?: any;

  public genreIdList: number[];
  public genreList: string;

  public vote: number;
  public voteCount: number;
  public popularity: number;

  public poster: string;
  public backdrop: string;
  public posterData: string;
  public backdropData: string;

  //public originCountry: string;
  public originalName: string;
  public originalLanguage: string;

  public mediaUrl: string;
  public mediaUrlBrowser: string;
}

@Component({
  selector: 'app-movie-carousel',
  templateUrl: './movie-carousel.component.html',
  styleUrls: ['./movie-carousel.component.scss'],
  animations: [
    trigger('fadeAnimation', [
      // ENTRATA (Quando *ngIf diventa true)
      transition(':enter', [
        style({ opacity: 0 }),
        animate('400ms 500ms ease-out', style({ opacity: 1 }))
      ]),

      // USCITA (Quando *ngIf diventa false)
      transition(':leave', [
        style({ opacity: 1 }),
        animate('300ms ease-in', style({ opacity: 0 }))
      ])
    ])
  ]
})
export class MovieCarouselComponent implements OnInit, OnDestroy {
  @Input() title: string;
  @Input() stats: MediaStatistics[] = [];
  @Input() highlight: boolean = false;
  @Input() focused: boolean = true;

  @Input() itemWidth: string = '200px';
  @Input() itemHeight: string = '320px';

  private _movies: MediaCardData[] = [];
  @Input()
  set movies(value: MediaCardData[]) {
    if (!this.areMoviesEqual(this._movies, value)) {
      this.isLoading = true;
      this._movies = [];
      setTimeout(() => {
        this._movies = [...value];
        this.loadViewPager();
      });
    }
  }
  get movies(): MediaCardData[] {
    return this._movies;
  }

  @ViewChild('scroller', {static: false}) scroller!: ElementRef<HTMLElement>;

  viewPager: any = null;

  protected isLoading = false;

  @Output()
  itemClicked: EventEmitter<any> = new EventEmitter();
  @Output()
  itemChanged: EventEmitter<any> = new EventEmitter();

  @Input()
  currentPage: number = 0;


  private refreshTimeout = null;
  @HostListener('window:resize', ['$event'])
  onResize(event: any) {
    clearTimeout(this.refreshTimeout);
    this.refreshTimeout = setTimeout(() => {
      this.viewPager?.refresh();
    }, 500);
  }


  constructor() { }

  ngOnInit(): void {
    this.loadViewPager();
  }

  ngOnDestroy() {
    if (this.viewPager) {
      zuix.unload(this.viewPager);
    }
  }

  setPage(page: number) {
    this.viewPager.page(page);
  }
  next() {
    this.viewPager.next();
  }
  prev() {
    this.viewPager.prev();
  }

  protected pageChanged(e, page) {
    this.currentPage = +page.in;
    const pageIn = this.viewPager.get(this.currentPage);
    if (pageIn) {
      pageIn.addClass('page-active');
    }
    const pageOut = this.viewPager.get(+page.out);
    if (pageOut) {
      pageOut.removeClass('page-active');
    }
    this.itemChanged.emit(this.movies[this.currentPage]);
  }

  protected onItemClick(m: MediaCardData) {
    if (this.movies.indexOf(m) === this.viewPager?.page()) {
      this.itemClicked.emit(m);
    } else {
      this.viewPager?.page(this.movies.indexOf(m));
    }
  }

  protected getMovieProgress(m: MediaCardData) {
    let p = 0;
    const stat = this.stats[m.id];
    if (stat) {
      p = Math.round(100 * (stat.position / this.timeToSeconds(m.duration)));
    }
    return `${p}%!important`;
  }


  private loadViewPagerTimeout = null;
  private loadViewPager() {
    clearTimeout(this.loadViewPagerTimeout);
    this.loadViewPagerTimeout = setTimeout(() => {
      this._loadViewPager();
    }, 100);
  }
  private _loadViewPager() {
    // dispose previous instance
    if (this.viewPager) {
      zuix.unload(this.viewPager);
    }
    // create new instance
    zuix.componentize(/*this.scroller.nativeElement*/);
    zuix.context(this.scroller?.nativeElement, (ctx) => {
      this.viewPager = ctx;
      this.viewPager.on('page:change', (e, page) => this.pageChanged(e, page));
      this.viewPager.page(this.currentPage, null);
      this.isLoading = false;
    });
  }

  private timeToSeconds(time: string): number {
    const d = moment.duration(time);
    return d.asSeconds();
  }

  private areMoviesEqual(newArr: MediaCardData[], oldArr: MediaCardData[]): boolean {
    // Se uno dei due è null/undefined
    if (!newArr || !oldArr) return newArr === oldArr;

    // Se la lunghezza è diversa, sono sicuramente diversi
    if (newArr.length !== oldArr.length) return false;

    // Confronto ID per ID (Molto veloce perché confronta solo stringhe)
    // .every si ferma al primo che non corrisponde
    return newArr.every((item, index) => item.id === oldArr[index].id);
  }

  protected notFinishedWatching(m: MediaCardData) {
    const duration = this.timeToSeconds(m.duration);
    const position = this.stats[m.id]?.position;
    if (position) {
      return ((this.stats[m.id]?.position / duration) * 100) > 5;
    }
    return false;
  }
}
