export class CodeEditorComponent implements OnInit, OnDestroy {
  @ViewChild('programInfo', {static: false})
  programInfo;

  @Input()
  adapter: HomegenieAdapter;
  @Input()
  program: Program;

  CodeType = SourceCodeType;
  Md5 = Md5;

  programModule: Module;
  programStatus: string;
  eventsLog: any[] = [];

  originalProgramData: string;

  theme = 'hc-light'; // 'vs-dark' // 'hc-black' // 'vs' // 'hc-light'
  codeModel: CodeModel[] = [{
    language: 'csharp',
    uri: 'program-script-main',
    value: '',
    dependencies: [ ]
  }, {
    language: 'csharp',
    uri: 'program-script-setup',
    value: '',
    dependencies: [ ]
  }, {
    language: 'csharp',
    uri: 'program-script-context',
    value: '',
    dependencies: [ ]
  }];
  extraLib: monaco.IDisposable;
  completionProvider: monaco.IDisposable;
  options: monaco.editor.IStandaloneEditorConstructionOptions = {
    lineNumbers: 'on',
    contextmenu: true,
    fixedOverflowWidgets: true,
    colorDecorators: true,
    cursorWidth: 2,
    cursorBlinking: 'expand',
    cursorSmoothCaretAnimation: 'on',
    cursorStyle: 'line',
    automaticLayout: true,
    minimap: {
      enabled: true
    },
    tabSize: 2
  };

  currentCodeModelType = SourceCodeType.SetupCode;
  enablePreview = true;
  programWidgets: DashboardWidget[] = [];
  refreshWidgetsTimeout = null;

  programErrors: any[] = [[], [], []];
  programChecksum = '';

  selectedTabIndex = 0;
  newLogEventsCount = 0;

  isLoading = false;

  programUpdateListener: Subscription;

  get isDisabled(): boolean {
    return !this.program?.IsEnabled;
  }

  get isChanged(): boolean {
    return this.originalProgramData !== JSON.stringify(this.program);
  }

  get canUpdate(): boolean {
    return (this.program && this.program.Name && this.program.Name.length > 1 && this.isChanged);
  }

  get isRunning(): boolean {
    return this.programStatus === 'Running' || this.programStatus === 'Background';
  }

  get isStopping(): boolean {
    return this.programStatus === 'Stopping' /*  || this.programStatus === 'Stopped' */;
  }
  get isCompiling(): boolean {
    return this.programStatus === 'Compile';
  }
  /*
  get hasErrors(): boolean {
    if (!this.program) return false;
    let errors = false;
    const scriptErrors = this.program.ScriptErrors ? this.program.ScriptErrors : '[]';
    if (this.programModule) {
      const errorField = this.programModule.field('Runtime.Error');
      errors = (errorField && errorField.value && errorField.value.length > 0);
    }
    return !this.isRunning && (errors || scriptErrors !== '[]');
  }
  */

  get hasConfigureOptions(): boolean {
    if (this.programModule) {
      return this.programModule.fields.findIndex(f => f.key.startsWith('ConfigureOptions.')) >= 0;
    }
    return false;
  }

  get programModules(): Module[] {
    const modules: Module[] = this.adapter.modules.filter((m) => {
      const parentId = m.Properties.find(p => p.Name === 'VirtualModule.ParentId');
      if (parentId && this.program && parentId.Value === this.program.Address.toString()
        && (m.Domain !== this.program.Domain || m.Address !== this.program.Address.toString())) {
        return true;
      }
    }).map((m) => this.adapter.yot.getModule(this.adapter.getModuleId(m), this.adapter.id));
    if (this.programModule) {
      return this.program && [...modules, this.programModule];
    }
    return this.program ? [...modules] : [];
  }

  private modulesEventSubscription: Subscription;
  private activatedRouteSubscription: Subscription;
  get isCSharpProgram(): boolean {
    return this.program?.Type.toLowerCase() === 'csharp';
  }

  @HostListener('document:keydown.control.s', ['$event'])
  onKeydownHandler(event: KeyboardEvent) {
    event.preventDefault();
    this.onBuildButtonClick(event);
  }

  constructor(private yot: YotService,
              private navigationService: NavigationService,
              private aiChatService: AiChatService,
              private dialog: MatDialog,
              private route: ActivatedRoute)
  {
    this.theme = yot.preferences.ui.theme === 'light' ? 'vs' : 'vs-dark';
  }

  ngOnInit(): void {
    this.activatedRouteSubscription = this.route.params.subscribe(params => {
      this.selectedTabIndex = 0;
      this.refresh(() => {
        if (this.program.Type.toLowerCase() === 'csharp') {

// TODO: implement completion provider for C# API below

          this.completionProvider = monaco.languages.registerCompletionItemProvider('csharp', {
            provideCompletionItems: function(model, position) {
              // find out if we are completing a property in the 'dependencies' object.
              const textUntilPosition = model.getValueInRange({
                startLineNumber: 1,
                startColumn: 1,
                endLineNumber: position.lineNumber,
                endColumn: position.column
              });
              const word = model.getWordUntilPosition(position);
// TODO: ...
              let match = false;
              if (!match) {
                return { suggestions: [] };
              }
              const range = {
                startLineNumber: position.lineNumber,
                endLineNumber: position.lineNumber,
                startColumn: word.startColumn,
                endColumn: word.endColumn
              };
              return {
                suggestions: [ 'test' ]
              };
            }
          } as any /* as CompletionItemProvider */);

        }
        // load JS API defs for Monaco editor
        this.adapter.yot.http.get('assets/editor/homegenie-js-app-api.js', {responseType: 'text'})
          .subscribe((res) => {
            //console.log(res, monaco.languages);
            this.extraLib = monaco.typescript.javascriptDefaults.addExtraLib(res);
          });
      });
      // subscribe to module events
      this.modulesEventSubscription?.unsubscribe();
      this.modulesEventSubscription = this.adapter.onModuleEvent.subscribe(({module, event}) => {
        if (this.programModules && this.programModules.includes(module)) {
          if (module === this.programModule) {
            switch (event.Property) {
              case 'Program.Status':
                this.programStatus = event.Value;
                this.refresh();
                /*
                if (!this.isLoading) {
                  if (this.programStatus === 'Running' || this.programStatus === 'Idle') {
//                  this.refreshProgramWidgets();
                  } else if (this.programStatus === 'Disabled' || this.programStatus === 'Enabled') {
                    this.refresh();
                  } else if (this.programStatus === 'Compile' || this.programStatus === 'Stopping') {
                    this.isLoading = true;
                  }
                } else if (this.programStatus === 'Stopped' || this.programStatus === 'Enabled') {
                  this.isLoading = false;
                }*/
                break;
              case 'Compiler.Warning':
//                this.adapter.yot
//                  .notify("Compiler warning", event.Value);
                break;
              case 'Runtime.Error':
                if (event.Value.length > 0) {
                  this.adapter.yot
                    .notify("Runtime error", event.Value);
                }
                break;
              case 'Program.Event':
                // TODO: handle 'MODULE_ADDED ' and 'MODULE_REMOVED ' events
                this.refreshProgramWidgets();
                break;
            }
            // TODO: ....
          }
          if (module && event.Property === 'Widget.DisplayModule') {
            // widget changed
            this.programWidgets.forEach((w) => {
              if (w.module && this.yot.getModuleByRef(w.module) === module) {
                w.type = module.getWidgetData().type;
              }
            });
          }
          // prepend event
          event.module = module;
          this.eventsLog = [event, ...this.eventsLog];
          if (this.selectedTabIndex !== EVENTS_LOG_TAB_INDEX) {
            this.newLogEventsCount++;
          }
        }
      });
    });

    setTimeout(() => {
      this.refresh();
    }, 300);

    this.yot.layoutService.contextualHelpLink = 'https://homegenie.it/api/2.0/ape/annotated.html';


    this.programUpdateListener = this.yot.onProgramUpdated.subscribe({
      next: (p) => {
//console.log("Injecting AI code into Editor with Undo support:", p);

        const updateModelWithUndo = (type: SourceCodeType, newValue: string) => {
          if (!newValue) return;

          const cm = this.codeModel[type];
          cm.value = newValue; // Aggiorna il riferimento locale
          const model = monaco.editor.getModel(`file:///${cm.uri}` as any);

          if (model) {
            // Applichiamo l'operazione di modifica invece di setValue
            model.pushEditOperations(
              [], // Non preserviamo lo stato del cursore specifico
              [
                {
                  range: model.getFullModelRange(), // Seleziona tutto il documento attuale
                  text: newValue,                   // Sostituisci con il nuovo codice
                },
              ],
              () => null // Funzione per il cursore post-operazione
            );

            this.triggerFormat(model);
          }
        };

        // Eseguiamo l'aggiornamento per i tre blocchi
        updateModelWithUndo(SourceCodeType.SetupCode, p.setup);
        updateModelWithUndo(SourceCodeType.MainCode, p.main);
        updateModelWithUndo(SourceCodeType.ContextCode, p.context);

        if (p.save && !this.isLoading) {
          setTimeout(() => {
            this.onBuildButtonClick(null);
          }, 500);
        }
      }
    });
  }
  ngOnDestroy() {
    this.yot.layoutService.contextualHelpLink = '';

    if (this.modulesEventSubscription) {
      this.modulesEventSubscription.unsubscribe();
    }
    if (this.activatedRouteSubscription) {
      this.activatedRouteSubscription.unsubscribe();
    }
    if (this.extraLib) {
      this.extraLib.dispose();
    }
    if (this.completionProvider) {
      this.completionProvider.dispose();
    }

    this.programUpdateListener?.unsubscribe();
  }
  /**
   * Helper to trigger Monaco auto-format after injection
   */
  private triggerFormat(model: any) {
    setTimeout(() => {
      // La formattazione avviene solo se il modello è quello attualmente visualizzato
      const cm = this.codeModel[this.currentCodeModelType];
      let currentModel = monaco.editor.getModel(`file:///${cm.uri}` as any);
      if (currentModel === model) {
        monaco.editor.getEditors()[this.currentCodeModelType].trigger('',  'editor.action.formatDocument', undefined);
      }
    }, 150);
  }

  onMainCodeChanged(code: string) {
    this.program.ScriptSource = code;
  }
  onSetupCodeChanged(code: string) {
    this.program.ScriptSetup = code;
  }
  onContextCodeChanged(code: string) {
    this.program.ScriptContext = code;
  }

  onBuildButtonClick(e) {
    this.isLoading = true;
    this.program.ScriptSetup = this.codeModel[SourceCodeType.SetupCode].value;
    this.program.ScriptSource = this.codeModel[SourceCodeType.MainCode].value;
    this.program.ScriptContext = this.codeModel[SourceCodeType.ContextCode].value;
    this.adapter.apiCall(HomegenieApi.Automation.Programs.Compile, this.program)
      .subscribe((res) => {
        const compilerErrors: CompilerErrors[] = res.response;
        this.program.ScriptErrors = JSON.stringify(compilerErrors);
        this.refreshProgramErrors();
        const errors = this.programErrors[0].length + this.programErrors[1].length + this.programErrors[2].length;
        const aiChatProvider = this.aiChatService.getCurrentAiChatGenie();
        if (errors > 0 && aiChatProvider?.providerId === 931 /* 931 = Gemini Widget Genie */ ) {
          // Set the Prompt Hint that will be shown in tha chat window
          // with "Ask AI" button that inject the fix-code request

          this.yot.translate.get(['error_compiling_program', 'line_number'], {
            address: this.program.Address
          }).subscribe((tr) => {

            let errorReport = `${tr['error_compiling_program']}\n`;
            if (this.programErrors[0].length > 0) {
              errorReport += `\n[MAIN]\n`;
              this.programErrors[0].map((error) => {
                errorReport += `- ${tr['line_number']} ${error.startLineNumber}: ${error.message}\n`;
              });
            }
            if (this.programErrors[1].length > 0) {
              errorReport += `\n[SETUP]\n`;
              this.programErrors[1].map((error) => {
                errorReport += `- ${tr['line_number']} ${error.startLineNumber}: ${error.message}\n`;
              });
            }
            if (this.programErrors[2].length > 0) {
              errorReport += `\n[CONTEXT]\n`;
              this.programErrors[2].map((error) => {
                errorReport += `- ${tr['line_number']} ${error.startLineNumber}: ${error.message}\n`;
              });
            }
            errorReport += `\n`;

            this.aiChatService.promptHint = errorReport;

          });

        } else if (errors === 0) {

          this.aiChatService.promptHint = '';

        }
        this.isLoading = false;
        this.setUnchanged();
      }, () => {this.isLoading = false});
  }
  onRunButtonClick(e) {
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Automation.Programs.Run(this.program.Address))
      .subscribe(() => {
        this.isLoading = false;
      });
    if (this.isChanged) {
      this.yot.translate.get(['unsaved_changes', 'save_to_apply_program_changes']).subscribe((tr) => {
        this.yot.notify(tr['unsaved_changes'], tr['save_to_apply_program_changes'], {
          verticalPosition: 'bottom',
          data: {action: undefined}
        });
      });
    }
  }
  onStopButtonClick(e) {
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Automation.Programs.Break(this.program.Address))
      .subscribe(() => {
        this.isLoading = false;
      });
    // TODO: ....
  }
  onEnableButtonClick(e) {
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Automation.Programs.Enable(this.program.Address))
      .subscribe((res) => {
        this.isLoading = false;
        this.refresh();
      });
    // TODO: ...
  }
  onDisableButtonClick(e) {
    this.isLoading = true;
    this.adapter.apiCall(HomegenieApi.Automation.Programs.Disable(this.program.Address))
      .subscribe((res) => {
        this.isLoading = false;
        this.refresh();
      });
    // TODO: ...
  }
  onSettingsButtonClick(e) {
    this.programModule.description = this.program.Description;
    // translate Name and Description
    const titleKey = `${this.adapter.translationPrefix}.$options.${this.program.Address}.Title`;
    this.yot.translate.get(titleKey).subscribe((tr) => {
      if (tr !== titleKey) {
        this.programModule.name = tr;
      }
    });
    const descriptionKey = `${this.adapter.translationPrefix}.$options.${this.program.Address}.Description`;
    this.yot.translate.get(descriptionKey).subscribe((tr) => {
      if (tr !== descriptionKey) {
        this.programModule.description = tr;
      }
    });
    const dialogRef = this.dialog.open(ModuleSettingsDialogComponent, {
      panelClass: 'dialog-no-padding',
      width: '100%',
      minWidth: '280px',
      maxWidth: '576px',
      disableClose: false,
      data: {module: this.programModule, options: this.programModule.getWidgetData()}
    });
  }

  onCodeTabChanged(index: number) {
    if (index === 0) {
      // TODO: ...
      return;
    }
    const ct = index - 1;
    if (ct === SourceCodeType.SetupCode || ct === SourceCodeType.MainCode || ct === SourceCodeType.ContextCode) {
      this.program.ScriptSetup = this.codeModel[SourceCodeType.SetupCode].value;
      this.program.ScriptSource = this.codeModel[SourceCodeType.MainCode].value;
      this.program.ScriptContext = this.codeModel[SourceCodeType.ContextCode].value;
      this.currentCodeModelType = ct;
      this.refreshProgramErrors();
      return;
    }
    // Log events
    if (index === EVENTS_LOG_TAB_INDEX) {
      this.newLogEventsCount = 0;
    }
  }

  onWidgetActionRequest(request: WidgetActionRequest, moduleRef?: ModuleReference): void {

    if (request.action === WidgetActionRequestAction.removeWidget && moduleRef) {
      return;
    }
    let dialogComponent;
    let dialogWidth = '576px';
    // TODO: add enum for dialog names (see `widget-actions-menu.component.ts`)
    switch (request.action) {
      case WidgetActionRequestAction.showSettings:
        dialogComponent = ModuleSettingsDialogComponent;
        break;
      case WidgetActionRequestAction.showStatistics:
        dialogComponent = ModuleStatisticsDialogComponent;
        dialogWidth = '960px';
        break;
      case WidgetActionRequestAction.showSchedule:
        dialogComponent = ModuleSchedulingDialogComponent;
        break;
      case WidgetActionRequestAction.showLogs:
        dialogComponent = ModuleEventsDialogComponent;
        break;
      case WidgetActionRequestAction.showEdit:
        dialogComponent = ModuleEditDialogComponent;
        break;
    }
    if (dialogComponent) {
      const module = this.adapter.yot.getModuleByRef(moduleRef);
      const dialogRef = this.dialog.open(dialogComponent, {
        panelClass: 'dialog-no-padding',
        width: '100%',
        minWidth: '280px',
        maxWidth: dialogWidth,
        disableClose: false,
        data: {module, options: module.getWidgetData()}
      });
    }

  }


  private refreshTimeout = null;
  refresh(callback?): void {
    clearTimeout(this.refreshTimeout);
    this.isLoading = true;
    this.refreshTimeout = setTimeout(() => {

      if (this.program) {

        this._refreshProgramWidgets() // TODO: this should be refreshed automatically
          .subscribe((res) => {

            this.adapter.loadPrograms().subscribe((programs) => {

              const prg = programs.find((p) => p.Address === this.program.Address);
              if (prg) {
                this.program = prg;
              }

              this.programChecksum = (Md5.hashStr(JSON.stringify({
                setup: this.program.ScriptSetup,
                source: this.program.ScriptSource,
                context: this.program.ScriptContext,
                data: this.program.Data
              })) as string).toUpperCase();

              this.programModule = this.adapter.getModuleByRef(this.program as any); // || this.programModule;

              if (this.programModule) {
                const status = this.programModule.field('Program.Status');
                this.programStatus = status && status.value !== 'Compile' ? status.value : 'Disabled';
              }
              this.refreshProgramErrors();

              this.codeModel.map((cm) => cm.language = this.program.Type.toLowerCase());
              this.codeModel[SourceCodeType.SetupCode].value = this.program.ScriptSetup;
              this.codeModel[SourceCodeType.MainCode].value = this.program.ScriptSource;
              this.codeModel[SourceCodeType.ContextCode].value = this.program.ScriptContext;
              this.setUnchanged();

              this.isLoading = false;
              if (callback) callback();

            });

          }, (err) => {
            console.log(err);

            this.isLoading = false;
            if (callback) callback();

          });
      }

    }, 500);
  }

  refreshProgramWidgets() {
    clearTimeout(this.refreshWidgetsTimeout);
    this.refreshWidgetsTimeout = setTimeout(() => {
      this._refreshProgramWidgets().subscribe({
        next: (res) => {},
        error: (err) => {},
        complete: () => {}
      });
    }, 500);
  }

  private _refreshProgramWidgets(): Subject<any> {
    const subject = new Subject();
    this.adapter.reloadModules().subscribe((modules) => {
      const widgets: DashboardWidget[] = [];
      this.programModules.forEach((m) => {
        const data = m.getWidgetData();
        if (data) {
          widgets.push({
            type: data.type,
            module: {adapterId: m.adapterId, moduleId: m.id},
            data
          });
        }
      });
      this.programWidgets = [...widgets];
      subject.next(null);
      subject.complete();
    }, (err) => {subject.error(err);});
    return subject;
  }

  private refreshProgramErrors() {
    let compilerErrors: string | CompilerErrors[] = this.program.ScriptErrors;
    if (typeof compilerErrors === 'string' && compilerErrors.length > 0) {
      try {
        compilerErrors = JSON.parse(compilerErrors);
      } catch {
        compilerErrors = [{
          Line: 0, EndLine: 0,
          Column: 0, EndColumn: 0,
          ErrorMessage: compilerErrors as string, ErrorNumber: '500',
          CodeBlock: "TC"
        }];
      }
    } else {
      compilerErrors = [];
    }
    this.programErrors = [[], [], []];
    (compilerErrors as CompilerErrors[]).forEach((ce) => {
      // CR = Code to Run (main) / TC = Trigger Code (setup)
      const codeModelIndex = ce.CodeBlock === 'CR'
        ? SourceCodeType.MainCode
        : ((ce.CodeBlock === 'PC')
            ? SourceCodeType.ContextCode
            : SourceCodeType.SetupCode
          );
      this.programErrors[codeModelIndex].push({
        startLineNumber: ce.Line,
        startColumn: ce.Column,
        endLineNumber: ce.EndLine,
        endColumn: ce.EndColumn,
        message: ce.ErrorMessage,
        severity: monaco.MarkerSeverity.Error
      });
    });
    const cm = this.codeModel[this.currentCodeModelType];
    if (monaco && cm) {
      try {
        const model = monaco.editor.getModel(`file:///${cm.uri}` as any);
        // Update error markers
        const errors = this.programErrors[this.currentCodeModelType];
        monaco.editor.setModelMarkers(model, 'compiler', errors);
      } catch (e) {
        console.log(e)
      }
    }
  }

  private setUnchanged() {
    this.originalProgramData = JSON.stringify(this.program);
  }
}
