import {Component, ElementRef, Inject, OnDestroy, OnInit, ViewChild} from '@angular/core';
import {HomegenieApi, ResponseStatus} from "../../homegenie-api";
import {ApiResponse, HomegenieAdapter} from "../../homegenie-adapter";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {Subscription} from "rxjs";
import * as moment from "moment/moment";

enum ManualUpdateStep {
  FileSelect,
  InstallRelease
}

enum InstallStatus {
  Installing,
  Installed,
  Error
}

@Component({
  selector: 'app-update-file-dialog',
  templateUrl: './update-file-dialog.component.html',
  styleUrls: ['./update-file-dialog.component.scss']
})
export class UpdateFileDialogComponent implements OnInit, OnDestroy {
  @ViewChild('terminalConsole', {static: false})
  terminalConsole: ElementRef;

  adapter: HomegenieAdapter;

  isLoading = false;
  isWaitingRestart = false;
  uploadedFiles: Array<File> = [];

  private _installStep: ManualUpdateStep = ManualUpdateStep.FileSelect;
  get installStep(): ManualUpdateStep {
    return this._installStep;
  }
  set installStep(step: ManualUpdateStep) {
    this._installStep  = step;
    if (this.installStep === ManualUpdateStep.InstallRelease) {
      this.installReleaseFile(this.uploadedFiles[0]);
    }
  }

  private _progressMessage = '';
  get progressMessage(): string {
    return this._progressMessage;
  }
  set progressMessage(message: string) {
    this._progressMessage = message;
    const scrollElement = this.terminalConsole?.nativeElement;
    if (scrollElement) {
      setTimeout(() => scrollElement.scrollTop = scrollElement.scrollHeight);
    }
  }

  serverBootProgress = 0;
  installStatus = InstallStatus.Installing;
  InstallStatus = InstallStatus;

  ManualUpdateStep = ManualUpdateStep;

  createBackup = true;

  private moduleEventSubscription: Subscription;

  constructor(@Inject(MAT_DIALOG_DATA) data) {
    this.adapter = data.adapter;
  }

  ngOnInit(): void {
    this.moduleEventSubscription =  this.adapter.onModuleEvent.subscribe((data) => {
      const e = data.event;
      if (e.Domain === 'HomeGenie.UpdateChecker' && e.Source === "0" && e.Property === 'InstallProgress.Message') {
        this.progressMessage += `${e.Value}\n`;
      } else if (this.isWaitingRestart && e.Domain === 'HomeGenie.System') {
        if (e.Property === 'SystemInfo.BootProgress') {
          this.serverBootProgress = +(e.Value.replace(',', '.'));
        } else if (e.Property === 'HomeGenie.Status' && e.Value === "STARTED") {
          this.isWaitingRestart = false;
          this.isLoading = false;
          this.installStatus = InstallStatus.Installed;
        }
      }
    });
  }
  ngOnDestroy() {
    this.moduleEventSubscription.unsubscribe();
  }

  onUpdateFileSelected() {
    if (this.uploadedFiles.length > 0) {
      // user must press confirm button to actually start the upload
    } else {
      // console.log('NO FILE SELECTED!');
    }
  }
  onConfirmButtonClick() {
    this.installStatus = InstallStatus.Installing;
    if (this.createBackup) {
      this.isLoading = true;
      this.adapter.apiCall(HomegenieApi.SystemConfig.System.ConfigurationBackup, null, {
        responseType: 'blob'
      }).subscribe({
        next: (ar) => {
          const a = document.createElement('a')
          const objectUrl = URL.createObjectURL(ar.response)
          a.href = objectUrl
          a.download = `homegenie_backup_${moment().format('YYYYMMDD_HHmmss')}.zip`;
          a.click();
          URL.revokeObjectURL(objectUrl);
          this.isLoading = false;
          this.installStep = ManualUpdateStep.InstallRelease;
        },
        error: (err) => {
          const yot = this.adapter.yot;
          yot.translate.get('error_occurred')
            .subscribe((tr) => {
              yot.notify(tr, err.message);
            });
          this.isLoading = false;
          this.installStatus = InstallStatus.Error;
        }
      });
    } else {
      this.installStep = ManualUpdateStep.InstallRelease;
    }
  }

  private installReleaseFile(file: File) {
    this.isLoading = true;
    let formData:FormData = new FormData();
    formData.append('uploadFile', file, file.name);
    this.adapter.apiCall(HomegenieApi.SystemConfig.UpdateManager.ManualUpdate(file.name), formData)
      .subscribe({
        next: (ar: ApiResponse) => {
          if (ar.response?.Status === ResponseStatus.Ok) {
            this.isWaitingRestart = ar.response.Message === "RESTART";
          } else {
            this.installStatus = InstallStatus.Error;
          }
          this.uploadedFiles = [];
          this.isLoading = false;
          if (!this.isWaitingRestart) {
            this.installStatus = InstallStatus.Installed;
          }
        },
        error: (err) => {
          const yot = this.adapter.yot;
          yot.translate.get('error_occurred')
            .subscribe((tr) => {
              yot.notify(tr, err.message);
            });
          this.installStatus = InstallStatus.Error;
          this.uploadedFiles = [];
          this.isLoading = false;
        }
      });
  }
}
