import {Component, EventEmitter, Input, OnInit, Output} from '@angular/core';
import {Module} from "../../../services/yot/module";
import {SystemApi} from "../../../api/system-api";
import {YotService} from "../../../services/yot/yot.service";
import {DashboardWidget} from "../../../services/dashboard/dashboard";
import {DashboardLayoutEventValue} from "../../../services/dashboard/dashboard.service";

export class WidgetActionRequest {
  action: WidgetActionRequestAction;
  data?: any;
}

export enum WidgetActionRequestAction {
  showSettings = 'show-settings',
  showSchedule = 'show-schedule',
  showLogs = 'show-logs',
  showStatistics = 'show-statistics',
  showEdit = 'show-edit',
  showChartEdit = 'show-chart-edit',
  showCustomWidgetOptions = 'show-custom-widget-options',
  removeWidget = 'remove-widget',
  resizeWidget = 'resize-widget',
  requestLayout = 'request-layout',
  startRowToggle = 'start-row-toggle'
}

@Component({
  selector: 'app-widget-actions-menu',
  templateUrl: './widget-actions-menu.component.html',
  styleUrls: ['./widget-actions-menu.component.scss']
})
export class WidgetActionsMenuComponent implements OnInit {
  @Input()
  widget: DashboardWidget;
  @Input()
  enableEdit: boolean;
  @Input()
  enableChartsMenu: boolean;
  @Input()
  hideStartNewRowOption: boolean;
  @Input()
  hideRemoveOption: boolean;
  @Input()
  hideSettings: boolean;
  @Input()
  customMenuIcon: string;
  @Input()
  sizeOptions: string[];
  @Input()
  isCustomWidget: boolean;
  @Input()
  hasCustomSettings: boolean;
  @Input()
  customSettingsLabel: string;
  @Output()
  widgetActionRequest = new EventEmitter<WidgetActionRequest>();

  @Input() temporary = false;

  schedulesCount = 0;

  ActionRequest = WidgetActionRequestAction;

  hasStatisticsFields = false;

  module: Module;

  constructor(private yot: YotService,) { }

  ngOnInit() {
    this.module = this.yot.getModuleByRef(this.widget?.module);
  }

  onMenuOpened(): void {
    this.module?.getAdapter()
      ?.system(SystemApi.Automation.Scheduling.List, {
        enabled: true,
        type: this.module.type
      })
      .subscribe((res) => {
        this.schedulesCount = res.length;
      });
    this.hasStatisticsFields = this.module?.getStatsFields().length > 0;
  }

  onMenuButtonClick(action: WidgetActionRequestAction): void {
    this.widgetActionRequest.emit({action: action});
  }

  setSize(size: '' | 'small' | 'medium' | 'big' | 'auto') {
    this.widget.configuration = this.widget.configuration || {};
    this.widget.configuration.size = size;
    if (!this.temporary) this.yot.saveConfiguration();
    this.widgetActionRequest
      .emit({action: WidgetActionRequestAction.resizeWidget, data: size});
    if (!this.temporary) this.yot.dashboardService.layoutEvents
      .next(DashboardLayoutEventValue.LayoutRefresh);
  }
}
