import {Component, EventEmitter, Input, OnDestroy, OnInit, Output, ViewChild} from '@angular/core';
import {Program} from "../../../adapters/home-genie/homegenie-api";
import {HomegenieAdapter} from "../../../adapters/home-genie/homegenie-adapter";
import {Module, ModuleField} from "../../../services/yot/module";
import {Subscription} from "rxjs";
import {Md5} from "ts-md5";
import {MatMenuTrigger} from "@angular/material/menu";
import {
  ModuleSettingsDialogComponent
} from "../../../components/dialogs/module-settings-dialog/module-settings-dialog.component";
import {YotService} from "../../../services/yot/yot.service";
import {MatDialog} from "@angular/material/dialog";

export class AutomationItemAction {
  item: Program;
  type: AutomationItemActionType;
}
export enum AutomationItemActionType {
  Edit,
  Enable,
  Disable,
  Run,
  Stop,
  Delete,
  Export,
  Clone,
  Restore,
  Upgrade
}

@Component({
  selector: 'app-automation-list-item',
  templateUrl: './automation-list-item.component.html',
  styleUrls: ['./automation-list-item.component.scss']
})
export class AutomationListItemComponent implements OnInit, OnDestroy {
  @Input()
  adapter: HomegenieAdapter;
  @Input()
  program: Program;
  @Input()
  packages: any[];
  @Output()
  itemActionRequest = new EventEmitter<AutomationItemAction>();

  @ViewChild(MatMenuTrigger)
  contextMenu: MatMenuTrigger;

  menuPosition = { x: 0, y: 0 };

  programModule: Module;
  programStatus: ModuleField;

  automanStatus: ModuleField;
  automanMessage: ModuleField;
  automanProgress: ModuleField;

  isLoading = false;

  programChecksum = '';
  updateAvailable: any = null;

  get hasConfigurationOptions(): boolean {
    return this.program?.IsEnabled
      && (this.programModule?.fields.find((f) => f.key.startsWith('ConfigureOptions.'))) != null;
  }

  get isRunning(): boolean {
    return this.program?.IsEnabled && (this.programStatus?.value === 'Running' || this.programStatus?.value === 'Background');
  }

  private modulesEventSubscription: Subscription;
  private _shouldShowAutomanStatus: boolean;
  get shouldShowAutomanStatus(): boolean {
    return this.automanStatus && this.automanMessage?.value?.length > 0
      && (this.automanStatus?.value !== 'Completed' || (Date.now() - this.automanStatus?.timestamp < 30000));
  }

  constructor(
    private yot: YotService,
    private dialog: MatDialog) { }

  ngOnInit(): void {
    this.programModule = this.adapter.getModuleByRef(this.program as any);
    this.checkDynamicField();
    this.modulesEventSubscription = this.adapter.onModuleEvent.subscribe(({module, event}) => {
      if (module === this.programModule) {
        this.checkDynamicField();
        switch (event.Property) {
          case 'Program.Status':
// TODO: this is now a reactive property (read: this case should be removed)
            //this.programStatus = event.Value;
            break;
          case 'Runtime.Error':
            if (event.Value.length > 0) {
              this.adapter.yot
                .notify("Runtime error", event.Value);
            }
            break;
        }
      }
    });
    this.programChecksum = (Md5.hashStr(JSON.stringify({
      setup: this.program.ScriptSetup,
      source: this.program.ScriptSource,
      context: this.program.ScriptContext,
      data: this.program.Data
    })) as string).toUpperCase();
    // version update check
    const pi = this.program.PackageInfo;
    const repositoryPackage = this.packages.find(p => p.repository === pi.repository && p.id == pi.packageId);
    if (repositoryPackage) {
      const repositoryProgram = repositoryPackage.programs.find(prg => prg.id === pi.id)
      if (repositoryProgram) {
        const versionStatus = this.adapter.yot.util.versionCompare(repositoryProgram.version, pi.version);
        if (versionStatus > 0) {
          this.updateAvailable = repositoryProgram;
        }
      }
    }
  }

  ngOnDestroy() {
    this.modulesEventSubscription?.unsubscribe();
  }

  onSettingsButtonClick(e) {
    this.programModule.description = this.program.Description;
    // translate Name and Description
    const titleKey = `${this.adapter.translationPrefix}.$options.${this.program.Address}.Title`;
    this.yot.translate.get(titleKey).subscribe((tr) => {
      if (tr !== titleKey) {
        this.programModule.name = tr;
      }
    });
    const descriptionKey = `${this.adapter.translationPrefix}.$options.${this.program.Address}.Description`;
    this.yot.translate.get(descriptionKey).subscribe((tr) => {
      if (tr !== descriptionKey) {
        this.programModule.description = tr;
      }
    });
    const dialogRef = this.dialog.open(ModuleSettingsDialogComponent, {
      panelClass: 'dialog-no-padding',
      width: '100%',
      minWidth: '280px',
      maxWidth: '576px',
      disableClose: false,
      data: {module: this.programModule, options: this.programModule.getWidgetData()}
    });
  }
  onEditButtonClick(e) {
    this.itemActionRequest &&
    this.itemActionRequest.next({item: this.program, type: AutomationItemActionType.Edit});
  }
  onRunButtonClick(e) {
    this.itemActionRequest &&
    this.itemActionRequest.next({item: this.program, type: AutomationItemActionType.Run});
  }
  onEnableButtonClick(e) {
    this.itemActionRequest &&
    this.itemActionRequest.next({item: this.program, type: AutomationItemActionType.Enable});
  }
  onDisableButtonClick(e) {
    this.itemActionRequest &&
    this.itemActionRequest.next({item: this.program, type: AutomationItemActionType.Disable});
  }
  onStopButtonClick(e) {
    this.itemActionRequest &&
    this.itemActionRequest.next({item: this.program, type: AutomationItemActionType.Stop});
  }
  onDeleteButtonClick(e) {
    this.itemActionRequest &&
    this.itemActionRequest.next({item: this.program, type: AutomationItemActionType.Delete});
  }
  onCloneButtonClick(e) {
    this.itemActionRequest &&
    this.itemActionRequest.next({item: this.program, type: AutomationItemActionType.Clone});
  }

  onRestoreButtonClick($event: MouseEvent) {
    this.itemActionRequest &&
    this.itemActionRequest.next({item: this.program, type: AutomationItemActionType.Restore});
  }

  onUpgradeButtonClick($event: MouseEvent) {
    this.itemActionRequest &&
    this.itemActionRequest.next({item: this.program, type: AutomationItemActionType.Upgrade});
  }


  protected onLeftClick($event: MouseEvent) {
    if (($event.target as any).tagName.toLowerCase() !== 'svg-icon') {
      this.menuPosition.x = $event.clientX;
      this.menuPosition.y = $event.clientY;
      setTimeout(() => {
        this.contextMenu.openMenu();
      });
    }
  }


  private checkDynamicField() {
    if (this.programModule) {
      if (!this.programStatus) this.programStatus = this.programModule.field('Program.Status');
      if (!this.automanProgress) this.automanProgress = this.programModule.field('Automan.Program.Progress');
      if (!this.automanMessage) this.automanMessage = this.programModule.field('Automan.Program.Message');
      if (!this.automanStatus) this.automanStatus = this.programModule.field('Automan.Program.Status');
    }
  }
}
