import {Component, OnInit, ViewChild} from '@angular/core';
import {ControlFieldBase} from "../control-field-base";
import {MatSelect} from "@angular/material/select";

export class SelectOption {
  description: string;
  value: string;
}

@Component({
  selector: 'app-select',
  templateUrl: './select.component.html',
  styleUrls: ['./select.component.scss']
})
export class SelectComponent extends ControlFieldBase implements OnInit {
  @ViewChild('select')
  select: MatSelect;

  options: Array<SelectOption> = [];

  ngOnInit(): void {
    super.ngOnInit();
    if (this.data.type.options[0]) {
      this.options = this.data.type.options[0].split(',').map((o) => {
        const description = o.split('=')[0];
        const value = o.split('=')[1];
        return {
          description, value
        };
      });
    }
  }

  reset() {
    super.reset();
    this.select.value = this.originalValue;
  }

}
