import {Component, OnInit} from '@angular/core';
import {YotService} from '../../services/yot/yot.service';
import {HomegenieAdapter} from "../../adapters/home-genie/homegenie-adapter";
import {environment} from "../../../environments/environment";
import {Router} from "@angular/router";
import {Adapter} from "../../adapters/adapter";
import {PagesRoute} from "../../pages-route";
import {ClientConfigService} from "../../services/client-config.service";
import {NavigationService} from "../../services/navigation.service";
import {VoiceControlService} from "../../services/voice-control.service";

@Component({
  selector: 'app-setup-page',
  templateUrl: './setup-page.component.html',
  styleUrls: ['./setup-page.component.scss']
})
export class SetupPageComponent implements OnInit {

  selectedAdapter: Adapter;

  isConfiguringAdapter: boolean = false;

  get isLoading(): boolean {
    return !this.isConfigured && this.navigationService.isLoading;
  }

  get isConfigured(): boolean {
    return this.yot.getAdapters().length > 0;
  }

  constructor(public yot: YotService, private clientConfigService: ClientConfigService, private voiceControlService: VoiceControlService, private navigationService: NavigationService, private router: Router) {
    // add default adapter if YoT is not configured
    if (!this.isConfigured) {
      this.isConfiguringAdapter = true;
// TODO: following code should be optimized...
      const homegenieAdapter = new HomegenieAdapter(yot);
      if (environment.production) {
        // config for direct connection to HG API on the same http server as app
        homegenieAdapter.options = {
          config: {
            connection: {
              localRoot: '/',
              address: yot.getHostname(),
              websocketPort: 8188,
              ssl: (window.location.protocol === 'https:')
            },
          },
        };
      } else if (environment.proxy) {
        // config for connection through angular proxy (see: 'src/proxy.conf.json')
        // to proxy HG API service to local Angular HTTP service (mg serve)
        homegenieAdapter.options = {
          config: {
            connection: {
              address: yot.getHostname(),
              port: yot.getHostPort(),
              websocketPort: 4200,
              ssl: (window.location.protocol === 'https:')
            },
          },
        };
      } else {
        // config for direct connection to HG API on different http server
        homegenieAdapter.options = {
          config: {
            connection: {
              address: 'localhost',
              port: 8080,
              ssl: false,
              websocketPort: 8188
            },
          },
        };
      }

      yot.addAdapter(homegenieAdapter);

      const redirectToHomePage = () => {
        this.isConfiguringAdapter = false;
        this.router.navigate([ PagesRoute.HomePage ])
          .then((res) => {
            // TODO:

            this.voiceControlService
              .setLanguage(this.yot.translate.currentLang);

            this.navigationService.isLoading = false;
          });
      };
      const connect = () => {
        homegenieAdapter.connect()
          .subscribe({
            complete: () => redirectToHomePage(),
            error: () => redirectToHomePage()
          });
      };
      this.navigationService.isLoading = true;
      this.clientConfigService
        .loadClientPreset(this.yot.clientPreset)
        .subscribe({
         complete: () => connect(),
         error: () => connect()
        });
    }
  }

  ngOnInit(): void {
    this.selectedAdapter = this.yot.getDefaultAdapter();
    this.navigationService.toolbarTitle.emit('settings');

    this.yot.layoutService.contextualHelpLink = 'https://homegenie.it/server/settings/';
  }
  ngOnDestroy(): void {
    this.yot.layoutService.contextualHelpLink = '';
  }

}
