import {Component, Inject, OnInit, ViewChild} from '@angular/core';
import {Module} from "../../../services/yot/module";
import {YotService} from "../../../services/yot/yot.service";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {ModuleInfoComponent} from "../../forms/module-info/module-info.component";

@Component({
  selector: 'app-module-edit-dialog',
  templateUrl: './module-edit-dialog.component.html',
  styleUrls: ['./module-edit-dialog.component.scss']
})
export class ModuleEditDialogComponent implements OnInit {
  @ViewChild('moduleInfoComponent', {static: false})
  moduleInfoComponent: ModuleInfoComponent;

  module: Module;

  get isChanged(): boolean {
    return this.moduleInfoComponent && this.moduleInfoComponent.isChanged;
  }

  get hasErrors(): boolean {
    return this.moduleInfoComponent && this.moduleInfoComponent.hasErrors;
  }

  constructor(
    public yot: YotService,
    @Inject(MAT_DIALOG_DATA) data: {module: Module}
  ) {
    this.module = data.module;
  }

  ngOnInit(): void {
  }

  onApplyClick(e) {
    if (this.moduleInfoComponent) {
      this.moduleInfoComponent.apply();
    }
  }
}
