import { Directive, Input } from '@angular/core';
import { NG_VALIDATORS, Validator, AbstractControl, ValidationErrors } from '@angular/forms';
import { duplicateNameValidator } from './duplicate-name.validator'; // La funzione che abbiamo creato

@Directive({
  selector: '[appDuplicateName]', // Questo è il nome che userai nel template
  providers: [{ provide: NG_VALIDATORS, useExisting: DuplicateNameDirective, multi: true }]
})
export class DuplicateNameDirective implements Validator {

  @Input() appDuplicateName: string[] = []; // Array di nomi esistenti

  validate(control: AbstractControl): ValidationErrors | null {
    // Chiama la funzione di validazione con l'array di nomi fornito dal template
    return duplicateNameValidator(this.appDuplicateName)(control);
  }
}
