import {Component, Inject} from '@angular/core';
import {MAT_DIALOG_DATA, MatDialogRef} from "@angular/material/dialog";

@Component({
  selector: 'app-commands-capture-dialog',
  templateUrl: './commands-capture-dialog.component.html',
  styleUrls: ['./commands-capture-dialog.component.scss']
})
export class CommandsCaptureDialogComponent  {
  commandsPause = -1;
  captureEnabled = false;

  constructor(@Inject(MAT_DIALOG_DATA) public data, private dialogRef: MatDialogRef<CommandsCaptureDialogComponent>) {
    this.commandsPause = data?.commandsPause;
    this.captureEnabled = data?.captureEnabled;
  }

  onCommandsPauseChange(pause: number) {
    if (this.captureEnabled) {
      this.dialogRef.close({
        commandsPause: this.commandsPause, captureEnabled: this.captureEnabled
      });
    }
  }
}
