import * as Blockly from "blockly";
import {Block, CodeGenerator, Generator, Input, Workspace} from "blockly";

import {HomegenieAdapter, Module} from "../../../../adapters/home-genie/homegenie-adapter";
import * as beautify from 'js-beautify';
import {Color} from "@iplab/ngx-color-picker";
import {ThermostatCommand} from "../../../../api/widgets/thermostat-widget.api";
import {DomainNames} from "../../../../adapters/home-genie/homegenie-api";

export class ProgramCode {
  codeDeclarations = '';
  setupDeclarations = '';
  setup = '';
  code = '';
  custom = '';
}

export class DeclarationItem {
  type: 'g' | 'm' | 'd';
  key: string;
  value: string;
}

export class HomegenieCodeGenerator extends CodeGenerator {
  codeGenerator: Generator;
  declaredModules: Array<Module> = [];

  private codeDeclarations: Array<DeclarationItem> = [];
  private setupDeclarations: Array<DeclarationItem> = [];
  private currentSelectionVar = '';
  private programCode: ProgramCode;
  private isSetupBlock = false;
  private isMainBlock = false;
  private currentVarIndex: number;
  private currentDomainIndex: number;

  constructor(private adapter: HomegenieAdapter, name: string) {
    super(name);
    const host = this;
    this.codeGenerator = new Blockly.Generator('CodeGenerator');
    this.codeGenerator['controls_if'] = function(block: Block) {
      return host.blockToCode(block);
    };
    this.codeGenerator['program_pause'] = function(block: Block) {
      return host.blockToCode(block);
    }
    this.codeGenerator['group_select'] = function(block: Block) {
      return host.blockToCode(block);
    }
    this.codeGenerator['module_select'] = function(block: Block) {
      return host.blockToCode(block);
    }
    this.codeGenerator['parameter_select'] = function(block: Block) {
      return host.blockToCode(block);
    }
    this.codeGenerator['context_function'] = function(block: Block) {
      return host.blockToCode(block);
    }
    this.codeGenerator['control_on'] = function(block: Block) {
      return host.blockToCode(block);
    }
    this.codeGenerator['control_off'] = function(block: Block) {
      return host.blockToCode(block);
    }
  }

  workspaceToProgramCode(workspace: Workspace): ProgramCode {
    this.programCode = new ProgramCode();
    this.workspaceToCode(workspace);
    return this.programCode;
  }

  private getDomainVariableName(declaration: DeclarationItem) {
    if (declaration.value === '') {
      let name = declaration.key;
      if (name.indexOf('.') != name.lastIndexOf('.')) {
        name = name.substring(name.indexOf('.') + 1);
      }
      //declaration.value = 'd' + name.replace('.', '_') + '_' + this.currentDomainIndex++;
      declaration.value = 'mList' + this.currentDomainIndex++;
    }
    return declaration.value;
  }

  /** @override */
  workspaceToCode(workspace?: Workspace): string {
    const p = this.programCode;
    this.declaredModules = [];
    this.codeDeclarations = [];
    this.setupDeclarations = [];
    this.currentVarIndex = 1;
    this.eventsWhen = [];
    //
    this.programCode.code = '';
    this.programCode.setup = '';
    this.programCode.custom = '';
    this.programCode.codeDeclarations = '';
    this.programCode.setupDeclarations = '';
    //
    super.workspaceToCode(workspace);
    // MAIN CODE
    this.currentDomainIndex = 1;
    this.codeDeclarations.forEach((declaration) => {
      if (declaration.type === 'd') {
        const dv = this.getDomainVariableName(declaration);
        p.codeDeclarations += `var ${dv} = Modules.InDomain("${declaration.key}");\n`;
      }
    });
    this.codeDeclarations.forEach((declaration) => {
      const varName = declaration.value;
      if (declaration.type === 'g') {
        p.codeDeclarations += `var ${varName} = Modules.InGroup("${declaration.key}");\n`;
      } else if (declaration.type === 'm') {
        const module = this.adapter.getModule(declaration.key);
        if (module) {
          if (this.declaredModules.indexOf(module) < 0) {
            this.declaredModules.push(module);
          }
          const domain = this.codeDeclarations.find((d) => d.type == 'd' && d.key === module.Domain)?.value;
          p.codeDeclarations += `var ${varName} = ${domain}.WithAddress("${module.Address}").Get();\n`;
        }
      }
    });
    // SETUP CODE
    this.currentDomainIndex = 1;
    this.setupDeclarations.forEach((declaration) => {
      if (declaration.type === 'd') {
        const dv = this.getDomainVariableName(declaration);
        p.setupDeclarations += `var ${dv} = Modules.InDomain("${declaration.key}");\n`;
      }
    });
    this.setupDeclarations.forEach((declaration) => {
      const varName = declaration.value;
      if (declaration.type === 'g') {
        p.setupDeclarations += `var ${varName} = Modules.InGroup("${declaration.key}");\n`;
      } else if (declaration.type === 'm') {
        const module = this.adapter.getModule(declaration.key);
        if (module) {
          if (this.declaredModules.indexOf(module) < 0) {
            this.declaredModules.push(module);
          }
          const domain = this.setupDeclarations.find((d) => d.type == 'd' && d.key === module.Domain)?.value;
          p.setupDeclarations += `var ${varName} = ${domain}.WithAddress("${module.Address}").Get();\n`;
        }
      }
    });
    // add event handlers
    if (this.eventsWhen.length > 0) {
      let code = '';
      this.eventsWhen.map((w) => {
        code += w.code;
      });
      code = `\nWhen.ModuleParameterChanged((m, p) => {${code}
      // returning true, will route event to other listeners
      return true;
    });`;
      p.setupDeclarations += code;
    }
    p.codeDeclarations = beautify.js(p.codeDeclarations);
    p.setupDeclarations = beautify.js(p.setupDeclarations);
    p.setup = beautify.js(p.setup);
    p.custom = beautify.js(p.custom);
    p.code = beautify.js(p.code);
    return p.custom + '\n\n' + p.code;
  }

  getFunctionName(name: string): string {
    return name.replace(' ', '_');
  }

  /** @override */
  blockToCode(block: Block): string {
    if (!block) return '';
    switch (block.type) {
      case 'setup_code':
        if (block.isEnabled()) {
          this.isSetupBlock = true;
          this.programCode.setup += this.blockToCode(block.getInputTargetBlock('SETUP'));
          this.isSetupBlock = false;
        }
        break;
      case 'main_code':
        if (block.isEnabled()) {
          this.isMainBlock = true;
          this.programCode.code += '// #MAIN\n';
          this.programCode.code += this.blockToCode(block.getInputTargetBlock('MAIN'));
          this.isMainBlock = false;
        }
        break;
      case 'custom_code':
        if (block.isEnabled()) {
          this.isMainBlock = true;
          const fn = block.getFieldValue("NAME");
          let code = this.blockToCode(block.getInputTargetBlock('CUSTOM'));
          if (code.startsWith('\n')) code = code.substring(1);
          this.programCode.custom += '\nvar ' + this.getFunctionName(fn)
            + ' = () => {\n'
            + ' // prevent recursion locks\n'
            + ' if (!Program.IsRunning) return;\n'
            + ` // #START [ ${fn} ]\n`
            + code
            + `\n// #END [ ${fn} ]\n};`;
          this.isMainBlock = false;
        }
        break;
    }
    if (!this.isSetupBlock && !this.isMainBlock) return '';
    // generate code for 'block'
    const varName = this.currentSelectionVar;
    let code = '';
    // then iterate to next block
    if (block.isEnabled()) {
      switch (block.type) {
        case 'events_when':
          code += this.parseEventWhen(block);
          break;
        case 'controls_if':
          code += this.parseControlsIf(block);
          break;
        case 'controls_switch':
          code += this.parseControlsSwitch(block);
          break;
        case 'controls_repeat':
          const loopCount = block.getFieldValue('TIMES');
          const loopCode = this.blockToCode(block.getInputTargetBlock('DO'));
          code += `for (var i = 0; i < ${loopCount} && Program.IsRunning; i++) { ${loopCode} };`;
          break;
        case 'controls_whileUntil':
          const repeatMode = block.getFieldValue('MODE');
          const repeatCode = this.blockToCode(block.getInputTargetBlock('DO'));
          const repeatCondition = this.blockToCode(block.getInputTargetBlock('BOOL'));
          if (repeatMode === 'UNTIL') {
            code += `while (!(${repeatCondition}) && Program.IsRunning) { ${repeatCode} }`;
          } else {
            code += `while ((${repeatCondition}) && Program.IsRunning) { ${repeatCode} }`;
          }
          break;
        case 'controls_flow_statements':
          const flowModifier = block.getFieldValue('FLOW');
          code += flowModifier.toLowerCase() + ';';
          break;
        case 'controls_for': {
            const varName = block.getVarModels()[0].name;
            const fromValue = block.getInputTargetBlock('FROM').getFieldValue('NUM')
            const toValue = block.getInputTargetBlock('TO').getFieldValue('NUM');
            const byValue = block.getInputTargetBlock('BY').getFieldValue('NUM');
            const doStatement = this.blockToCode(block.getInputTargetBlock('DO'));
            code += `for (var ${varName} = ${fromValue}; ${varName} <= ${toValue} && Program.IsRunning; ${varName} += ${byValue}) { ${doStatement} }`;
          }
          break;
        case 'schedule_active':
          const scheduleName = block.getFieldValue('SCHEDULE');
          code += `Scheduler.IsScheduling("@${scheduleName}")`;
          break;
        case 'group_select':
          const groupName = block.getFieldValue('GROUP');
          // this will set the currently selected group (even if `varName` is actually not used)
          const varName = this.getGroupVariableName(groupName);
          break;
        case 'module_select': {
            const moduleAddress = block.getFieldValue('MODULE');
            // this will set the currently selected module (even if `varName` is actually not used)
            const varName = this.getModuleVariableName(moduleAddress);
          }
          break;
        case 'parameter_select': {
            const moduleAddress = block.getFieldValue('MODULE');
            const varName = this.getModuleVariableName(moduleAddress);
            const fieldName = block.getFieldValue('PARAMETER');
            const fieldValue = block.getFieldValue('VALUE');
            if (fieldValue) {
              code += `${varName}.Parameter("${fieldName}")${fieldValue}`
            } else {
              code += `${varName}.Parameter("${fieldName}")`
            }
          }
          break;
        case 'context_function': {
            const functionName = block.getFieldValue('FUNCTION');
            const paramBlock = block.getInputTargetBlock('PARAMETER');
            const moduleVar = this.currentSelectionVar ? this.currentSelectionVar : "null";
            code += `${functionName}(${this.blockToCode(paramBlock)}, ${moduleVar})`;
          }
          break;
        case 'function_call': {
            const functionName = block.getFieldValue('FUNCTION');
            const async = block.getFieldValue('ASYNC');
            /*
            const paramBlock =  block.getInputTargetBlock('PARAMETER');
            if (async === 'TRUE') {
              code += `Program.RunAsyncTask(() => ${functionName}(${this.blockToCode(paramBlock)}));`;
            } else {
              code += `${functionName}(${this.blockToCode(paramBlock)});`;
            }
            */
            if (async === 'TRUE') {
              code += `Program.RunAsyncTask(() => ${functionName}());`;
            } else {
              code += `${functionName}();`;
            }
          }
          break;
        case 'control_on':
          code += `\n${this.currentSelectionVar}.On();`;
          break;
        case 'control_off':
          code += `\n${this.currentSelectionVar}.Off();`;
          break;
        case 'control_toggle':
          code += `\n${this.currentSelectionVar}.Toggle();`;
          break;
        case 'control_level':
          const level = block.getFieldValue('LEVEL');
          code += `\n${this.currentSelectionVar}.Level = ${level};`;
          break;
        case 'control_level_p':
          const paramBlock = block.getInputTargetBlock('LEVEL');
          code += `\n${this.currentSelectionVar}.Level = ${this.blockToCode(paramBlock)};`;
          break;
        case 'control_color':
          const duration = block.getFieldValue('DURATION');
          const cf = block.getFieldValue('COLOR');
          const color = Color.from(cf);
          const hsv = color.getHsva();
          const h = hsv.hue / 360.0;
          const s = hsv.saturation / 100.0;
          const v = hsv.value / 100.0;
          const hsbString = `${h},${s},${v},${duration}`;
          code += `\n${this.currentSelectionVar}.ColorHsb = "${hsbString}";`;
          break;
        case 'thermostat_mode':
          const mode = block.getFieldValue('MODE');
          code += `\n${this.currentSelectionVar}.Command("${ThermostatCommand.Mode.Set}").Submit("${mode}");`;
          break;
        case 'thermostat_fanmode':
          const fanMode = block.getFieldValue('FANMODE');
          code += `\n${this.currentSelectionVar}.Command("${ThermostatCommand.FanMode.Set}").Submit("${fanMode}");`;
          break;
        case 'thermostat_setpoint':
          const type = block.getFieldValue('TYPE');
          const setPoint = block.getFieldValue('SETPOINT');
          code += `\n${this.currentSelectionVar}.Command("${ThermostatCommand.SetPoint.Set}").Submit("${type}/${setPoint}");`;
          break;
        case 'custom_command':
          const command = block.getFieldValue('COMMAND');
          const options = block.getFieldValue('OPTIONS');
          if (command === 'Config.ParameterSet') {
            const si = options.indexOf('/');
            const param = options.substring(0, si);
            const value = options.substring(si + 1);
            code += `\n${this.currentSelectionVar}.SetParameter("${param}", "${value}");`;
          } else {
            code += `\n${this.currentSelectionVar}.Command("${command}").Submit("${options}");`;
          }
          break;
        case 'program_run':
          const program = block.getFieldValue('PROGRAM');
          const module = this.adapter.getModuleByRef({Domain: DomainNames.HomeAutomation_HomeGenie_Automation, Address: program});
          if (program.length === 0) {
            code += `\nProgram.Run(); // "Main"`;
          } else {
            code += `\nProgram.Run("${program}"); // "${module?.name}"\n`;
          }
          break;
        case 'program_wait_for':
          const waitProgram = block.getFieldValue('PROGRAM');
          code += `\nProgram.WaitFor("${waitProgram}");`;
          break;
        case 'program_pause':
          const delay = block.getInputTargetBlock('SECONDS');
          code += `\nPause(${delay});`;
          break;
        case 'program_emit':
          const paramName = block.getInputTargetBlock('PARAMETER_NAME');
          const paramValue = block.getInputTargetBlock('PARAMETER_VALUE');
          const par = JSON.stringify(paramName?.getFieldValue('TEXT'));
          const val = this.blockToCode(paramValue);
          if (par && val) {
            code += `Program.Emit(${par}, ${val});`;
          }
          break;
        case 'program_play':
          const mediaUrl = block.getInputTargetBlock('MEDIA_URL')
            .getFieldValue('TEXT');
          code += `Program.Play("${mediaUrl}");`;
          break;
        case 'program_say':
          const sentence = block.getInputTargetBlock('SENTENCE')
            .getFieldValue('TEXT');
          code += `Program.Say("${sentence}");`;
          break;
        case 'logic_compare': // A =|<|>|!=|>=|<= B
          code += this.parseLogicCompare(block);
          break;
        case 'math_number':
          code += this.parseMathNumber(block);
          break;
        case 'text':
          code += this.parseText(block);
          break;
        case 'logic_boolean': // A and|or B
          code += this.parseLogicBoolean(block);
          break;
        case 'logic_negate':
          const negateExpression = this.blockToCode(block.getChildren(true)[0]);
          code += `!(${negateExpression})`;
          break;
        case 'logic_operation':
          code += this.parseLogicOperation(block);
          break;
        default:
          console.log(`/* UNIMPLEMENTED COMMAND ${block.type} */`, block)
      }
    }
    const nextBlock = block.getNextBlock();
    const parentBlock = block.getSurroundParent();
    if (nextBlock) {
      code += this.blockToCode(nextBlock);
    } else if (parentBlock) {
//      if (parentBlock.type === 'module_select') {
//        code += ';\n'
//      }
    }
    this.currentSelectionVar = varName;
    return code;
  }

  private eventsWhen = [];

  private parseEventWhen(block) {
    const moduleAddress = block.getFieldValue('MODULE');
    const varName = this.getModuleVariableName(moduleAddress);
    const parameterName = block.getFieldValue('PARAMETER');
    let doStatement = block.getInputTargetBlock('DO0'); // blockChildren[1];
    let doStatementValue = this.blockToCode(doStatement);
    let code = `\nif (m.Instance == ${varName}.Instance && p.Is("${parameterName}")) {${doStatementValue}
  }`;
    this.eventsWhen.push({
      variable: varName,
      module: moduleAddress,
      fieldName: parameterName,
      code
    });
    return '';
  }

  private parseControlsIf(block) {
    const blockChildren = block.getChildren(true);
    let logicOperator = block.getInputTargetBlock('IF0'); //blockChildren[0];
    let doStatement = block.getInputTargetBlock('DO0'); // blockChildren[1];
    let logicOperationValue = this.blockToCode(logicOperator);
    let doStatementValue = this.blockToCode(doStatement);
    let code = `\nif (${logicOperationValue}) {${doStatementValue}\n}`;
    blockChildren.slice(2).forEach((b, i) => {
      const input = block.inputList[i + 2];
      if (!input) return;
      if (input.name.startsWith('IF')) {
        const idx = input.name.substring(2);
        logicOperator = block.getInputTargetBlock(`IF${idx}`);
        doStatement = block.getInputTargetBlock(`DO${idx}`);
        logicOperationValue = this.blockToCode(logicOperator);
        doStatementValue = this.blockToCode(doStatement);
        code += ` else if (${logicOperationValue}) {${doStatementValue}\n}`;
      } else if (input.name === 'ELSE') {
        doStatement = blockChildren[i + 2];
        doStatementValue = this.blockToCode(doStatement);
        code += ` else {${doStatementValue}\n}`;
      }
    });
    return code;
  }
  private parseControlsSwitch(block) {
    const asString = (v) => v.startsWith('"') ? v : `"${v}"`;
    const blockChildren = block.getChildren(true);
    let switchBlock = block.getInputTargetBlock('VALUE');
    if (!switchBlock) return '';
    let switchValue = this.blockToCode(switchBlock);
    if (switchBlock.type === 'parameter_select') {
      if (switchValue.indexOf(').') < 0) {
        switchValue += '.Value';
      } else if (!switchValue.endsWith('.Value')) {
        switchValue += '.ToString()';
      }
    }
    let caseBlock = block.getInputTargetBlock('CASE0');
    let caseValue = asString(this.blockToCode(caseBlock));
    let doStatement = block.getInputTargetBlock('DO0');
    let doStatementValue = this.blockToCode(doStatement);
    let code = `\nswitch (${switchValue}) {\n`;
    let caseCode = `case ${caseValue}:${doStatementValue}\nbreak;`;
    blockChildren.slice(3).forEach((b, i) => {
      const input = block.inputList[i + 3];
      if (!input) return;
      if (input.name.startsWith('CASE')) {
        const idx = input.name.substring(4);
        caseBlock = block.getInputTargetBlock(`CASE${idx}`);
        doStatement = block.getInputTargetBlock(`DO${idx}`);
        caseValue = asString(this.blockToCode(caseBlock));
        doStatementValue = this.blockToCode(doStatement);
        caseCode += `case ${caseValue}:${doStatementValue}\nbreak;`;
      } else if (input.name === 'DEFAULT') {
        doStatement = block.getInputTargetBlock(`DEFAULT`);
        doStatementValue = this.blockToCode(doStatement);
        caseCode += `default:${doStatementValue}\nbreak;`;
      }
    });
    return `${code}${caseCode}\n}`;
  }
  private parseLogicOperation(block) {
    const leftOperand = block.getChildren(true)[0];
    const rightOperand = block.getChildren(true)[1];
    let logicOperator = block.getFieldValue('OP');
    switch (logicOperator) {
      case 'OR':
        logicOperator = '||';
        break;
      case 'AND':
        logicOperator = '&&';
        break;
    }
    return `${this.blockToCode(leftOperand)} ${logicOperator} ${this.blockToCode(rightOperand)}`;
  }
  private parseLogicCompare(block) {
    const leftOperand = block.getChildren(true)[0];
    const rightOperand = block.getChildren(true)[1];
    let rightOperandValue = this.blockToCode(rightOperand);
    let leftOperandValue = this.blockToCode(leftOperand);
    let logicOperator = block.getFieldValue('OP');
    switch (logicOperator) {
      case 'EQ':
        logicOperator = '==';
        break;
      case 'LT':
        logicOperator = '<';
        break;
      case 'LTE':
        logicOperator = '<=';
        break;
      case 'GT':
        logicOperator = '>';
        break;
      case 'GTE':
        logicOperator = '>=';
        break;
      case 'NEQ':
        logicOperator = '!=';
        break;
    }
    return `(${leftOperandValue} ${logicOperator} ${rightOperandValue})`;
  }
  private parseLogicBoolean(block) {
    const value = block.inputList[0].fieldRow[0].getValue() === 'TRUE';
    return value;
  }
  private parseMathNumber(block) {
    const value = block.inputList[0].fieldRow[0].getValue();
    return value;
  }
  private parseText(block) {
    const value = block.inputList[0].fieldRow[1].getValue();
    return `"${value}"`;
  }
  private getDeclaration(type: 'm' | 'g' | 'd', name: string) {
    return (this.isSetupBlock ? this.setupDeclarations : this.codeDeclarations)
      .find((declaration) => declaration.type === type && declaration.key === name);
  }
  private getGroupVariableName(groupName: string) {
    let declaration = this.getDeclaration('g', groupName);
    if (declaration == null) {
      declaration = {type: 'g', key: groupName, value: ''};
      declaration.value = 'g';
      if (groupName.length > 0) {
        groupName.split(' ').forEach((n) => {
          if (n[0]) declaration.value += n[0].toUpperCase() + n.slice(1).toLowerCase();
        });
      } else {
        // TODO: should report warning
        return;
      }
      if (this.isSetupBlock) {
        this.setupDeclarations.push(declaration);
      } else if (this.isMainBlock) {
        this.codeDeclarations.push(declaration);
      }
    }
    return this.currentSelectionVar = declaration.value;
  }
  private getModuleVariableName(moduleAddress: string) {
    let declaration = this.getDeclaration('m', moduleAddress);
    if (declaration == null) {
      declaration = {type: 'm', key: moduleAddress, value: ''};
      declaration.value = 'm';
      const module = this.adapter.getModule(moduleAddress);
      if (module) {
        const domainDeclaration = this.getDeclaration('d', module.Domain);
        if (domainDeclaration == null) {
          const dd: DeclarationItem = {type: 'd', key: module.Domain, value: ''};
          if (this.isSetupBlock) {
            this.setupDeclarations.push(dd);
          } else if (this.isMainBlock) {
            this.codeDeclarations.push(dd);
          }
        }
        let name = module.Name;
        if (name == null || name.length == 0) {
          name = module.DeviceType;
        }
        name.split(/[^a-zA-Z\d:]/).forEach((n) => {
          if (n[0]) declaration.value += n[0].toUpperCase() + n.slice(1).toLowerCase();
        });
      } else {
        // TODO: should report warning
        return;
      }
      declaration.value += '_' + this.currentVarIndex++;
      if (this.isSetupBlock) {
        this.setupDeclarations.push(declaration);
      } else if (this.isMainBlock) {
        this.codeDeclarations.push(declaration);
      }
    }
    return this.currentSelectionVar = declaration.value;
  }
}
