@Injectable({
  providedIn: 'root'
})
export class YotService implements OnDestroy {
  adapters: Array<Adapter> = [];
  modules: Array<Module> = [];

  onModuleAdded = new Subject<Module>();
  onModuleRemoved = new Subject<Module>();
  onModuleEvent = new Subject<{ module: Module, event: ModuleField }>()

  onAdapterAdded = new Subject<Adapter>();

  onConfigurationSaved = new Subject<Configuration>();

  onWidgetUpdated = new Subject<{id?:string,html?:string,css?:string,js?:string}>();
  onProgramUpdated = new Subject<{address?:string,name:string,language:string,main?:string,setup?:string,context?:string,save?:boolean}>();


  public readonly configStorage = 'config';
  public readonly preferencesStorage = 'preferences';

  preferences = {
    ui: {
      dashboard: 'Dashboard', // name of current dashboard
      automation: {
        selectedGroups: [],
        showDisabled: true,
        showFiltered: true
      },
      theme: 'dark',
      drawer: {
        mode: 'over',
        open: false
      },
      notifications: {
        enabled: true,
        filter: []
      },
      dragSortEnabled: true,
      aiChatGenie: {providerId: 0} as any,
      aiChatAutoUpdate: false,
      aiChatSpeechEnabled: false,
      aiChatSpeechEngine: 'browser',
      aiChatRecognitionEngine: 'browser',
      language: '',
      mediaPlayer: {
        volume: 0.5
      }
    },
    units: {
      current: 'A',
      digital: 'Mb',
      energy: 'kWh',
      illuminance: 'lx',
      power: 'W',
      pressure: 'bar',
      speed: 'km/h',
      temperature: 'C',
      voltage: 'V'
    }
  };

  clientPreset = 'default';

  isSystemUpdateAvailable = false;
  isProgramsUpdateAvailable = false;

  public get converters() {
    return self['converter'] || converter;
  };

  private readonly singleNodeMode = true;

  constructor(
    public storage: StorageMap,
    public http: HttpClient,
    public translate: TranslateService,
    public dashboardService: DashboardService,
    public notificationService: NotificationService,
    public layoutService: LayoutService,
    public dialog: MatDialog,
    private snackBar: MatSnackBar,
    private toolTip: MatSnackBar
  ) {
    const _t = this;
    Object.defineProperty(window, 'utils', {get(): any {

      // global utils class
      // TODO: move to a separate file
      // create global utility class
      return {
        format: {
          fieldName: (field: ModuleField): string => {
            const sensorFieldFormatter = new SensorFieldFormatterPipe();
            return sensorFieldFormatter.transform(field.key);
          },
          fieldValue: (field: ModuleField): string => {
            const sensorValueFormatter = new SensorValueFormatterPipe(_t);
            return sensorValueFormatter.transform(field.value, field.key, ModuleType.Sensor, 1);
          }
        },
        filter: {
          stripHTML: (s: string) => new StripHtmlPipe().transform(s)
        },
        get preferences() {
          return _t.preferences;
        },
        get convert() {
          return _t.converters;
        },
        ui: {
          notify: (title, message, options) => _t.notify(title, message, options),
          tooltip: (message, options) => _t.toolTip.open(message, null, options)
        }
      };

    }});
  }

  ngOnDestroy(): void {
    this
      .saveConfiguration();
    this.onModuleAdded
      .complete();
    this.onModuleRemoved
      .complete();
    this.onModuleEvent
      .complete();
    this.onAdapterAdded
      .complete();
    this.onConfigurationSaved
      .complete();
  }

  /**
   * Displays a notification message (snackbar)
   *
   * @param title
   * @param message
   * @param options
   */
  notify(title: string, message: string, options?: any): void {
    // TODO: implement message queueing
    const o = Object.assign({},{
      verticalPosition: 'top',
      duration: 5000
    }, options);
    Object.assign(o, {
      data: { title, message, action: 'close' }
    });
    if (options && options.data) {
      Object.assign(o.data, options.data);
    }
    this.snackBar.openFromComponent(NotificationSnackbarComponent, o);
  }
  tooltip(message: string, options?: any): void {
    // TODO: implement message queueing
    const o = Object.assign({},{
      duration: 1500,
      data: { message }
    }, options);
    if (options && options.data) {
      Object.assign(o.data, options.data);
    }
    this.toolTip.openFromComponent(ArrowTooltipComponent, o);
  }

  connect(): Subject<any> {
    const subject = new Subject<any>();
    const connectRequests: Subject<any>[] = [];
    this.getAdapters().map((ac) => {
      const adapter = this.getAdapter(ac.id);
      connectRequests.push(adapter.connect());
    });
    if (connectRequests.length === 0) {
      setTimeout(() => subject.complete());
    }
    concat(...connectRequests).subscribe({
      next: (status) => {
        if (status) {
          // TODO: handle adapter connect error
        } else {
          // TODO: log 'adapter connected'
        }
        subject.next(status);
      },
      error: (err) => {
        console.log('YOT: adapter connection error', err);
        subject.error(err);
      },
      complete: () => {
        subject.complete();
      }
    });
    return subject;
  }

  /**
   * Loads YOT configuration
   */
  loadConfiguration(): Subject<Configuration> {
    const subject = new Subject<Configuration>();
    this.storage
      .get(this.configStorage)
      .subscribe((config: Configuration) => {
        if (config != null) {
          this.modules = [];
          config.modules.map((m) => {
            m = new Module(m);
            this.modules.push(m);
            this.onModuleAdded.next(m);
          });
          this.dashboardService.dashboards = [];
          if (config.dashboards) {
            config.dashboards.map((d) => {
              const dashboard = this.dashboardService
                .addDashboard(d.name, d.description, d.config);
              d.widgets.map((w) => {
                w &&
                this.dashboardService
                  .addDashboardWidget(dashboard.name, w.type, this.getModuleByRef(w.module), w.data, w.configuration);
              });
            });
          }
        }
        // Add adapters
        if (config && config.adapters) {
          config.adapters.map((ac) => {
            const adapter = this.getAdapter(ac.id, ac.type);
            adapter.options.config = ac.config;
            this.modules.map((m) => {
              if (this.singleNodeMode || m.adapterId === adapter.id) {
                m.adapter = adapter;
              }
            });
            this.addAdapter(adapter);
          });
          // get client configuration preset name
          this.storage.get('clientPreset').subscribe({
            next: (preset: string) => {
              this.clientPreset = (preset || 'default');
              subject.next(config);
              subject.complete();
            }
          });
        } else {
          // System is not configured yet
          subject.next(null);
          subject.complete();
        }
      });
    return subject;
  }
  /**
   * Saves YOT configuration
   */
  saveConfiguration(): Subject<Configuration> {
    const subject = new Subject<Configuration>();
    const adaptersConfig = [];
    this.adapters.map((adapter) => {
      const ac: AdapterConfiguration = {
        id: adapter.id,
        type: adapter.className,
        config: adapter.options.config,
      };
      adaptersConfig.push(ac);
    });
    const config: Configuration = {
      dashboards: this.dashboardService.dashboards,
      modules: this.modules.map((m) => new Module(m)),
      adapters: adaptersConfig
    };
    const cfg = JSON.parse(JSON.stringify(config)); // <-- this intermediate step is necessary to apply `toJSON()` overrides
    this.storage.set(this.configStorage, cfg).subscribe((status) => {
      // TODO: test status value
      this.onConfigurationSaved.next(cfg);
      subject.next(cfg);
      subject.complete();
    });
    return subject;
  }
  /**
   * Replaces current config with a new configuration
   */
  replaceConfiguration(config: Configuration): Subject<any> {
    const subject = new Subject();
    // prevents overwriting adapters settings.
    const adaptersConfig = [];
    this.adapters.map((adapter) => {
      const ac: AdapterConfiguration = {
        id: adapter.id,
        type: adapter.className,
        config: adapter.options.config,
      };
      adaptersConfig.push(ac);
    });
    Object.assign(adaptersConfig, config.adapters);
    config.adapters = adaptersConfig;
    this.storage.set(this.configStorage, config).subscribe((res) => {
      // reload config -- TODO: should also refresh page
      this.loadConfiguration().subscribe({
        next: (cfg) => subject.next(cfg),
        error: (err) => subject.error(err),
        complete: () => subject.complete()
      })
    });
    return subject;
  }
  /**
   * Load YOT preferences
   */
  loadPreferences(): Subject<any> {
    const subject = new Subject<any>();
    this.storage
      .get(this.preferencesStorage)
      .subscribe((prefs: any) => {
        this.preferences = { ...this.preferences, ...prefs};
        // Apply UI preferences
        this.setUiLanguage();
        this.setUiTheme();
        this.setUiLayout();
        // Complete subject
        subject.next(this.preferences);
        subject.complete();
      });
    return subject;
  }
  /**
   * Saves YOT preferences
   */
  savePreferences(): Subject<any> {
    const subject = new Subject<any>();
    this.storage.set(this.preferencesStorage, this.preferences).subscribe((status) => {
      subject.next(this.preferences);
      subject.complete();
    });
    return subject;
  }
  /**
   * Replaces current preferences with new preferences
   */
  replacePreferences(preferences: any): Subject<any> {
    const subject = new Subject();
    this.storage.set(this.preferencesStorage, preferences).subscribe((status) => {
      // reload preferences
      this.loadPreferences()
        .subscribe({
          next: (res) => {
            subject.next(res);
            subject.complete();
          },
          error: (err) => subject.error(err)
        });
    });
    return subject;
  }
  /**
   * Adds a new adapter
   * @param adapter The new YOT adapter
   */
  addAdapter(adapter: Adapter): boolean {
    if (this.adapters.find((a) => a.id === adapter.id) != null) {
      return false;
    }
    this.adapters.push(adapter);
    this.onAdapterAdded.next(adapter);
    return true;
  }
  /**
   * Gets the adapter with `id` = `adapterId` or creates a new one of type `className`
   * @param adapterId The adapter id
   * @param className The adapter class name
   */
  getAdapter(adapterId: string, className?: string): Adapter {
    let adapter = this.adapters.find((a) => a.id === adapterId);
    // create a new instance if 'adapterId' was not found and a 'typeName' was given
    if (className != null && adapter == null) {
      adapter = AdapterFactory.create(className, this);
      // this.addAdapter(adapter);
    }
    return adapter;
  }
  /**
   * Gets the list of adapters in the actual YOT configuration
   */
  getAdapters(): Array<Adapter> {
    return this.adapters;
  }

  /**
   * Gets the default adapter
   */
  getDefaultAdapter(): Adapter {
    return this.adapters[0];
  }

  /**
   * Gets a module instance given its reference (adapterId+moduleId)
   * @param mr
   */
  getModuleByRef(mr: ModuleReference): Module {
    return mr ? this.modules
      .find((m) => m.id === mr.moduleId && (m.adapterId === mr.adapterId || this.singleNodeMode)) : undefined;
  }

  /**
   * Adds a new module to YOT configutation
   * @param module The module to add
   */
  addModule(module: Module): Module {
    const m = this.getModule(module.id, module.adapterId);
    if (m != null) { return m; }
    module.adapter = this.getAdapter(module.adapterId);
    this.modules.push(module);
    this.onModuleAdded.next(module);
    return module;
  }
  /**
   * Gets a module given its id and adapter id
   * @param moduleId The module id
   * @param adapterId The adapter id
   */
  getModule(moduleId: string, adapterId?: string): Module {
    if (adapterId == null) {
      adapterId = this.getDefaultAdapter()?.id;
    }
    return this.modules.find(
      (item) => item.id === moduleId && item.adapterId === adapterId
    );
  }
  /**
   * Removes a module
   * @param module The module to remove
   */
  removeModule(module: Module): void {
    this.modules = this.modules.filter((item) => item !== module);
    this.onModuleRemoved.next(module);
  }
  /**
   * Checks if a module with the specified `moduleId` and `adapterId` exists in YOT configuration
   * @return true if the module exists, false otherwise
   */
  hasModule(moduleId: string, adapterId: string): boolean {
    return this.getModule(moduleId, adapterId) != null;
  }

  /**
   * Gets the list of modules in actual YOT configuration
   */
  getModules(): Array<Module> {
    return this.modules;
  }

  isBusy(): boolean {
    return false;
  }

  getHostPort(): string {
    return window.location.port;
  }
  getHostname() : string {
    return window.location.hostname;
  }
  setUiLanguage(l?: string): Subject<string> {
    const subject = new Subject<string>();
    // apply language preference
    this.http.get('assets/i18n/index.json').subscribe((list) => {
      let browserLang = this.translate.getBrowserLang().toLowerCase();
      let lang = Object.keys(list).indexOf(browserLang) >= 0 ? browserLang : 'en';
      //if (list[lang] && list[lang].code) {
      //  lang = list[lang].code;
      //}
      if (l != null) {
        this.preferences.ui.language = l;
      }
      if (this.preferences.ui.language.length > 0) {
        lang = this.preferences.ui.language;
      }
      this.translate.use(lang);
      moment.locale(lang)
      subject.next(lang);
    });
    return subject;
  }
  setUiTheme(themeClass?: string) {
    const body = document.body;
    if (!this.preferences.ui.theme) {
      this.preferences.ui.theme = 'dark'; // default theme
    }
    const oldPrismTheme = `prism-${this.preferences.ui.theme}-theme`;
    body.classList
      .remove(oldPrismTheme);

    body.classList
      .remove(`${this.preferences.ui.theme}-theme`);
    body.classList
      .remove(`dark-theme`);
    body.classList
      .remove(`light-theme`);
    if (themeClass) {
      this.preferences.ui.theme = themeClass;
    }
    body.classList.add(`${this.preferences.ui.theme}-theme`);

    const newPrismTheme = `prism-${this.preferences.ui.theme}-theme`;
    body.classList.add(newPrismTheme);
  }
  setUiLayout() {
    // TODO: fix this, navigationService and YotService cannot reference each other
    // --> Side drawer
    const drawerMode = this.layoutService.isSmallScreen ? 'over' : this.preferences.ui.drawer.mode as any;
    const drawerOpen = this.layoutService.isSmallScreen ? false : this.preferences.ui.drawer.open;
    /*
    this.navigationService
      .toggleDrawerMode(drawerMode, drawerOpen);
    if (drawerOpen) {
      this.navigationService.drawer.open();
    }
    */
    this.dashboardService.isDragSortEnabled = this.preferences.ui.dragSortEnabled;
  }

  util = {
    /**
     * Compares two software version numbers (e.g. "1.7.1" or "1.2b").
     *
     * This function was born in http://stackoverflow.com/a/6832721.
     *
     * @param {string} v1 The first version to be compared.
     * @param {string} v2 The second version to be compared.
     * @param {object} [options] Optional flags that affect comparison behavior:
     * lexicographical: (true/[false]) compares each part of the version strings lexicographically instead of naturally;
     *                  this allows suffixes such as "b" or "dev" but will cause "1.10" to be considered smaller than "1.2".
     * zeroExtend: ([true]/false) changes the result if one version string has less parts than the other. In
     *             this case the shorter string will be padded with "zero" parts instead of being considered smaller.
     *
     * @returns {number|NaN}
     * - 0 if the versions are equal
     * - a negative integer iff v1 < v2
     * - a positive integer iff v1 > v2
     * - NaN if either version string is in the wrong format
     */

    versionCompare: (v1, v2, options?) => {
      const lexicographical = (options && options.lexicographical) || false;
      const zeroExtend = (options && options.zeroExtend) || true;
      let v1parts = (v1 || "0").split('.');
      let v2parts = (v2 || "0").split('.');

      function isValidPart(x) {
        return (lexicographical ? /^\d+[A-Za-zαß]*$/ : /^\d+[A-Za-zαß]?$/).test(x);
      }

      if (!v1parts.every(isValidPart) || !v2parts.every(isValidPart)) {
        return NaN;
      }

      if (zeroExtend) {
        while (v1parts.length < v2parts.length) v1parts.push("0");
        while (v2parts.length < v1parts.length) v2parts.push("0");
      }

      if (!lexicographical) {
        v1parts = v1parts.map(function(x){
          const match = (/[A-Za-zαß]/).exec(x);
          return Number(match ? x.replace(match[0], "." + x.charCodeAt(match.index)):x);
        });
        v2parts = v2parts.map(function(x){
          const match = (/[A-Za-zαß]/).exec(x);
          return Number(match ? x.replace(match[0], "." + x.charCodeAt(match.index)):x);
        });
      }

      for (let i = 0; i < v1parts.length; ++i) {
        if (v2parts.length == i) {
          return 1;
        }

        if (v1parts[i] == v2parts[i]) {
          continue;
        }
        else if (v1parts[i] > v2parts[i]) {
          return 1;
        }
        else {
          return -1;
        }
      }

      if (v1parts.length != v2parts.length) {
        return -1;
      }

      return 0;
    }
  }

}
