import {Component, ElementRef, Input, OnInit, ViewChild} from '@angular/core';
import {Module, ModuleField} from "../../../services/yot/module";
import {CMD, YotService} from "../../../services/yot/yot.service";
import {ApiResponse} from "../../../adapters/home-genie/homegenie-adapter";
import {ResponseStatus} from "../../../adapters/home-genie/homegenie-api";
import {now} from "moment-timezone";

@Component({
  selector: 'app-module-fields',
  templateUrl: './module-fields.component.html',
  styleUrls: ['./module-fields.component.scss']
})
export class ModuleFieldsComponent implements OnInit {
  @Input()
  module: Module;

  selectedField: ModuleField;
  value = '';

  @Input()
  fields: ModuleField[];

  lastRefreshTs = Date.now() - 10000;

  isLoading = false;

  get availableFields(): ModuleField[] {
    const now = Date.now();
    if (now - this.lastRefreshTs > 1000) {
      this.lastRefreshTs = now;
      const allowed = (fieldName: string) => {
        let valid = !fieldName?.startsWith('ConfigureOptions.');
        valid = valid && !fieldName?.startsWith('Program.');
        valid = valid && !fieldName?.startsWith('MQTT.SourceNode');
        valid = valid && (fieldName != 'System.Info');
        valid = valid && !fieldName?.startsWith('Widget.');
        valid = valid && !fieldName?.startsWith('VirtualModule.');
        return valid;
      };
      this.fields = this.module.fields
        .filter((f) => allowed(f.key))
        .sort((a, b) => a.key.localeCompare(b.key));
    }
    return this.fields;
  }

  constructor(private yot: YotService) { }

  ngOnInit(): void {
  }

  saveField() {
    this.isLoading = true;
    this.module.control(CMD.Options.Set, {[this.selectedField.key]: this.value}).subscribe((res) => {
      this.isLoading = false;
    });
  }
  deleteField() {
    this.isLoading = true;
    this.module.control(CMD.Options.Delete, this.selectedField.key).subscribe({
      next : (res: ApiResponse) => {
        // TODO: `response?.Status` should be handled on the HomegenieAdapter side
        if (res.response?.Status === ResponseStatus.Ok) {
          this.module.fields.splice(this.module.fields.indexOf(this.selectedField), 1);
          this.yot.saveConfiguration();
        } else {
          this.yot.notify('Error', res.response.Message, {
            duration: 2000,
            verticalPosition: 'bottom'
          });
        }
        this.isLoading = false;
      },
      error: (err) => {
        this.yot.notify('Error', err.message, {
          duration: 2000,
          verticalPosition: 'bottom'
        });
        this.isLoading = false;
      }
    });
  }
  editField(field: ModuleField) {
    if (this.selectedField !== field) {
      setTimeout(() => {
        this.selectedField = field;
        this.value = field?.value;
      });
    }
  }

  protected readonly now = now;
}
