import {Component, ElementRef, OnInit} from '@angular/core';
import {ControlFieldBase} from "../control-field-base";
import {CodeModel} from "@ngstack/code-editor";
import {CMD, YotService} from "../../../services/yot/yot.service";
import {HomegenieAdapter} from "../../../adapters/home-genie/homegenie-adapter";
import {MatSnackBar} from "@angular/material/snack-bar";

@Component({
  selector: 'app-editor-control',
  templateUrl: './editor-control.component.html',
  styleUrls: ['./editor-control.component.scss']
})
export class EditorControlComponent extends ControlFieldBase implements OnInit {

  theme = 'vs-dark'; // 'hc-black';
  codeModel: CodeModel = {
    language: 'markdown',
    uri: 'schedule-script-editor',
    value: ``,
    dependencies: [ ]
  };
  extraLib: monaco.IDisposable;
  options: monaco.editor.IStandaloneEditorConstructionOptions = {
    lineNumbers: 'on',
    contextmenu: true,
    fixedOverflowWidgets: true,
    cursorWidth: 2,
    cursorBlinking: 'expand',
    cursorSmoothCaretAnimation: 'on',
    cursorStyle: 'line',
    automaticLayout: true,
    readOnly: true,
    minimap: {
      enabled: false,
    },
    tabSize: 2
  };

  destinationFileName = '';


  private _showEditor = false;
  get showEditor() {
    return this._showEditor;
  }
  set showEditor(value: boolean) {
    const el = this.view.nativeElement;
    const $dialog = zuix.$(el).parent('.mat-dialog-content');

    if (!value) {
      this._showEditor = value;
      this.requestModal.emit({ field: this, value });

      $dialog.css('overflow-y', 'auto');

      return;
    }

    ($dialog.get() as HTMLElement).scrollTop = 0;
    $dialog.css('overflow-y', 'hidden');

    const valueType = this.data.type.options[0];
    const fileName = this.data.type.options[1];
    const editorLanguage = this.data.type.options[2];

    switch (valueType) {

      case 'file':

        this.destinationFileName = fileName;

        this.isBusy = true;
        const adapter = (this.module.getAdapter() as HomegenieAdapter);
        adapter
          .apiCall(`HomeAutomation.HomeGenie/FileManager/ReadText/${ encodeURIComponent(fileName) }`)
          .subscribe({
            next: (res) => {
              if (res?.response?.Status !== 'Error') {
                let text = res.response;
                if (typeof text === 'object' && text !== null) {
                  text = JSON.stringify(text, null, 2);
                } else {
                  text = String(text);
                }
                this.codeModel.value = text;
              } else {
                this.codeModel.value = '';
              }
              this.codeModel.language = editorLanguage;
              this._showEditor = true;
              this.isBusy = false;
            },
            error: (err) => {
// TODO: report error
              //console.log(err);
              this._showEditor = true;
              this.isBusy = false;
            }
          });

        this.requestModal.emit({ field: this, value });
        break;

      case 'value':

// TODO: .... update field value

        break;
    }

  }

  ///*
  constructor(
    private view: ElementRef,
    protected _snackBar: MatSnackBar,
    public yot: YotService
  ) {
    super(_snackBar, yot);
  }
  //*/

  protected isBusy = false;

  ngOnInit(): void {
    super.ngOnInit();

    this.theme = this.yot.preferences.ui.theme === 'light' ? 'vs' : 'vs-dark';
    this.destinationFileName = this.data.type?.options[1];
  }

  saveModal() {
    super.saveModal();
    this.showEditor = false;

    const valueType = this.data.type.options[0];
    const fileName = this.data.type.options[1];

    switch (valueType) {

      case 'file':

        this.isBusy = true;
        const adapter = (this.module.getAdapter() as HomegenieAdapter);
        adapter
          .apiCall(`HomeAutomation.HomeGenie/FileManager/WriteText/${ encodeURIComponent(fileName) }`, this.codeModel.value)
          .subscribe(res => {
            // update option to signal update
            this.module.control(CMD.Options.Set, {[this.data.field.key]: this.data.field.value}).subscribe((res) => {
              //console.log(res);
            });
            this.isBusy = false;

          });

        break;

      case 'value':

// TODO: .... update field value

        break;
    }

  }
  cancelModal() {
    super.cancelModal();
    this.showEditor = false;
  }

  onCodeChanged(value) {
    //if (this.scheduleAction.actionType === "script") {
    //  this.schedulerItem.Script = value;
    //}
  }

}
