import {Component, Input, OnInit, ViewChild} from '@angular/core';
import {Program} from "../../../adapters/home-genie/homegenie-api";
import {HomegenieAdapter} from "../../../adapters/home-genie/homegenie-adapter";

@Component({
  selector: 'app-program-info',
  templateUrl: './program-info.component.html',
  styleUrls: ['./program-info.component.scss']
})
export class ProgramInfoComponent implements OnInit {
  @ViewChild('programName', {static: true})
  programName;
  @ViewChild('groupName', {static: true})
  groupName;

  @Input()
  adapter: HomegenieAdapter;
  @Input()
  program: Program;

  programGroups: string[] = [];

  get valid(): boolean {
    return this.programName && this.programName.valid
      && this.groupName && this.groupName.valid;
  }

  constructor() { }

  ngOnInit(): void {

    // get programs group list for auto-complete in program's Group text input
    this.adapter.programs.forEach((p) => {
      if (!this.programGroups.includes(p.Group)) {
        this.programGroups.push(p.Group);
      }
    });
    // Sort groups
    this.programGroups
      .sort((g1, g2) => g1.localeCompare(g2));

  }

}
