  @HostListener('document:keydown.control.s', ['$event'])
  onKeydownHandler(event: KeyboardEvent) {
    event.preventDefault();
    this.onSaveButtonClick(event);
  }

  constructor(private yot: YotService, private navigationService: NavigationService, private dialog: MatDialog, private _bottomSheet: MatBottomSheet, private route: ActivatedRoute, private snackBar: MatSnackBar) {
    this.theme = yot.preferences.ui.theme === 'light' ? 'vs' : 'vs-dark';
  }

  canDeactivate(): Observable<boolean> | boolean {
    if (this.canUpdate) {
      // translations
      let textExitWithoutSaving = 'exit_without_saving';
      this.yot.translate.get(textExitWithoutSaving).subscribe((tr) => textExitWithoutSaving = tr);
      let textChangesWillBeLost = 'changes_will_be_lost';
      this.yot.translate.get(textChangesWillBeLost).subscribe((tr) => textChangesWillBeLost = tr);
      // show dialog
      const subject = new Subject<boolean>();
      const dialogRef = this.yot.dialog.open(ActionConfirmDialogComponent, {
        data: {
          title: textExitWithoutSaving,
          message: textChangesWillBeLost
        } as ActionConfirmDialogConfig
      });
      dialogRef.afterClosed().subscribe((confirm) => {
        subject.next(confirm === true);
        subject.complete();
      });
      return subject.asObservable();
    }
    return true;
  }

  ngOnInit(): void {
    this.activatedRouteSubscription = this.route.params.subscribe((params) => {
      const path = params['path'];
      const name = params['name'];
      this.componentId = `${path}/${name}`;

      // validation settings
      monaco.typescript.javascriptDefaults.setDiagnosticsOptions({
        noSemanticValidation: true,
        noSyntaxValidation: false,
        noSuggestionDiagnostics: false,
        diagnosticCodesToIgnore: [2451, 2722, 7006, 18048] // work-around for "Cannot redeclare block-scoped variable"
      });
      // compiler options
      monaco.typescript.javascriptDefaults.setCompilerOptions({
        alwaysStrict: true,
        strict: true,
        strictFunctionTypes: true,
        target: monaco.typescript.ScriptTarget.ES2015,
        allowNonTsExtensions: true,
        noLib:false
      });

      // load JS API defs for Monaco editor (zuix.d.ts as well)
      this.yot.http.get('assets/editor/zuix.d.ts', {responseType: 'text'})
        .subscribe((res) => {
          const additionalDeclarations = "/** info object */ declare const info: any;"; // <-- TODO: just a test, to be used to declare component's context variables/members
          monaco.typescript.javascriptDefaults.addExtraLib(
            `${res}\n${additionalDeclarations}`,
            'file:///assets/editor/zuix.d.ts'
          );
        });

      // make Monaco recognize "jscript" as "javascript" alias
      (monaco.languages.getLanguages().find((lang) => lang.id === 'html') as any).loader().then(
        (lang) => {
          const tokenizer = lang.language.tokenizer;
          tokenizer.scriptAfterTypeEquals.unshift([
            /'jscript'/, {token: 'attribute.value', switchTo: '@scriptWithCustomType.text/javascript'}
          ]);
          tokenizer.scriptAfterTypeEquals.unshift([
            /"jscript"/, {token: 'attribute.value', switchTo: '@scriptWithCustomType.text/javascript'}
          ]);
        }
      );

      // Refresh widget if error markers changed
      this.markerChangeListener = monaco.editor.onDidChangeMarkers(changes => {
        this.refresh();
      });

      this.yot.layoutService.contextualHelpLink = 'https://homegenie.it/server/programming/widgets/';
    });

    this.navigationService.drawer.close();
    this.navigationService
      .appMenuChange
        .next('widget');
    this.navigationService
      .navigationToolbar
        .next({ title: this.componentId });

    // initial widget options: load html/css/js from file
    this.isLoading = true;
    this.widgetOptions = {
      disableMenu: true,
      componentId: this.componentId,
      ready: (ctx) => {
        this.componentContext = ctx;
        this.isLoading = false;
        this.loadResources();
      },
      error: (err) => {
        this.isLoading = false;
        this.loadResources();
        console.log(err);
      }
    };

    this.widgetEventSubscription = this.yot.onWidgetUpdated.subscribe({
      next: (widget) => {

        if (widget.id !== this.componentId) {
          console.log("Widget Update ignored: ID mismatch", widget.id, this.componentId);
          return;
        }

        const updateWidgetModel = (type: WidgetCodeType, newValue: string) => {
          if (!newValue) return;

          const cm = this.codeModel[type];
          const model = monaco.editor.getModel(`file:///${cm.uri}` as any);

          if (model) {
            // Usiamo pushEditOperations invece di setValue per preservare la cronologia
            model.pushEditOperations(
              [],
              [
                {
                  range: model.getFullModelRange(),
                  text: newValue,
                },
              ],
              () => null
            );

            // Segnala che il modello ha bisogno di essere formattato
            cm.needsFormatting = true;
          }
        };

        // Aggiorna i tre modelli se i dati sono presenti nel messaggio del Genie
        updateWidgetModel(WidgetCodeType.HtmlCode, widget.html);
        updateWidgetModel(WidgetCodeType.CssCode, widget.css);
        updateWidgetModel(WidgetCodeType.JsCode, widget.js);

        // Esegue la formattazione per il tab attualmente visibile
        this.updateCodeModelFormatting(this.currentCodeModelType);
      }
    });
  }
  ngOnDestroy() {
    this.activatedRouteSubscription?.unsubscribe();
    this.widgetEventSubscription?.unsubscribe();
    this.extraLib?.dispose();
    this.markerChangeListener?.dispose();

    this.navigationService.drawer.open();
    this.navigationService
      .navigationToolbar.next({ title: '' });
    this.navigationService
      .appMenuChange.next('');

    clearTimeout(this.refreshTimeout);

//    zuix.unload(this.zuixComponent.nativeElement);
    zuix.setComponentCache([]);
  }

