import {Component, ElementRef, EventEmitter, Input, OnDestroy, OnInit, Output, ViewChild} from '@angular/core';

export class CategoryCardData {
  public id: string;
  public name: string;
  public poster: string;
}

@Component({
  selector: 'app-movie-category-carousel',
  templateUrl: './movie-category-carousel.component.html',
  styleUrls: ['./movie-category-carousel.component.scss']
})
export class MovieCategoryCarouselComponent implements OnInit, OnDestroy {
  @Input() title: string;
  @Input() categories: CategoryCardData[] = [];
  @Input() highlight: boolean = false;

  @ViewChild('scroller', {static: true}) scroller!: ElementRef<HTMLElement>;

  viewPager: any = null;

  @Output()
  itemClicked: EventEmitter<any> = new EventEmitter();
  @Output()
  itemChanged: EventEmitter<any> = new EventEmitter();

  @Input()
  currentPage: number = 0;

  constructor() { }

  ngOnInit(): void {
    setTimeout(() => {
      zuix.componentize(/*this.scroller.nativeElement*/);
    }, 100);
    zuix.context(this.scroller?.nativeElement, (ctx) => {
      this.viewPager = ctx;
      this.viewPager.on('page:change', (e, page) => this.pageChanged(e, page));
      this.viewPager.page(this.currentPage);
    });
  }
  ngOnDestroy() {
    if (this.viewPager) {
      zuix.unload(this.viewPager);
    }
  }

  pageChanged(e, page) {
    this.currentPage = +page.in;
    const pageIn = this.viewPager.get(this.currentPage);
    if (pageIn) {
      pageIn.addClass('page-active');
    }
    const pageOut = this.viewPager.get(+page.out);
    if (pageOut) {
      pageOut.removeClass('page-active');
    }
    this.itemChanged.emit(this.categories[this.currentPage]);
  }

  protected onItemClick(m: CategoryCardData) {
    if (this.categories.indexOf(m) === this.viewPager?.page()) {
      this.itemClicked.emit(m);
    } else {
      this.viewPager?.page(this.categories.indexOf(m));
    }
  }
}
