import {Component, Inject, OnDestroy, OnInit} from '@angular/core';
import {MAT_DIALOG_DATA, MatDialog, MatDialogRef} from "@angular/material/dialog";
import {Dashboard} from "../../../services/dashboard/dashboard";
import {YotService} from "../../../services/yot/yot.service";
import {
  RenameDashboardDialogComponent
} from "../../../components/dialogs/rename-dashboard-dialog/rename-dashboard-dialog.component";
import {PagesRoute} from "../../../pages-route";
import {
  ActionConfirmDialogComponent,
  ActionConfirmDialogConfig
} from "../../../components/dialogs/action-confirm-dialog/action-confirm-dialog.component";
import {NavigationService} from "../../../services/navigation.service";
import {map} from "rxjs/operators";
import * as yaml from 'js-yaml';

@Component({
  selector: 'app-dashboard-theme-dialog',
  templateUrl: './dashboard-theme-dialog.component.html',
  styleUrls: ['./dashboard-theme-dialog.component.scss']
})
export class DashboardThemeDialogComponent implements OnInit, OnDestroy {

  imageBase64: string | null = null;

  isNetworkBusy = false;
  cardColor: string;
  cardOpacity: number;
  cardBlur: number;

  wallpaperList = [];

  constructor(@Inject(MAT_DIALOG_DATA) public dashboard: Dashboard,
              private dialog: MatDialog,
              private dialogRef: MatDialogRef<DashboardThemeDialogComponent>,
              private yot: YotService,
              private navigationService: NavigationService) {
  }

  ngOnInit(): void {
    const theme = this.yot.dashboardService.getDashboardTheme(this.dashboard);
    if (theme) {
      this.imageBase64 = theme.wallpaper;
      this.cardColor = theme.cardColor;
      this.cardOpacity = theme.cardOpacity;
      this.cardBlur = theme.cardBlur;

      this.yot.http.get(`assets/images/wallpapers/${this.yot.preferences.ui.theme}/index.yaml`, { responseType: 'text' })
        .pipe(
          map(yamlString => {
            return yaml.load(yamlString);
          })
        ).subscribe((wallpapers) => {
          this.wallpaperList = [...wallpapers?.wallpapers];
        });

    }
    setTimeout(() => {
      (zuix.$.find('.cdk-overlay-backdrop').get() as HTMLElement).style.backgroundColor = '#00000000';
    }, 150);
  }
  ngOnDestroy(): void {
    this.saveConfig();
  }

  onFileSelected(event: Event): void {
    const input = event.target as HTMLInputElement;
    if (input.files && input.files[0]) {
      const file = input.files[0];
      const reader = new FileReader();
      reader.onload = () => {
        this.setWallpaper(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  }

  onNoClick(): void {
    this.dialogRef.close();
  }

  onMenuOpened() {

  }
  onRenameDashboardClick(e) {
    const dialogRef = this.dialog.open(RenameDashboardDialogComponent, {
      disableClose: false,
      width: '100%',
      maxWidth: '360px',
      data: {
        defaultValue: this.dashboard.name
      }
    });
    dialogRef.afterClosed().subscribe((dashboardName) => {
      if (dashboardName) {
        this.isNetworkBusy = true;
        this.yot.dashboardService.renameDashboard(this.dashboard.name, dashboardName);
          this.navigationService.router.navigate([ PagesRoute.HomePage, dashboardName ])
            .then((res) => {
              this.isNetworkBusy = false;
            });
      }
    });
  }
  onRemoveDashboardClick(e) {
    const name = this.yot.dashboardService.getCurrentDashboard().name;
    this.yot.translate.get(['confirm_action', 'delete_dashboard_confirm'], {name})
      .subscribe((res) => {
        const dialogRef = this.dialog.open(ActionConfirmDialogComponent, {
          width: '320px',
          disableClose: false,
          data: {
            title: res['confirm_action'],
            message: res['delete_dashboard_confirm']
          } as ActionConfirmDialogConfig
        });
        dialogRef.afterClosed().subscribe((confirm) => {
          if (confirm) {
            this.isNetworkBusy = true;
            this.yot.dashboardService.removeDashboard(this.dashboard.name);
            this.saveConfig(() => {
              this.navigationService.router.navigate([ PagesRoute.HomePage ])
                .then((res) => {
                  this.isNetworkBusy = false;
                  this.dialogRef.close();
                });
            });
          }
        });
      });
  }

  onCardColorChange($e: any) {
    const color = $e.target.value;
    const theme = this.yot.dashboardService.getDashboardTheme(this.dashboard);
    theme.cardColor = color;
    this.yot.dashboardService.setDashboardCardColor(color, theme.cardOpacity, theme.cardBlur);
  }

  onOpacityInput($e: any) {
    const opacity = $e.value; // 0 - 100
    const theme = this.yot.dashboardService.getDashboardTheme(this.dashboard);
    theme.cardOpacity = opacity;
    this.yot.dashboardService.setDashboardCardColor(theme.cardColor, theme.cardOpacity, theme.cardBlur);
  }
  onBlurInput($e: any) {
    const blur = $e.value; // 0 - 100
    const theme = this.yot.dashboardService.getDashboardTheme(this.dashboard);
    theme.cardBlur = blur;
    this.yot.dashboardService.setDashboardCardBlur(theme.cardBlur);
  }

  setWallpaper(wallpaper?) {
    const result = this.getWallpaperPath(wallpaper);
    const defaultTheme = this.yot.dashboardService.getDefaultTheme();
    const theme = this.yot.dashboardService.getDashboardTheme(this.dashboard);
    theme.wallpaper = this.imageBase64 = result as string;
    this.yot.dashboardService.setDashboardWallpaper(theme.wallpaper);
    if (!wallpaper) {
      // reset to default
      this.cardColor = theme.cardColor = defaultTheme.cardColor;
      this.cardOpacity = theme.cardOpacity = defaultTheme.cardOpacity;
      this.cardBlur = theme.cardBlur = defaultTheme.cardBlur;
    } else {
      // apply selected wallpaper theme
      this.cardColor = theme.cardColor = wallpaper.card?.color || defaultTheme.cardColor;
      this.cardOpacity = theme.cardOpacity = wallpaper.card?.opacity || defaultTheme.cardOpacity;
      this.cardBlur = theme.cardBlur = wallpaper.card?.blur || defaultTheme.cardBlur;
    }
    this.yot.dashboardService.setDashboardCardColor(this.cardColor, this.cardOpacity, this.cardBlur);
    this.saveConfig();
  }

  private saveConfig(callback?: Function | undefined) {
      // save config
      this.navigationService.isLoading = true;
      this.yot.saveConfiguration().subscribe((e) => {
        this.navigationService.isLoading = false;
        if (callback) {
          callback();
        }
      });
  }

  protected getWallpaperPath(wallpaper: any) {
    if (typeof(wallpaper) === 'string') {
      return wallpaper;
    }
    return wallpaper ? `assets/images/wallpapers/${this.yot.preferences.ui.theme}/${wallpaper.background?.file}` : '';
  }
}
