import {Component, EventEmitter, Input, Output} from '@angular/core';

@Component({
  selector: 'app-saturation-slider',
  templateUrl: './saturation-slider.component.html',
  styleUrls: ['./saturation-slider.component.scss']
})
export class SaturationSliderComponent {

  @Input() hue: number = 0;
  @Input() saturation: number = 100;
  @Output() saturationChange = new EventEmitter<number>();

  onInput(event: Event) {
    const value = +(event.target as HTMLInputElement).value;
    this.saturationChange.emit(value);
  }
}
