import {Component, Inject} from '@angular/core';
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {YotService} from "../../../services/yot/yot.service";

@Component({
  selector: 'app-rename-dashboard-dialog',
  templateUrl: './rename-dashboard-dialog.component.html',
  styleUrls: ['./rename-dashboard-dialog.component.scss']
})
export class RenameDashboardDialogComponent {
  dashboardName: string;
  originalName: string;
  dashboardNameList: string[] = [];

  constructor(@Inject(MAT_DIALOG_DATA) data, private yot: YotService) {
    this.dashboardName = this.originalName = data?.defaultValue;
    this.dashboardNameList = yot.dashboardService.dashboards.map((d) => d.name)
      .filter((n) => n !== this.dashboardName);
  }
}
