import {EventEmitter, Injectable, OnDestroy, OnInit} from "@angular/core";
import {Location} from '@angular/common';
import {MatDrawer} from "@angular/material/sidenav";
import {YotService} from "./yot/yot.service";
import {Subscription} from "rxjs";
import {NavigationEnd, Router} from "@angular/router";
import {PagesRoute} from "../pages-route";

export class NavigationToolbarEventValue {
  title?: string;
  show?: boolean;
}
export class LoadingOverlayEventValue {
  show: boolean;
}

export class UiEventArg {
  public event: UiEvents;
  public value: DrawerModeEventValue | DrawerStateEventValue;
  public data?: any;
}
export enum UiEvents {
  DrawerState = 'ui:drawer-state',
  DrawerMode = 'ui:drawer-mode'
}
export enum DrawerModeEventValue {
  Side = 'side',
  Over = 'over'
}
export enum DrawerStateEventValue {
  Opened = 'opened',
  Closed = 'closed'
}

@Injectable({
  providedIn: 'root',
})
export class NavigationService implements OnInit, OnDestroy {
  public navigationToolbar = new EventEmitter<NavigationToolbarEventValue>();
  public loadingOverlay = new EventEmitter<LoadingOverlayEventValue>();
  public drawerEvents = new EventEmitter<UiEventArg>();
  public toolbarTitle = new EventEmitter<string>();
  public appMenuChange = new EventEmitter<string>();

  public drawer: MatDrawer;

  public route: string;
  public subRoute: string;

  public isShowingToolbar: boolean = true;

  private hideToolBarTimeout;
  private lastChangeTs = new Date().getTime();
  private drawerChangeSubscription: Subscription;
  private redirectTimeout;

  constructor(private location: Location, private yot: YotService, public router: Router) {
    router.events.subscribe(event => {
      if (!(event instanceof NavigationEnd)) {
        return;
      }
      let route = window.location.pathname;
      if (window.location.pathname.startsWith('/')) {
        route = route.substring(1);
      }
      const routeParts = route.split('/');
      if (routeParts[0] === 'app') { // TODO: replace this with production base url var
        this.route = routeParts[1];
        this.subRoute = routeParts[2];
      } else {
        this.route = route.split('/')[0];
        this.subRoute = routeParts[1];
      }
      // close drawer if mode is 'over'
      if (this.drawer.mode === 'over') {
        this.drawer.close();
      }
      // reposition to top of page
      window.scrollTo({ top: 0 });
      // redirect to dashboards home
      if (this.route === '') {
        console.log('redirecting home page')
        this.redirectHomePage();
      } else {
        //console.log(this.route);
      }
    });
  }

  ngOnInit() {
  }
  ngOnDestroy() {
    clearTimeout(this.hideToolBarTimeout);
    if (this.drawerChangeSubscription) {
      this.drawerChangeSubscription.unsubscribe();
    }
  }

  setDrawer(drawer: MatDrawer) {
    this.drawer = drawer;
    if (this.drawerChangeSubscription) {
      this.drawerChangeSubscription.unsubscribe();
    }
    this.drawerChangeSubscription = this.drawer.openedChange.subscribe((opened) => {
      if (opened) {
        this.drawerEvents.next({
          event: UiEvents.DrawerState,
          value: DrawerStateEventValue.Opened
        });
        if (this.drawer.mode === 'side') {
          this.yot.preferences.ui.drawer.open = true;
          this.yot.savePreferences();
        }
      } else {
        this.drawerEvents.next({
          event: UiEvents.DrawerState,
          value: DrawerStateEventValue.Closed
        });
        this.yot.preferences.ui.drawer.open = false;
        this.yot.savePreferences();
      }
    });
  }

  navigateBack() {
    if (this.subRoute == null) {
      this.router
        .navigate([PagesRoute.HomePage])
        .then(() => {
          // TODO: ...
        });
    } else {
      this.location.back();
    }
  }

  showToolbar() {
    const now = new Date().getTime();
    if (now - this.lastChangeTs > 200) {
      this.navigationToolbar.next({ show: true });
      this.lastChangeTs = now;
    } else {
      clearTimeout(this.hideToolBarTimeout);
      this.hideToolBarTimeout = setTimeout(() => {
        this.navigationToolbar.next({ show: true });
        this.lastChangeTs = now;
      }, 200);
    }
    this.isShowingToolbar = true;
  }
  hideToolbar() {
    const now = new Date().getTime();
    if (now - this.lastChangeTs > 200) {
      this.navigationToolbar.next({ show: false });
      this.lastChangeTs = now;
    } else {
      clearTimeout(this.hideToolBarTimeout);
      this.hideToolBarTimeout = setTimeout(() => {
        this.navigationToolbar.next({ show: false })
        this.lastChangeTs = now;
      }, 200);
    }
    this.isShowingToolbar = false;
  }

  toggleDrawerMode(mode?: 'side' | 'over', open?: boolean) {
    if (mode) {
      this.drawer.mode = mode;
      this.drawer.disableClose = open;
    } else if (this.drawer.mode !== 'side') {
      this.drawer.mode = 'side';
      this.drawer.disableClose = true;
      this.drawerEvents.next({
        event: UiEvents.DrawerMode,
        value: DrawerModeEventValue.Side
      });
    } else {
      this.drawer.mode = 'over';
      this.drawer.disableClose = false;
      this.drawer.close().then((res) => console.log(res));
      this.drawerEvents.next({
        event: UiEvents.DrawerMode,
        value: DrawerModeEventValue.Over
      });
    }
    this.yot.preferences.ui.drawer.mode = this.drawer.mode;
    this.yot.preferences.ui.drawer.open = this.drawer.disableClose;
    this.yot.savePreferences();
  }

  reload(callback?) {
    this.router.navigate([ '/' ], {skipLocationChange: true} )
      .then(() => {
        this.router.navigate([ PagesRoute.HomePage ] )
          .then((res) => {
            if (callback) callback(res);
          });
      });
  }

  private _isLoading = 0;
  get isLoading(): boolean {
    return this._isLoading !== 0;
  }
  set isLoading(v) {
    this._isLoading += (v ? 1 : -1);
    this.isLoading ? this.showPageLoading()
      : this.showPageReady();
  }
  setLoading(count: number) {
    if (count === 0) {
      this._isLoading = 1;
      this.isLoading = false;
    } else {
      this._isLoading += (count - 1);
      this.isLoading = true;
    }
  }

  private showPageLoading() {
    this.loadingOverlay.next({ show: true });
  }
  private showPageReady() {
    this.loadingOverlay.next({ show: false });
  }

  private redirectHomePage() {
    if (this.redirectTimeout) {
      clearTimeout(this.redirectTimeout);
    }
    this.redirectTimeout = setTimeout(() => {
      this.reload();
    });
  }
}
