import {Component, Inject, OnInit, Optional} from '@angular/core';
import {MAT_BOTTOM_SHEET_DATA, MatBottomSheetRef} from "@angular/material/bottom-sheet";
import {CMD, FLD, YotService} from "../../../../services/yot/yot.service";
import {Module} from "../../../../services/yot/module";
import {forkJoin, Observable} from "rxjs";
import {Dashboard} from "../../../../services/dashboard/dashboard";
import {UtilsService} from "../../../../services/utils.service";
import {WidgetType} from "../../../../api/widgets/widget-type";

@Component({
  selector: 'app-lights-bottom-sheet',
  templateUrl: './lights-bottom-sheet.component.html',
  styleUrls: ['./lights-bottom-sheet.component.scss']
})
export class LightsBottomSheetComponent implements OnInit {

  dashboard: Dashboard;
  hue = 180;
  saturation= 50;
  level = 0;
  modules: Module[];

  hasColorLights = false;

  isBusy = false;
  private commandTimeout = null;

  get totalWatts(): number {
    let total = 0;
    this.modules
      .filter((m) => this.isOn(m))
      .forEach((m) => {
        const mw = m.field(FLD.Meter.Watts);
        if (mw && mw.value) {
          total += this.utils.getFloatValue(mw.value);
        }
      });
    return total;
  }

  get lightsCount() {
    const on = this.modules
      .filter((m) => this.isOn(m))
      .length;
    return on + "/" + this.modules.length;
  }

  constructor(
    @Optional() private bsRef: MatBottomSheetRef<any>,
    @Inject(MAT_BOTTOM_SHEET_DATA) public data: any,
    private yot: YotService,
    private utils: UtilsService
  ) {
    this.dashboard = data.dashboard;
    this.modules = data.modules;
    this.hasColorLights = data.modules?.filter((w) => w.type === WidgetType.Color).length > 0;
  }

  closeSheet() {
    this.bsRef.dismiss();
  }

  ngOnInit(): void {
    let activeLights = 0;
    this.modules
      .filter((m) => this.isOn(m))
      .map((module) => {
        const hsvField = module.field(FLD.Status.ColorHsb);
        if (hsvField) {
          let hsv = hsvField.value.split(',').map(v => +v);
          const h = hsv[0] * 360;
          const s = hsv[1] * 100;
          const v = hsv[2] * 100;
//          if (hsv[3]) {
//            this.colorTransition = hsv[3] + 's';
//          }
//          const c = new Color();
//          c.setHsva(h, s, v, 1);
//          this._color = c.toHexString();
          this.hue = h;
          this.saturation = s;
        }
        const levelField = module.field(FLD.Status.Level);
        this.level += 100 * this.utils.getFloatValue(levelField?.value);
        activeLights++;
      });
    if (activeLights) {
      this.level /= activeLights;
    }
  }

  onSliderInput(e): void {
    this.level = e.value;
    this.setLevel();
  }

  lightsOff() {
    const controlObservables: Observable<any>[] = [];
    this.modules.forEach((module) => {
      controlObservables.push(
        module.control(CMD.Control.Off)
      );
    });
    forkJoin(controlObservables).subscribe({
      next: (allResults) => {
        // TODO: ...
      },
      error: (err) => {
        // one or more requests failed
        // TODO: ...
      },
      complete: () => {
        // TODO: ...
        setTimeout(() => this.updateAverageLevel(), 200);
      }
    });
  }
  lightsOn() {
    const controlObservables: Observable<any>[] = [];
    this.modules.forEach((module) => {
      controlObservables.push(
        module.control(CMD.Control.On)
      );
    });
    forkJoin(controlObservables).subscribe({
      next: (allResults) => {
        // TODO: ...
      },
      error: (err) => {
        // one or more requests failed
        // TODO: ...
      },
      complete: () => {
        // TODO: ...
        setTimeout(() => this.updateAverageLevel(), 200);
      }
    });
  }

  private updateAverageLevel() {
    this.level = 0;
    this.modules
      .filter((m) => this.isOn(m))
      .map((module) => {
        const levelField = module.field(FLD.Status.Level);
        this.level += 100 * this.utils.getFloatValue(levelField?.value);
      });
    this.level /= this.modules.length;
  }

  private isOn(module: Module): boolean {
    return this.utils.getFloatValue(module.field(FLD.Status.Level)?.value) > 0;
  }

  private setLevel() {
    clearTimeout(this.commandTimeout);
    if (this.isBusy) {
      this.commandTimeout = setTimeout(() => this.setLevel());
      return;
    }

    this.isBusy = true;
    const controlObservables: Observable<any>[] = [];
    this.modules.filter((m) => this.isOn(m)).forEach((module) => {
      controlObservables.push(
        module.control(CMD.Control.Level, this.level)
      );
    });
    forkJoin(controlObservables).subscribe({
      next: (allResults) => {
        // TODO: ...
      },
      error: (err) => {
        // one or more requests failed
        // TODO: ...
      },
      complete: () => {
        this.isBusy = false;
      }
    });
  }


  setColorHsb() {
    clearTimeout(this.commandTimeout);
    if (this.isBusy) {
      this.commandTimeout = setTimeout(() => this.setColorHsb());
      return;
    }

    this.isBusy = true;
    const controlObservables: Observable<any>[] = [];
    this.modules.filter((m) => this.isOn(m)).forEach((module) => {
      controlObservables.push(
        module.control(CMD.Control.ColorHsb, `${this.hue / 360.0},${this.saturation / 100.0},${this.level / 100.0},0.2`)
      );
    });
    forkJoin(controlObservables).subscribe({
      next: (allResults) => {
        // TODO: ...
      },
      error: (err) => {
        // one or more requests failed
        // TODO: ...
      },
      complete: () => {
        this.isBusy = false;
      }
    });
  }

}
