import {Component, Inject, OnInit} from '@angular/core';
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {HomegenieAdapter} from "../../homegenie-adapter";
import {LocationInfo} from "../../../geolocation-adapter";

@Component({
  selector: 'app-location-dialog',
  templateUrl: './location-dialog.component.html',
  styleUrls: ['./location-dialog.component.scss']
})
export class LocationDialogComponent implements OnInit {
  adapter: HomegenieAdapter;
  currentLocation: LocationInfo;

  get changed() {
    let info = {
      name: this.data.locationInfo.name,
      latitude: this.data.locationInfo.latitude,
      longitude: this.data.locationInfo.longitude
    };
    return JSON.stringify(info) !== JSON.stringify(this.currentLocation);
  }

  constructor(@Inject(MAT_DIALOG_DATA) public data) {
    if (data && data.locationInfo) {
      this.currentLocation = {
        name: data.locationInfo.name,
        latitude: data.locationInfo.latitude,
        longitude: data.locationInfo.longitude
      };
    }
    if (data && data.adapter) {
      this.adapter = data.adapter;
    }
  }

  ngOnInit(): void {
  }

  onLocationChange(locationInfo: LocationInfo) {
    this.currentLocation = locationInfo;
  }
}
