import {Component, OnDestroy, OnInit} from '@angular/core';
import {YotService} from "../../services/yot/yot.service";
import {NavigationService} from "../../services/navigation.service";
import {Subject} from "rxjs";
import {
  TextInputDialogComponent,
  TextInputDialogConfig
} from "../../components/dialogs/text-input-dialog/text-input-dialog.component";
import {
  ActionConfirmDialogComponent,
  ActionConfirmDialogConfig
} from "../../components/dialogs/action-confirm-dialog/action-confirm-dialog.component";
import {ClientConfigService} from "../../services/client-config.service";
import {VoiceControlService} from "../../services/voice-control.service";
import {SpeechSynthesisService} from "../../services/speech-synthesis.service";

@Component({
  selector: 'app-region-settings',
  templateUrl: './preferences-page.component.html',
  styleUrls: ['./preferences-page.component.scss']
})
export class PreferencesPageComponent implements OnInit, OnDestroy {
  unitsList = {};
  presetsList = [];
  languagesList: any = {};

  get currentTheme(): string {
    return this.yot.preferences.ui.theme;
  }
  set currentTheme(themeClass: string) {
    this.yot.setUiTheme(themeClass);
    this.saveConfig();
  }

  get unitsPreference(): any {
    return this.yot.preferences.units;
  }

  constructor(
    public yot: YotService,
    private navigationService: NavigationService,
    protected clientConfigService: ClientConfigService,
    private voiceControlService: VoiceControlService,
    private speechSynthesisService: SpeechSynthesisService,
  ) {
    // build units list definitions
    Object.keys(yot.converters).forEach(key => {
      this.unitsList[key] = yot.converters[key]().list();
    });
    this.clientConfigService.getLanguagesList().subscribe(list => this.languagesList = list);
  }

  ngOnInit(): void {
    this.reloadList();
    this.navigationService.toolbarTitle.emit('preferences');
  }
  ngOnDestroy() {
    this.saveConfig();
  }
  onUiLanguageChange(lang) {
    this.yot.setUiLanguage(lang).subscribe(actualLanguage => {
      lang = actualLanguage;
      // save and reload UI
      this.saveConfig().subscribe(() => {
        location.reload();
      });
    });
  }
  onSelectedPresetChange(p) {
    const presetName = p.options[0].value;
    this.saveConfig().subscribe(() => {
      this.clientConfigService
        .loadClientPreset(presetName);
    });
  }
  onCreateConfigClick() {
    this.yot.translate.get(['create_configuration', 'only_letters_numbers'])
      .subscribe((res: string) => {
        const dialogRef = this.yot.dialog.open(TextInputDialogComponent, {
          disableClose: false,
          data: {
            title: res['create_configuration'],
            label: 'name',
            placeholder: 'enter_name',
            pattern: '([A-Za-z0-9-_]+)',
            patternError: res['only_letters_numbers'],
            value: ''
          } as TextInputDialogConfig
        });
        dialogRef.afterClosed().subscribe((name) => {
          if (name && name.length > 1) {
            this.yot.saveConfiguration().subscribe((config) => {
              this.clientConfigService
                .saveClientPreset(config, name)
                .subscribe(() => this.reloadList());
            });
          }
        });
      });
  }

  onDeleteConfigClick() {
    this.yot.translate.get(['confirm_action', 'delete_configuration'], {name: this.yot.clientPreset})
      .subscribe((res: string) => {
        const dialogRef = this.yot.dialog.open(ActionConfirmDialogComponent, {
          width: '320px',
          disableClose: false,
          data: {
            title: res['confirm_action'],
            message: res['delete_configuration']
          } as ActionConfirmDialogConfig
        });
        dialogRef.afterClosed().subscribe((deleteConfirm) => {
          if (deleteConfirm) {
            this.clientConfigService
              .deleteClientPreset(this.yot.clientPreset)
              .subscribe(() => this.reloadList());
          }
        });
      });
  }

  private saveConfig(): Subject<void> {
    const subject = new Subject<void>();
    this.navigationService.isLoading = true;
    this.yot.savePreferences().subscribe((prefs) => {
      this.yot.saveConfiguration().subscribe((config) => {
        // TODO:
        this.navigationService.isLoading = false;
        subject.next();
        subject.complete();
      });
    });
    return subject;
  }

  private reloadList() {
    this.clientConfigService.loadPresetsList()
      .subscribe((list) => this.presetsList = list);
  }
}
