import {Component, EventEmitter, Input, Output} from '@angular/core';
import {WidgetType} from "../../api/widgets/widget-type";
import {
  WidgetActionRequest
} from "../common-parts/widget-actions-menu/widget-actions-menu.component";
import {DashboardWidget} from "../../services/dashboard/dashboard";

@Component({
  selector: 'app-dynamic-widget',
  templateUrl: './dynamic-widget.component.html',
  styleUrls: ['./dynamic-widget.component.scss']
})
export class DynamicWidgetComponent {
  @Input()
  widget: DashboardWidget;
  @Input()
  options: any = {};

  @Output()
  widgetActionRequest: EventEmitter<WidgetActionRequest> = new EventEmitter();

  WidgetType = WidgetType;

  onWidgetActionRequest(actionRequest: WidgetActionRequest): void {
    this.widgetActionRequest.emit(actionRequest);
  }
}
