import { Component, OnInit } from '@angular/core';
import {WidgetBaseComponent} from "../widget-base.component";
import {HomegenieUpnpApi} from "../../adapters/home-genie/homegenie-upnp-api";
import {ApiResponse} from "../../adapters/home-genie/homegenie-adapter";

@Component({
  selector: 'app-media-renderer',
  templateUrl: './media-renderer.component.html',
  styleUrls: ['./media-renderer.component.scss']
})
export class MediaRendererComponent extends WidgetBaseComponent implements OnInit {
  isMuted = false;

  get lastUpdateTimestamp(): number {
    let lastUpdateTimestamp = 0;
    const f = this.module.field('UPnP.FriendlyName');
    if (f != null) {
      lastUpdateTimestamp = new Date(f.timestamp).getTime();
    }
    return lastUpdateTimestamp;
  }

  ngOnInit(): void {
    super.ngOnInit();
  }

  onVolumeChange(volume: number) {
    this.module.control(HomegenieUpnpApi.AvMedia.SetVolume, volume)
      .subscribe((res: ApiResponse) => {
        // TODO: handle errors
        //  console.log(res);
      });
  }

  onPrevButtonClick() {
    this.module.control(HomegenieUpnpApi.AvMedia.Prev)
      .subscribe((res: ApiResponse) => {
        // TODO: handle errors
        //  console.log(res);
      });
  }

  onStopButtonClick() {
    this.module.control(HomegenieUpnpApi.AvMedia.Stop)
      .subscribe((res: ApiResponse) => {
        // TODO: handle errors
        //  console.log(res);
      });
  }

  onPlayButtonClick() {
    this.module.control(HomegenieUpnpApi.AvMedia.Play)
      .subscribe((res: ApiResponse) => {
        // TODO: handle errors
        //  console.log(res);
      });
  }

  onPauseButtonClick() {
    this.module.control(HomegenieUpnpApi.AvMedia.Pause)
      .subscribe((res: ApiResponse) => {
        // TODO: handle errors
        //  console.log(res);
      });
  }

  onNextButtonClick() {
    this.module.control(HomegenieUpnpApi.AvMedia.Next)
      .subscribe((res: ApiResponse) => {
        // TODO: handle errors
        //  console.log(res);
      });
  }

  onMuteButtonClicked(mute) {
    this.isMuted = mute;
    this.module.control(HomegenieUpnpApi.AvMedia.Mute, mute ? 1 : 0)
      .subscribe((res: ApiResponse) => {
        // TODO: handle errors
        //  console.log(res);
      });
  }
}
