import {Component, ElementRef, OnDestroy, OnInit, ViewChild} from '@angular/core';
import {WidgetBaseComponent} from "../widget-base.component";
import {CMD, FLD} from "../../services/yot/yot.service";
import {SecurityArmedStatus, SecuritySensorEvent, SecurityTriggerStatus} from "../../services/yot/widgets-model";
import {Subscription} from "rxjs";
import {
  ModuleEventsDialogComponent
} from "../../components/dialogs/module-events-dialog/module-events-dialog.component";
import {CdkVirtualScrollViewport} from "@angular/cdk/scrolling";

@Component({
  selector: 'app-alarm-system',
  templateUrl: './alarm-system.component.html',
  styleUrls: ['./alarm-system.component.scss']
})
export class AlarmSystemComponent extends WidgetBaseComponent implements OnInit, OnDestroy {
  @ViewChild(CdkVirtualScrollViewport)
  viewport: CdkVirtualScrollViewport;
  @ViewChild('viewport', { read: ElementRef })
  viewportRef: ElementRef<HTMLElement>;


  // TODO: rewrite using `WidgetData`  (eg. see WeatherForecastComponent and EnergyMonitorComponent)

  ArmedStatus = SecurityArmedStatus;
  TriggeredStatus = SecurityTriggerStatus;

  securityEvents: SecuritySensorEvent[] = [];

  isLoading = false;

  private eventSubscription: Subscription;

  get armedStatus(): SecurityArmedStatus {
    const statusLevel = this.module.field(FLD.Status.Level);
    const securityArmed = this.module.field(FLD.Security.ArmedStatus);
    if (statusLevel && +statusLevel.value > 0) {
      if (securityArmed && securityArmed.value) {
        switch (securityArmed.value) {
          case SecurityArmedStatus.Away:
            return SecurityArmedStatus.Away;
          case SecurityArmedStatus.Home:
            return SecurityArmedStatus.Home;
          case SecurityArmedStatus.Disarmed:
            return SecurityArmedStatus.Arming;
        }
      }
    }
    return SecurityArmedStatus.Disarmed;
  }
  get triggerStatus(): SecurityTriggerStatus {
    const securityTriggered = this.module.field(FLD.Security.TriggerStatus);
    if (securityTriggered && +securityTriggered.value > 0) {
      return SecurityTriggerStatus.Triggered;
    }
    return SecurityTriggerStatus.Normal;
  }

  ngOnInit(): void {
    super.ngOnInit();
    this.eventSubscription = this.module.events.subscribe((e) => {
      switch (e.key) {
        case FLD.Program.UiRefresh:
          this.refreshEventsList();
          break;
      }
    });
    this.refreshEventsList();
  }
  ngOnDestroy(): void {
    this.eventSubscription && this.eventSubscription.unsubscribe();
  }

  onArmHomeClick(e): void {
    const subject = this.module.control(CMD.Control.ArmHome);
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => {
          this.isLoading = false;
        },
        error: (err) => {
          // TODO: show error state
          this.isLoading = false;
        }
      });
    }
  }
  onArmAwayClick(e): void {
    const subject = this.module?.control(CMD.Control.ArmAway);
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => {
          this.isLoading = false;
        },
        error: (err) => {
          // TODO: show error state
          this.isLoading = false;
        }
      });
    }
  }
  onDisarmClick(e): void {
    const subject = this.module?.control(CMD.Control.Disarm);
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => {
          this.isLoading = false;
        },
        error: (err) => {
          // TODO: show error state
          this.isLoading = false;
        }
      });
    }
  }

  onEventItemClick(e): void {
    this.dialog.open(ModuleEventsDialogComponent, {
      panelClass: 'dialog-no-padding',
      width: '100%',
      minWidth: '280px',
      maxWidth: '576px',
      disableClose: false,
      data: {module: e.module, field: e.field.key}
    });
  }

  private eventListLoadTimeout = null;
  private refreshEventsList(): void {
    clearTimeout(this.eventListLoadTimeout);
    this.eventListLoadTimeout = setTimeout(() => {
      const subject = this.module?.control(CMD.Security.Events.List);
      if (subject) {
        subject.subscribe({
          next: (res: SecuritySensorEvent[]) => {
            this.securityEvents = res; //.reverse();
            setTimeout(() => {
              this.viewport.scrollToIndex(this.securityEvents.length - 1, 'smooth');
            }, 100);
          },
          error: (err) => {
            // TODO: show error state
          }
        });
      }
    }, 500);
  }

  protected getStatusText() {
    if (this.armedStatus === this.ArmedStatus.Disarmed) {
      let offText = 'deactivated';
      this.yot.translate.get(offText).subscribe((tr) => {
        offText = tr;
      });
      return offText;
    }
    return this.armedStatus + ' / ' + this.triggerStatus;
  }
}
