import {Component, ElementRef, Inject, OnInit, ViewChild} from '@angular/core';
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {HomegenieAdapter} from "../../homegenie-adapter";

@Component({
  selector: 'app-service-dialog',
  templateUrl: './service-dialog.component.html',
  styleUrls: ['./service-dialog.component.scss']
})
export class ServiceDialogComponent implements OnInit {
  @ViewChild('password', { read: ElementRef, static: false })
  passwordInput!: ElementRef;

  adapter: HomegenieAdapter;

  serviceConfiguration: {Port?: string, Host?: string, AuthPassword?: boolean, AuthUsername?: string} = {};
  newPassword = '';

  get changed(): boolean {
    return JSON.stringify(this.data.systemInfo.Configuration.Service)
      !== JSON.stringify(this.serviceConfiguration) || this.newPassword.length > 0;
  }

  constructor(@Inject(MAT_DIALOG_DATA) private data) {
    this.serviceConfiguration = {...data.systemInfo.Configuration.Service};
  }

  ngOnInit(): void {
  }

  onPasswordProtectChange(value: boolean) {
    if (value && !this.data.systemInfo.Configuration.Service.AuthPassword) {
      setTimeout(() => {
        this.passwordInput.nativeElement.focus();
      });
    } else if (!value) {
      this.newPassword = '';
    }
  }
}
