import {Component, ElementRef, HostListener, Inject, OnDestroy, OnInit, ViewChild} from '@angular/core';
import {Module, ModuleField} from "../../../services/yot/module";
import {YotService} from "../../../services/yot/yot.service";
import {MAT_DIALOG_DATA, MatDialogRef} from "@angular/material/dialog";
import {forkJoin, ObservableInput, Subject, Subscription} from "rxjs";
import {FieldLogEvent} from "../../../services/yot/automation";
import {SystemApi} from "../../../api/system-api";
import {CdkVirtualScrollViewport} from "@angular/cdk/scrolling";
import {ChartComponent, HgChartOptions} from "../../chart/chart.component";
import {ChartDataWorkerConfig} from "../../chart/chart-data.worker";


class DateTimeRange {
  public start: number;
  public end: number;
  public count: number
}


@Component({
  selector: 'app-module-events-dialog',
  templateUrl: './module-events-dialog.component.html',
  styleUrls: ['./module-events-dialog.component.scss']
})
export class ModuleEventsDialogComponent implements OnInit, OnDestroy {
  @ViewChild(CdkVirtualScrollViewport)
  viewport: CdkVirtualScrollViewport;
  @ViewChild('viewport', { read: ElementRef })
  viewportRef: ElementRef<HTMLElement>;
  @ViewChild('chartComponent', {static: false})
  chartComponent: ChartComponent;

  module: Module;

  events: FieldLogEvent[] = [];
  newEvents: ModuleField[] = [];

  preferredHeight = 1024;

  loadingResources = 0;

  /*
  timeRanges: TimeRange[] = [
    { value: 0.016, label: 'MODULE.stats.one_minute' },
    { value: 0.083, label: 'MODULE.stats.ten_minutes' },
    { value: 0.5, label: 'MODULE.stats.half_hour' },
    { value: 1, label: 'MODULE.stats.one_hour' },
    { value: 3, label: 'MODULE.stats.three_hours' },
    { value: 6, label: 'MODULE.stats.six_hours' },
    { value: 12, label: 'MODULE.stats.twelve_hours' },
    { value: 24, label: 'MODULE.stats.twentyfour_hours' }
  ]
  selectedTimeRange: TimeRange = this.timeRanges[7];
*/

  chartConfig: ChartDataWorkerConfig[];

  private eventSubscription: Subscription;
  private _selectedField: string;
  private _statFields: ModuleField[] = [];
  private hiddenFields: string[] = [ 'VirtualModule.ParentId', 'Widget.DisplayModule', 'Program.UiRefresh'];

  currentPage: number = 1;
  dataTimeRange: DateTimeRange;
  itemsPerPage = 250;
  dataFilter = '';

  displayMode: 'page-browser' | 'chart-slider';

  get isLoading(): boolean {
    return this.loadingResources > 0;
  }

  get currentItemsLabel(): string {
    const from = 1 + (this.currentPage - 1) * this.itemsPerPage;
    let to = from + this.itemsPerPage - 1;
    if (to > this.dataTimeRange?.count) {
      to = this.dataTimeRange.count;
    }
    return `${from}-${to}`;
  }

  get selectedField() {
    return this._selectedField;
  }
  set selectedField(v: string) {
    if (v && v.length > 0 && this.module.isOnline) {
      this._selectedField = v;
      this.refresh();
    }
  }
  get statFields(): ModuleField[] {
    if (this._statFields.length === 0 && !this.isLoading) {
      this._statFields = this.module.fields
        .filter((f) => {
          return this.hiddenFields.indexOf(f.key) === -1;
        })
        .sort((a, b) =>
          a.idle > b.idle ? 1
          : a.idle < b.idle ? -1 : 0);
      if (this._statFields.length > 0 && (this.selectedField == null || this.hiddenFields.indexOf(this.selectedField) !== -1)) {
        this.selectedField = this._statFields[0].key;
      }
    }
    return this._statFields;
  }

  @HostListener('window:resize', ['$event'])
  onResize(event: any) {
    this.adjustViewportHeight();
  }

  constructor(
    public yot: YotService,
    @Inject(MAT_DIALOG_DATA) data: {module: Module, field?: any},
    private dialogRef: MatDialogRef<ModuleEventsDialogComponent>
  ) {
    this.module = data.module;
    this.selectedField = data.field instanceof ModuleField ? data.field.key : data.field;
  }

  ngOnInit(): void {
    if (!this.module.isOnline) return;
    // Live feed events stream
    this.eventSubscription = this.module.events.subscribe((e) => {
      if (this.events && e.key === this.selectedField) {
        const moduleEvent = new ModuleField(e.key, e.value, e.timestamp);
        if (this.displayMode === 'chart-slider' && !this.chartComponent?.isLiveFeedPaused) {
          this.dequeueNewEvents(moduleEvent);
        } else {
          this.newEvents.unshift(moduleEvent);
        }
      }
    });
    this.refreshAvailableFields();
  }
  ngOnDestroy(): void {
    this.eventSubscription && this.eventSubscription.unsubscribe();
  }

  adjustViewportHeight(): void {
    if (!this.viewportRef || !this.viewportRef.nativeElement) {
      return;
    }
    let contentHeight = window.document.scrollingElement.clientHeight;
    if (contentHeight > this.preferredHeight) {
      contentHeight = this.preferredHeight;
    }
    const availableHeight = contentHeight - (240 + (this.displayMode === 'chart-slider' ? 156 : 0));
    if (availableHeight > 0) {
      this.viewportRef.nativeElement.style.height = `${availableHeight}px`;
    }
    this.viewport.checkViewportSize();
  }

  refresh() {
    this.updateFieldTimeRange().subscribe(() => {
      this.refreshResults();
    });
  }

  protected onNewEventsButtonClick($event: MouseEvent) {
    if (this.currentPage === 1 && this.events.length > 0) {
      this.dequeueNewEvents();
    } else {
      if (this.events.length === 0) {
        this.refreshAvailableFields();
      }
      // force reload
      this.onModuleFieldChange(this.selectedField);
    }
  }

  protected onPrevPageClick() {
    if (this.currentPage > 1) {
      this.currentPage--;
      this.refreshResults().subscribe(() => {
        this.scrollToFirstResult();
      });
    }
  }

  protected onNextPageClick() {
    const totalPages = this.dataTimeRange.count / this.itemsPerPage;
    if (this.currentPage < totalPages) {
      this.currentPage++;
      this.refreshResults().subscribe(() => {
        this.scrollToFirstResult();
      });
    }
  }

  protected onModuleFieldChange(fieldName: string) {
    this.selectedDataPointIndex = -1;
    this.currentPage = 1;
    this.newEvents = [];
    this._selectedField = fieldName;
    this.refresh();
  }

  private dequeueNewEvents(newEvent?: ModuleField) {
    const newReversed = this.newEvents.slice().reverse();
    const added = newReversed.length + (newEvent ? 1 : 0);
    this.events = [...this.events, ...newReversed,  ...(newEvent ? [newEvent] : [])].slice(added);
    this.newEvents = [];
    this.dataTimeRange.count += added;
    this.dataTimeRange.end = Math.max(...this.events.map((f) => f.timestamp));
    this.scrollToFirstResult();
  }

  private scrollToFirstResult(animate: boolean = true) {
//    if (this.displayMode === 'page-browser') {
//      this.viewport?.scrollToIndex(0, 'smooth');
//    } else if (this.displayMode === 'chart-slider') {
    setTimeout(() => {
      this.viewport?.scrollToIndex(this.events.length - 1, animate ? 'smooth' : 'auto');
    }, 100);
//    }
  }

  private updateFieldTimeRange(): Subject<void> {
    this.loadingResources++;
    const subject = new Subject<void>();
    const adapter = this.module.getAdapter();
    adapter.system(SystemApi.Logging.Field.GetTimeRange, { module: this.module, field: this._selectedField })
      .subscribe({
        next: (res) => {
          this.loadingResources--;
          this.dataTimeRange = res;
          subject.next();
          subject.complete();
        },
        error: (err) => {
          // TODO: report error
          this.loadingResources--;
          subject.error(err);
        }
      });
    return subject;
  }

  private refreshAvailableFields(): Subject<void>  {
    this.loadingResources++;
    const subject = new Subject<void>();
    let fieldTimeRangeRequests: ObservableInput<DateTimeRange>[] = [];
    const adapter = this.module.getAdapter();
    const fields = this.module.fields;
    fields.forEach(field => {
      fieldTimeRangeRequests.push(
        adapter.system(SystemApi.Logging.Field.GetTimeRange, { module: this.module, field: field.key })
      );
    });
    let fieldIndex = 0;
    forkJoin(fieldTimeRangeRequests).subscribe({
      next: (results: DateTimeRange[]) => {
        results.map((r) => {
          const f = fields[fieldIndex++];
          if (r.count === 0 && f.key !== this.selectedField) {
            // hide fields with no records in the database
            this.hiddenFields.push(f.key);
          }
        });
        this.loadingResources--;
        subject.next();
      },
      error: (err) => {
        this.loadingResources--;
        subject.error(err);
      },
      complete: () => {
        subject.complete();
      }
    });
    return subject;
  }

  private refreshResults(field?: string, start: number = 0, end: number = 0, noChartRefresh: boolean = false): Subject<void> {
    this.loadingResources++;

    if (!noChartRefresh) {
      this.chartConfig = [];
    }

    if (!field) {
      field = this.selectedField
    }

    const subject = new Subject<void>();
    const adapter = this.module.getAdapter();
    adapter.system(SystemApi.Logging.Field.GetData, { module: this.module, field: field, start, end, limit: this.itemsPerPage, page: this.currentPage })
      .subscribe((res) => {
        this.events = res;
        this._selectedField = field;

        if (!noChartRefresh) {
          // auto-detect display mode (page browser / chart slider)
          const allNumbers = res.find(r => Number.isFinite(parseFloat(r.value?.replace(',', ''))) && !isNaN(Number(+r.value?.replace(',', ''))));
          this.displayMode = (allNumbers) ? 'chart-slider' : 'page-browser';
          if (this.displayMode === 'chart-slider') {

            const start = Math.min(...this.events.map((ev) => ev.timestamp));
            const end = Math.max(...this.events.map((ev) => ev.timestamp));
            // chart config
            const chartWorker = new ChartDataWorkerConfig();
            chartWorker.moduleId = this.module.id;
            chartWorker.chartOptions = new HgChartOptions();
            chartWorker.chartOptions.fill = true;
            chartWorker.chartOptions.storage = 'HomeGenie.EventsLogger';
//        const rangeEnd = new Date().getTime();
//        const windowHours = 0.083;
            chartWorker.queryOptions = {
              dataFilter: this.dataFilter ? this.dataFilter : 'RawData',
              field: this.selectedField,
              rangeStart: start,
              rangeEnd: end,
              timeRange: (end - start) / 3600000
            };
            this.chartConfig = [chartWorker];
          }

        }

        // Reverse list display order when chart view is active
        this.events.reverse();

        this.scrollToFirstResult(false);

        this.loadingResources--;
        subject.next();
      }, (err) => {
        this.loadingResources--;
        subject.error(err);
      }, () => {
        this.adjustViewportHeight();
        subject.complete();
      });
    return subject;
  }

  protected selectedDataPointIndex = -1;
  protected onPointClicked(event) {
    // TODO: ... (?)
  }
  protected onPointHover(event) {
    if (!this.chartComponent?.isLiveFeedPaused) {
      return;
    }
    const dataPoint = event.elements[0]?.element?.$context?.raw;
    if (dataPoint) {
      const i = event.elements[0]?.element?.$context?.index;
      this.selectedDataPointIndex = (this.events.length - i) - 1;
      const offset = Math.round(this.viewport?.elementRef.nativeElement.clientHeight / 48 /* itemSize */) - 1;
      this.viewport?.scrollToIndex(this.selectedDataPointIndex - offset, 'smooth');
    }
  }

  private rangeUpdateTimeout = null;
  protected onChartRangeUpdated(range) {
    if (this.chartComponent) {
      this.chartComponent.setLiveFeedPaused(true);
    }
    clearTimeout(this.rangeUpdateTimeout);
    if (this.isLoading) {
      this.rangeUpdateTimeout = window.setTimeout(() => {
        this.refreshResults(this.selectedField, range.start, range.end, true);
      }, 100);
    } else {
      this.refreshResults(this.selectedField, range.start, range.end, true);
    }
  }

  protected pauseLiveFeed() {
    if (this.chartComponent) {
      this.chartComponent.setLiveFeedPaused(true);
    }
  }
  protected resumeLiveFeed() {
    if (this.chartComponent) {
      this.chartComponent.setLiveFeedPaused(false);
    }
    this.onModuleFieldChange(this.selectedField);
  }
}
