export class HomegenieUpnpApi {
  static AvMedia = {
    Browse: 'AvMedia.Browse',
    GetItem: 'AvMedia.GetItem',
    SetVolume: 'AvMedia.SetVolume',
    SetUri: 'AvMedia.SetUri',
    Play: 'AvMedia.Play',
    Pause: 'AvMedia.Pause',
    Stop: 'AvMedia.Stop',
    Prev: 'AvMedia.Prev',
    Next: 'AvMedia.Next',
    Mute: 'AvMedia.SetMute' // 0 = mute, 1 = unmute
  };
}

export class AvMediaItem {
  Class: string;
  Creator = null;
  Id: string;
  Title: string;

  Type?: string;
  ProtocolInfo?: string;
  Duration?: string;
  Info?: string;
  CoverImage?: string;

  Details?: any;

  Resources?: { image: string, video: {webm: string, mp4: string, mpeg: string}};

  MediaUrlBrowser?: string;
  MediaUrl?: string;

  MovieDbData?: any;

  static isFolder(i: AvMediaItem) {
    return i.Class.startsWith('object.container');
  }
}


export class AvMediaPositionInfo {
  public Track: string;
  public TrackDuration: string;
  public TrackMetaData: string;
  public TrackURI: string;
  public RelTime: string;
  public AbsTime: string;
  public RelCount: number;
  public AbsCount: number;
}

export class AvMediaTransportInfo {
  //{ "CurrentTransportState" : "TRANSITIONING", "CurrentTransportStatus" : "OK", "CurrentSpeed" : "1" }
  public CurrentTransportState: string;
  public CurrentTransportStatus: string;
  public CurrentSpeed: string;
}
