import {Component, Inject, OnInit} from '@angular/core';
import {Module} from "../../../services/yot/module";
import {WidgetData} from "../../../widgets/widget-data";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {YotService} from "../../../services/yot/yot.service";
import {Dashboard, DashboardWidget} from "../../../services/dashboard/dashboard";

export class AddWidgetDialogData {
  public dashboard: Dashboard;
  public modules: Module[];
}

@Component({
  selector: 'app-add-widget-dialog',
  templateUrl: './add-widget-dialog.component.html',
  styleUrls: ['./add-widget-dialog.component.scss']
})
export class AddWidgetDialogComponent implements OnInit {

  widgetData: WidgetData;
  module: Module;
  compatibleModules: Array<Module> = [];

  modules: Array<Module> = [];
  dashboard: Dashboard;

  previewWidgets: DashboardWidget[] = [];

  get widgetPreview(): DashboardWidget {
    if (this.module == null) return;
    const adapter = this.yot.getAdapter(this.module.adapterId);
    const data = adapter.getWidgetData(this.module);
    return {
      type: data.type,
      module: {adapterId: adapter.id, moduleId: this.module.id},
      data
    };
  }

  constructor(@Inject(MAT_DIALOG_DATA) public data:{dashboard:Dashboard,modulesList:Module[], widgetType:string, moduleType:string[], propertyFilter:RegExp|string}, public yot: YotService) {
    // build list of selectable modules based on given data filters
    this.dashboard = data.dashboard;
    if (data.modulesList?.length > 0) {
      // explicit list was passed
      this.compatibleModules = data.modulesList;
      this.modules = [...data.modulesList];
      this.refreshWidgets();
// TODO: .....................
    } else {
      // apply module type and property filters to the global modules list
      const propertyFilter = data.propertyFilter;
      let effectiveRegex: RegExp;
      if (typeof propertyFilter === 'string') {
        try {
          effectiveRegex = new RegExp(propertyFilter);
        } catch (e) {
          console.error("RegExp filter error:", e);
        }
      } else {
        effectiveRegex = propertyFilter;
      }
      yot.getModules().forEach((m) => {
        const opts = m.getWidgetData();
        const matchesProperty = effectiveRegex ? m.fields.filter(p => effectiveRegex.test(p.key)).length > 0 : false;
        if (m.isOnline && ((opts?.type === data.widgetType) || (data.moduleType?.includes(m.type)) || matchesProperty)) {
          this.compatibleModules.push(m);
        }
      });
    }
    // select the first of any compatible module found
    if (this.compatibleModules.length > 0) {
      this.module = this.compatibleModules[0];
      this.widgetData = this.module.getWidgetData();
      // select item automatically if it's the only one
      if (this.compatibleModules.length === 1) {
        this.modules = [ this.module ];
        this.refreshWidgets();
      }
    }
  }

  ngOnInit(): void {
  }

  onModuleSelectionChange(e) {
    this.modules = e.value;
    this.refreshWidgets();
  }
  onDashboardSelectionChange(e) {

  }

  private refreshWidgets() {
    const widgets: DashboardWidget[] = [];
    this.modules.forEach((m) => {
      const data = m.getWidgetData();
      if (data) {
        widgets.push({
          type: data.type,
          module: {adapterId: m.adapterId, moduleId: m.id},
          data
        });
      }
    });
    this.previewWidgets = [...widgets];
  }
}
