import {Module} from "./module";

export class Scene {
  public id: string;
  public group: string;
  public name: string;
  public description: string;
}

export class Schedule {
  public id: string;
  public enabled: boolean;
  public name: string;
  public description: string;
  public moduleTypes: string[];
  public boundModules: Module[];
  public hasScript: boolean;
}
export class ScheduleOccurrence {
  public id: string;
  public date = new Date();
  public at?: Date;
  public from?: Date;
  public to?: Date;
  public occurs: {from: number, to: number}[] = [];
  public prevOccurrence: number;
  public nextOccurrence: number;
}

export class FieldLogEvent {
  public value: any;
  public timestamp: number;
}
