import {Component, Inject, OnInit, ViewChild} from '@angular/core';
import {Module, ModuleField} from "../../../services/yot/module";
import {UiMode, YotService} from "../../../services/yot/yot.service";
import {MAT_DIALOG_DATA, MatDialogRef} from "@angular/material/dialog";
import {ChartComponent, ChartProvider} from "../../chart/chart.component";
import {ChartDataWorkerConfig} from "../../chart/chart-data.worker";
import {WidgetType} from "../../../api/widgets/widget-type";
import {Dashboard} from "../../../services/dashboard/dashboard";

@Component({
  selector: 'app-module-statistics-dialog',
  templateUrl: './module-statistics-dialog.component.html',
  styleUrls: ['./module-statistics-dialog.component.scss']
})
export class ModuleStatisticsDialogComponent implements OnInit {
  @ViewChild('chartComponent')
  chartComponent: ChartComponent;

  module: Module;
  field: ModuleField;

  title: string;
  provider: ChartProvider;
  chartConfig: ChartDataWorkerConfig[];

  dashboard: Dashboard;

  private originalConfig = '';

  constructor(
    public yot: YotService,
    @Inject(MAT_DIALOG_DATA) data: {
      module: Module,
      field: ModuleField,
      chartConfig: ChartDataWorkerConfig[],
      title: string,
      provider: ChartProvider,
      dashboard: Dashboard
    },
    private dialogRef: MatDialogRef<ModuleStatisticsDialogComponent>
  ) {
    this.title = data.title || '';
    this.provider = data.provider;
    this.module = data.module;
    this.field = data.field;
    this.chartConfig = data.chartConfig;
    this.dashboard = data.dashboard;
    if (!this.chartConfig && data.module) {
      const cfg = new ChartDataWorkerConfig();
      cfg.moduleId = data.module.id;
      cfg.queryOptions.field = this.field?.key;
      if (!cfg.queryOptions.field) {
        // if field was not provided auto-select first valid field
        cfg.queryOptions.field = data.module.getStatsFields()[0]?.key;
      }
      cfg.queryOptions.dataFilter = 'SimpleAverage';
      this.chartConfig = [ cfg ];
    }
    this.dialogRef.beforeClosed().subscribe(() => {
      const cfg = this.chartComponent.getConfiguration();
      if (this.originalConfig && (JSON.stringify(cfg) !== this.originalConfig)) {
        this.dialogRef.close(cfg);
      }
    });
  }

  ngOnInit() {
    setTimeout(() => {
      this.originalConfig = JSON.stringify(this.chartComponent.getConfiguration());
    }, 500);
  }

  onAddToDashboardClick() {
    const widget = this.yot.dashboardService
      .addDashboardWidget(
        this.dashboard.name,
        WidgetType.Statistics,
        null,
        null,
        this.chartComponent
          .getConfiguration()
      );
    this.dialogRef
      .close();
  }

  protected readonly UiMode = UiMode;
}
