import {Component, ViewChild} from '@angular/core';
import {WidgetBaseComponent} from "../widget-base.component";
import {CMD, FLD} from "../../services/yot/yot.service";
import * as moment from "moment/moment";
import {ActivityStatusComponent} from "../common-parts/activity-status/activity-status.component";


export class ModuleField {
  /**
   * The field name
   */
  key: string;
  /**
   * Update timestamp.
   */
  timestamp: number;
  value: any;
  events: any;

}

export class DoorLockFeatures {
}

@Component({
  selector: 'app-door-lock',
  templateUrl: './door-lock.component.html',
  styleUrls: ['./door-lock.component.scss']
})
export class DoorLockComponent extends WidgetBaseComponent  {
  @ViewChild(ActivityStatusComponent)
  private activityStatus: ActivityStatusComponent;

  isLoading = false;

  private readonly GENERIC_ERROR_MESSAGE = 'Error issuing command';

  get features(): DoorLockFeatures {
    return super.features;
  }
  get statusText(): string {
    let status = null;
    const lockStatus = this.module.field(FLD.Status.DoorLock);
    const lockAlarm = this.module.field('Sensor.Alarm');
    let triggeredEvent: ModuleField = null;
    if (lockStatus) {
      triggeredEvent = lockStatus;
    }
    if (lockAlarm && lockAlarm.timestamp > lockStatus.timestamp) {
      triggeredEvent = lockAlarm;
    }
    if (lockStatus && lockStatus.value && lockStatus.value === 'Secured') {
      status = 'Locked ' + moment(lockStatus.timestamp).fromNow();
    } else if (triggeredEvent?.key == 'Sensor.Alarm' && (+triggeredEvent?.value == 1 || +triggeredEvent?.value == 5)) {
      status = 'Alarmed ' + moment(lockAlarm.timestamp).fromNow();
    } else if (lockStatus) {
      status = 'Unlocked ' + moment(lockStatus.timestamp).fromNow();
    } else {
      status = 'Unlocked';
    }
    return status;
  }

  onLockUnlockButtonClick(value: string) {
    if (this.isLoading) return;
    const subject = this.module?.control(CMD.DoorLock.Set, value);
    if (subject) {
      this.isLoading = true;
      subject.subscribe({
        next: (res) => this.isLoading = false,
        error: (err) => {
          this.activityStatus.setError(this.GENERIC_ERROR_MESSAGE);
          this.isLoading = false;
        }
      });
    }
  }
}
