import {Component, Input, OnInit} from '@angular/core';
import {Group, HomegenieAdapter} from "../homegenie-adapter";
import {ModuleTypes, SchedulerItem} from "../homegenie-api";

@Component({
  selector: 'app-scheduler-wizard-modules',
  templateUrl: './scheduler-wizard-modules.component.html',
  styleUrls: ['./scheduler-wizard-modules.component.scss']
})
export class SchedulerWizardModulesComponent implements OnInit {
  @Input()
  adapter: HomegenieAdapter;
  @Input()
  schedulerItem: SchedulerItem;

  moduleTypes: any[];

  scheduleGroup = new Group();

  constructor() { }

  ngOnInit(): void {
    this.moduleTypes = Object.keys(ModuleTypes).map((k) => ({
      name: k,
      // map YOT module type to HG module type (first letter uppercase)
      value: ModuleTypes[k].charAt(0).toUpperCase() + ModuleTypes[k].slice(1)
    }));
    this.refreshModuleList();
  }

  applyChanges(): void {
    this.schedulerItem.BoundModules = this.scheduleGroup.Modules
      .filter((mr) => {
        // filter modules not matching selected types
        const id = this.adapter.getModuleId(mr);
        const m = this.adapter.getModule(id);
        if (m) {
          return this.schedulerItem.BoundDevices.includes(m.DeviceType);
        }
      }).map((mr) => ({ Domain: mr.Domain, Address: mr.Address }));
  }

  onModuleTypesChange(e) {
  }

  private refreshModuleList() {
    this.scheduleGroup.Modules = this.schedulerItem.BoundModules.filter((mr) => {
      const id = this.adapter.getModuleId(mr);
      return this.adapter.getModule(id);
    });
  }

}
