import {StatisticsChartData, StatisticsFieldGetOptions} from "../../services/yot/widgets-model";
import {ChartDataset} from "chart.js";
import {HgChartOptions} from "./chart.component";
import {Subject} from "rxjs";

export class ChartDataWorkerConfig {
  title? = '';
  moduleId: string;
  /// dataset options
  queryOptions = new StatisticsFieldGetOptions();
  chartOptions = new HgChartOptions();
  colors?: any;
  autoscale? = false;
}

export class ChartDataWorker {
  updateTimestampMs = 0;

  index: number = -1;
  config: ChartDataWorkerConfig;

  isLoading = false;

  initialized = false;
  animate = false;

  invalidated = true;
  dataInterval: {start: number; end: number} = {
    start: 0, end: 0
  };

  updated?: Function;
  error?: Function;


  dataSet: ChartDataset;
  private updateTimeout;

  constructor(index: number, config: ChartDataWorkerConfig) {
    this.index = index;
    this.config = config;
  }

  update() {
    if (this.isLoading) {
      clearTimeout(this.updateTimeout);
      this.updateTimeout = setTimeout(() => this.update(), 100);
      return;
    }

    const success = () => {
      // emit the result
      this.updateTimestampMs = new Date().getTime();
      this.updated(this.index, this.dataSet);
    };
    const error = (err) => {
// TODO: ....
      this.error(err);
    };

    if (this.dataSet && this.config.chartOptions.hidden) {
      this.dataSet = {...this.dataSet, ...this.config.colors, ...this.config.chartOptions, data: []};
      success();
      return;
    }

    this.isLoading = true;
    this.getData(this.config.queryOptions)?.subscribe((data: StatisticsChartData) => {
        const fieldStats: any = {...this.config.chartOptions};
        fieldStats.data = data as StatisticsChartData;
        this.dataSet = {...this.config.colors, ...fieldStats};
        const max = Math.max(...fieldStats.data.map(v => v.x));
        if (this.dataInterval.end < max) {
          this.dataInterval.end = max;
        }
        success();
      }, (err) => {
        this.isLoading = false;
        error(err);
      }, () => {
        this.isLoading = false;
      });
  }

  getData(options: StatisticsFieldGetOptions): Subject<any> {
    throw new Error('Not implemented.');
  }

}
