import {Component, Inject, OnInit} from '@angular/core';
import {Module, ModuleField} from "../../../services/yot/module";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {OptionField, OptionFieldTypeId} from "../../../services/yot/module-options";
import {FieldChangeEvent} from "../../../components/controls/control-field-base";
import {HomegenieAdapter} from "../../../adapters/home-genie/homegenie-adapter";
import {map} from "rxjs/operators";
import {HomegenieApi} from "../../../adapters/home-genie/homegenie-api";
import {ContextController} from "zuix-dist";

@Component({
  selector: 'app-custom-widget-settings-dialog',
  templateUrl: './custom-widget-settings-dialog.component.html',
  styleUrls: ['./custom-widget-settings-dialog.component.scss']
})
export class CustomWidgetSettingsDialogComponent implements OnInit {

  module: Module;
  adapter: HomegenieAdapter;
  configuration: any;
  controller: ContextController;
  callback: any;
  uiMode: string;

  optionFields: OptionField[] = [];
  constructor(@Inject(MAT_DIALOG_DATA) public data) {
    this.module = data.module;
    this.adapter = data.adapter;
    this.configuration = data.configuration || {};
    this.callback  = data.callback;
    this.uiMode = data.uiMode;
  }

  ngOnInit() {
    this.configure(this.data.controller);
  }

  public configure(controller?: any): void {
    if (this.configuration.size === undefined) {
      this.configuration.size = '';
    }
    // translations
    let textWidgetType = 'custom_widget_field_type_label';
    this.adapter.yot.translate.get(textWidgetType)
      .subscribe((value: string) => { textWidgetType = value; })
    let textBoundModule = 'custom_widget_field_datasource_label';
    this.adapter.yot.translate.get(textBoundModule)
      .subscribe((value: string) => { textBoundModule = value; })
    let textWidgetSize = 'custom_widget_field_size_label';
    this.adapter.yot.translate.get(textWidgetSize)
      .subscribe((value: string) => { textWidgetSize = value; })
    // options fields definition
    let moduleFilterOptions = [];
    // apply any given filter to the module select
    const moduleSelectOptions: {fieldFilter?:string, typeFilter?:string} = controller?.settings?.moduleSelect;
    if (moduleSelectOptions?.fieldFilter || moduleSelectOptions?.typeFilter) {
      moduleFilterOptions = ['', moduleSelectOptions?.typeFilter, moduleSelectOptions?.fieldFilter]
    }
    this.optionFields = [
      {
        pid: '0',
        name: 'module',
        field: new ModuleField('module', this.configuration.module),
        type: {id: OptionFieldTypeId.ModuleSelect, options: moduleFilterOptions},
        description: textBoundModule
      }
      /*,
      {
        pid: '0',
        name: 'size',
        field: new ModuleField('size', this.configuration.size),
        type: {
          id: OptionFieldTypeId.Select,
          options: [
            'small=small,medium=medium,large=big'
          ]
        },
        description: textWidgetSize
      }
      */
    ];
    if (this.uiMode === 'edit') {
      this.optionFields.unshift({
        pid: '0',
        name: 'componentId',
        field: new ModuleField('componentId', this.configuration.componentId),
        type: {id: OptionFieldTypeId.Text, options: [
            (filter) => this.adapter
              ?.apiCall(HomegenieApi.Config.Widgets.List)
              .pipe(map((apiResponse) => apiResponse.response as string[]))
          ]},
        description: textWidgetType
      });
    }
  }

  changed(o: OptionField) {
    return false;
  }

  onFieldChange(e: FieldChangeEvent) {
    this.configuration[e.field.key] = e.value;
    if (this.callback) {
      this.callback(this.configuration);
    }
  }

}
