import {Component, Inject, OnInit, Optional} from '@angular/core';
import {Module} from "../../../../services/yot/module";
import {CMD, FLD, YotService} from "../../../../services/yot/yot.service";
import {Dashboard} from "../../../../services/dashboard/dashboard";
import {MAT_BOTTOM_SHEET_DATA, MatBottomSheetRef} from "@angular/material/bottom-sheet";
import {UtilsService} from "../../../../services/utils.service";
import {forkJoin, Observable} from "rxjs";

@Component({
  selector: 'app-shutters-bottom-sheet',
  templateUrl: './shutters-bottom-sheet.component.html',
  styleUrls: ['./shutters-bottom-sheet.component.scss']
})
export class ShuttersBottomSheetComponent implements OnInit {

  dashboard: Dashboard;
  level = 0;
  modules: Module[];

  isBusy = false;
  private commandTimeout = null;

  get shuttersCount() {
    const on = this.modules
      .filter((m) => this.isOpen(m))
      .length;
    return on + "/" + this.modules.length;
  }

  constructor(
    @Optional() private bsRef: MatBottomSheetRef<any>,
    @Inject(MAT_BOTTOM_SHEET_DATA) public data: any,
    private yot: YotService,
    private utils: UtilsService
  ) {
    this.dashboard = data.dashboard;
    this.modules = data.modules;
  }

  closeSheet() {
    this.bsRef.dismiss();
  }

  ngOnInit(): void {
    this.modules.map((module) => {
      const levelField = module.field(FLD.Status.Level);
      this.level += 100 * this.utils.getFloatValue(levelField?.value);
    });
    this.level /= this.modules.length;
  }

  onSliderInput(e): void {
    this.level = e.value;
    this.setLevel();
  }

  shuttersClose() {
    const controlObservables: Observable<any>[] = [];
    this.modules.forEach((module) => {
      controlObservables.push(
        module.control(CMD.Control.Close)
      );
    });
    forkJoin(controlObservables).subscribe({
      next: (allResults) => {
        // TODO: ...
      },
      error: (err) => {
        // one or more requests failed
        // TODO: ...
      },
      complete: () => {
        // TODO: ...
        setTimeout(() => this.updateAverageLevel(), 200);
      }
    });
  }
  shuttersOpen() {
    const controlObservables: Observable<any>[] = [];
    this.modules.forEach((module) => {
      controlObservables.push(
        module.control(CMD.Control.Open)
      );
    });
    forkJoin(controlObservables).subscribe({
      next: (allResults) => {
        // TODO: ...
      },
      error: (err) => {
        // one or more requests failed
        // TODO: ...
      },
      complete: () => {
        // TODO: ...
        setTimeout(() => this.updateAverageLevel(), 200);
      }
    });
  }

  private updateAverageLevel() {
    this.level = 0;
    this.modules
//      .filter((m) => this.isOpen(m))
      .map((module) => {
        const levelField = module.field(FLD.Status.Level);
        this.level += 100 * this.utils.getFloatValue(levelField?.value);
      });
    this.level /= this.modules.length;
  }

  private isOpen(module: Module): boolean {
    return this.utils.getFloatValue(module.field(FLD.Status.Level)?.value) > 0;
  }

  private setLevel() {
    clearTimeout(this.commandTimeout);
    if (this.isBusy) {
      this.commandTimeout = setTimeout(() => this.setLevel());
      return;
    }

    this.isBusy = true;
    const controlObservables: Observable<any>[] = [];
    this.modules.forEach((module) => {
      controlObservables.push(
        module.control(CMD.Control.Level, this.level)
      );
    });
    forkJoin(controlObservables).subscribe({
      next: (allResults) => {
        // TODO: ...
      },
      error: (err) => {
        // one or more requests failed
        // TODO: ...
      },
      complete: () => {
        this.isBusy = false;
      }
    });
  }

}
