import {Component, Input, OnInit, ViewChild} from '@angular/core';
import {HomegenieAdapter} from "../../homegenie-adapter";
import {HomegenieApi} from "../../homegenie-api";
import {LocationPickerComponent} from "../../homegenie-maintenance/location-picker/location-picker.component";
import {LocationInfo} from "../../../geolocation-adapter";

export class SetupRegionalConfiguration {
  location = new LocationInfo();
  formats = 'metric';
}

@Component({
  selector: 'app-regional-settings',
  templateUrl: './regional-settings.component.html',
  styleUrls: ['./regional-settings.component.scss']
})
export class RegionalSettingsComponent implements OnInit {
  @ViewChild('locationPicker')
  locationPicker: LocationPickerComponent;
  @Input()
  adapter: HomegenieAdapter;
  @Input()
  config = new SetupRegionalConfiguration();

  constructor() { }

  ngOnInit(): void {
    this.adapter.apiCall(HomegenieApi.SystemConfig.Location.Get)
      .subscribe((res) => {
        this.config.location = res.response;
      });
  }

  configure(): SetupRegionalConfiguration {
    this.adapter
      .apiCall(HomegenieApi.SystemConfig.Location.Set, this.config.location)
      .subscribe();

    // TODO: apply number formats settings

    return this.config;
  }

  onLocationChange(locationInfo: LocationInfo) {
    this.config.location = locationInfo;
  }
}
