import {Component, Input, OnInit} from '@angular/core';
import {Group, Module, ModuleReference, ModuleTypes} from "../homegenie-api";
import {HomegenieAdapter} from "../homegenie-adapter";

class ListItem {
  domain: string;
  modules: Array<Module>;
}

@Component({
  selector: 'app-group-modules',
  templateUrl: './group-modules.component.html',
  styleUrls: ['./group-modules.component.scss']
})
export class GroupModulesComponent implements OnInit {
  @Input()
  adapter: HomegenieAdapter;
  @Input()
  group: Group;
  @Input()
  set typeFilter(typeFilter: ModuleTypes[]) {
    this._typeFilter = typeFilter;
    this.refreshList();
  }
  get typeFilter(): ModuleTypes[] {
    return this._typeFilter;
  }
  private _typeFilter: ModuleTypes[] = [];

  items: Array<ListItem> = [];

  private originalGroup: Group;
  get isChanged(): boolean {
    return this.originalGroup && JSON.stringify(this.originalGroup) !== JSON.stringify(this.group);
  }

  get modules(): Array<Module> {
    if (this.adapter) {
      return this.adapter.modules;
    }
  }

  constructor() { }

  ngOnInit(): void {
    this.originalGroup = JSON.parse(JSON.stringify(this.group));
    this.refreshList();
  }

  onSelectionChange(e): void {
    const m: ModuleReference = e.options[0].value;
    if (!e.options[0].selected) {
      // exclude
      this.group.Modules = this.group.Modules.filter((mod) => {
        return (m.Domain !== mod.Domain || m.Address !== mod.Address) ? mod: undefined;
      });
    } else {
      // include
      const existingItem = this.originalGroup.Modules.find((mr) => mr.Domain === m.Domain && mr.Address === m.Address);
      const originalIndex = this.originalGroup.Modules.indexOf(existingItem);
      const mr: ModuleReference = { Address: m.Address, Domain: m.Domain };
      if (originalIndex >= 0) {
        this.group.Modules.splice(originalIndex, 0, mr);
      } else {
        this.group.Modules.push(mr);
      }
    }
  }

  isIncluded(m: Module): boolean {
    return this.group && this.group.Modules ? this.group.Modules.find((mod) =>
      m.Domain === mod.Domain && m.Address === mod.Address) != null : false;
  }

  wasIncluded(m: Module): boolean {
    return this.originalGroup && this.originalGroup.Modules ? this.originalGroup.Modules.find((mod) =>
      m.Domain === mod.Domain && m.Address === mod.Address) != null : false;
  }

  private refreshList() {
    this.items = [];
    const modules = this.adapter.modules.slice();
    modules.sort((m1, m2) => {
      const id1 = this.adapter.getModuleId(m1);
      const id2 = this.adapter.getModuleId(m2);
      return id1 > id2 ? 1 : id1 < id2 ? -1 : 0;
    });
    let currentDomain = ''; let currentItem: ListItem;
    modules.forEach((m) => {
      if (this.typeFilter && this.typeFilter.length > 0 && !this.typeFilter.includes(m.DeviceType as any)) {
        // skip element if it does not match type filter
        return;
      }
      if (currentDomain !== m.Domain) {
        currentDomain = m.Domain;
        currentItem = {
          domain: currentDomain,
          modules: []
        };
        this.items.push(currentItem);
      }
      const moduleWidget = this.adapter.getModuleWidget(m);
      // exclude program apps from list
      if (m.DeviceType !== 'Program' || moduleWidget) {
        currentItem.modules.push(m);
      }
    });
  }

}
