import {Component, OnDestroy, OnInit} from '@angular/core';
import {DashboardWidget} from "../../services/dashboard/dashboard";
import {CMD, FLD} from "../../services/yot/yot.service";
import {Module} from "../../services/yot/module";
import {WidgetBaseComponent} from "../widget-base.component";
import {
  TextInputDialogComponent,
  TextInputDialogConfig
} from "../../components/dialogs/text-input-dialog/text-input-dialog.component";
import {WidgetType} from "../../api/widgets/widget-type";
import {Subscription} from "rxjs";
import {DashboardLayoutEventValue} from "../../services/dashboard/dashboard.service";

@Component({
  selector: 'app-section-label',
  templateUrl: './section-label.component.html',
  styleUrls: ['./section-label.component.scss']
})
export class SectionLabelComponent extends WidgetBaseComponent implements OnInit, OnDestroy {
  sectionWidgets: DashboardWidget[] = [];

  defaultConfiguration = {
    showLightsControl: false,
    showSwitchesControl: false,
    showSensorsAverage: false,
    label: ''
  };

  lightTypes = [
    WidgetType.Color,
    WidgetType.Light
  ];
  switchTypes = [
    WidgetType.Switch
  ];

  operatingDevicesCount(types: WidgetType[]): number {
    return this.getOnModules(types);
  }

  private dashboardServiceSubscription: Subscription;
  ngOnInit(): void {
    super.ngOnInit();
    this.dashboardServiceSubscription = this.yot.dashboardService.layoutEvents.subscribe((event) => {
      if (event === DashboardLayoutEventValue.LayoutDone) {
        this.collectSectionWidgets();
      }
    });
    this.collectSectionWidgets();
  }
  ngOnDestroy() {
    if (this.dashboardServiceSubscription) {
      this.dashboardServiceSubscription.unsubscribe();
    }
  }

  onMenuOptionChange(e) {
    e.cancelBubble = true;
    //console.log(this.configuration, this)
    this.save(); // save widgets and its settings
  }

  onControlToggleChange(types: WidgetType[]) {
    const cmd = this.operatingDevicesCount(types) > 0 ? CMD.Control.Off : CMD.Control.On;
    this.sectionWidgets.forEach((w) => {
      const m = this.yot.getModuleByRef(w.module);
      if (m && types.indexOf(w.type) >= 0) {
        m.control(cmd).subscribe();
      }
    });
  }

  onEditLabelClick(e) {
    const dialogRef = this.dialog.open(TextInputDialogComponent, {
      data: {
        //title: 'Enter label name',
        label: 'name',
        placeholder: 'enter_name',
        value: this.configuration.label,
        //cancelButtonText: 'cancel',
        confirmButtonText: 'edit'
      } as TextInputDialogConfig
    });
    dialogRef.afterClosed().subscribe((name: string) => {
      if (name) {
        this.configuration.label = name;
        this.save();
      }
    });
  }

  onWidgetRemoveClick(e) {
    const dashboard = this.yot.dashboardService.getCurrentDashboard();
    this.yot.dashboardService.removeDashboardWidget(dashboard.name, this.widget);
  }

  private collectSectionWidgets() {
    // get widgets within this section
    const widgets = this.yot.dashboardService.getCurrentDashboard().widgets;
    const widgetIndex = widgets.indexOf(this.widget);
    const sectionStartIndex = widgetIndex + 1;
    let sectionEndIndex = widgets.length;
    for (let w = sectionStartIndex; w < widgets.length; w++) {
      if (widgets[w].type === WidgetType.SectionLabel) {
        sectionEndIndex = w;
        break;
      }
    }
    this.sectionWidgets = widgets.slice(sectionStartIndex, sectionEndIndex);
  }
  private getOnModules(types: WidgetType[]) {
    let count = 0;
    this.sectionWidgets.forEach((w) => {
      const m = this.yot.getModuleByRef(w.module);
      if (m && types.indexOf(w.type) >= 0 && this.getLevel(m) > 0) {
        count++;
      }
    });
    return count;
  }
  private getLevel(m: Module): number {
    const level = m.field(FLD.Status.Level);
    let v = 0;
    if (level?.value != null) {
      v = this.utils.getFloatValue(level.value);
    }
    return v;
  }
}
