import {Pipe, PipeTransform} from '@angular/core';

@Pipe({ name: 'sensorFieldFormatter' })
export class SensorFieldFormatterPipe implements PipeTransform {

  constructor() {}

  transform(fieldKey: string): string {
    const idx = fieldKey?.lastIndexOf('.');
    if (idx > 0) {
      return fieldKey.substring(idx + 1);
    }
    return fieldKey;
  }
}
