import {Component, Inject, Input, OnInit, ViewChild} from '@angular/core';
import {Group, HomegenieAdapter} from "../homegenie-adapter";
import {UiMode, YotService} from "../../../services/yot/yot.service";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {UntypedFormControl} from "@angular/forms";

@Component({
  selector: 'app-group-modules-dialog',
  templateUrl: './group-modules-dialog.component.html',
  styleUrls: ['./group-modules-dialog.component.scss']
})
export class GroupModulesDialogComponent implements OnInit {
  @Input()
  adapter: HomegenieAdapter;
  @Input()
  group: Group;
  @Input()
  groupNames: string[];
  @ViewChild('nameField', {static:true})
  nameField: UntypedFormControl;

  mode = UiMode.Add;

  UiMode = UiMode;

  get isValid(): boolean {
    return this.nameField.valid;
  }

  constructor(@Inject(MAT_DIALOG_DATA) data, public yot: YotService) {
    this.adapter = data.adapter;
    this.group = JSON.parse(JSON.stringify(data.group));
    this.groupNames = data.groupNames;
    this.mode = data.mode;
  }

  ngOnInit(): void {
    // TODO: request / refresh adapter modules list
  }

}
