import {Component, Input, OnDestroy, OnInit} from '@angular/core';
import {Program} from "../../adapters/home-genie/homegenie-api";
import {Module} from "../../services/yot/module";
import {HomegenieAdapter} from "../../adapters/home-genie/homegenie-adapter";
import {Subscription} from "rxjs";

export class ProgramStatusView {
  enabled: boolean;
  running: boolean;
  status: string;
  timestamp: number;
  errors: boolean;
}

@Component({
  selector: 'app-program-status',
  templateUrl: './program-status.component.html',
  styleUrls: ['./program-status.component.scss']
})
export class ProgramStatusComponent implements OnInit, OnDestroy {
  @Input()
  program: Program;
  @Input()
  adapter: HomegenieAdapter;

  private programModule: Module;

  private _programStatus = new ProgramStatusView();
  get programStatus(): ProgramStatusView {
    return this._programStatus;
  }

  get isRunning(): boolean {
    return this.program.IsEnabled && (this._programStatus.status === 'Running' || this._programStatus.status === 'Background');
  }

  get hasErrors(): boolean {
    if (!this.program) return false;
    let errors = false;
    const scriptErrors = this.program.ScriptErrors ? this.program.ScriptErrors : '[]';
    if (this.programModule) {
      const errorField = this.programModule.field('Runtime.Error');
      errors = (errorField && errorField.value && errorField.value.length > 0);
    }
    return !this.isRunning && (errors || scriptErrors !== '[]');
  }

  private modulesEventSubscription: Subscription;

  constructor() { }

  ngOnInit() {
    this.modulesEventSubscription = this.adapter.onModuleEvent.subscribe(({module, event}) => {
      if (module?.id === this.adapter.getModuleId(this.program as any)) {
        switch (event.Property) {
          case 'Program.Status':
            this._programStatus.status = event.Value;
            this._programStatus.timestamp = event.UnixTimestamp;
            break;
          case 'Runtime.Error':
            if (event.Value.length > 0) {
              this.adapter.yot
                .notify("Runtime error", event.Value);
            }
            break;
        }
        this.refresh();
      }
    });
    this.refresh();
  }
  ngOnDestroy() {
    this.modulesEventSubscription?.unsubscribe();
  }


  protected refresh() {
    this.program = this.adapter.programs.find(p => p.Address === this.program.Address);
    this.programModule = this.adapter.getModuleByRef(this.program as any);
    if (this.programModule) {
      const status = this.programModule.field('Program.Status');
      this._programStatus.status = status ? status.value : 'Broken';
      this._programStatus.timestamp = status?.timestamp;
    }
    this._programStatus.enabled = this.program.IsEnabled;
    this._programStatus.running = this.isRunning;
    this._programStatus.errors = this.hasErrors;
  }

}
