import {
  ChangeDetectorRef,
  Component, ElementRef,
  EventEmitter,
  Input, NgZone,
  OnInit, OnDestroy,
  Output
} from '@angular/core';
import {Module} from '../services/yot/module';
import {WidgetData} from "./widget-data";
import {MatDialog} from "@angular/material/dialog";
import {YotService} from "../services/yot/yot.service";
import {WidgetActionRequest} from "./common-parts/widget-actions-menu/widget-actions-menu.component";
import {DashboardWidget} from "../services/dashboard/dashboard";
import {LayoutService} from "../services/layout.service";
import {UtilsService} from "../services/utils.service";
import {OverlayContainer} from "@angular/cdk/overlay";

@Component({
  template: 'no-ui'
})
export class WidgetBaseComponent implements OnInit, OnDestroy {
  @Input()
  widget: DashboardWidget;
  @Input()
  options: any = {};
  @Output()
  widgetActionRequest: EventEmitter<WidgetActionRequest> = new EventEmitter();
  @Output()
  widgetStatusChange: EventEmitter<any> = new EventEmitter();

  module: Module;
  defaultConfiguration: {};
  defaultData: {};

  private _widgetData: WidgetData;
  get widgetData(): WidgetData {
    const m = this.module;
    const w = this.widget;
    this._widgetData = m ? m.getWidgetData() : w?.data ? w.data : { type: w?.type };
    return this._widgetData;
  }

  get configuration(): any {
    if (this.widget?.configuration) {
      return this.widget.configuration;
    }
    return this.widget.configuration = this.defaultConfiguration;
  }

  set configuration(config: any) {
    if (this.widget) {
      this.widget.configuration = config;
    }
  }
  save() {
    if (this.widget) {
      this.widget.configuration = this.configuration;
      this.yot.saveConfiguration(); // maybe split this task into a specific `this.yot.saveDashboard()` method?
    }
  }

  get isSmallScreen(): boolean {
    return this.layoutService.isSmallScreen;
  }

  get features(): any {
    return this.data && this.data.features ?
      this.data.features : {};
  }

  get data(): any {
    const data = this.widgetData;
    return data && data.value ? data.value : this.defaultData;
  }

  protected isVisible = false;
  private _is_paused = true;
  private observer: IntersectionObserver;

  constructor(
    protected containerRef: ElementRef,
    protected dialog: MatDialog,
    protected ngZone: NgZone,
    public yot: YotService,
    private layoutService: LayoutService,
    protected utils: UtilsService,
    protected changeDetector: ChangeDetectorRef,
    protected overlayContainer: OverlayContainer
  ) {
  }

  ngOnInit() {
    const w = this.widget;
    if (w && typeof w['_componentReady'] === 'function') {
      w['_componentReady'](this);
    }
    this.module = w?.module ? this.yot.getModuleByRef(w.module) : null;

    this.setupIntersectionObserver();
    setTimeout(() => {
      this.checkVisible();
    });
  }

  ngOnDestroy() {
    this.observer?.disconnect();
  }

  public onWidgetActionRequest(actionRequest: WidgetActionRequest): void {
    this.widgetActionRequest.emit(actionRequest);
  }

  public checkVisible(): void {
    if (this.containerRef) {
      if (!this.isVisible && !this._is_paused) {
        this._is_paused = true;
        this.widgetStatusChange.emit('widget:paused');
      } else if (this._is_paused && this.isVisible) {
        this._is_paused = false;
        this.widgetStatusChange.emit('widget:resumed');
      }
    }
  }

  setupIntersectionObserver() {
    const options = {
      root: null,
      rootMargin: '0px',
      threshold: 0.1
    };
    this.observer = new IntersectionObserver(this.handleIntersection.bind(this), options);
    this.observer.observe(this.containerRef.nativeElement);
  }

  handleIntersection(entries: IntersectionObserverEntry[]) {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        this.isVisible = true;
      } else {
        this.isVisible = false;
      }
      this.checkVisible();
    });
  }
}
